// ── Post scheduling through Zernio (Dani, 20 Oct 2026) ─────────────────────
// ── Content Calendar access (Danielle, 27 Oct 2026) ─────────────────────────
// The one access check for the Content Calendar subscription: what a member's
// level gives them (the calendar, the library, scheduling, Done For You, which
// courses). Worked out here, never in the browser, from either source of
// access: a TEG brand paying for its agents, or the member's own card.
// Neither exists yet, so everyone is Free; staff get everything and can see
// any level with ?as=<level>. Build list: docs/content-calendar-build.md.
const ACCESS_LEVELS = {
  free:         { rank: 0, calendar: false, library_back: null, scheduling: false, done_for_you: false },
  calendar:     { rank: 1, calendar: true,  next_month: true, library_back: 0,  scheduling: false, done_for_you: false },
  scheduling:   { rank: 2, calendar: true,  next_month: true, library_back: 3,  scheduling: true,  done_for_you: false },
  done_for_you: { rank: 3, calendar: true,  next_month: true, library_back: -1, scheduling: true,  done_for_you: true },
};
// The levels as set in Admin › Content calendar › Overview (content_levels,
// Danielle, 29 Oct 2026). Read for a minute at a time. Until that table's SQL
// has run, ACCESS_LEVELS above (the same values the SQL seeds) stands in, and
// the answer says so (levels_from: "built-in") rather than passing quietly.
let ACCESS_LEVELS_CACHE = null;
async function accessLevels(env) {
  if (ACCESS_LEVELS_CACHE && Date.now() - ACCESS_LEVELS_CACHE.at < 60000) return ACCESS_LEVELS_CACHE;
  const rows = await sbGet(env, "content_levels", "select=key,sort_order,calendar,next_month,library_months,scheduling,done_for_you");
  let out = { at: Date.now(), from: "built-in", levels: ACCESS_LEVELS };
  if (Array.isArray(rows) && rows.length) {
    const levels = {};
    Object.keys(ACCESS_LEVELS).forEach((k) => {
      const r = rows.find((x) => x.key === k);
      levels[k] = r
        ? { rank: ACCESS_LEVELS[k].rank, calendar: !!r.calendar, next_month: !!r.next_month,
            library_back: r.library_months == null ? null : Number(r.library_months),
            scheduling: !!r.scheduling, done_for_you: !!r.done_for_you }
        : ACCESS_LEVELS[k];
    });
    out = { at: Date.now(), from: "table", levels };
  } else {
    console.warn("access: content_levels unreadable; using the built-in levels");
  }
  ACCESS_LEVELS_CACHE = out;
  return out;
}
// Which month's posts a TEG brand gets. Anyone not on a TEG brand is independent.
const ACCESS_EDITION_OF_BRAND = {
  "The Property Experts": "property",
  "Prestige Property Experts": "prestige",
  "The Letting Experts": "lettings",
  // Same posts as England until there's a Scottish edition (Dani, 3 Nov 2026).
  "The Letting Experts Scotland": "lettings",
};
/* Launch switches (Danielle, 11 Nov 2026; content_calendar_launch.sql):
   the December rule for TPE and PPE agents, off until launch, and the test
   logins, which are treated as if it were already on. Read for 30 seconds
   at a time; before the SQL has run, both are off and nobody changes. */
const CC_TEG_EDITIONS = ["property", "prestige"];
let CC_SETTINGS_CACHE = null;
async function ccSettings(env, fresh) {
  if (!fresh && CC_SETTINGS_CACHE && Date.now() - CC_SETTINGS_CACHE.at < 30000) return CC_SETTINGS_CACHE;
  let row = ((await sbGet(env, "content_calendar_settings", "id=eq.1&select=teg_live,test_user_ids,updated_at,updated_by,dfy_spaces,dfy_audience,dfy_open")) || [])[0];
  // Before dfy_waitlist.sql has added its columns.
  if (!row) row = ((await sbGet(env, "content_calendar_settings", "id=eq.1&select=teg_live,test_user_ids,updated_at,updated_by")) || [])[0];
  CC_SETTINGS_CACHE = {
    at: Date.now(), ready: !!row,
    teg_live: !!(row && row.teg_live),
    test_user_ids: (row && Array.isArray(row.test_user_ids)) ? row.test_user_ids : [],
    updated_at: row ? row.updated_at : null, updated_by: row ? row.updated_by : null,
    dfy_ready: !!(row && row.dfy_spaces != null),
    dfy_spaces: (row && Number(row.dfy_spaces)) || 10,
    dfy_audience: (row && row.dfy_audience) || "teg",
    dfy_open: !!(row && row.dfy_open),
  };
  return CC_SETTINGS_CACHE;
}
function accessMonth(offset) {
  const p = londonParts(new Date()).ymd.split("-").map(Number);
  const d = new Date(Date.UTC(p[0], p[1] - 1 + offset, 1));
  return d.toISOString().slice(0, 10);
}
async function memberAccess(env, user, asLevel) {
  // Their TEG brands, from the agent profiles on their contact record.
  let editions = [], primary = null;
  try {
    let c = ((await sbGet(env, "contacts", `user_id=eq.${encodeURIComponent(user.id)}&select=id&limit=1`)) || [])[0];
    if (!c && user.email) c = ((await sbGet(env, "contacts", `email=eq.${encodeURIComponent(String(user.email).toLowerCase())}&select=id&limit=1`)) || [])[0];
    if (c) {
      const rows = (await sbGet(env, "agent_profiles", `contact_id=eq.${encodeURIComponent(c.id)}&left_at=is.null&select=brand,is_primary`)) || [];
      rows.forEach((r) => {
        const ed = ACCESS_EDITION_OF_BRAND[r.brand];
        if (!ed) return;
        if (!editions.includes(ed)) editions.push(ed);
        if (r.is_primary && !primary) primary = ed;
      });
    }
  } catch (_) {}
  const teg = editions.length > 0;
  if (!teg) editions = ["independent"];
  const staff = !!user._isAdmin;
  // Until subscriptions exist: Free for members, everything for staff.
  let level = staff ? "done_for_you" : "free";
  let source = staff ? "staff" : "none";
  if (staff && ACCESS_LEVELS[asLevel]) level = asLevel;
  // The December rule: a TPE or PPE agent's brand pays for the calendar. Off
  // until launch; a test login gets it now, exactly as an agent would then.
  const S = await ccSettings(env);
  const test = !staff && S.test_user_ids.includes(user.id);
  if (!staff && editions.some((e) => CC_TEG_EDITIONS.includes(e)) && (S.teg_live || test)) {
    level = "calendar";
    source = test ? "test" : "teg";
  }
  const AL = await accessLevels(env);
  const L = AL.levels[level];
  const joined = null;   // the month they first subscribed, once subscriptions exist
  let library = null;
  if (L.calendar) {
    let from = L.library_back == null ? accessMonth(0) : L.library_back < 0 ? null : accessMonth(-L.library_back);
    if (joined && (!from || joined > from)) from = joined;
    library = { from, to: accessMonth(L.next_month ? 1 : 0) };
  }
  return {
    ok: true, level, staff, teg,
    edition: primary || editions[0], editions,
    source,                                  // staff | test | teg (brand pays) | none; later "card"
    calendar: L.calendar,
    preview: !L.calendar,                    // free members see the month blurred
    library,                                 // months they can open, inclusive; from null = all
    scheduling: L.scheduling,
    done_for_you: L.done_for_you,
    course_levels: Object.keys(ACCESS_LEVELS).filter((k) => ACCESS_LEVELS[k].rank <= L.rank),
    levels_from: AL.from,                    // "table", or "built-in" before the SQL has run
    test,                                    // a test login (content_calendar_settings)
  };
}

/* ---- The month for members, through the Worker (Danielle, 11 Nov 2026) ----
   content_months and content_month_posts are admin-only in the database, and
   calendar designs aren't readable by members either, so a real agent reads
   their month here: memberAccess decides, the service key reads. A member
   with the calendar gets their own edition's published months inside their
   library; a member without it gets this month and next as a blurred
   preview (pictures and titles only). Staff can open any edition. */
const CC_POST_COLS = "id,month_id,post_date,date_tied,occasion,title,post_type,pillar,captions,how_to_edit,reel_prompt,platforms,template_id,sort_order";
const CC_PREVIEW_COLS = "id,month_id,post_date,title,post_type,pillar,template_id,sort_order";
const CC_EDITION_ORDER = ["property", "prestige", "independent", "lettings"];
function ccMonthKey(v) {
  const m = String(v || "").match(/^(\d{4})-(\d{2})/);
  return m ? `${m[1]}-${m[2]}-01` : null;
}
function ccMayOpenMonth(a, ym) {
  if (a.staff) return true;
  if (a.calendar) return !!a.library && (!a.library.from || ym >= a.library.from) && ym <= a.library.to;
  return ym >= accessMonth(0) && ym <= accessMonth(1);   // the blurred preview: this month and next
}
function ccMayOpenEdition(a, ed) {
  return a.staff || (a.editions || []).includes(ed);
}
function ccPickEdition(a, published, want) {
  const ok = published.filter((ed) => ccMayOpenEdition(a, ed));
  if (want && ok.includes(want)) return want;
  if (ok.includes(a.edition)) return a.edition;
  if (ok.length) return ok.sort((x, y) => CC_EDITION_ORDER.indexOf(x) - CC_EDITION_ORDER.indexOf(y))[0];
  // Nothing in their own edition: a preview shows the first published one, blurred.
  if (!a.calendar && published.length) return published.slice().sort((x, y) => CC_EDITION_ORDER.indexOf(x) - CC_EDITION_ORDER.indexOf(y))[0];
  return null;
}
async function ccTemplatesById(env, ids, full) {
  const want = [...new Set((ids || []).filter(Boolean))];
  if (!want.length) return new Map();
  const cols = full ? "id,name,category,thumb_url,canvas,elements,pages,size_variants" : "id,name,thumb_url";
  const list = want.map((x) => `"${String(x).replace(/"/g, "")}"`).join(",");
  let rows = await sbGet(env, "templates", `id=in.(${encodeURIComponent(list)})&select=${cols}`);
  if (!rows && full) rows = await sbGet(env, "templates", `id=in.(${encodeURIComponent(list)})&select=id,name,category,thumb_url,canvas,elements`);
  return new Map((rows || []).map((t) => [t.id, t]));
}
// A published month row this member may open, or null.
/* ---- The Done For You waitlist (Danielle, 11 Nov 2026; dfy_waitlist.sql) ----
   Done For You opens in January. In December the website's waitlist page
   takes sign-ups: 10 spaces, TEG agents only (dfy_audience "teg"); from
   February the same list opens to independents ("all"). Past the spaces,
   people join the reserve list in order. Closed (dfy_open false) until the
   page goes out, except for test logins and staff, so it can be tried. */
const DFY_TEG_BRANDS = ["The Property Experts", "Prestige Property Experts"];
const DFY_OPTIONS = { subscription: "The Done For You subscription", add_on: "Done For You as a monthly add-on" };
async function dfyCounts(env) {
  const rows = (await sbGetAll(env, "dfy_waitlist", "status=neq.removed&select=id,created_at&order=created_at.asc")) || [];
  return rows;
}
// The confirmation (copy: tmke-copywriter, 11 Nov). A reserve place counts
// from the end of the spaces, so the eleventh to join is reserve number 1.
function dfyWaitlistEmail(r, place, spaces, reserve) {
  const esc = (v) => String(v ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  const first = esc(String(r.name || "").split(" ")[0] || "there");
  const opt = esc(DFY_OPTIONS[r.option] || "");
  const what = `<p style="${EM_P}">Done For You is the top tier of the Content Calendar subscription in your Member Hub. Our team takes the month&rsquo;s Content Calendar posts and brands them for you, finalising ten posts a month.</p>
    <p style="${EM_P}">${opt} is the option you chose when you signed up.</p>`;
  const tail = `<p style="${EM_P}">If you&rsquo;d like to change your option or come off the list, just reply to this email.</p>
    <p style="${EM_P}">The TMKE Team</p>`;
  if (!reserve) return {
    to: r.email,
    subject: "You're on the Done For You waitlist.",
    html: `<div style="${EM_WRAP}">
      <h1 style="${EM_H1}">You&rsquo;ve Got One of the Spaces.</h1>
      <p style="${EM_P}">Hi ${first},</p>
      <p style="${EM_P}">Thanks for joining the Done For You waitlist. You&rsquo;re number ${place} of ${spaces}, so you&rsquo;ve got one of the spaces.</p>
      ${what}
      <p style="${EM_P}">Done For You launches in January 2027. We&rsquo;re inviting people in the order they joined, ahead of January, and we&rsquo;ll email you when it&rsquo;s your turn.</p>
      <p style="${EM_P}">Joining the waitlist doesn&rsquo;t charge you anything. It isn&rsquo;t an account and doesn&rsquo;t commit you to anything.</p>
      ${tail}
    </div>`,
  };
  return {
    to: r.email,
    subject: "You're on the Done For You reserve list.",
    html: `<div style="${EM_WRAP}">
      <h1 style="${EM_H1}">You&rsquo;re on the Reserve List.</h1>
      <p style="${EM_P}">Hi ${first},</p>
      <p style="${EM_P}">Thanks for joining the Done For You waitlist. All ${spaces} spaces have already been taken, so you&rsquo;re on the reserve list at number ${place - spaces}.</p>
      <p style="${EM_P}">If a space opens up, we&rsquo;ll offer it to the reserve list in order, and we&rsquo;ll email you when it&rsquo;s your turn.</p>
      ${what}
      <p style="${EM_P}">Done For You launches in January 2027. Being on the reserve list doesn&rsquo;t charge you anything. It isn&rsquo;t an account and doesn&rsquo;t commit you to anything.</p>
      ${tail}
    </div>`,
  };
}
async function ccOpenMonthRow(env, a, monthId) {
  const m = ((await sbGet(env, "content_months", `id=eq.${encodeURIComponent(monthId)}&select=id,month,edition,status,intro`)) || [])[0];
  if (!m || (m.status !== "published" && !a.staff)) return null;
  if (!ccMayOpenMonth(a, m.month) || (a.calendar && !ccMayOpenEdition(a, m.edition))) return null;
  return m;
}

// Zernio posts to the member's own social accounts. One Zernio profile per
// member, tagged with their TMKE user id (externalId), holds the accounts they
// connect through Zernio's sign-in links. Scheduling is the Content Calendar
// subscription's add-on and isn't on sale yet: staff only until
// SCHEDULE_OPEN = "1" (or a per-member entitlement) says otherwise.
// https://zernio.com/llms.txt  ·  ZERNIO_API_KEY is a Worker secret.
const ZERNIO_API = "https://zernio.com/api/v1";
const ZERNIO_PLATFORMS = ["instagram", "facebook", "linkedin", "tiktok"];
function scheduleAllowed(env, user) {
  // Staff, or a member whose plan includes it: zernioMemberMayPost is the one
  // rule, and the daily check disconnects anyone it stops allowing.
  return !!user && (isAdminEmail(user) || env.SCHEDULE_OPEN === "1");
}
async function zernio(env, path, init = {}) {
  if (!env.ZERNIO_API_KEY) return { ok: false, status: 503, data: { error: "Scheduling isn't set up (ZERNIO_API_KEY)." } };
  const res = await fetch(`${ZERNIO_API}${path}`, {
    ...init,
    headers: { Authorization: `Bearer ${env.ZERNIO_API_KEY}`, "Content-Type": "application/json", ...(init.headers || {}) },
  }).catch(() => null);
  if (!res) return { ok: false, status: 502, data: { error: "Couldn't reach Zernio." } };
  const data = await res.json().catch(() => ({}));
  return { ok: res.ok, status: res.status, data };
}
// The house profile: Zernio's default one, holding TMKE's own accounts. Staff
// test against it (Dani, 20 Oct: the free plan allows two accounts, so no
// member connects anything until they pay).
async function zernioHouseProfile(env) {
  const r = await zernio(env, "/profiles");
  const list = (r.ok && r.data.profiles) || [];
  return list.find((p) => p.isDefault) || list[0] || null;
}
// The member's Zernio profile, made the first time they need one.
async function zernioProfile(env, user) {
  const ext = encodeURIComponent(user.id);
  const found = await zernio(env, `/profiles?externalId=${ext}`);
  if (found.ok && Array.isArray(found.data.profiles) && found.data.profiles[0]) return found.data.profiles[0];
  const made = await zernio(env, "/profiles", { method: "POST", body: JSON.stringify({ name: String(user.email || user.id).slice(0, 120), externalId: user.id, timezone: "Europe/London" }) });
  if (made.ok) return made.data.profile || made.data;
  // Made by a request a moment ago: Zernio names the one that exists.
  const existing = made.data && made.data.details && made.data.details.existingProfileId;
  if (existing) { const got = await zernio(env, `/profiles/${existing}`); if (got.ok) return got.data.profile || got.data; }
  return null;
}
// A calendar entry's London date and time as the instant Zernio schedules for.
function londonToUtcIso(date, time) {
  const [y, m, d] = String(date).split("-").map(Number);
  const [hh, mm] = String(time || "09:00").split(":").map(Number);
  const guess = Date.UTC(y, m - 1, d, hh, mm);
  const p = Object.fromEntries(new Intl.DateTimeFormat("en-GB", { timeZone: "Europe/London", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", hourCycle: "h23" }).formatToParts(new Date(guess)).map((x) => [x.type, x.value]));
  const shown = Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute);
  return new Date(guess - (shown - guess)).toISOString();
}

// Idle accounts cost us (Zernio charges per connected account), so a member's
// accounts are disconnected after 30 days with nothing scheduled or posted,
// and straight away once they're no longer allowed to schedule (Dani, 20 Oct). They reconnect with one button when they're back. Only
// members' profiles (those with an externalId); never the house profile. An
// account connected in the last 30 days is left alone, so a new connection
// has its month too. Runs at 8am.
const ZERNIO_NAMES = { instagram: "Instagram", facebook: "Facebook", linkedin: "LinkedIn", tiktok: "TikTok" };
// Disconnect a member's accounts from Zernio and tell them why. The one way
// accounts come off: the idle check below, and (when subscriptions exist)
// every cancellation, ours or theirs, must call zernioDisconnectMember.
async function zernioDisconnectAccounts(env, prof, accounts, why) {
  const gone = [];
  for (const a of accounts) {
    const r = await zernio(env, `/accounts/${encodeURIComponent(a._id || a.id)}`, { method: "DELETE" });
    if (r.ok) gone.push(ZERNIO_NAMES[a.platform] || a.platform);
  }
  if (gone.length && prof.externalId) {
    const names = gone.length === 1 ? gone[0] : `${gone.slice(0, -1).join(", ")} and ${gone[gone.length - 1]}`;
    const body = why === "ended"
      ? "Your scheduling has ended with your subscription, so we've disconnected them. Your designs and calendar stay as they are."
      : "Nothing has been scheduled or posted for 30 days. Connect again from your Content Calendar whenever you're ready: it's one button.";
    await notifyMember(env, prof.externalId, { kind: "schedule_disconnected", title: `We've disconnected your ${names}`, body, href: "/account/schedule" });
  }
  return gone;
}
// Every account a member has, off, because their scheduling has ended.
async function zernioDisconnectMember(env, userId) {
  if (!env.ZERNIO_API_KEY || !userId) return [];
  const found = await zernio(env, `/profiles?externalId=${encodeURIComponent(userId)}`);
  const prof = found.ok && (found.data.profiles || [])[0];
  if (!prof || prof.isDefault) return [];
  const acc = await zernio(env, `/accounts?profileId=${prof._id}`);
  return zernioDisconnectAccounts(env, prof, (acc.ok && acc.data.accounts) || [], "ended");
}
// May this member schedule? Until subscriptions exist, only when it's opened
// for everyone; then, their tier (or the TEG add-on) must include scheduling.
async function zernioMemberMayPost(env, userId) {
  return env.SCHEDULE_OPEN === "1";
}
async function runZernioIdleCheck(env) {
  if (!env.ZERNIO_API_KEY) return;
  const DAY = 86400000, now = Date.now(), cutoff = now - 30 * DAY;
  const profs = await zernio(env, "/profiles");
  const members = ((profs.ok && profs.data.profiles) || []).filter((p) => p.externalId && !p.isDefault && (p.accountCount || 0) > 0);
  for (const prof of members) {
    try {
      // No longer allowed to schedule (cancelled, ended, not paid): off now.
      // A safety net behind the cancellation itself calling zernioDisconnectMember.
      if (!(await zernioMemberMayPost(env, prof.externalId))) {
        const all = await zernio(env, `/accounts?profileId=${prof._id}`);
        await zernioDisconnectAccounts(env, prof, (all.ok && all.data.accounts) || [], "ended");
        continue;
      }
      const posts = await zernio(env, `/posts?profileId=${prof._id}&limit=100`);
      if (!posts.ok) continue;
      const list = posts.data.posts || [];
      // Anything still to go out means they're using it.
      if (list.some((x) => x.status === "scheduled" && new Date(x.scheduledFor).getTime() > now)) continue;
      const last = Math.max(0, ...list.map((x) => Math.max(new Date(x.publishedAt || 0).getTime() || 0, new Date(x.scheduledFor || 0).getTime() || 0, new Date(x.createdAt || 0).getTime() || 0)));
      if (last > cutoff) continue;
      const acc = await zernio(env, `/accounts?profileId=${prof._id}`);
      const accounts = (acc.ok && acc.data.accounts) || [];
      const idle = accounts.filter((a) => new Date(a.connectedAt || a.createdAt || 0).getTime() < cutoff);
      if (!idle.length) continue;
      await zernioDisconnectAccounts(env, prof, idle, "idle");
    } catch (_) { /* one member's trouble never stops the rest */ }
  }
}

// A notification in a member's bell (member_notifications.sql). Never throws:
// a missing table or a failed write costs the notification, not the action.
async function notifyMember(env, userId, { kind, title, body, href, meta }) {
  if (!userId || !env.SUPABASE_SERVICE_ROLE) return false;
  try {
    const res = await fetch(`${env.SUPABASE_URL}/rest/v1/member_notifications`, {
      method: "POST",
      headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=minimal" },
      body: JSON.stringify({ user_id: userId, kind, title, body: body || null, href: href || null, meta: meta || {} }),
    });
    return res.ok;
  } catch (_) { return false; }
}

// Every sign-in account, a thousand at a time, banned ones left out.
// { users: [{ id, email, created_at }], error } -- error is "" when complete.
async function listAccounts(env) {
  const H = { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}` };
  const out = [];
  for (let page = 1; page <= 50; page++) {
    const r = await fetch(`${env.SUPABASE_URL}/auth/v1/admin/users?page=${page}&per_page=1000`, { headers: H }).catch(() => null);
    if (!r || !r.ok) return { users: out, error: `Couldn't list accounts (${r ? r.status : "no answer"}).` };
    const j = await r.json().catch(() => ({}));
    const users = Array.isArray(j.users) ? j.users : [];
    for (const u of users) {
      if (!u.id || (u.banned_until && new Date(u.banned_until) > new Date())) continue;
      out.push({ id: u.id, email: String(u.email || "").toLowerCase(), created_at: u.created_at });
    }
    if (users.length < 1000) break;
  }
  return { users: out, error: "" };
}

// Hub notices (member_broadcasts.sql): a message the admin writes once for
// every member's bell, sent at the time it was set for. Each due notice is
// claimed first (scheduled → sending, only if still scheduled), so two ticks
// can never send it twice. 'withdraw' takes a sent one back out of every bell.
// The Community's next topic (Dani, 17 Oct): two weeks before the last one
// scheduled runs out, a reminder in Danielle's and Sam's admin bells to set
// the next. Daily at 08:00; once per due date (the once-only key), so a date
// that passes unset is said once, not every morning.
/* Social media clients with a leaving date (Danielle, 23 Oct 2026): on the
   day, the lead becomes lost, or the client Ended, as was chosen when the
   date was set. lost_at is stamped with the date itself. Runs at 07:00 and
   08:00; the second finds nothing because the first cleared the date. */
/* Social media clients whose invoicing stops (Danielle, 4 Nov 2026): a lost
   client, and a paused one until they're active again. Given lead ids, the
   ones that are stopped and why ("Lost" or "Paused"). Nothing is switched
   off, so invoicing picks up again by itself when a client comes back. */
async function smmStoppedLeads(env, ids) {
  const list = [...new Set((ids || []).filter(Boolean))];
  const out = new Map();
  for (let i = 0; i < list.length; i += 80) {
    const rows = (await sbGet(env, "smm_leads", `id=in.(${list.slice(i, i + 80).join(",")})&select=id,pipeline_stage,client_status`)) || [];
    rows.forEach((l) => {
      if (l.pipeline_stage === "lost" || l.client_status === "ended") out.set(l.id, "Lost");
      else if (l.client_status === "paused") out.set(l.id, "Paused");
    });
  }
  return out;
}

async function runSmmLeavingDue(env) {
  try {
    const hdr = { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=representation" };
    const a = await fetch(`${env.SUPABASE_URL}/rest/v1/smm_leads?client_status=eq.ended&pipeline_stage=neq.lost&select=id`, { method: "PATCH", headers: hdr, body: JSON.stringify({ pipeline_stage: "lost" }) });
    const b = await fetch(`${env.SUPABASE_URL}/rest/v1/smm_leads?pipeline_stage=eq.lost&lost_from_stage=eq.active_client&client_status=eq.active&select=id`, { method: "PATCH", headers: hdr, body: JSON.stringify({ client_status: "ended" }) });
    const mended = [...(a.ok ? await a.json() : []), ...(b.ok ? await b.json() : [])];
    for (const m of mended) { try { await syncSmmContact(env, m.id); } catch (_) {} }
  } catch (_) {}
  try {
    const today = new Date().toLocaleDateString("en-CA", { timeZone: "Europe/London" });
    const due = (await sbGet(env, "smm_leads", `leaving_on=lte.${today}&leaving_as=not.is.null&select=id,full_name,business,leaving_on,leaving_as,lost_reason`)) || [];
    for (const l of due) {
      const patch = { leaving_on: null, leaving_as: null, lost_at: `${l.leaving_on}T00:00:00Z` };
      // Ended and Lost are one thing (Danielle, 4 Nov 2026): a client who
      // leaves is lost, and keeps "was a client" in lost_from_stage.
      patch.pipeline_stage = "lost";
      if (l.leaving_as === "ended") patch.client_status = "ended";
      const res = await sbPatch(env, "smm_leads", `id=eq.${encodeURIComponent(l.id)}&leaving_on=eq.${l.leaving_on}`, patch);
      if (res && res.ok === false) continue;
      try { await syncSmmContact(env, l.id); } catch (_) {}
      try {
        await notifyAdmins(env, {
          area: "social", event: "smm_left", key: `smm_left:${l.id}:${l.leaving_on}`,
          title: `${l.full_name || l.business || "A client"} is now lost${l.leaving_as === "ended" ? " (was a client)" : ""}`,
          body: [l.business, l.lost_reason].filter(Boolean).join(" · ") || null,
          href: "/admin/social",
        });
      } catch (_) {}
    }
  } catch (_) {}
}

async function runCommunityTopicDue(env) {
  try {
    const rows = await sbGet(env, "community_posts", "kind=eq.topic&hidden=is.false&pinned=is.false&ends_on=not.is.null&select=ends_on&order=ends_on.desc&limit=1");
    const due = rows && rows[0] && rows[0].ends_on;
    if (!due) return;
    const today = new Date().toLocaleDateString("en-CA", { timeZone: "Europe/London" });
    const from = new Date(due + "T12:00:00Z");
    from.setUTCDate(from.getUTCDate() - 14);
    if (today < from.toISOString().slice(0, 10)) return;
    const nice = new Date(due + "T12:00:00Z").toLocaleDateString("en-GB", { weekday: "short", day: "numeric", month: "short", year: "numeric", timeZone: "Europe/London" });
    await notifyAdmins(env, {
      area: "community", event: "community_topic_due",
      title: `The next Community topic is due ${nice}`,
      body: "Set it in Admin > Community > Fortnight topics: the topic, the question, the intro and TMKE's view. It goes live at 8am that day.",
      href: "/admin/community", key: `topic_due:${due}`,
    });
  } catch (_) {}
}

async function runMemberBroadcasts(env) {
  if (!env.SUPABASE_SERVICE_ROLE) return;
  const H = { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json" };
  const now = new Date().toISOString();
  const due = await sbGet(env, "member_broadcasts", `status=in.(scheduled,withdraw)&send_at=lte.${encodeURIComponent(now)}&select=*&order=send_at.asc&limit=5`);
  if (!Array.isArray(due) || !due.length) return;
  for (const b of due) {
    if (b.status === "withdraw") {
      const del = await fetch(`${env.SUPABASE_URL}/rest/v1/member_notifications?meta->>broadcast_id=eq.${b.id}`, { method: "DELETE", headers: { ...H, Prefer: "return=minimal" } }).catch(() => null);
      if (del && del.ok) await sbPatch(env, "member_broadcasts", `id=eq.${b.id}&status=eq.withdraw`, { status: "withdrawn" });
      continue;
    }
    const claim = await fetch(`${env.SUPABASE_URL}/rest/v1/member_broadcasts?id=eq.${b.id}&status=eq.scheduled`, {
      method: "PATCH", headers: { ...H, Prefer: "return=representation" }, body: JSON.stringify({ status: "sending" }),
    }).catch(() => null);
    const claimed = claim && claim.ok ? await claim.json().catch(() => []) : [];
    if (!claimed.length) continue;
    const { users, error: listError } = await listAccounts(env);
    const ids = users.map((u) => u.id);
    let sent = 0, failed = 0;
    const meta = { broadcast_id: b.id };
    for (let i = 0; i < ids.length; i += 500) {
      const rows = ids.slice(i, i + 500).map((user_id) => ({ user_id, kind: "pack_news", title: b.title, body: b.body || null, href: b.href || null, meta }));
      const r = await fetch(`${env.SUPABASE_URL}/rest/v1/member_notifications`, { method: "POST", headers: { ...H, Prefer: "return=minimal" }, body: JSON.stringify(rows) }).catch(() => null);
      if (r && r.ok) sent += rows.length; else failed += rows.length;
    }
    const error = listError || (failed ? `${failed} account${failed === 1 ? "" : "s"} didn't get it.` : null);
    await sbPatch(env, "member_broadcasts", `id=eq.${b.id}`, { status: sent ? "sent" : "failed", sent_at: new Date().toISOString(), sent_count: sent, error });
  }
}

async function runSetupReminders(env) {
  if (!env.SUPABASE_SERVICE_ROLE) return;
  const MINUTES = 30; // remind once a paid order has been unclaimed this long
  try {
    const newer = new Date(Date.now() - MINUTES * 60 * 1000).toISOString();
    const older = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString(); // don't chase ancient orders
    const rows = await sbGet(
      env,
      "orders",
      `status=eq.paid&payment_method=neq.gift&user_id=is.null&setup_reminder_sent_at=is.null` +   // a gift has its own email and nothing to "unlock"
        `&created_at=lt.${encodeURIComponent(newer)}&created_at=gt.${encodeURIComponent(older)}` +
        `&select=id,buyer_email,buyer_name,pack_title&order=created_at.asc&limit=50`
    );
    if (!rows || !rows.length) return;
    for (const o of rows) {
      if (!o.buyer_email) continue;
      // Stamp first so a slow/failed send can't double-email on the next tick.
      await sbPatch(env, "orders", `id=eq.${o.id}`, { setup_reminder_sent_at: new Date().toISOString() });
      // Skip if an account already exists for this email — they can just sign in.
      const hasAccount = !!(await findUserByEmail(env, o.buyer_email));
      if (hasAccount) continue;
      const link = `${(env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "")}/edit/thanks?order=${encodeURIComponent(o.id)}`;
      await sendEmail(env, {
        to: o.buyer_email,
        subject: "Set your password to unlock your TMKE pack",
        html: await wrapInBrandedBase(env, setupReminderHtml({ name: o.buyer_name, pack: o.pack_title, link })),
      });
    }
  } catch (_) { /* best-effort; the next tick retries any newly-eligible orders */ }
}

// ---- Inbound email capture (Phase 4) -----------------------------------
// Polls the SMM manager's mailbox on the frequent cron and logs client replies
// into the correspondence thread as inbound emails, matched to the lead by
// sender address. Best-effort: needs the Mail.Read application permission on the
// Graph app (admin-consented); without it the Graph read 403s and we skip.
async function pollSmmInbox(env) {
  const mailbox = env.SMM_MAIL_SENDER || env.MAIL_SENDER;
  if (!mailbox) return { ok: false, error: "No mailbox configured (SMM_MAIL_SENDER / MAIL_SENDER)." };
  // Look back a generous window and dedup by the Graph message id, so a message
  // is never logged twice however often the cron runs.
  const sinceIso = new Date(Date.now() - 2 * 3600000).toISOString();
  let messages = [];
  try {
    const q = `/users/${encodeURIComponent(mailbox)}/mailFolders/inbox/messages?$filter=receivedDateTime ge ${sinceIso}&$select=id,subject,bodyPreview,from,receivedDateTime&$orderby=receivedDateTime desc&$top=40`;
    const data = await graph(env, "GET", q);
    messages = (data && data.value) || [];
  } catch (err) { return { ok: false, error: (err && err.message) || "Graph read failed (Mail.Read may be missing)." }; }
  if (!messages.length) return { ok: true, read: 0, captured: 0 };

  // Message ids we've already captured recently, to dedup.
  const seen = new Set();
  try {
    const rows = await sbGet(env, "booking_messages", `booking_source=eq.smm&direction=eq.inbound&external_id=not.is.null&select=external_id&order=created_at.desc&limit=200`);
    for (const r of (rows || [])) if (r.external_id) seen.add(r.external_id);
  } catch (_) {}

  let captured = 0;
  for (const m of messages) {
    if (!m.id || seen.has(m.id)) continue;
    const from = m.from && m.from.emailAddress && m.from.emailAddress.address;
    if (!from) continue;
    // Match to the most recent SMM lead with this sender address.
    let lead = null;
    try {
      const rows = await sbGet(env, "smm_leads", `email=ilike.${encodeURIComponent(String(from).toLowerCase())}&select=id,email,account_user_id&order=created_at.desc&limit=1`);
      lead = rows && rows[0];
    } catch (_) {}
    if (!lead) continue;
    await logBookingMessage(env, {
      booking_id: lead.id, booking_source: "smm", account_user_id: lead.account_user_id, client_email: lead.email,
      direction: "inbound", channel: "email", kind: "reply", subject: m.subject || null,
      body: (m.bodyPreview || "").trim(), is_automated: false, created_by: from, external_id: m.id,
    });
    captured++;
  }
  return { ok: true, read: messages.length, captured };
}

// The TMKE services brochure (social media). Overridden by SMM_BROCHURE_URL in
// wrangler.toml; this is only what GET /smm/brochure.pdf streams when it's unset.
const SMM_BROCHURE_FALLBACK = "https://assets.tmke.co.uk/TMKE%20SMM/TMKE%20-%20Services%20Brochure%202026.pdf";

/* The morning run's jobs. They sat inside fetch()'s second try block, where
   scheduled() can't see them, so the 8am run stopped at runVideographyChasers
   with a ReferenceError, and every job after it never started. Lifted out on 6
   Nov 2026, and held behind invoice_settings.morning_jobs_on: see scheduled(). */
/* ---- "Raise this invoice" ------------------------------------------------
   Two days before a shoot, if nothing has been invoiced yet, tell Jack and
   Danielle. This is the one step in the process that starts the money, and
   until now it was the only one that depended on somebody remembering.

   Deliberately looks for an actual invoice rather than trusting the stage: a
   booking can be nudged along by hand, and the question here is "has anyone
   billed for this?", which only the invoices table can answer.
--------------------------------------------------------------------------- */
// ---- The monthly invoicing checklist ------------------------------------------
// Every active social media client, and every recurring invoice added by hand,
// against six months: sent (sent or paid) and paid. Admin > Invoicing > Monthly
// checklist, and the 14th/21st reminder. Danielle does the month's invoicing in
// its first week, so by the 14th anything missing wants a look (30 Sep 2026).
// A function declaration, not a const: this sits in the same scope as the
// route that calls it, earlier in the file, and a const isn't ready until its
// line has run ("Cannot access 'ymAdd' before initialization").
function ymAdd(ym, k) { const [y, m] = ym.split("-").map(Number); const d = new Date(Date.UTC(y, m - 1 + k, 1)); return d.toISOString().slice(0, 7); }

function londonToday() {
  const p = Object.fromEntries(new Intl.DateTimeFormat("en-GB", { timeZone: "Europe/London", year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(new Date()).map((x) => [x.type, x.value]));
  return { ym: `${p.year}-${p.month}`, day: Number(p.day) };
}

async function monthlyInvoiceChecklist(env, fromYm, n = 6) {
  const months = Array.from({ length: n }, (_, i) => ymAdd(fromYm, i));
  const last = months[months.length - 1];
  const pounds = (v) => { const x = Number(String(v ?? "").replace(/[^0-9.]/g, "")); return Number.isFinite(x) && x > 0 ? Math.round(x * 100) : null; };
  // Read directly, so a database error is reported rather than read as "no
  // clients" (30 Sep 2026: the first live load showed no social clients).
  const warnings = [];
  const readAll = async (table, qs) => {
    const out = [];
    for (let off = 0; off < 50000; off += 1000) {
      const r = await fetch(`${env.SUPABASE_URL}/rest/v1/${table}?${qs}&limit=1000&offset=${off}`, { headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}` } });
      if (!r.ok) { warnings.push(`${table}: ${r.status} ${(await r.text().catch(() => "")).slice(0, 160)}`); break; }
      const page = await r.json(); out.push(...page);
      if (page.length < 1000) break;
    }
    return out;
  };
  const leads = await readAll("smm_leads", "pipeline_stage=eq.active_client&or=(client_status.is.null,client_status.not.in.(internal,paused,ended))&select=id,full_name,business,price,start_date,social_media_manager,inter_brand_invoice&order=business.asc,id.asc");
  let recurring = [], recurringReady = true;
  const rr = await fetch(`${env.SUPABASE_URL}/rest/v1/recurring_invoices?active=eq.true&select=*&order=name.asc`, { headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}` } });
  if (rr.ok) recurring = await rr.json(); else recurringReady = false;
  // Invoices that could belong to the window: raised or billed from a month
  // before it (late invoices for the first month) to its end.
  const from = ymAdd(fromYm, -1);
  // recurring_id arrives with supabase/invoice_month_notes.sql; ask for it
  // only once it's there.
  const hasLink = (await fetch(`${env.SUPABASE_URL}/rest/v1/invoices?select=recurring_id&limit=1`, { headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}` } })).ok;
  const invs = await readAll("invoices",
    `status=in.(draft,sent,paid)&or=(billing_month.gte.${from},issued_date.gte.${from}-01)&select=id,number,booking_id,booking_source,bill_to_email,billing_month,issued_date,created_at,status,line_items,notes${hasLink ? ",recurring_id" : ""}&order=created_at.asc,id.asc`);
  const monthOf = (iv) => iv.billing_month || String(iv.issued_date || iv.created_at || "").slice(0, 7);
  // Notes on a month, and months marked as no invoice due.
  const notes = new Map();
  const nr = await fetch(`${env.SUPABASE_URL}/rest/v1/invoice_month_notes?month=gte.${months[0]}&month=lte.${last}&select=row_kind,row_id,month,note,skip`, { headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}` } });
  const notesReady = nr.ok;
  if (nr.ok) (await nr.json()).forEach((x) => notes.set(`${x.row_kind}|${x.row_id}|${x.month}`, x));
  const cellsFor = (list, start, kind, id) => Object.fromEntries(months.map((ym) => {
    const n = notes.get(`${kind}|${id}|${ym}`);
    const extra = n ? { note: n.note || "", skip: !!n.skip } : {};
    const here = list.filter((iv) => monthOf(iv) === ym);
    // Before its first month, unless an invoice was raised for it anyway
    // (October's TPE hub, raised by hand on 10 Nov 2026).
    if (start && ym < start && !here.length) return [ym, { due: false, ...extra }];
    return [ym, {
      ...extra,
      due: !(n && n.skip),
      sent: here.some((iv) => iv.status === "sent" || iv.status === "paid"),
      paid: here.some((iv) => iv.status === "paid"),
      draft: here.some((iv) => iv.status === "draft"),
      numbers: here.map((iv) => `${iv.number || "draft"} (${iv.status})`),
      invs: here.map((iv) => ({ id: iv.id, number: iv.number || "", status: iv.status })),
    }];
  }));
  const rows = [];
  const stoppedRec = await smmStoppedLeads(env, recurring.map((r) => r.lead_id));
  recurring = recurring.filter((r) => !(r.lead_id && stoppedRec.has(r.lead_id)));
  for (const l of leads) {
    // Their monthly invoice's setup, so Raise makes it the same way, and an
    // invoice raised from it counts here even without the client on it (10 Nov 2026).
    const recRow = recurring.find((x) => x.lead_id === l.id && x.kind === "social");
    const mine = invs.filter((iv) => (iv.booking_source === "smm" && iv.booking_id === l.id) || (recRow && iv.recurring_id === recRow.id));
    rows.push({ kind: "social", id: l.id, client: l.business || l.full_name || "Client", contact: l.full_name || "", manager: l.social_media_manager || "",
      recurring_id: recRow ? recRow.id : null, payer: recRow ? (recRow.bill_to_name || "") : "", brand: !!l.inter_brand_invoice || /@newman\.uk\.com\b/i.test(String((recRow && (recRow.bill_to_email || recRow.match_email)) || "")),
      amount_pence: pounds(l.price), note: l.inter_brand_invoice ? "Billed to another brand" : "",
      cells: cellsFor(mine, l.start_date ? String(l.start_date).slice(0, 7) : null, "social", l.id) });
  }
  // The month's number for one that has one (the TPE hub's agents).
  const qtys = new Map();
  if (recurring.some((r) => r.quantity_label)) {
    const qr = await fetch(`${env.SUPABASE_URL}/rest/v1/recurring_quantities?month=gte.${ymAdd(months[0], -1)}&month=lte.${last}&select=recurring_id,month,qty`, { headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}` } });
    if (qr.ok) (await qr.json()).forEach((x) => qtys.set(`${x.recurring_id}|${x.month}`, Number(x.qty)));
  }
  for (const r of recurring) {
    const want = String(r.match_email || "").toLowerCase().trim(), text = String(r.match_text || "").toLowerCase().trim();
    const mine = invs.filter((iv) => iv.recurring_id === r.id || (!iv.recurring_id && !iv.booking_id && String(iv.bill_to_email || "").toLowerCase().trim() === want
      && (!text || JSON.stringify([iv.line_items || [], iv.notes || ""]).toLowerCase().includes(text))));
    rows.push({ kind: "recurring", id: r.id, client: r.name, contact: r.contact_name || "", amount_pence: r.amount_pence ?? null,
      match_email: r.match_email, match_text: r.match_text || "", start_month: r.start_month || "",
      sub: r.kind === "social" ? "social" : "recurring", quantity_label: r.quantity_label || null, lead_id: r.lead_id || null,
      brand: /@newman\.uk\.com\b/i.test(String(r.bill_to_email || r.match_email || "")),
      quantities: Object.fromEntries([ymAdd(months[0], -1), ...months].filter((ym) => qtys.has(`${r.id}|${ym}`)).map((ym) => [ym, qtys.get(`${r.id}|${ym}`)])),
      // What the automatic invoicing needs (supabase/invoicing_automation.sql).
      auto: { auto_send: !!r.auto_send, day_of_month: r.day_of_month ?? null, frequency: r.frequency || "monthly", end_month: r.end_month || "", bill_to_name: r.bill_to_name || "", bill_to_email: r.bill_to_email || "", cc_email: r.cc_email || "", bill_to_address: r.bill_to_address || "", line: (Array.isArray(r.line_items) && r.line_items[0] && r.line_items[0].description) || "", terms_days: r.terms_days ?? null },
      // It starts from its first month, or its earliest invoice if that's sooner:
      // invoices moved over from an older row count (Dani, 10 Nov 2026).
      cells: cellsFor(mine, [r.start_month, ...mine.map(monthOf)].filter(Boolean).sort()[0] || null, "recurring", r.id) });
  }
  // Videography: where each shoot's invoice is. The rule: invoiced two days
  // before the shoot; past that and not sent, we're late (Danielle, 30 Sep
  // 2026). Shown: this month's shoots (and the first two days of next month,
  // whose invoice is due this month), plus any earlier shoot still unsettled.
  // Settled past shoots stay off, or the page fills with done work.
  // The chosen month (the window's last): a past month shows that month's
  // shoots, settled or not; this month works as above (Dani, 10 Nov 2026).
  const todayYm = londonToday().ym;
  const nowYm = last < todayYm ? last : todayYm, pastView = nowYm < todayYm;
  const nextStart = `${ymAdd(nowYm, 1)}-01`;
  const lookEnd = new Date(Date.parse(nextStart + "T00:00:00Z") + 2 * 864e5).toISOString().slice(0, 10);
  const bookings = await readAll("videography_bookings",
    `shoot_date=gte.${ymAdd(nowYm, -12)}-01T00:00:00&shoot_date=lt.${lookEnd}T00:00:00&kind=eq.booking&stage=neq.cancelled&select=*&order=shoot_date.asc,id.asc`);
  const vInv = [];
  const bIds = bookings.map((b) => b.id);
  for (let i = 0; i < bIds.length; i += 80) {
    vInv.push(...(await readAll("invoices", `booking_source=eq.videography&booking_id=in.(${bIds.slice(i, i + 80).join(",")})&status=neq.void&select=id,booking_id,number,status,total_pence,due_date,paid_date&order=created_at.asc,id.asc`)));
  }
  // Drafts with someone to approve them (Jack), so they don't read as yours to do.
  const draftIds = vInv.filter((iv) => iv.status === "draft").map((iv) => iv.id);
  const withJack = new Set();
  for (let i = 0; i < draftIds.length; i += 80) ((await readAll("invoice_approvals", `status=eq.pending&invoice_id=in.(${draftIds.slice(i, i + 80).join(",")})&select=invoice_id`)) || []).forEach((x) => withJack.add(x.invoice_id));
  const todayIso = new Date().toISOString().slice(0, 10);
  const shoots = bookings.map((b) => {
    const mine = vInv.filter((iv) => iv.booking_id === b.id);
    const sent = mine.filter((iv) => iv.status === "sent" || iv.status === "paid");
    const shootDay = String(b.shoot_date || "").slice(0, 10);
    const dueBy = shootDay ? new Date(Date.parse(shootDay + "T12:00:00Z") - 2 * 864e5).toISOString().slice(0, 10) : null;
    let status;
    if (b.payment_route === "smm_package") status = "package";
    else if (b.paid_at || mine.some((iv) => iv.status === "paid")) status = "paid";
    else if (sent.length) status = sent.some((iv) => iv.due_date && iv.due_date < todayIso) ? "payment_overdue" : "sent";
    else if (mine.some((iv) => iv.status === "draft" && withJack.has(iv.id))) status = "with_jack";
    else status = dueBy && todayIso >= dueBy ? "late" : "not_due";
    const brand = b.payment_route === "brand_invoice" || b.payment_route === "brand_invoice_teg";
    return {
      id: b.id, client: b.client_name || "Client", company: b.client_company || b.company || "", service: b.service || "",
      shoot_date: b.shoot_date, due_by: dueBy, status, draft: mine.some((iv) => iv.status === "draft"),
      amount_pence: sent[0]?.total_pence ?? mine[0]?.total_pence ?? b.total_pence ?? null,
      numbers: mine.map((iv) => `${iv.number || "draft"} (${iv.status})`), billed_to: brand ? "Brand" : "",
      earlier: shootDay.slice(0, 7) < nowYm,
    };
  // Shoots covered by a social package never need an invoice, so they're left
  // off altogether (Danielle, 30 Sep 2026).
  }).filter((x) => x.status !== "package" && (pastView ? String(x.shoot_date || "").slice(0, 7) === nowYm : (!x.earlier || x.status !== "paid")));
  return { months, rows, shoots, recurringReady, notesReady, today: londonToday().ym, warnings, found: { social: leads.length, invoices: invs.length, shoots: shoots.length } };
}

// Every morning: a shoot whose invoice should have gone two days before it and
// hasn't. One bell per shoot, the first morning it's late (Danielle, 30 Sep
// 2026). Looks back a month so a miss isn't lost, and ahead only as far as
// two days, which is when an invoice becomes due.
async function runLateVideoInvoiceCheck(env) {
  const day = (ms) => new Date(ms).toISOString().slice(0, 10);
  const now = Date.now();
  const bookings = (await sbGetAll(env, "videography_bookings",
    `shoot_date=gte.${day(now - 30 * 864e5)}T00:00:00&shoot_date=lt.${day(now + 3 * 864e5)}T00:00:00&kind=eq.booking&stage=neq.cancelled&select=*&order=shoot_date.asc,id.asc`)) || [];
  const today = day(now);
  for (const b of bookings) {
    if (b.payment_route === "smm_package" || b.paid_at) continue;
    const shootDay = String(b.shoot_date || "").slice(0, 10);
    if (!shootDay) continue;
    const dueBy = day(Date.parse(shootDay + "T12:00:00Z") - 2 * 864e5);
    if (today < dueBy) continue;
    const invs = (await sbGet(env, "invoices", `booking_source=eq.videography&booking_id=eq.${encodeURIComponent(b.id)}&status=in.(sent,paid)&select=id&limit=1`)) || [];
    if (invs.length) continue;
    const when = new Date(shootDay + "T12:00:00Z").toLocaleDateString("en-GB", { weekday: "short", day: "numeric", month: "short" });
    await notifyAdmins(env, {
      area: "money", event: "video_invoice_late",
      title: `Invoice late: ${b.client_name || "a shoot"}`,
      body: `Shoot ${when}${b.service ? ` (${b.service})` : ""}. It should have been invoiced by two days before, and nothing has gone out yet.`,
      href: `/admin/videography?booking=${encodeURIComponent(b.id)}`,
      key: `video-invoice-late:${b.id}`,
    });
  }
}

// On the 14th and 21st, 08:00: anything due this month and not sent yet.
async function runMonthlyInvoiceCheck(env) {
  const { ym, day } = londonToday();
  if (day !== 14 && day !== 21) return;
  const { rows } = await monthlyInvoiceChecklist(env, ym, 1);
  const missing = rows.filter((r) => r.cells[ym] && r.cells[ym].due && !r.cells[ym].sent);
  if (!missing.length) return;
  const monthName = new Date(`${ym}-15T12:00:00Z`).toLocaleDateString("en-GB", { month: "long" });
  const names = missing.map((r) => r.client + (r.cells[ym].draft ? " (draft not sent)" : ""));
  await notifyAdmins(env, {
    area: "money", event: "invoices_not_sent",
    title: `${missing.length} ${missing.length === 1 ? "invoice hasn't" : "invoices haven't"} gone out for ${monthName}`,
    body: names.slice(0, 8).join(", ") + (names.length > 8 ? `, and ${names.length - 8} more` : ""),
    href: "/admin/invoicing?tab=monthly",
    key: `invoices-not-sent:${ym}:${day}`,
  });
}

async function runInvoicePrompt(env) {
  // Automatic invoicing in live mode drafts these and asks Jack itself, so
  // the "invoices to raise" list would only repeat it.
  try { const st0 = (await sbGet(env, "invoice_settings", "id=eq.1&select=automation_mode"))?.[0]; if (st0 && st0.automation_mode === "live") return; } catch (_) {}
  const inTwoDays = new Date();
  inTwoDays.setDate(inTwoDays.getDate() + 2);
  const day = inTwoDays.toISOString().slice(0, 10);

  const shoots = (await sbGet(env, "videography_bookings",
    `shoot_date=gte.${day}T00:00:00&shoot_date=lte.${day}T23:59:59`
    + `&stage=neq.cancelled&invoice_prompt_sent_at=is.null&kind=eq.booking&select=*`)) || [];
  if (!shoots.length) return;

  const needing = [];
  for (const bk of shoots) {
    const invs = (await sbGet(env, "invoices",
      `booking_id=eq.${encodeURIComponent(bk.id)}&select=id,status`)) || [];
    // A voided invoice is not an invoice. If the only one was cancelled, this
    // shoot still needs billing.
    if (invs.some((iv) => iv.status !== "void")) continue;
    needing.push(bk);
  }
  if (!needing.length) return;

  const team = [...new Set([env.ACCOUNTS_NOTIFY, env.JACK_NOTIFY || env.JACK_UPN]
    .flatMap((v) => String(v || "").split(","))
    .map((v) => v.trim()).filter(Boolean))];
  if (!team.length) return;

  const esc = (v) => String(v ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  const rowsHtml = needing.map((bk) => {
    const brand = bk.payment_route === "brand_invoice" || bk.payment_route === "brand_invoice_teg";
    // Only an F&C invoice needs the office to confirm the fee first - TEG has
    // no such step, so this must never fire for it.
    const blocked = bk.payment_route === "brand_invoice" && !bk.brand_fee_confirmed;
    const where = (bk.property_address || bk.location || "").replace(/\s*\n\s*/g, ", ").trim();
    return `<tr>
      <td style="padding:7px 12px 7px 0;font-size:12px">${esc(bk.client_name || "-")}</td>
      <td style="padding:7px 12px 7px 0;font-size:12px">${esc(bk.service || "-")}${where ? `<br><span style="color:#8a8796">${esc(where)}</span>` : ""}</td>
      <td style="padding:7px 12px 7px 0;font-size:12px">${brand ? "Brand" : "Client"}</td>
      <td style="padding:7px 0;font-size:12px">${bk.total_pence != null ? esc(gbpW(bk.total_pence)) : "-"}${
        blocked ? `<br><span style="color:#8a5a2b">Fee not confirmed yet</span>` : ""}</td>
    </tr>`;
  }).join("");

  const niceDay = inTwoDays.toLocaleDateString("en-GB", { weekday: "long", day: "numeric", month: "long" });
  const sent = await sendEmail(env, {
    to: team,
    subject: `Invoices to raise — ${needing.length} shoot${needing.length === 1 ? "" : "s"} on ${niceDay}`,
    html: await wrapInBrandedBase(env, `<div style="${EM_WRAP}">
      <p style="${EM_P}">These shoots are on <strong>${esc(niceDay)}</strong> and haven't been invoiced yet.</p>
      <table style="border-collapse:collapse;margin:0 0 14px">
        <tr>
          <th style="text-align:left;padding:0 12px 6px 0;font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:#8a8796">Client</th>
          <th style="text-align:left;padding:0 12px 6px 0;font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:#8a8796">Shoot</th>
          <th style="text-align:left;padding:0 12px 6px 0;font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:#8a8796">Billed to</th>
          <th style="text-align:left;padding:0 0 6px;font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:#8a8796">Amount</th>
        </tr>
        ${rowsHtml}
      </table>
      <p style="${EM_P}">Raise each from its booking in the admin centre - that links the invoice to the shoot, which is what lets payment release the client's PIN on its own.</p>
      <p style="${EM_SMALL}">Anything marked "fee not confirmed yet" is a Fine &amp; Country shoot where the office hasn't confirmed they hold the marketing fee. That has to be settled before the invoice can go.</p>
    </div>`),
  });
  if (!sent.ok) return;

  const stamp = new Date().toISOString();
  for (const bk of needing) {
    await sbPatch(env, "videography_bookings", `id=eq.${encodeURIComponent(bk.id)}`, { invoice_prompt_sent_at: stamp });
  }
}

/* ---- Stalled shoots -------------------------------------------------------
   A shoot left in one stage too long looks exactly like one that moved
   yesterday, so nothing surfaces it. This does.

   Thresholds are per stage because "too long" means different things: a day in
   Shoot day is normal, a fortnight in Editing is not. They are deliberately
   generous - an alert that fires early is one people learn to ignore.

   Reported once when it stalls, then weekly while it stays stuck. Recording
   which STAGE was alerted means a shoot that moves on and stalls somewhere
   else is reported afresh rather than staying quiet.
--------------------------------------------------------------------------- */
const STALL_DAYS = {
  // Only the stages where a shoot genuinely sits waiting on us. Booked,
  // Invoiced and Shoot day all move themselves - on the shoot date, and again
  // the morning after - so a shoot cannot quietly rot in any of them.
  editing: 10,       // 1.5 days editing + the amendments buffer, generously
  gallery_ready: 5,  // gallery built but never sent
  sent: 10,          // with the client, still unpaid or edits unsettled
};

// A live funnel that's run out of people but still has dated emails to
// send: nobody will get them. That's how the Autumn Edit's email 3 was
// missed (Sep 2026: a broken check ended every journey after email 2, and
// the only sign was "0 in the funnel"). Checked every morning; one bell
// notification per email, so it isn't repeated daily.
async function runEmptyFunnelCheck(env) {
  try {
    const autos = (await sbGet(env, "automations", "status=eq.active&select=id,name,graph")) || [];
    const today = new Date().toLocaleDateString("en-CA", { timeZone: "Europe/London" }); // YYYY-MM-DD
    for (const a of autos) {
      const nodes = ((a.graph || {}).nodes) || [];
      const sends = nodes.filter((n) => n.type === "send_email" && n.config && /^\d{4}-\d{2}-\d{2}$/.test(String(n.config.send_on || "")))
        .sort((x, y) => String(x.config.send_on).localeCompare(String(y.config.send_on)));
      const upcoming = sends.filter((n) => n.config.send_on >= today);
      if (!upcoming.length) continue;
      const live = (await sbGet(env, "automation_enrollments", `automation_id=eq.${encodeURIComponent(a.id)}&status=in.(active,waiting)&select=id&limit=1`)) || [];
      if (live.length) continue;
      const next = upcoming[0];
      const which = sends.indexOf(next) + 1;
      const when = new Date(`${next.config.send_on}T12:00:00`).toLocaleDateString("en-GB", { weekday: "short", day: "numeric", month: "short" });
      await notifyAdmins(env, {
        area: "problem", event: "funnel_empty",
        title: `${a.name}: nobody left for email ${which}`,
        body: `The funnel is live but has nobody in it, so email ${which} on ${when}${next.config.send_at ? ` at ${next.config.send_at}` : ""} won't go to anyone. Check what ended everyone's journey.`,
        href: `/admin/automations/edit?id=${a.id}`,
        key: `funnel_empty:${a.id}:${next.id}`,
        meta: { automation_id: a.id, node_id: next.id },
      });
    }
  } catch (e) { console.error("runEmptyFunnelCheck", String((e && e.message) || e).slice(0, 200)); }
}

async function runStallCheck(env) {
  const now = Date.now();
  const days = (ms) => Math.floor((now - ms) / 86400000);
  const rows = (await sbGet(env, "videography_bookings",
    `stage=in.(editing,gallery_ready,sent)&select=*`)) || [];

  const stalled = [];
  for (const bk of rows) {
    const limit = STALL_DAYS[bk.stage];
    if (!limit) continue;
    // updated_at is when the row last changed, which for a stage move is the
    // move itself - so this measures time sitting in the current stage.
    const since = Date.parse(bk.updated_at || bk.created_at || "");
    if (!since) continue;
    const stuckFor = days(since);
    if (stuckFor < limit) continue;

    // Once per stall, then weekly.
    const alerted = bk.stalled_alerted_at ? Date.parse(bk.stalled_alerted_at) : 0;
    const sameStage = bk.stalled_alerted_stage === bk.stage;
    if (sameStage && alerted && days(alerted) < 7) continue;

    stalled.push({ bk, stuckFor });
  }
  if (!stalled.length) return;

  const team = [...new Set([env.ACCOUNTS_NOTIFY, env.JACK_NOTIFY || env.JACK_UPN]
    .flatMap((v) => String(v || "").split(","))
    .map((v) => v.trim()).filter(Boolean))];
  if (!team.length) return;

  const esc = (v) => String(v ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  const STAGE_NAME = { editing: "Editing", gallery_ready: "Gallery ready", sent: "Sent" };

  const rowsHtml = stalled.map(({ bk, stuckFor }) => `
    <tr>
      <td style="padding:7px 12px 7px 0;font-size:12px">${esc(bk.client_name || "-")}</td>
      <td style="padding:7px 12px 7px 0;font-size:12px">${esc(bk.service || "-")}</td>
      <td style="padding:7px 12px 7px 0;font-size:12px"><strong>${esc(STAGE_NAME[bk.stage] || bk.stage)}</strong></td>
      <td style="padding:7px 0;font-size:12px">${stuckFor} days</td>
    </tr>`).join("");

  const sent = await sendEmail(env, {
    to: team,
    subject: `${stalled.length} videography shoot${stalled.length === 1 ? "" : "s"} sitting still`,
    html: await wrapInBrandedBase(env, `<div style="${EM_WRAP}">
      <p style="${EM_P}">These shoots haven't moved in a while. Most likely the work has happened and the system hasn't been told - worth a quick check, and a note on anything that is genuinely held up.</p>
      <table style="border-collapse:collapse;margin:0 0 14px">
        <tr>
          <th style="text-align:left;padding:0 12px 6px 0;font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:#8a8796">Client</th>
          <th style="text-align:left;padding:0 12px 6px 0;font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:#8a8796">Service</th>
          <th style="text-align:left;padding:0 12px 6px 0;font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:#8a8796">Stuck at</th>
          <th style="text-align:left;padding:0 0 6px;font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:#8a8796">For</th>
        </tr>
        ${rowsHtml}
      </table>
      <p style="${EM_SMALL}">You'll get this once when a shoot stalls, then weekly while it stays put. Moving it on stops it.</p>
    </div>`),
  });
  if (!sent.ok) return;

  const stamp = new Date().toISOString();
  for (const { bk } of stalled) {
    await sbPatch(env, "videography_bookings", `id=eq.${encodeURIComponent(bk.id)}`,
      { stalled_alerted_at: stamp, stalled_alerted_stage: bk.stage });
  }
}

/* ---- Invoice chasing ------------------------------------------------------
   Two emails on the same daily run:

     on the due date        -> a reminder to the client
     the day after          -> an alert to Danielle and Jack, who chase it
                               however the situation deserves

   Deliberately keyed on the INVOICE rather than the booking, so social media
   management invoices are covered by the same code rather than a second copy
   of it that drifts.

   Direct Debit invoices are skipped entirely. Those are reminders to our own
   accounts team about money that collects itself; chasing the client for it
   would be worse than not chasing at all.
--------------------------------------------------------------------------- */
/* Every chaser leaves a trace in two places: the contact's email history, and -
   when the invoice belongs to a shoot - the booking's own record, so the
   invoice panel can show what was sent and when without anyone going hunting
   through a mailbox. An automatic email nobody can see having been sent is
   indistinguishable from one that never went. */
async function logInvoiceChase(env, inv, subject, to, internal) {
  try {
    await logEmailEvent(env, {
      email: to, event: "sent", provider: "microsoft", subject,
      detail: internal ? `Overdue alert for invoice ${inv.number}` : `Due-date reminder for invoice ${inv.number}`,
    });
  } catch (_) {}
  if (!inv.booking_id) return;
  try {
    await logBookingMessage(env, {
      booking_id: inv.booking_id,
      booking_source: inv.booking_source || "videography",
      client_email: internal ? null : inv.bill_to_email,
      // Internal alerts are notes, not correspondence - a client must never see
      // us discussing chasing them.
      channel: internal ? "note" : "email",
      kind: internal ? "invoice_overdue_alert" : "invoice_chase",
      subject,
      body: internal
        ? `Overdue alert sent to ${to}.`
        : `Due-date reminder sent to ${to}.`,
      is_automated: true, created_by: "system",
    });
  } catch (_) {}
}

async function runInvoiceChasers(env) {
  const iso = (d) => d.toISOString().slice(0, 10);
  const today = new Date();
  const yesterday = new Date(today); yesterday.setDate(yesterday.getDate() - 1);
  const esc = (v) => String(v ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  const st = (await sbGet(env, "invoice_settings", "id=eq.1&select=*"))?.[0] || {};
  const niceDate = (d) => new Date(d + "T12:00:00").toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" });

  // ---- 1. Due today: remind the client -----------------------------------
  const dueToday = (await sbGet(env, "invoices",
    `status=eq.sent&due_date=eq.${iso(today)}&due_reminder_sent_at=is.null&select=*`)) || [];

  for (const inv of dueToday) {
    if (inv.payment_method === "direct_debit") continue;
    if (!inv.bill_to_email) continue;

    let payUrl = null;
    if (inv.pay_by_card && env.STRIPE_SECRET_KEY) payUrl = await invoicePayUrl(env, inv.id);
    let attachments;
    try {
      const obj = await env.BUCKET.get(`invoices/${inv.number}.pdf`);
      if (obj) attachments = [{ filename: `Invoice-${inv.number}.pdf`, content: bufToBase64(await obj.arrayBuffer()), contentType: "application/pdf" }];
    } catch (_) {}

    // Wording: src/lib/invoice-email.js (email 8 in Danielle's doc).
    const remCtx = await invoiceEmailCtx(env, inv);
    const rem = invoiceReminderEmail(inv, remCtx);
    const mail = invoiceMailTo(inv.bill_to_email, null);
    const sent = await sendEmail(env, {
      to: mail.to,
      subject: rem.subject,
      attachments,
      html: await wrapInBrandedBase(env, invoiceEmailHtml(st, inv, rem.body, payUrl, null, { noStripeLine: true, portalUrl: await invoicePortalUrl(env, inv, remCtx) })),
    });
    if (!sent.ok) continue;
    await sbPatch(env, "invoices", `id=eq.${encodeURIComponent(inv.id)}`, { due_reminder_sent_at: new Date().toISOString() });
    await logInvoiceChase(env, inv, `Invoice ${inv.number} is due today.`, inv.bill_to_email, false);
  }

  // ---- 2. A day past due: tell Danielle and Jack --------------------------
  const overdue = (await sbGet(env, "invoices",
    `status=eq.sent&due_date=eq.${iso(yesterday)}&overdue_alerted_at=is.null&select=*`)) || [];

  const team = [...new Set([env.ACCOUNTS_NOTIFY || st.accounts_cc_email, env.JACK_NOTIFY || env.JACK_UPN]
    .flatMap((v) => String(v || "").split(","))
    .map((v) => v.trim())
    .filter(Boolean))];

  for (const inv of overdue) {
    if (inv.payment_method === "direct_debit") continue;
    if (!team.length) break;

    const sent = await sendEmail(env, {
      to: team,
      subject: `Overdue: invoice ${inv.number} - ${inv.bill_to_name || "client"}`,
      html: await wrapInBrandedBase(env, `<div style="${EM_WRAP}">
        <p style="${EM_P}">Invoice <strong>${esc(inv.number)}</strong> passed its due date yesterday and is still unpaid.</p>
        <p style="${EM_QUOTE}">Billed to: ${esc(inv.bill_to_name || "-")}<br>Amount: ${esc(gbpW(inv.total_pence))}<br>Due: ${esc(niceDate(inv.due_date))}<br>Sent to: ${esc(noAutoLink(inv.bill_to_email || "-"))}</p>
        <p style="${EM_P}">The client had a reminder on the due date. Worth deciding how to chase this one.</p>
        <p style="${EM_SMALL}">If it has been paid and we simply haven't recorded it, mark it paid in the admin centre - that releases the client's PIN and stops any further chasers.</p>
      </div>`),
    });
    if (!sent.ok) continue;
    await sbPatch(env, "invoices", `id=eq.${encodeURIComponent(inv.id)}`, { overdue_alerted_at: new Date().toISOString() });
    await logInvoiceChase(env, inv, `Overdue: invoice ${inv.number}`, team.join(", "), true);
  }
}

/* ---- Daily videography chasers ------------------------------------------
   Two jobs that ride the existing 08:00 cron, because both are "look for rows
   matching a date, send once, stamp a column so it never repeats".

   Everything else in this process happens because a person pressed something.
   These two cannot: a reminder that arrives when someone remembers is not a
   reminder, and a gallery that expires without warning is just a gallery that
   disappeared.
--------------------------------------------------------------------------- */
// "Hi ," is worse than no greeting, and a client whose name we only hold as a
// company should not be addressed as that company.
function firstName(full) {
  const first = String(full || "").trim().split(/\s+/)[0];
  return first || "there";
}

// Most email clients auto-detect anything shaped like an email address and
// turn it into their own mailto: link, styled however that client styles
// links - regardless of the HTML we actually sent. That's wrong wherever
// we're just telling someone what to type (into Pixieset, say), not asking
// them to click. A zero-width space right after the @ breaks the pattern
// match without changing how the address looks, copies, or reads to a
// screen reader. Never use this on an address that's meant to be a real,
// clickable mailto: link.
function noAutoLink(v) {
  const s = String(v ?? "");
  const at = s.indexOf("@");
  return at === -1 ? s : s.slice(0, at + 1) + "​" + s.slice(at + 1);
}

async function runVideographyChasers(env) {
  const today = new Date();
  const iso = (d) => d.toISOString().slice(0, 10);
  const esc = (v) => String(v ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

  // ---- 1. Payment reminder, the day after the shoot ----------------------
  // Deliberately a nudge: it lands on day three of a ten-day term, so they are
  // not late and should not be told they are.
  const yesterday = new Date(today); yesterday.setDate(yesterday.getDate() - 1);
  const due = (await sbGet(env, "videography_bookings",
    `shoot_date=gte.${iso(yesterday)}T00:00:00&shoot_date=lte.${iso(yesterday)}T23:59:59`
    // A package shoot has no invoice to chase — reminding those clients to pay
    // for something their package already covers is worse than staying quiet.
    + `&paid_at=is.null&payment_route=neq.smm_package`
    + `&reminder_sent_at=is.null&stage=neq.cancelled&select=*`)) || [];

  for (const bk of due) {
    const to = bk.client_email;
    if (!to) continue;
    const invs = (await sbGet(env, "invoices",
      `booking_id=eq.${encodeURIComponent(bk.id)}&select=id,number,status,pay_by_card,total_pence&order=created_at.desc`)) || [];
    const live = invs.find((iv) => iv.status !== "void" && iv.status !== "paid");
    if (!live) continue;   // nothing outstanding to chase

    let attachments, payUrl = null;
    if (live.pay_by_card && env.STRIPE_SECRET_KEY) payUrl = await invoicePayUrl(env, live.id);
    try {
      const obj = await env.BUCKET.get(`invoices/${live.number}.pdf`);
      if (obj) attachments = [{ filename: `Invoice-${live.number}.pdf`, content: bufToBase64(await obj.arrayBuffer()), contentType: "application/pdf" }];
    } catch (_) {}

    const sent = await sendEmail(env, {
      to,
      subject: "Great to see you yesterday - here's what happens next",
      attachments,
      html: await wrapInBrandedBase(env, `<div style="${EM_WRAP}">
        <p style="${EM_P}">Hi ${esc(firstName(bk.client_name))},</p>
        <p style="${EM_P}">It was great shooting with you yesterday. We hope you enjoyed the session!</p>
        <p style="${EM_P}">Now that your shoot is wrapped, Jack will get to work on your edits. This usually takes a few days, and as soon as everything is ready, we'll send you a link to your gallery where you can view your finished content.</p>
        <p style="${EM_P}">In the meantime, a quick reminder that invoice ${esc(live.number)} for ${esc(gbpW(live.total_pence))} is awaiting payment. We've attached another copy here so you've got it to hand.</p>
        <p style="${EM_P}">You can pay by card using the link below, or by bank transfer using the details on your invoice.</p>
        ${payUrl ? `<p style="${EM_P}"><a href="${esc(payUrl)}" style="${EM_BTN}">Pay invoice</a></p>` : ""}
        <p style="${EM_P}">You'll still be able to view your gallery when your edits are ready, but downloads will unlock once payment has been received.</p>
        <p style="${EM_P}">We'll be back in touch as soon as your content is ready. We can't wait for you to see it!</p>
        <p style="${EM_P}">The TMKE Team</p>
      </div>`),
    });
    if (!sent.ok) continue;

    await sbPatch(env, "videography_bookings", `id=eq.${encodeURIComponent(bk.id)}`, { reminder_sent_at: new Date().toISOString() });
    await logBookingMessage(env, {
      booking_id: bk.id, booking_source: "videography",
      account_user_id: bk.account_user_id, client_email: to,
      channel: "email", kind: "payment_reminder", subject: "Great to see you yesterday - here's what happens next",
      body: "Day-after-shoot reminder sent with the invoice.", is_automated: true, created_by: "system",
    });
  }

  // ---- 2. Gallery expiry warning, a week out -----------------------------
  const weekOut = new Date(today); weekOut.setDate(weekOut.getDate() + 7);
  const expiring = (await sbGet(env, "videography_bookings",
    `gallery_expires_on=eq.${iso(weekOut)}&expiry_warned_at=is.null&select=*`)) || [];

  for (const bk of expiring) {
    const to = bk.gallery_email || bk.client_email;
    if (!to || !bk.gallery_url) continue;
    const when = new Date(bk.gallery_expires_on + "T12:00:00")
      .toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" });

    const shotOn = bk.shoot_date
      ? new Date(bk.shoot_date).toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" })
      : "";
    const sent = await sendEmail(env, {
      to,
      subject: "Your gallery expires in one week",
      html: await wrapInBrandedBase(env, `<div style="${EM_WRAP}">
        <p style="${EM_P}">Hi ${esc(firstName(bk.client_name))},</p>
        <p style="${EM_P}">Just a quick heads up that the gallery from your ${esc((bk.service || "shoot").toLowerCase())}${shotOn ? ` on ${esc(shotOn)}` : ""} is due to expire on ${esc(when)}.</p>
        <p style="${EM_P}"><a href="${esc(bk.gallery_url)}" style="${EM_BTN}">Open your gallery</a></p>
        <p style="${EM_P}">You can also find the gallery by heading to Previous Bookings in TMKE Studio.</p>
        <p style="${EM_P}">Once the gallery expires, your content will no longer be available to view or download, so we recommend having a quick check that you've got everything you need.</p>
        <p style="${EM_P}">The TMKE Team</p>
      </div>`),
    });
    if (!sent.ok) continue;

    await sbPatch(env, "videography_bookings", `id=eq.${encodeURIComponent(bk.id)}`, { expiry_warned_at: new Date().toISOString() });
    await logBookingMessage(env, {
      booking_id: bk.id, booking_source: "videography",
      account_user_id: bk.account_user_id, client_email: to,
      channel: "email", kind: "gallery_expiring", subject: "Your gallery expires in one week",
      body: `Expiry warning sent - gallery closes ${bk.gallery_expires_on}.`, is_automated: true, created_by: "system",
    });
  }
}

// Off unless it's been turned on, including before its SQL has run.
async function morningJobsOn(env) {
  const row = (await sbGet(env, "invoice_settings", "id=eq.1&select=morning_jobs_on"))?.[0];
  return !!(row && row.morning_jobs_on === true);
}

/* Top level on purpose: Revenue's route, the portal's and the morning run all
   call these, and a function declared further down this file sits inside
   fetch()'s second try block, where nothing else can see it (6 Nov 2026). */
/* ---- The invoice book (Dani, 5-6 Nov 2026) --------------------------------
   Every invoice with what the Invoicing page and the accounts portal need to
   know about it: what kind of work it was, who the work was for, whether it's
   inter-brand and which sector its money goes under. None of that's on the
   invoice row, so it's worked out here, once, for both pages. */
const BOOK_COLS = "id,number,booking_id,booking_source,recurring_id,billing_month,bill_to_name,bill_to_email,client_name,line_items,subtotal_pence,vat_pence,total_pence,status,issued_date,due_date,paid_date,payment_method,pay_by_card,sent_at,sent_to,release_on_payment,accounts_note,accounts_marked_at,accounts_reminders,sector,created_at";
function chunks(a, n) { const out = []; for (let i = 0; i < a.length; i += n) out.push(a.slice(i, i + n)); return out; }
async function revenueOverrides(env) {
  const rows = await sbGet(env, "revenue_rules", "select=source,sector");
  return Object.fromEntries((rows || []).map((r) => [r.source, r.sector]));
}
async function invoiceContext(env, invoices) {
  const ids = (f) => [...new Set(invoices.map(f).filter(Boolean))];
  const read = async (table, list, select) => {
    const out = {};
    for (const part of chunks(list, 80)) {
      const rows = await sbGet(env, table, `id=in.(${part.join(",")})&select=${select}`);
      for (const r of rows || []) out[r.id] = r;
    }
    return out;
  };
  const rec = await read("recurring_invoices", ids((v) => v.recurring_id), "id,name,kind,lead_id,quantity_label");
  const bookings = await read("videography_bookings", ids((v) => ((v.booking_source || "videography") === "videography" ? v.booking_id : null)), "*");
  const leadIds = ids((v) => (v.booking_source === "smm" ? v.booking_id : null)).concat(Object.values(rec).map((r) => r.lead_id).filter(Boolean));
  const leads = await read("smm_leads", [...new Set(leadIds)], "id,business,full_name,first_name,last_name,inter_brand_invoice");
  return { rec, bookings, leads, overrides: await revenueOverrides(env) };
}
function invoiceBookRow(v, ctx) {
  const r = v.recurring_id ? ctx.rec[v.recurring_id] : null;
  const bk = (v.booking_source || "videography") === "videography" && v.booking_id ? ctx.bookings[v.booking_id] : null;
  const lead = (v.booking_source === "smm" && v.booking_id ? ctx.leads[v.booking_id] : null) || (r && r.lead_id ? ctx.leads[r.lead_id] : null);
  const leadName = lead ? (lead.business || lead.full_name || `${lead.first_name || ""} ${lead.last_name || ""}`.trim()) : "";
  // Social media monthly, a shoot, a brand's regular invoice, or a one-off.
  // Raised from a social media client's file, it's social media, monthly or
  // not; a one-off is one raised on Invoicing for no one's file (Dani, 10 Nov).
  const kind = bk ? "video" : (r && r.kind === "social") ? "social" : r ? "agent" : lead ? "social" : "oneoff";
  const interBrand = !!(bk && (bk.payment_route === "brand_invoice" || bk.payment_route === "brand_invoice_teg"))
    || !!(lead && lead.inter_brand_invoice)
    || kind === "agent"
    || /@newman\.uk\.com\b/i.test(String(v.bill_to_email || ""));
  const rule = bk ? ruleForService(bk.service) : r && r.kind === "social" ? "social-monthly" : r && r.quantity_label ? "agent-hub" : r ? "agent-assets" : lead ? "social-other" : "other";
  const sector = v.sector || sectorForRule(rule, ctx.overrides);
  const items = Array.isArray(v.line_items) ? v.line_items : [];
  const contentReady = !!(bk && v.status !== "paid" && ["gallery_ready", "sent"].includes(bk.stage) && !bk.paid_at && !bk.released_unpaid_at);
  return {
    id: v.id, number: v.number || "", status: v.status,
    kind, route: interBrand ? "internal" : "client", rule, sector, sector_chosen: !!v.sector,
    client: v.client_name || (bk && (bk.company || bk.client_company || bk.client_name)) || leadName || v.bill_to_name || "",
    what: String((items[0] && items[0].description) || "").trim(),
    lines: items.map((it) => ({ description: it.description || "", net_pence: (Number(it.unit_pence) || 0) * (Number(it.qty) || 1) })),
    payer: v.bill_to_name || "", email: v.bill_to_email || "",
    net_pence: Number(v.subtotal_pence) || 0, vat_pence: Number(v.vat_pence) || 0, total_pence: Number(v.total_pence) || 0,
    month: String(v.sent_at || v.issued_date || v.created_at || "").slice(0, 7),
    sent: v.status === "draft" ? "" : String(v.sent_at || v.issued_date || "").slice(0, 10),
    due: String(v.due_date || "").slice(0, 10),
    paid_on: String(v.paid_date || "").slice(0, 10), paid_how: v.accounts_marked_at ? "Accounts confirmed" : v.payment_method === "card" ? "Card" : v.payment_method === "direct_debit" ? "Direct debit" : v.status === "paid" ? "Marked paid" : "",
    method: v.payment_method || "", pay_by_card: !!v.pay_by_card,
    note: v.accounts_note || "", marked_at: v.accounts_marked_at || null,
    reminders: Array.isArray(v.accounts_reminders) ? v.accounts_reminders : [],
    release: !bk || bk.pin_released_at || bk.paid_at || bk.released_unpaid_at ? "" : bk.delivery_method === "portal" ? "Portal folder" : "Gallery PIN", content_ready: contentReady,
    booking_id: v.booking_id || null, booking_source: v.booking_source || null,
    sent_to: v.sent_to || "",
  };
}
// Null if the SQL hasn't run: the new columns are in the select.
async function invoiceBook(env, filter) {
  const rows = await sbGetAll(env, "invoices", `${filter}&select=${BOOK_COLS}&order=created_at.desc,id.asc`);
  if (!rows) return null;
  const ctx = await invoiceContext(env, rows);
  return rows.map((v) => invoiceBookRow(v, ctx));
}
// What accounts are asked about: sent and unpaid. Paid by card or direct debit
// never lands here, because we already know.
const PORTAL_FILTER = "status=eq.sent&or=(payment_method.is.null,payment_method.neq.direct_debit)";
async function accountsPortalRow(env) {
  return (await sbGet(env, "accounts_portal", "id=eq.1&select=*"))?.[0] || null;
}
async function accountsFromSession(env, request) {
  const auth = request.headers.get("Authorization") || "";
  const [token, exp, sig] = (auth.startsWith("Bearer ") ? auth.slice(7) : "").split(".");
  if (!token || !/^\d+$/.test(exp || "") || Number(exp) < Date.now() || !sig) return null;
  const p = await accountsPortalRow(env);
  if (!p || !p.enabled || p.token !== token) return null;
  const want = await portalSig(env, `accounts:${token}`, p.passcode, exp);
  return want && want === sig ? p : null;
}
// Who's copied in on an accounts email: the settings' list, plus whoever pressed
// send (or Danielle, for the automatic ones).
function accountsCc(env, p, me) { return [p.email_cc, me || invDanielle(env)].filter(Boolean).join(","); }
function accountsLink(env, p) { return `${invSite(env)}/accounts?c=${encodeURIComponent(p.token)}`; }

/* The month-end email: to Paula, short, and what to do. Plain table cells, so
   the split shows in Outlook with pictures off. */
async function accountsMonthEndMail(env, p) {
  const open = await invoiceBook(env, PORTAL_FILTER);
  if (!open) return null;
  const byM = {};
  for (const v of open) (byM[v.month] = byM[v.month] || []).push(v);
  const sum = (a) => a.reduce((t, v) => t + v.net_pence, 0);
  const ib = open.filter((v) => v.route === "internal"), cl = open.filter((v) => v.route !== "internal");
  const label = (ym) => invMonthLabel(ym);
  const cell = "padding:9px 10px;border-bottom:1px solid #eae5e1;font-size:14px;color:#2b2226;";
  const head = "padding:9px 10px;border-top:1px solid #c9bcb7;border-bottom:1px solid #c9bcb7;font-size:14px;font-weight:400;color:#7e6765;text-align:left;";
  const table = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:0 0 18px"><tr><th style="${head}">Month</th><th style="${head}text-align:right">Invoices</th><th style="${head}text-align:right">Net</th></tr>${Object.keys(byM).sort().map((k) => `<tr><td style="${cell}">${invEsc(label(k))}</td><td style="${cell}text-align:right">${byM[k].length}</td><td style="${cell}text-align:right">${gbpW(sum(byM[k]))}</td></tr>`).join("")}</table>`;
  const ibW = open.length ? Math.max(ib.length ? 8 : 0, Math.round(ib.length / open.length * 100)) : 50;
  const bar = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:separate;border-spacing:0;margin:0 0 10px"><tr>${ib.length ? `<td width="${ibW}%" height="14" bgcolor="#371e28" style="background:#371e28;font-size:0;line-height:0">&nbsp;</td>` : ""}${cl.length ? `<td width="${100 - (ib.length ? ibW : 0)}%" height="14" bgcolor="#c9bcb7" style="background:#c9bcb7;font-size:0;line-height:0">&nbsp;</td>` : ""}</tr></table>`;
  const key = (colour, n, words) => `<td width="50%" valign="top" style="padding:0 10px 0 0;font-size:14px;color:#7e6765"><span style="display:inline-block;width:10px;height:10px;background:${colour};margin-right:8px"></span><span style="font-size:22px;color:#2b2226">${n}</span> ${words}</td>`;
  const split = `${bar}<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 18px"><tr>${key("#371e28", ib.length, `Inter-brand, ${gbpW(sum(ib))}`)}${key("#c9bcb7", cl.length, `Waiting on client payment, ${gbpW(sum(cl))}`)}</tr></table>`;
  const link = accountsLink(env, p);
  const html = `<div style="${EM_WRAP}">
    <h1 style="${EM_H1}">Coming Up to Month End.</h1>
    <p style="${EM_P}">Hi all,</p>
    <p style="${EM_P}">It's coming up to month end, and these invoices are still outstanding.</p>
    ${table}${split}
    <p style="${EM_P}"><a href="${link}" style="color:#371e28;text-decoration:underline">Click here</a> to review all of our outstanding invoices, and please update them accordingly. Any problems, please let me know.</p>
    <p style="${EM_P}">Thank you,<br>Danielle</p>
  </div>`;
  return { html, subject: "Coming up to month end.", count: open.length, to: p.email_to, cc: p.email_cc || "" };
}

/* The first email to accounts (Dani, 6 Nov 2026): why the page exists, what it
   is, what to do, and the emails to expect, so the 20th doesn't come out of the
   blue. Pressed by hand; it doesn't switch the automatic emails on. */
function accountsFirstEmail(env, p) {
  const t = invToday(), ym = t.day <= 20 ? t.ym : ymAddMonth(t.ym), first = `20 ${invMonthLabel(ym).split(" ")[0]}`;
  const P = (x) => `<p style="${EM_P}">${x}</p>`, H = (x) => `<p style="${EM_P}margin-bottom:4px;"><strong>${x}</strong></p>`;
  const LI = (x) => `<li style="${EM_P}margin-bottom:6px;">${x}</li>`;
  const html = `<div style="${EM_WRAP}text-align:left;">
    <h1 style="${EM_H1}">One Place for Every Open Invoice.</h1>
    ${P("Hi all,")}
    ${P("I wanted to tell you about a change to how we confirm invoices have been paid, which will improve efficiency and reduce the number of chasers and chaser emails spamming your inbox.")}
    ${H("Why we're changing it")}
    ${P("At the moment, I email you at the end of each month to ask whether invoices have been paid. That means back and forth between people, which slows down confirming payment. Because, in some instances, we won't release a client's finished content until the invoice is confirmed paid, it can delay our delivery of work. So we've set up one place for accounts to see and answer everything.")}
    ${H("What the page is")}
    ${P("It's a private web page just for accounts, which you open with a link and a passcode. It lists every invoice still open, grouped by month, with the invoice number, client, who it's billed to, sent date, due date and net amount without VAT, and it shows whether an invoice is <strong>Overdue</strong>.")}
    ${P("Each invoice is labelled <strong>Inter-brand</strong> or <strong>External client</strong> and has a <strong>View</strong> button that opens it, so you won't need any attachments. The invoices themselves still come through as they do now.")}
    ${P("An unpaid invoice with the option to pay by card is still on the page. If the client pays by card, Stripe will update our system, so there's nothing for you to do. An invoice you've marked stays on the page with a green Paid or Settled box until everything in that month is closed, then the whole month drops off by itself.")}
    ${H("What you need to do")}
    ${P("You can open the page using the button below. Your passcode is in a separate email, sent straight after this one, and it doesn't matter whether you use capitals.")}
    <p style="${EM_P}margin-bottom:28px;"><a href="${accountsLink(env, p)}" style="${EM_BTN}">Open the accounts portal</a></p>
    ${P("Once you're in, here's what to do with each invoice. We see it on our side straight away:")}
    <ul style="margin:0 0 14px;padding:0 0 0 18px;">
      ${LI("<strong>External client invoices:</strong> Press <strong>Paid</strong> once the money has landed. Until then the invoice simply stays on the page, so there's nothing else to press.")}
      ${LI("<strong>Inter-brand invoices:</strong> Press <strong>Settled</strong> once it's been settled.")}
      ${LI("<strong>Notes:</strong> If there's a problem with an invoice, add a note with the note icon or message us. Both sides can see notes.")}
      ${LI("<strong>Mistakes:</strong> If you make a mistake, press <strong>Undo</strong>. It's there for as long as the invoice is on the page.")}
    </ul>
    ${P("<strong>Important:</strong> Please only mark an invoice once the money has arrived. Marking a videography invoice paid releases the client's content straight away, because their download PIN goes out automatically. That can't be taken back, even with <strong>Undo</strong>.")}
    ${H("Your month-end emails")}
    ${P("These replace my month-end chase. From now on, you'll get a short email on the 20th of each month, and a second on the 28th if anything's still open. It tells you how many invoices are outstanding and their net value by month, splits them into inter-brand and waiting on client payment, and links to the page. If everything's closed, you won't get one.")}
    ${P(`The first one will arrive on ${first}.`)}
    ${P("If you have any problems or questions, just let me know.")}
    ${P("Thank you,<br>Danielle")}
  </div>`;
  return { html, subject: `A new page for open invoices, and an email to expect on ${first}.`, to: p.email_to, cc: p.email_cc || "" };
}
// Goes straight after the first email, with no link in it (Dani, 6 Nov). This is
// the only email the passcode ever goes in.
function accountsPasscodeEmail(p) {
  const html = `<div style="${EM_WRAP}text-align:left;">
    <h1 style="${EM_H1}">Your Passcode for the Accounts Portal.</h1>
    <p style="${EM_P}">Hi all,</p>
    <p style="${EM_P}">Here's the passcode for the accounts portal, to use with the button in my last email:</p>
    <p style="${EM_P}font-size:22px;letter-spacing:.12em;"><strong>${invEsc(p.passcode)}</strong></p>
    <p style="${EM_P}">It doesn't matter whether you use capitals. Please keep it within the accounts team.</p>
    <p style="${EM_P}">Thank you,<br>Danielle</p>
  </div>`;
  return { html, subject: "Your passcode for the accounts portal." };
}
function ymAddMonth(ym) { const [y, m] = ym.split("-").map(Number); return new Date(Date.UTC(y, m, 1)).toISOString().slice(0, 7); }

// Goes by itself on the 20th, and again on the 28th if anything's still open.
async function runAccountsMonthEnd(env) {
  const t = invToday();
  if (t.day !== 20 && t.day !== 28) return;
  const p = await accountsPortalRow(env);
  if (!p || !p.enabled || !p.emails_on) return;
  const mail = await accountsMonthEndMail(env, p);
  if (!mail || !mail.count) return;
  if (!(await invLogOnce(env, `accounts-month-end:${t.ymd}`, `${mail.count} open`))) return;
  await sendEmail(env, { to: p.email_to, cc: accountsCc(env, p), subject: mail.subject, html: await wrapInBrandedBase(env, mail.html) });
}

export default {
  // Cron (see wrangler.toml [triggers]). The 07:00 & 08:00 daily runs send post
  // reminders (runReminders self-gates to 8am UK); every other (frequent) run
  // advances automations + chases any paid-but-no-password orders.
  async scheduled(event, env, ctx) {
    if (event && (event.cron === "0 7 * * *" || event.cron === "0 8 * * *")) {
      ctx.waitUntil(runReminders(env));
      ctx.waitUntil(runSmmLeavingDue(env));
      ctx.waitUntil(runDdMonthly(env));
      // Only on the 08:00 run, so the day-after reminder and the expiry warning
      // go out once a day rather than twice.
      // The switch (Dani, 6 Nov 2026): these didn't run for weeks because of a
      // scope mistake, so they stay off until she turns them on in Invoicing >
      // Settings > Automatic invoicing. Each catches its own failure, so one
      // going wrong can't stop the rest again.
      const jobsOn = await morningJobsOn(env);
      if (event.cron === "0 8 * * *") {
        ctx.waitUntil(runAccountsMonthEnd(env).catch(() => {}));
        if (jobsOn) {
          for (const job of [runVideographyChasers, runInvoiceChasers, runInvoiceAutomation, runStallCheck, runEmptyFunnelCheck, runInvoicePrompt, runMonthlyInvoiceCheck, runLateVideoInvoiceCheck, runMonthlyRosterCheck, runCommunityTopicDue, runZernioIdleCheck]) {
            ctx.waitUntil(Promise.resolve().then(() => job(env)).catch((e) => console.error("morning job", job.name, String((e && e.message) || e).slice(0, 200))));
          }
        }
      }
      // The TEG new-starter sheet, once a day at 8am UK (Dani, 4 Nov): new
      // rows into the funnel, booked dates and gallery links back to the
      // sheet, then the Studio Days blocked in Jack's calendar. Both daily
      // crons call in; only the one that lands on 8am UK runs it (07:00 UTC in
      // summer time, 08:00 UTC in winter). Bookings and reschedules write
      // their date to the sheet straight away; Automations' Sync button runs
      // it on demand.
      if (jobsOn && ukHourNow() === 8) ctx.waitUntil(runEditAutoClose(env).catch(() => {}).then(() => syncAgentSheet(env)).catch(() => {}).then(() => newStarterEnsureBlocks(env)).then(() => runPortalFolderNotices(env)));
    }
    else {
      ctx.waitUntil(runAutomationsTick(env));
      ctx.waitUntil(runSetupReminders(env));
      ctx.waitUntil(runMemberBroadcasts(env));
      ctx.waitUntil(runContactReviewAlerts(env));
      ctx.waitUntil(pollSmmInbox(env));
      let mins = 0; try { mins = new Date(event.scheduledTime).getUTCMinutes(); } catch (_) {}
      if (mins === 0) ctx.waitUntil(runAiCreditCheck(env));
      // A folder added to a portal that emails someone (the TEG new-starter portal).
      ctx.waitUntil(pinArchiveFolders(env).catch(() => {}).then(() => runStarterPortalAdds(env)).catch(() => {}).then(() => runSmmPortalFlags(env)).catch(() => {}).then(() => runPortalDeliveries(env)).catch(() => {}).then(() => runPortalFolderNotices(env)).catch(() => {}));
    }
  },

  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname.replace(/\/+$/, "");

    if (request.method === "OPTIONS") {
      return new Response(null, { status: 204, headers: corsHeaders(request, env) });
    }

    // Refresh the house style before anything can build an email. Cached for a
    // minute, so this is a no-op on all but the first request in that window.
    await loadEmailStyles(env);

    try {
      // ---- Hub notices: send what's due now (admin) --------------------------
      // The five-minute tick does this anyway; the admin calls it so "Send now"
      // and "Withdraw" happen straight away.
      // ---- Admin: video captions, step 1 - the words and when they're said --
      // (Dani, 3 Nov 2026.) The page sends the video's audio, small: 16kHz
      // mono WAV, a couple of MB a minute. Cloudflare's Whisper writes it
      // down with a time for every word; `prompt` primes it with names it
      // would otherwise mishear (Porsche, Fine & Country). Nothing is kept.
      if (path.endsWith("/admin/video/transcribe") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!env.AI) return json({ error: "Cloudflare AI isn't connected to the Worker." }, 503, request, env);
        const buf = new Uint8Array(await request.arrayBuffer());
        if (!buf.length) return json({ error: "No audio came through." }, 400, request, env);
        if (buf.length > 25000000) return json({ error: "That audio is too long for one go (over 25MB)." }, 413, request, env);
        let bin = "";
        for (let i = 0; i < buf.length; i += 0x8000) bin += String.fromCharCode.apply(null, buf.subarray(i, i + 0x8000));
        const prompt = String(url.searchParams.get("prompt") || "").slice(0, 400);
        let out;
        try {
          out = await env.AI.run("@cf/openai/whisper-large-v3-turbo", Object.assign({ audio: btoa(bin), language: "en", vad_filter: true }, prompt ? { initial_prompt: prompt } : {}));
        } catch (e) { return json({ error: "Transcribing failed: " + String((e && e.message) || e).slice(0, 200) }, 502, request, env); }
        const words = [];
        (out.segments || []).forEach((sg) => (sg.words || []).forEach((w) => {
          const t = String(w.word || "").trim();
          if (t) words.push({ w: t, s: Math.round(Number(w.start) * 1000) / 1000, e: Math.round(Number(w.end) * 1000) / 1000 });
        }));
        return json({
          ok: true, text: String(out.text || "").trim(), words,
          segments: (out.segments || []).map((sg) => ({ s: sg.start, e: sg.end, text: String(sg.text || "").trim(), hasWords: Array.isArray(sg.words) })),
          info: out.transcription_info || null,
        }, 200, request, env);
      }

      // ---- Admin: video captions, step 2 - Claude plans the edit -----------
      // (Dani, 3 Nov 2026.) Claude can't watch a video, so it gets what it
      // needs as text: every word with its time (step 1), the style rules,
      // and what the person asked for this video. It answers with a plan the
      // page draws from: the stretches to keep, the caption phrases and their
      // italic words, and the big statement words with their small labels.
      // The cutting and drawing happen in the browser, not here.
      /* ---- TMKE OS search: "where do I…?" (Dani, 4 Nov 2026) ----
         The sidebar search matches its list of places instantly; when that
         finds nothing clear, it asks here. The page sends the question and
         the list (name, where it lives, what you do there); Claude Haiku
         points to the best one to three and says why in a sentence. The
         list comes from src/data/admin-places.js, so it's always the
         page's own. Admins only. */
      if (path.endsWith("/admin/nav-ask") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!env.ANTHROPIC_API_KEY) return json({ error: "Claude isn't set up on the Worker." }, 503, request, env);
        const b = await request.json().catch(() => ({}));
        const q = String((b && b.q) || "").trim().slice(0, 300);
        const places = Array.isArray(b && b.places) ? b.places.slice(0, 400) : [];
        if (!q || !places.length) return json({ error: "Ask something first." }, 400, request, env);
        const list = places.map((pl, i) => `${i}. ${String(pl.n || "").slice(0, 90)} | ${String(pl.w || "").slice(0, 60)} | ${String(pl.j || "").slice(0, 200)}`).join("\n");
        const schema = {
          type: "object", additionalProperties: false,
          properties: {
            picks: { type: "array", items: { type: "integer" } },
            answer: { type: "string" },
          },
          required: ["picks", "answer"],
        };
        const system = "You help the TMKE team find where to do something in their admin system, TMKE OS. You are given a numbered list of every place (page, tab or panel) with where it lives and what you do there. Pick the one to three places that best answer the question, best first, by their numbers. Then write the answer in one or two short plain sentences in British English: name the place and where it is (for example \"That's Trending month, under Member hub.\"), and say what to do there if it helps. If nothing fits, return no picks and say so plainly. Never invent a place that isn't in the list.";
        let aiRes;
        try {
          aiRes = await aiFetch(env, "help", {
            max_tokens: 800, system,
            output_config: { format: { type: "json_schema", schema } },
            messages: [{ role: "user", content: `The places:\n${list}\n\nThe question: ${q}` }],
          });
        } catch (_) { return json({ error: "Couldn't reach Claude." }, 502, request, env); }
        const out = await aiRes.json().catch(() => null);
        if (!aiRes.ok || !out) return json({ error: aiFailMessage(aiRes.status, out && out.error && out.error.message) }, 502, request, env);
        const text = ((out.content || []).find((c) => c.type === "text") || {}).text || "";
        let parsed = null; try { parsed = JSON.parse(text); } catch (_) {}
        const picks = (parsed && Array.isArray(parsed.picks) ? parsed.picks : []).filter((n) => Number.isInteger(n) && n >= 0 && n < places.length).slice(0, 3);
        return json({ picks, answer: String((parsed && parsed.answer) || "").slice(0, 500) }, 200, request, env);
      }

      if (path.endsWith("/admin/video/plan") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const words = (Array.isArray(b.words) ? b.words : []).slice(0, 4000)
          .map((w) => ({ w: String(w.w || "").slice(0, 60), s: Number(w.s) || 0, e: Number(w.e) || 0 }));
        if (!words.length) return json({ error: "No words to plan from." }, 400, request, env);
        const rules = String(b.rules || "").slice(0, 20000);
        const brief = String(b.brief || "").slice(0, 4000);
        const list = words.map((w, i) => `${i}|${w.w}|${w.s.toFixed(2)}|${w.e.toFixed(2)}`).join("\n");
        const duration = Number(b.duration) || words[words.length - 1].e;
        const schema = {
          type: "object", additionalProperties: false,
          required: ["keep", "fixes", "phrases", "heroes", "notes"],
          properties: {
            keep: { type: "array", items: { type: "object", additionalProperties: false, required: ["start", "end"],
              properties: { start: { type: "number" }, end: { type: "number" } } } },
            fixes: { type: "array", items: { type: "object", additionalProperties: false, required: ["index", "text"],
              properties: { index: { type: "integer" }, text: { type: "string" } } } },
            phrases: { type: "array", items: { type: "object", additionalProperties: false, required: ["first", "last", "emphasis"],
              properties: { first: { type: "integer" }, last: { type: "integer" }, emphasis: { type: "array", items: { type: "integer" } } } } },
            heroes: { type: "array", items: { type: "object", additionalProperties: false, required: ["text", "label", "start", "end"],
              properties: { text: { type: "string" }, label: { type: "string" }, start: { type: "number" }, end: { type: "number" } } } },
            notes: { type: "string" },
          },
        };
        const prompt = `You are editing a short vertical social video for a UK estate agent. You can't see or hear it; you have every spoken word with its start and end time in seconds, the house style rules, and the brief for this video.

STYLE RULES
${rules || "(none given)"}

BRIEF FOR THIS VIDEO
${brief || "(none given)"}

VIDEO LENGTH: ${duration.toFixed(2)}s

WORDS (index|word|start|end)
${list}

Plan the edit:
- keep: the stretches of the ORIGINAL timeline to keep, in order, in seconds. Start and end each one inside a natural pause (the gap between one word's end and the next word's start), never mid-word. Follow the brief and the trimming rules.
- fixes: only where a word is mis-transcribed (a name, a figure, a brand). Usually empty.
- phrases: the caption phrases, as inclusive word-index ranges, in order, covering every KEPT word exactly once and no cut word. Follow the phrase grouping rules; a phrase never spans a cut. emphasis lists the word indices in that phrase shown in the italic serif.
- heroes: the statement words shown big behind the subject, with their small label ("" for none), start and end on the ORIGINAL timeline, inside a kept stretch. Follow the rules on how many and what not to show.
- notes: one or two sentences on the choices, for the person reviewing it.`;
        let aiRes;
        try {
          aiRes = await aiFetch(env, "admin", { max_tokens: 32000, output_config: { effort: "high", format: { type: "json_schema", schema } }, messages: [{ role: "user", content: prompt }] });
        } catch (e) { return json({ error: "Couldn't reach Claude." }, 502, request, env); }
        const out = await aiRes.json().catch(() => null);
        if (!aiRes.ok || !out) return json({ error: aiFailMessage(aiRes.status, out && out.error && out.error.message), detail: (out && out.error && out.error.message) || "" }, 502, request, env);
        const text = (out.content || []).filter((c) => c.type === "text").map((c) => c.text).join("");
        let plan = null;
        try { plan = JSON.parse(text); } catch (_) {}
        if (!plan) return json({ error: "Claude's plan couldn't be read.", stop: out.stop_reason || null }, 502, request, env);
        return json({ ok: true, plan, model: out.model || null, usage: out.usage || null, stop: out.stop_reason || null }, 200, request, env);
      }

      // ---- Admin: which Claude does which job, and is there credit left ----
      // GET reports the three models and asks the cheapest one for a single
      // token. POST {test:true} sends the "credit has run out" alert as a
      // test, so the email can be seen without the credit running out.
      if (path.endsWith("/admin/ai/status") && (request.method === "GET" || request.method === "POST")) {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const models = { help: aiModel(env, "help"), write: aiModel(env, "write"), admin: aiModel(env, "admin") };
        if (request.method === "POST") {
          let body = {}; try { body = await request.json(); } catch (_) {}
          if (!body.test) return json({ error: "Only a test alert can be sent from here." }, 400, request, env);
          return json({ ok: await aiCreditAlert(env, "admin test", true), models }, 200, request, env);
        }
        let credit = "unknown";
        try {
          const r = await aiFetch(env, "help", { max_tokens: 1, messages: [{ role: "user", content: "ok" }] });
          const t = r.ok ? "" : await r.text().catch(() => "");
          credit = r.ok ? "ok" : (/credit balance/i.test(t) ? "out" : "error " + r.status);
        } catch (_) { credit = "unreachable"; }
        return json({ ok: true, models, credit }, 200, request, env);
      }

      if (path.endsWith("/admin/broadcasts/run") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        await runMemberBroadcasts(env);
        return json({ ok: true }, 200, request, env);
      }

      // ---- Members on the admin dashboard -----------------------------------
      // Everyone with a hub account, staff left out, and when each joined.
      // Counted from the accounts themselves: a contact's CRM stage moves on
      // from "member" when they buy or book, so it undercounts members.
      if (path.endsWith("/admin/members/stats") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const { users, error } = await listAccounts(env);
        if (error && !users.length) return json({ error }, 502, request, env);
        const members = users.filter((u) => !emailLooksAdmin(u));
        return json({ total: members.length, joined: members.map((u) => u.created_at).filter(Boolean), partial: !!error }, 200, request, env);
      }

      // ---- Admin bell: how urgent each notification is (Dani, 17 Oct) -------
      // The pop-out's "Most urgent" sort. Claude reads each notification once
      // and the answer is kept on the row (meta.urgency, meta.urgency_why), so
      // the same one is never asked about twice. Only rows addressed to the
      // person asking are read, as the bell itself shows them.
      //   3  something is broken, or someone is stuck waiting on us
      //   2  something was reported, we have to do something, or the member
      //      has to do something within 48 hours
      //   1  worth knowing     0  routine
      if (path.endsWith("/admin/notifications/urgency") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const me = String(user.email || "").toLowerCase();
        const b = await request.json().catch(() => ({}));
        const ids = (Array.isArray(b.ids) ? b.ids : []).map(String).filter((x) => /^[0-9a-f-]{36}$/i.test(x)).slice(0, 80);
        if (!ids.length) return json({ urgency: {} }, 200, request, env);
        const rows = ((await sbGet(env, "admin_notifications", `id=in.(${ids.join(",")})&select=id,created_at,area,event,title,body,recipients,meta`)) || [])
          .filter((r) => (r.recipients || []).map((x) => String(x).toLowerCase()).includes(me));
        const out = {};
        const todo = [];
        for (const r of rows) {
          if (r.meta && typeof r.meta.urgency === "number") out[r.id] = { level: r.meta.urgency, why: r.meta.urgency_why || "" };
          else todo.push(r);
        }
        // Without the AI: the area and the event say enough to rank roughly.
        const byRule = (r) => r.area === "problem" ? 3 : /report|stall|fail|error|broken|bounce/i.test(r.event || "") ? 2 : /question|request|approval|waiting/i.test((r.event || "") + " " + (r.title || "")) ? 2 : 1;
        let judged = {};
        if (todo.length && env.ANTHROPIC_API_KEY) {
          const list = todo.map((r) => ({ id: r.id, when: r.created_at, area: r.area, event: r.event, title: String(r.title || "").slice(0, 200), body: String(r.body || "").slice(0, 400) }));
          const prompt = `You sort the notifications in the admin centre of TMKE, a marketing agency for estate agents, by how urgently the owner (Dani) needs to act. It is now ${new Date().toISOString()}.

Rate each one 0-3:
3 = something is broken or failing, or a person can't do something because they are waiting for Dani's approval or action.
2 = something has been reported, Dani has to do something, or the customer/member has to do something within the next 48 hours.
1 = worth knowing about but needs nothing now.
0 = routine activity.

Give a reason of at most 8 words, plain English, no full stop.

Notifications (JSON):
${JSON.stringify(list)}

Return ONLY minified JSON, no markdown: {"r":[{"id":"...","level":0,"why":"..."}]}`;
          try {
            const ai = await aiFetch(env, "admin", { max_tokens: 8000, messages: [{ role: "user", content: prompt }] });
            if (ai.ok) {
              const d = await ai.json();
              const text = (d.content || []).filter((c) => c.type === "text").map((c) => c.text).join("");
              const s0 = text.indexOf("{"), e0 = text.lastIndexOf("}");
              const parsed = JSON.parse(text.slice(s0, e0 + 1));
              for (const x of (parsed.r || [])) {
                const lv = Math.max(0, Math.min(3, Math.round(Number(x.level))));
                if (x.id && !isNaN(lv)) judged[x.id] = { level: lv, why: String(x.why || "").slice(0, 80) };
              }
            }
          } catch (_) { judged = {}; }
        }
        for (const r of todo) {
          const j = judged[r.id];
          out[r.id] = j || { level: byRule(r), why: "" };
          // Kept only when Claude judged it, so a rough rule never sticks.
          if (j) await sbPatch(env, "admin_notifications", `id=eq.${r.id}`, { meta: Object.assign({}, r.meta || {}, { urgency: j.level, urgency_why: j.why }) }).catch(() => null);
        }
        return json({ urgency: out }, 200, request, env);
      }

      // ---- The Marketing Calendar in their own calendar ----------------------
      // The member's private link (made from their sign-in; reset on request).
      // ── Scheduling test (staff only): TMKE's own accounts ────────────────
      // Proof that posting works, without opening it to members: post to the
      // house profile's accounts from /admin/scheduling-test.
      if (path.endsWith("/schedule/test") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const prof = await zernioHouseProfile(env);
        if (!prof) return json({ error: "Couldn't reach Zernio's profiles." }, 502, request, env);
        const [acc, posts] = await Promise.all([zernio(env, `/accounts?profileId=${prof._id}`), zernio(env, `/posts?profileId=${prof._id}&limit=20`)]);
        const accounts = ((acc.ok && acc.data.accounts) || []).map((a) => ({ id: a._id || a.id, platform: a.platform, username: a.username || "", name: a.displayName || "", picture: a.profilePicture || "" }));
        const list = ((posts.ok && posts.data.posts) || []).map((p) => ({ id: p._id, status: p.status, content: p.content, scheduledFor: p.scheduledFor, media: ((p.mediaItems || [])[0] || {}).url || "", platforms: (p.platforms || []).map((x) => ({ platform: x.platform, status: x.status, url: x.platformPostUrl || x.url || "", error: x.errorMessage || x.error || "" })) }));
        return json({ ok: true, profile: { id: prof._id, name: prof.name }, accounts, posts: list }, 200, request, env);
      }
      if (path.endsWith("/schedule/test-post") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const prof = await zernioHouseProfile(env);
        if (!prof) return json({ error: "Couldn't reach Zernio's profiles." }, 502, request, env);
        const acc = await zernio(env, `/accounts?profileId=${prof._id}`);
        const owned = (acc.ok && acc.data.accounts) || [];
        const picked = (Array.isArray(b.accountIds) ? b.accountIds : []).map(String);
        const targets = owned.filter((a) => picked.includes(a._id || a.id)).map((a) => ({ platform: a.platform, accountId: a._id || a.id }));
        if (!targets.length) return json({ error: "Pick at least one account." }, 400, request, env);
        const media = String(b.image_url || "");
        if (!/^https:\/\//.test(media)) return json({ error: "Pick a picture." }, 400, request, env);
        const body = { content: String(b.caption || ""), profileId: prof._id, platforms: targets, mediaItems: [{ type: /\.(mp4|mov|m4v|webm)(\?|$)/i.test(media) ? "video" : "image", url: media }] };
        if (b.now) body.publishNow = true;
        else {
          const when = londonToUtcIso(String(b.date || ""), String(b.time || ""));
          if (!/^\d{4}-\d{2}-\d{2}$/.test(String(b.date || "")) || new Date(when).getTime() < Date.now() + 2 * 60000) return json({ error: "Pick a time at least two minutes from now." }, 400, request, env);
          body.scheduledFor = when;
        }
        const r = await zernio(env, "/posts", { method: "POST", body: JSON.stringify(body) });
        if (!r.ok) return json({ error: (r.data && (r.data.error || r.data.message)) || `Zernio didn't take it (${r.status}).`, details: r.data }, 502, request, env);
        const post = r.data.post || r.data;
        return json({ ok: true, post: { id: post._id, status: post.status, scheduledFor: post.scheduledFor } }, 200, request, env);
      }
      if (path.endsWith("/schedule/test-cancel") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        if (!/^[0-9a-f]{24}$/.test(String(b.post_id || ""))) return json({ error: "Which post?" }, 400, request, env);
        const r = await zernio(env, `/posts/${b.post_id}`, { method: "DELETE" });
        return json(r.ok ? { ok: true } : { error: (r.data && r.data.error) || "Couldn't cancel it." }, r.ok ? 200 : 502, request, env);
      }

      /* How a pack did (Danielle, 28 Oct 2026): for a promotion, how many
         members opened its templates, saved their own copy and downloaded one,
         between two dates (by default the pack's free window). Staff are left
         out. Opens are counted from the template_opened event, which started
         on 28 Oct 2026; a saved copy is a My Designs row made from one of the
         pack's templates; a download is the editor's design_downloaded event
         for one of those templates or a copy of one. */
      if (path.endsWith("/admin/pack-results") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const packId = String(url.searchParams.get("pack_id") || "");
        if (!/^[0-9a-f-]{36}$/i.test(packId)) return json({ error: "Which pack?" }, 400, request, env);
        const pack = (await sbGet(env, "packs", `id=eq.${packId}&select=*`))?.[0];
        if (!pack) return json({ error: "Pack not found." }, 404, request, env);
        const day = (v) => (/^\d{4}-\d{2}-\d{2}$/.test(String(v || "")) ? String(v) : null);
        const from = day(url.searchParams.get("from")) || (pack.available_from ? String(pack.available_from).slice(0, 10) : String(pack.created_at || "2026-01-01").slice(0, 10));
        const to = day(url.searchParams.get("to")) || londonParts(new Date()).ymd;
        const toEnd = new Date(Date.UTC(+to.slice(0, 4), +to.slice(5, 7) - 1, +to.slice(8, 10) + 1)).toISOString().slice(0, 10);
        const inRange = `created_at=gte.${from}&created_at=lt.${toEnd}`;

        const staff = new Set(((await sbGet(env, "admins", "select=user_id")) || []).map((r) => r.user_id));
        const tpls = (await sbGet(env, "templates", `pack_id=eq.${packId}&select=id,name,thumb_url,sort_order&order=sort_order.asc`)) || [];
        const tplIds = tpls.map((t) => t.id);
        const quoted = (arr) => arr.map((i) => `"${String(i).replace(/"/g, "")}"`).join(",");
        const copies = tplIds.length ? ((await sbGetAll(env, "user_designs", `source_template_id=in.(${quoted(tplIds)})&select=id,user_id,source_template_id,created_at`)) || []) : [];
        const copyTpl = new Map(copies.map((d) => [d.id, d.source_template_id]));
        const member = (uid) => !!uid && !staff.has(uid);

        // Events for these templates (or copies of them) in the window.
        const keys = [...tplIds, ...copyTpl.keys()];
        let events = [];
        if (keys.length) {
          const q = quoted(keys);
          events = (await sbGetAll(env, "site_events",
            `name=in.(design_downloaded,template_opened)&${inRange}&or=(props->>template.in.(${q}),props->>design_id.in.(${q}))&select=name,user_id,props,created_at`)) || [];
        }
        const tplOf = (e) => {
          const p = e.props || {};
          if (tplIds.includes(p.template)) return p.template;
          if (tplIds.includes(p.design_id)) return p.design_id;
          return copyTpl.get(p.design_id) || null;
        };

        const per = new Map(tpls.map((t) => [t.id, { id: t.id, name: t.name, thumb_url: t.thumb_url, opened: new Set(), saved: new Set(), downloaded: new Set(), downloads: 0 }]));
        const people = new Map();
        const person = (uid) => { if (!people.has(uid)) people.set(uid, { user_id: uid, opened: 0, saved: 0, downloads: 0, last: null }); return people.get(uid); };
        const touch = (pp, at) => { if (!pp.last || at > pp.last) pp.last = at; };
        for (const d of copies) {
          if (!member(d.user_id) || d.created_at < from || d.created_at >= toEnd) continue;
          per.get(d.source_template_id)?.saved.add(d.user_id);
          const pp = person(d.user_id); pp.saved++; touch(pp, d.created_at);
        }
        for (const e of events) {
          if (!member(e.user_id)) continue;
          const t = per.get(tplOf(e));
          if (!t) continue;
          const pp = person(e.user_id); touch(pp, e.created_at);
          if (e.name === "template_opened") { t.opened.add(e.user_id); pp.opened++; }
          else { t.downloaded.add(e.user_id); t.downloads++; pp.downloads++; }
        }

        // Names for the people list.
        const uids = [...people.keys()];
        const names = new Map();
        for (let i = 0; i < uids.length; i += 100) {
          const rows = (await sbGet(env, "contacts", `user_id=in.(${quoted(uids.slice(i, i + 100))})&select=user_id,first_name,last_name,email,company`)) || [];
          rows.forEach((c) => names.set(c.user_id, c));
        }
        const uniq = (k) => new Set([...per.values()].flatMap((t) => [...t[k]])).size;
        return json({
          ok: true,
          pack: { id: pack.id, title: pack.title, demo: !!pack.demo, available_from: pack.available_from || null, available_until: pack.available_until || null },
          from, to, opens_since: "2026-10-28",
          totals: { opened: uniq("opened"), saved: uniq("saved"), downloaded: uniq("downloaded"), downloads: [...per.values()].reduce((n, t) => n + t.downloads, 0) },
          templates: [...per.values()].map((t) => ({ id: t.id, name: t.name, thumb_url: t.thumb_url, opened: t.opened.size, saved: t.saved.size, downloaded: t.downloaded.size, downloads: t.downloads })),
          people: [...people.values()].map((pp) => {
            const c = names.get(pp.user_id) || {};
            return { ...pp, name: [c.first_name, c.last_name].filter(Boolean).join(" ") || null, email: c.email || null, company: c.company || null };
          }).sort((a, b) => String(b.last).localeCompare(String(a.last))),
        }, 200, request, env);
      }

      // What this member's Content Calendar level gives them (memberAccess).
      if (path.endsWith("/access/me") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in again." }, 401, request, env);
        return json(await memberAccess(env, user, url.searchParams.get("as")), 200, request, env);
      }

      // ---- The Content Calendar month, for members (Danielle, 11 Nov) ----
      if (path.includes("/calendar/") && request.method === "GET"
          && /\/calendar\/(month|months|post|templates|template)$/.test(path)) {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in again." }, 401, request, env);
        const a = await memberAccess(env, user, url.searchParams.get("as"));
        const sp = url.searchParams;

        // One month: the posts of the edition to show, and the editions on offer.
        if (path.endsWith("/calendar/month")) {
          const ym = ccMonthKey(sp.get("month"));
          if (!ym) return json({ error: "Which month?" }, 400, request, env);
          if (!ccMayOpenMonth(a, ym)) return json({ ok: true, access: a, month: null }, 200, request, env);
          const months = (await sbGet(env, "content_months", `month=eq.${ym}&status=eq.published&select=id,month,edition,intro`)) || [];
          const ed = ccPickEdition(a, months.map((m) => m.edition), sp.get("edition"));
          const m = ed && months.find((x) => x.edition === ed);
          if (!m) return json({ ok: true, access: a, month: null }, 200, request, env);
          const preview = !a.calendar;
          const posts = (await sbGet(env, "content_month_posts", `month_id=eq.${m.id}&select=${preview ? CC_PREVIEW_COLS : CC_POST_COLS}&order=post_date.asc,sort_order.asc`)) || [];
          const tpls = await ccTemplatesById(env, posts.map((p) => p.template_id));
          return json({
            ok: true, access: a, preview, month: m,
            editions: months.map((x) => x.edition).filter((e) => a.staff || (a.editions || []).includes(e))
              .sort((x, y) => CC_EDITION_ORDER.indexOf(x) - CC_EDITION_ORDER.indexOf(y)),
            posts: posts.map((p) => ({ ...p, template: tpls.get(p.template_id) || null })),
          }, 200, request, env);
        }

        // The months to offer as packs in the Studio, from a month on.
        if (path.endsWith("/calendar/months")) {
          if (!a.calendar) return json({ ok: true, access: a, months: [] }, 200, request, env);
          const from = ccMonthKey(sp.get("from")) || accessMonth(0);
          const rows = (await sbGet(env, "content_months", `status=eq.published&month=gte.${from}&select=id,month,edition&order=month.asc`)) || [];
          const want = sp.get("edition");
          const byMonth = new Map();
          rows.filter((m) => ccMayOpenMonth(a, m.month) && ccMayOpenEdition(a, m.edition)).forEach((m) => {
            const have = byMonth.get(m.month);
            const rank = (x) => (x.edition === want ? 0 : x.edition === a.edition ? 1 : 2 + CC_EDITION_ORDER.indexOf(x.edition));
            if (!have || rank(m) < rank(have)) byMonth.set(m.month, m);
          });
          const out = [...byMonth.values()];
          if (out.length) {
            const posts = (await sbGet(env, "content_month_posts", `month_id=in.(${out.map((m) => m.id).join(",")})&template_id=not.is.null&select=month_id,template_id&order=post_date.asc,sort_order.asc`)) || [];
            const first = new Map();
            posts.forEach((p) => { if (!first.has(p.month_id)) first.set(p.month_id, p.template_id); });
            const tpls = await ccTemplatesById(env, [...first.values()]);
            out.forEach((m) => { const t = tpls.get(first.get(m.id)); m.cover = (t && t.thumb_url) || null; });
          }
          return json({ ok: true, access: a, months: out }, 200, request, env);
        }

        if (!a.calendar) return json({ error: "Your plan doesn't include the Content Calendar." }, 403, request, env);

        // One post, with its month (?ccpost= in the Studio).
        if (path.endsWith("/calendar/post")) {
          const p = ((await sbGet(env, "content_month_posts", `id=eq.${encodeURIComponent(sp.get("id") || "")}&select=${CC_POST_COLS}`)) || [])[0];
          const m = p && await ccOpenMonthRow(env, a, p.month_id);
          if (!m) return json({ ok: true, post: null }, 200, request, env);
          return json({ ok: true, post: { ...p, month: m } }, 200, request, env);
        }

        // A month's posts with their whole designs, for the Studio pack.
        if (path.endsWith("/calendar/templates")) {
          const m = await ccOpenMonthRow(env, a, sp.get("month_id") || "");
          if (!m) return json({ ok: true, posts: [], templates: [] }, 200, request, env);
          const posts = (await sbGet(env, "content_month_posts", `month_id=eq.${m.id}&select=${CC_POST_COLS}&order=post_date.asc,sort_order.asc`)) || [];
          const ids = [...new Set(posts.map((p) => p.template_id).filter(Boolean))];
          const byId = await ccTemplatesById(env, ids, true);
          return json({ ok: true, month: m, posts, templates: ids.map((id) => byId.get(id)).filter(Boolean) }, 200, request, env);
        }

        // One whole design, when it belongs to a post in a month they may open.
        if (path.endsWith("/calendar/template")) {
          const id = sp.get("id") || "";
          const posts = (await sbGet(env, "content_month_posts", `template_id=eq.${encodeURIComponent(id)}&select=month_id`)) || [];
          let ok = false;
          for (const p of posts) { if (await ccOpenMonthRow(env, a, p.month_id)) { ok = true; break; } }
          if (!ok) return json({ ok: true, template: null }, 200, request, env);
          const t = (await ccTemplatesById(env, [id], true)).get(id) || null;
          return json({ ok: true, template: t }, 200, request, env);
        }
      }

      // ---- Content Calendar launch switches, for staff (Danielle, 11 Nov) ----
      // The December rule and the test logins (content_calendar_launch.sql).
      if (path.endsWith("/calendar/launch") && (request.method === "GET" || request.method === "POST")) {
        const user = await getUser(request, env);
        if (!user || !user._isAdmin) return json({ error: "Staff only." }, 403, request, env);
        const describe = async () => {
          const S = await ccSettings(env, true);
          const testers = [];
          for (const id of S.test_user_ids) {
            const c = ((await sbGet(env, "contacts", `user_id=eq.${encodeURIComponent(id)}&select=id,email,first_name,last_name&limit=1`)) || [])[0] || null;
            const brands = c ? ((await sbGet(env, "agent_profiles", `contact_id=eq.${c.id}&left_at=is.null&select=brand`)) || []).map((r) => r.brand) : [];
            const acc = await memberAccess(env, { id, email: c && c.email, _isAdmin: false });
            testers.push({ id, email: c ? c.email : null, name: c ? [c.first_name, c.last_name].filter(Boolean).join(" ") : null,
              brands, level: acc.level, calendar: acc.calendar, preview: acc.preview, edition: acc.edition });
          }
          return { ok: true, ready: S.ready, teg_live: S.teg_live, updated_at: S.updated_at, updated_by: S.updated_by, testers };
        };
        if (request.method === "GET") return json(await describe(), 200, request, env);
        let b; try { b = await request.json(); } catch (_) { return json({ error: "Bad JSON" }, 400, request, env); }
        const S = await ccSettings(env, true);
        if (!S.ready) return json({ error: "Run content_calendar_launch.sql first. It's on the SQL to run list." }, 409, request, env);
        const patch = { updated_at: new Date().toISOString(), updated_by: user.email || null };
        if (typeof b.teg_live === "boolean") patch.teg_live = b.teg_live;
        let ids = S.test_user_ids.slice();
        if (b.add_email) {
          const email = String(b.add_email).trim().toLowerCase();
          const c = ((await sbGet(env, "contacts", `email=eq.${encodeURIComponent(email)}&select=id,user_id&limit=1`)) || [])[0];
          if (!c) return json({ error: `There's no contact with the email ${email}. Add them in People first.` }, 404, request, env);
          if (!c.user_id) return json({ error: `${email} hasn't signed in to the Hub yet. Sign in once with it, then add it here.` }, 409, request, env);
          const who = { id: c.user_id, email };
          const staffCheck = emailLooksAdmin(who) || !!(((await sbGet(env, "admins", `user_id=eq.${c.user_id}&select=user_id`)) || []).length);
          if (staffCheck) return json({ error: `${email} is a staff login, so it would see everything. Use an ordinary member login.` }, 409, request, env);
          if (!ids.includes(c.user_id)) ids.push(c.user_id);
        }
        if (b.remove_id) ids = ids.filter((x) => x !== b.remove_id);
        patch.test_user_ids = ids;
        const r = await sbPatch(env, "content_calendar_settings", "id=eq.1", patch);
        if (!r || !r.ok) return json({ error: "Couldn't save the change." }, 502, request, env);
        CC_SETTINGS_CACHE = null;
        return json(await describe(), 200, request, env);
      }

      // ---- Done For You waitlist: the website's page (public) ----
      if (path.endsWith("/dfy/waitlist/status") && request.method === "GET") {
        const S = await ccSettings(env);
        if (!S.dfy_ready) return json({ ok: true, ready: false, open: false }, 200, request, env);
        const taken = (await dfyCounts(env)).length;
        return json({ ok: true, ready: true, open: S.dfy_open, audience: S.dfy_audience, spaces: S.dfy_spaces,
          taken, left: Math.max(0, S.dfy_spaces - taken),
          brands: S.dfy_audience === "teg" ? DFY_TEG_BRANDS : [...DFY_TEG_BRANDS, "Independent agent"],
          options: DFY_OPTIONS }, 200, request, env);
      }
      if (path.endsWith("/dfy/waitlist") && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        if (b.hp) return json({ ok: true }, 200, request, env);   // honeypot: a bot, dropped quietly
        const ip = request.headers.get("CF-Connecting-IP") || "";
        if (!(await verifyTurnstile(env, b.turnstile_token, ip))) return json({ error: "Spam check failed. Please try again." }, 400, request, env);
        const S = await ccSettings(env, true);
        if (!S.dfy_ready) return json({ error: "The waitlist isn't open yet." }, 503, request, env);
        const name = String(b.name || "").replace(/\s+/g, " ").trim().slice(0, 120);
        const email = String(b.email || "").trim().toLowerCase().slice(0, 200);
        const brand = String(b.brand || "").trim();
        const option = String(b.option || "");
        if (!name || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return json({ error: "Add your name and email address." }, 400, request, env);
        if (!DFY_OPTIONS[option]) return json({ error: "Choose how you'd like Done For You." }, 400, request, env);
        const brands = S.dfy_audience === "teg" ? DFY_TEG_BRANDS : [...DFY_TEG_BRANDS, "Independent agent"];
        if (!brands.includes(brand)) return json({ error: S.dfy_audience === "teg"
          ? "This waitlist is for The Property Experts and Prestige Property Experts agents for now. Independent agents can join from February."
          : "Choose your brand." }, 400, request, env);
        // Who they are, if we know them: their contact, and whether they're an agent on that brand.
        const c = ((await sbGet(env, "contacts", `email=eq.${encodeURIComponent(email)}&select=id,user_id&limit=1`)) || [])[0] || null;
        let matched = false;
        if (c && brand !== "Independent agent") {
          matched = !!(((await sbGet(env, "agent_profiles", `contact_id=eq.${c.id}&brand=eq.${encodeURIComponent(brand)}&left_at=is.null&select=id&limit=1`)) || []).length);
        }
        // Closed until the page goes out, but test logins and staff can try it.
        if (!S.dfy_open) {
          const viewer = await getUser(request, env).catch(() => null);
          const tester = (c && c.user_id && S.test_user_ids.includes(c.user_id)) || (viewer && (viewer._isAdmin || S.test_user_ids.includes(viewer.id)));
          if (!tester) return json({ error: "The waitlist isn't open yet." }, 403, request, env);
        }
        let rows = await dfyCounts(env);
        const existing = ((await sbGet(env, "dfy_waitlist", `email=eq.${encodeURIComponent(email)}&status=neq.removed&select=id,created_at&limit=1`)) || [])[0];
        if (existing) {
          const place = rows.findIndex((r) => r.id === existing.id) + 1;
          return json({ ok: true, already: true, place, spaces: S.dfy_spaces, reserve: place > S.dfy_spaces }, 200, request, env);
        }
        const ins = await sbPost(env, "dfy_waitlist", { name, email, brand, option, user_id: c ? c.user_id : null, contact_id: c ? c.id : null,
          matched, source: String(b.source || "").slice(0, 120) || null }, "return=representation");
        if (!ins || !ins.ok) {
          const t = ins ? await ins.text().catch(() => "") : "";
          if (/duplicate|unique/i.test(t)) return json({ ok: true, already: true }, 200, request, env);
          return json({ error: "Couldn't add you to the waitlist. Please try again." }, 502, request, env);
        }
        const row = ((await ins.json().catch(() => [])) || [])[0] || {};
        rows = await dfyCounts(env);
        const place = Math.max(1, rows.findIndex((r) => r.id === row.id) + 1);
        const reserve = place > S.dfy_spaces;
        try { await sendEmail(env, dfyWaitlistEmail({ name, email, option }, place, S.dfy_spaces, reserve)); }
        catch (e) { console.warn("dfy waitlist email", e && e.message); }
        return json({ ok: true, place, spaces: S.dfy_spaces, reserve }, 200, request, env);
      }

      // ---- Done For You waitlist: the team's list (staff) ----
      if (path.endsWith("/dfy/waitlist/admin") && (request.method === "GET" || request.method === "POST")) {
        const user = await getUser(request, env);
        if (!user || !user._isAdmin) return json({ error: "Staff only." }, 403, request, env);
        const S0 = await ccSettings(env, true);
        if (!S0.dfy_ready) return json({ ok: true, ready: false }, 200, request, env);
        if (request.method === "POST") {
          let b; try { b = await request.json(); } catch (_) { return json({ error: "Bad JSON" }, 400, request, env); }
          const set = {};
          if (Number.isInteger(b.spaces) && b.spaces >= 0 && b.spaces <= 500) set.dfy_spaces = b.spaces;
          if (b.audience === "teg" || b.audience === "all") set.dfy_audience = b.audience;
          if (typeof b.open === "boolean") set.dfy_open = b.open;
          if (Object.keys(set).length) {
            const r = await sbPatch(env, "content_calendar_settings", "id=eq.1", { ...set, updated_at: new Date().toISOString(), updated_by: user.email || null });
            if (!r || !r.ok) return json({ error: "Couldn't save the change." }, 502, request, env);
            CC_SETTINGS_CACHE = null;
          }
          if (b.id && (["waiting", "invited", "joined", "removed"].includes(b.status) || typeof b.note === "string")) {
            const patch = {};
            if (b.status) { patch.status = b.status; if (b.status === "invited") patch.invited_at = new Date().toISOString(); }
            if (typeof b.note === "string") patch.note = b.note.trim().slice(0, 500) || null;
            const r = await sbPatch(env, "dfy_waitlist", `id=eq.${encodeURIComponent(b.id)}`, patch);
            if (!r || !r.ok) return json({ error: "Couldn't save the change." }, 502, request, env);
          }
        }
        const S = await ccSettings(env, true);
        const list = (await sbGetAll(env, "dfy_waitlist", "select=id,created_at,name,email,brand,option,matched,status,invited_at,note,source&order=created_at.asc")) || [];
        let n = 0;
        list.forEach((r) => { if (r.status !== "removed") { n += 1; r.place = n; r.reserve = n > S.dfy_spaces; } else r.place = null; });
        return json({ ok: true, ready: true, open: S.dfy_open, audience: S.dfy_audience, spaces: S.dfy_spaces, taken: n, list, options: DFY_OPTIONS }, 200, request, env);
      }

      // ── Scheduling (Zernio) ──────────────────────────────────────────────
      // Where the member stands: their connected accounts.
      if (path.endsWith("/schedule/status") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in again." }, 401, request, env);
        if (!scheduleAllowed(env, user)) return json({ ok: true, open: false, accounts: [] }, 200, request, env);
        if (!env.ZERNIO_API_KEY) return json({ ok: true, open: true, configured: false, accounts: [] }, 200, request, env);
        const prof = await zernioProfile(env, user);
        if (!prof) return json({ error: "Couldn't open your scheduling profile just now." }, 502, request, env);
        const acc = await zernio(env, `/accounts?profileId=${prof._id}`);
        const accounts = (acc.ok && acc.data.accounts || []).map((a) => ({ id: a._id || a.id, platform: a.platform, username: a.username || a.displayName || a.name || "", picture: a.profilePicture || a.avatar || "" }));
        return json({ ok: true, open: true, configured: true, accounts }, 200, request, env);
      }
      // Connect an account: Zernio's sign-in link for that platform, coming
      // back to the Content Calendar afterwards.
      if (path.endsWith("/schedule/connect") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in again." }, 401, request, env);
        if (!scheduleAllowed(env, user)) return json({ error: "Scheduling isn't open yet." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const platform = String(b.platform || "").toLowerCase();
        if (!ZERNIO_PLATFORMS.includes(platform)) return json({ error: "Pick Instagram, Facebook, LinkedIn or TikTok." }, 400, request, env);
        const prof = await zernioProfile(env, user);
        if (!prof) return json({ error: "Couldn't open your scheduling profile just now." }, 502, request, env);
        const back = `${(env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "")}/account/schedule?connected=${platform}`;
        const r = await zernio(env, `/connect/${platform}?profileId=${prof._id}&redirect_url=${encodeURIComponent(back)}`);
        if (!r.ok || !r.data.authUrl) return json({ error: (r.data && r.data.error) || "Couldn't start the connection." }, 502, request, env);
        return json({ ok: true, authUrl: r.data.authUrl }, 200, request, env);
      }
      // Disconnect one of their accounts.
      if (path.endsWith("/schedule/disconnect") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in again." }, 401, request, env);
        if (!scheduleAllowed(env, user)) return json({ error: "Scheduling isn't open yet." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const prof = await zernioProfile(env, user);
        const acc = prof ? await zernio(env, `/accounts?profileId=${prof._id}`) : null;
        const mine = acc && acc.ok && (acc.data.accounts || []).some((a) => (a._id || a.id) === b.accountId);
        if (!mine) return json({ error: "That account isn't yours to disconnect." }, 403, request, env);
        const r = await zernio(env, `/accounts/${encodeURIComponent(b.accountId)}`, { method: "DELETE" });
        return json(r.ok ? { ok: true } : { error: "Couldn't disconnect it just now." }, r.ok ? 200 : 502, request, env);
      }
      // Schedule a calendar post to the accounts they pick, at its date and
      // time (UK time), with its picture and caption. Kept on the entry as
      // details.zernio so it can be cancelled or shown as scheduled.
      if (path.endsWith("/schedule/post") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in again." }, 401, request, env);
        if (!scheduleAllowed(env, user)) return json({ error: "Scheduling isn't open yet." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String(b.item_id || "");
        if (!/^[0-9a-f-]{36}$/.test(id)) return json({ error: "Which post?" }, 400, request, env);
        const rows = await sbGet(env, "calendar_items", `select=*&id=eq.${id}&user_id=eq.${user.id}`);
        const item = rows && rows[0];
        if (!item) return json({ error: "That post isn't on your calendar." }, 404, request, env);
        if (!item.asset_url) return json({ error: "Add the design to this post first." }, 400, request, env);
        const when = londonToUtcIso(item.scheduled_date, item.has_time === false ? "09:00" : item.scheduled_time);
        if (new Date(when).getTime() < Date.now() + 5 * 60000) return json({ error: "Pick a time at least five minutes from now." }, 400, request, env);
        const prof = await zernioProfile(env, user);
        if (!prof) return json({ error: "Couldn't open your scheduling profile just now." }, 502, request, env);
        const acc = await zernio(env, `/accounts?profileId=${prof._id}`);
        const owned = (acc.ok && acc.data.accounts || []);
        const picked = (Array.isArray(b.accountIds) ? b.accountIds : []).map(String);
        const targets = owned.filter((a) => picked.includes(a._id || a.id)).map((a) => ({ platform: a.platform, accountId: a._id || a.id }));
        if (!targets.length) return json({ error: "Pick at least one of your connected accounts." }, 400, request, env);
        const isVideo = /\.(mp4|mov|m4v|webm)(\?|$)/i.test(item.asset_url);
        const body = { content: String(item.caption || ""), scheduledFor: when, profileId: prof._id, platforms: targets, mediaItems: [{ type: isVideo ? "video" : "image", url: item.asset_url }] };
        const prev = item.details && item.details.zernio && item.details.zernio.post_id;
        const r = prev
          ? await zernio(env, `/posts/${prev}`, { method: "PUT", body: JSON.stringify(body) })
          : await zernio(env, "/posts", { method: "POST", body: JSON.stringify(body) });
        if (!r.ok) return json({ error: (r.data && (r.data.error || r.data.message)) || "Zernio didn't take the post." }, 502, request, env);
        const post = r.data.post || r.data;
        const zern = { post_id: post._id || prev, status: post.status || "scheduled", scheduled_for: when, accounts: targets.map((t) => t.accountId), at: new Date().toISOString() };
        await sbPatch(env, "calendar_items", `id=eq.${id}&user_id=eq.${user.id}`, { details: { ...(item.details || {}), zernio: zern } });
        return json({ ok: true, zernio: zern }, 200, request, env);
      }
      // Take a scheduled post back off.
      if (path.endsWith("/schedule/cancel") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in again." }, 401, request, env);
        if (!scheduleAllowed(env, user)) return json({ error: "Scheduling isn't open yet." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String(b.item_id || "");
        const rows = /^[0-9a-f-]{36}$/.test(id) ? await sbGet(env, "calendar_items", `select=id,details&id=eq.${id}&user_id=eq.${user.id}`) : null;
        const item = rows && rows[0];
        const pid = item && item.details && item.details.zernio && item.details.zernio.post_id;
        if (!pid) return json({ error: "That post isn't scheduled." }, 404, request, env);
        const r = await zernio(env, `/posts/${pid}`, { method: "DELETE" });
        if (!r.ok && r.status !== 404) return json({ error: "Couldn't cancel it just now." }, 502, request, env);
        const { zernio: _gone, ...rest } = item.details || {};
        await sbPatch(env, "calendar_items", `id=eq.${id}&user_id=eq.${user.id}`, { details: rest });
        return json({ ok: true }, 200, request, env);
      }

      if (path.endsWith("/calendar/feed-link") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in again." }, 401, request, env);
        const b = await request.json().catch(() => ({}));
        const training = !!(b && b.training);
        if (training && String(user.email || "").toLowerCase() !== CAL_TRAINER) return json({ error: "The training calendar is Dani's." }, 403, request, env);
        const fu = await calFeedUser(env, user.id);
        if (!fu) return json({ error: "Couldn't make your link just now." }, 500, request, env);
        let v = training ? fu.vT : fu.v, seen = training ? fu.seenT : fu.seen;
        if (b && b.reset) {
          // A new link: nothing is subscribed to it yet.
          v += 1; seen = {};
          const meta = training ? { cal_feed_v_training: v, cal_feed_seen_training: {} } : { cal_feed_v: v, cal_feed_seen: {} };
          if (!(await calFeedSetMeta(env, user.id, meta))) return json({ error: "Couldn't reset your link just now." }, 500, request, env);
        }
        const token = await calFeedToken(env, user.id, v, training);
        if (!token) return json({ error: "Calendar links aren't set up." }, 503, request, env);
        const base = (env.WORKER_PUBLIC_URL || url.origin).replace(/\/+$/, "");
        const at = `${base}/calendar/feed/${training ? "t/" : ""}${token}`;
        return json({ feed: `${at}.ics`, base: at, synced: seen }, 200, request, env);
      }
      // The feed (every entry) or one entry, as a calendar file.
      const calFeedT = request.method === "GET" && /\/calendar\/feed\/t\/([^/]+?)(?:\/([0-9a-f-]{36}))?\.ics$/.exec(path);
      const calFeedM = calFeedT || (request.method === "GET" && /\/calendar\/feed\/([^/]+?)(?:\/([0-9a-f-]{36}))?\.ics$/.exec(path));
      if (calFeedM) {
        const calTable = calFeedT ? "training_calendar_items" : "calendar_items";
        const who = await calFeedVerify(env, calFeedM[1], !!calFeedT);
        if (!who) return new Response("This calendar link has been reset or isn't valid.", { status: 404, headers: { "Content-Type": "text/plain; charset=utf-8" } });
        const uid = who.uid;
        // The whole feed: note which calendar app is checking it, at most every
        // six hours, so Sync to my calendar can say "Synced" on that one.
        if (!calFeedM[2]) {
          const app = calFeedApp(url, request);
          console.log("[cal feed]", app, (request.headers.get("User-Agent") || "").slice(0, 160));
          const last = Date.parse(who.seen[app] || "");
          if (!isFinite(last) || Date.now() - last > 6 * 3600 * 1000) {
            const k = calFeedT ? "cal_feed_seen_training" : "cal_feed_seen";
            try { await calFeedSetMeta(env, uid, { [k]: { ...who.seen, [app]: new Date().toISOString() } }); } catch (_) {}
          }
        }
        const site = (env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "");
        let rows;
        if (calFeedM[2]) {
          rows = await sbGet(env, calTable, `select=*&user_id=eq.${uid}&id=eq.${calFeedM[2]}`);
        } else {
          // From three months back, so recent history stays in place.
          rows = await sbGetAll(env, calTable, `select=*&user_id=eq.${uid}&status=neq.cancelled&scheduled_date=gte.${calAddDays(new Date().toISOString().slice(0, 10), -90)}&order=scheduled_date.asc,id.asc`);
        }
        if (!rows) return new Response("Couldn't read the calendar just now.", { status: 503, headers: { "Content-Type": "text/plain; charset=utf-8" } });
        if (calFeedM[2] && !rows.length) return new Response("That entry isn't on the calendar any more.", { status: 404, headers: { "Content-Type": "text/plain; charset=utf-8" } });
        const name = calFeedM[2] ? "tmke-calendar-entry.ics" : "tmke-marketing-calendar.ics";
        return new Response(calIcs(rows, site, !calFeedM[2]), {
          headers: { "Content-Type": "text/calendar; charset=utf-8", "Content-Disposition": `inline; filename="${name}"`, "Cache-Control": "private, max-age=0" },
        });
      }

      // ---- Trigger a site rebuild (publish/edit a blog -> push live) ----------
      // The public site is a static Astro build, so DB writes don't change the
      // live pages until a redeploy. The admin editor calls this after a
      // publish/save so Railway rebuilds (re-runs `astro build`, which re-queries
      // Supabase) and the new/edited post goes live — no manual deploy.
      // Railway has no incoming deploy-hook URL, so we call its GraphQL API.
      // Set on the Worker:
      //   wrangler secret put RAILWAY_API_TOKEN     (Account/Project API token)
      //   [vars] RAILWAY_SERVICE_ID, RAILWAY_ENVIRONMENT_ID  (ids of the prod service)
      if (path.endsWith("/deploy") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user) return json({ ok: false, error: "Sign in to publish." }, 401, request, env);
        if (!isAdminEmail(user)) return json({ ok: false, error: "Not authorised." }, 403, request, env);
        if (!env.RAILWAY_API_TOKEN || !env.RAILWAY_SERVICE_ID || !env.RAILWAY_ENVIRONMENT_ID) {
          return json({ ok: false, error: "Auto-deploy isn't configured - set RAILWAY_API_TOKEN (secret), plus RAILWAY_SERVICE_ID and RAILWAY_ENVIRONMENT_ID, on the Worker." }, 503, request, env);
        }
        const now = Date.now();
        // A rebuild already in flight picks up the latest content, so coalesce
        // bursts (e.g. publish then a quick edit) into one deploy.
        if (now - _lastDeployAt < 45000) {
          return json({ ok: true, queued: false, message: "A site update is already in progress - your changes will be included." }, 200, request, env);
        }
        _lastDeployAt = now;
        try {
          // An account or workspace token goes as a Bearer; a project token
          // has its own header. Try the first, then the second, so either works.
          const redeploy = (auth) => fetch("https://backboard.railway.com/graphql/v2", {
            method: "POST",
            headers: { "Content-Type": "application/json", ...auth },
            body: JSON.stringify({
              query: "mutation Redeploy($e: String!, $s: String!) { serviceInstanceRedeploy(environmentId: $e, serviceId: $s) }",
              variables: { e: env.RAILWAY_ENVIRONMENT_ID, s: env.RAILWAY_SERVICE_ID },
            }),
          });
          let r = await redeploy({ Authorization: `Bearer ${env.RAILWAY_API_TOKEN}` });
          let out = await r.json().catch(() => ({}));
          if (!r.ok || (out && out.errors && out.errors.length)) {
            r = await redeploy({ "Project-Access-Token": env.RAILWAY_API_TOKEN });
            out = await r.json().catch(() => ({}));
          }
          if (!r.ok || (out && out.errors && out.errors.length)) {
            _lastDeployAt = 0; // allow a retry
            const msg = (out && out.errors && out.errors[0] && out.errors[0].message) || ("Railway API returned " + r.status);
            const expired = /not authori[sz]ed|unauthori[sz]ed|invalid token/i.test(msg) || r.status === 401;
            return json({ ok: false, error: expired ? "the Railway token on the Worker has expired or been revoked - make a new one in Railway and set it with wrangler secret put RAILWAY_API_TOKEN." : msg }, 502, request, env);
          }
        } catch (e) {
          _lastDeployAt = 0;
          return json({ ok: false, error: "Couldn't reach the Railway API." }, 502, request, env);
        }
        return json({ ok: true, queued: true, message: "Site is updating - your post will be live in a minute or two." }, 200, request, env);
      }

      // ---- Admin image upload → R2 (assets.tmke.co.uk), returns the URL -------
      // The email builder (and any admin tool) POSTs a file here; we store it in
      // the public ASSETS bucket and hand back its URL to drop into an image field.
      if (path.endsWith("/admin/upload") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in to upload." }, 401, request, env);
        if (!isAdminEmail(user)) return json({ error: "Not authorised." }, 403, request, env);
        if (!env.ASSETS) return json({ error: "Asset storage isn't configured on the Worker." }, 503, request, env);
        const form = await request.formData().catch(() => null);
        const file = form && form.get("file");
        if (!file || typeof file === "string") return json({ error: "No file uploaded." }, 400, request, env);
        const type = file.type || "application/octet-stream";
        if (!/^image\//.test(type)) return json({ error: "Images only." }, 415, request, env);
        const buf = await file.arrayBuffer();
        if (buf.byteLength > 12 * 1024 * 1024) return json({ error: "Image is too large (max 12MB)." }, 413, request, env);
        const extFromType = (type.split("/")[1] || "jpg").replace("jpeg", "jpg").replace("svg+xml", "svg");
        const nameExt = ((file.name || "").split(".").pop() || "").toLowerCase().replace(/[^a-z0-9]/g, "");
        const ext = nameExt || extFromType;
        const key = `email-uploads/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;
        try {
          await env.ASSETS.put(key, buf, { httpMetadata: { contentType: type, cacheControl: "public, max-age=31536000" } });
        } catch (e) {
          return json({ error: "Upload failed - try again." }, 502, request, env);
        }
        const fileUrl = "https://assets.tmke.co.uk/" + key.split("/").map(encodeURIComponent).join("/");
        return json({ ok: true, url: fileUrl }, 200, request, env);
      }

      // ---- Public: one order, for the thank-you page ---------------------------
      // A buyer lands on /edit/thanks straight from Stripe, usually before they
      // have an account, so this can't ask them to sign in. The order's own
      // random id is the key, and it only ever opens that one order. The orders
      // table itself is closed to the public (supabase/orders_lockdown.sql).
      if (path.endsWith("/orders/receipt") && request.method === "GET") {
        const id = String(new URL(request.url).searchParams.get("id") || "").trim();
        if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)) return json({ error: "Order not found." }, 404, request, env);
        const rows = await sbGet(env, "orders", `id=eq.${id}&select=id,pack_id,pack_title,amount_pence,vat_pence,total_pence,status,payment_method,invoice_number,buyer_name,buyer_email,buyer_company,buyer_phone,created_at&limit=1`);
        if (!rows || !rows[0]) return json({ error: "Order not found." }, 404, request, env);
        return json(rows[0], 200, request, env);
      }

      // ---- Admin: the email for a gifted pack ----------------------------------
      // Who it goes to and what it says come from the order itself, never the browser.
      if (path.endsWith("/packs/gift-email") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String((b && b.order_id) || "").trim();
        if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)) return json({ error: "Order not found." }, 404, request, env);
        const rows = await sbGet(env, "orders", `id=eq.${id}&payment_method=eq.gift&status=eq.paid&select=buyer_email,buyer_name,pack_title&limit=1`);
        const o = rows && rows[0];
        if (!o || !o.buyer_email) return json({ error: "Gift not found." }, 404, request, env);
        await loadEmailStyles(env);
        const site = (env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "");
        const mail = packGiftedEmail({ first: deliveryFirstName(o.buyer_name), pack: o.pack_title, studioUrl: `${site}/account/studio` });
        const sent = await sendEmail(env, { to: o.buyer_email, subject: mail.subject, html: mail.html });
        if (!sent.ok) return json({ error: "The email didn't send." }, 502, request, env);
        return json({ ok: true }, 200, request, env);
      }

      // ---- Stripe: create a hosted Checkout Session ---------------------------
      // The browser posts the pack id + buyer details; we re-read the pack price
      // from Supabase (never trust the client), create a `pending` order with the
      // service role, then hand back Stripe's hosted payment URL to redirect to.
      if (path.endsWith("/stripe/checkout") && request.method === "POST") {
        if (!env.STRIPE_SECRET_KEY) return json({ error: "Payments aren't set up yet - add the STRIPE_SECRET_KEY secret to the Worker." }, 503, request, env);
        let body;
        try { body = await request.json(); } catch (_) { return json({ error: "Bad JSON" }, 400, request, env); }
        const name = String(body.name || "").trim();
        // Lowercased, because an account's email always is: an order typed as
        // "Jane@Example.co.uk" would never match the library's lookup, and the
        // pack they paid for would not be there.
        const email = String(body.email || "").trim().toLowerCase();
        const phone = String(body.phone || "").trim();
        const company = String(body.company || "").trim();
        const packId = String(body.pack_id || "").trim();
        if (!packId || !name || !email) return json({ error: "Please complete your details." }, 400, request, env);
        if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return json({ error: "That email doesn't look right." }, 400, request, env);

        const packs = await sbGet(env, "packs", `id=eq.${encodeURIComponent(packId)}&status=eq.active&select=id,slug,title,price_pence,cover_image_url&limit=1`);
        const pack = packs && packs[0];
        if (!pack) return json({ error: "That pack isn't available." }, 404, request, env);
        // price_pence is the advertised EX-VAT figure; the customer is charged gross.
        const { net: amountNet, vat: amountVat, gross: amount } = await vatBreakdown(env, pack.price_pence || 0);

        // Only redirect back to a known-good origin.
        const origin = request.headers.get("Origin") || "";
        const allowed = String(env.ALLOWED_ORIGINS || "").split(",").map((s) => s.trim());
        const base = allowed.includes(origin) ? origin : (env.SITE_URL || "https://tmke.co.uk");

        // Create the order up-front as `pending` (or `paid` for free packs).
        const ins = await sbPost(env, "orders", {
          pack_id: pack.id, pack_slug: pack.slug, pack_title: pack.title,
          amount_pence: amountNet, vat_pence: amountVat, total_pence: amount,
          buyer_name: name, buyer_email: email, buyer_phone: phone || null, buyer_company: company || null,
          payment_method: "card", status: amount === 0 ? "paid" : "pending",
        }, "return=representation");
        const created = await ins.json().catch(() => null);
        const order = Array.isArray(created) ? created[0] : created;
        if (!order || !order.id) {
          // Same lesson as the edit-request insert: "please try again" about a
          // permanent failure wastes everyone's time. The buyer still gets a
          // sentence they can act on; the reason goes to `wrangler tail`.
          console.log("order insert failed", ins.status, JSON.stringify(created));
          return json({ error: "Couldn't start your order. Please try again." }, 500, request, env);
        }

        // Free pack — no Stripe needed. Still a customer → make/merge a contact.
        if (amount === 0) { await contactFromOrder(env, order); return json({ url: `${base}/edit/thanks?order=${order.id}` }, 200, request, env); }

        try {
          const session = await stripeApi(env, "checkout/sessions", {
            mode: "payment",
            "payment_method_types[0]": "card",
            success_url: `${base}/edit/thanks?order=${order.id}`,
            cancel_url: `${base}/edit?canceled=1`,
            customer_email: email,
            client_reference_id: order.id,
            "metadata[order_id]": order.id,
            "line_items[0][quantity]": 1,
            "line_items[0][price_data][currency]": "gbp",
            "line_items[0][price_data][unit_amount]": amount,
            "line_items[0][price_data][product_data][name]": pack.title,
          });
          await sbPatch(env, "orders", `id=eq.${order.id}`, { stripe_session_id: session.id });
          return json({ url: session.url }, 200, request, env);
        } catch (e) {
          await sbPatch(env, "orders", `id=eq.${order.id}`, { status: "failed" });
          return json({ error: "Couldn't reach the payment provider. Please try again." }, 502, request, env);
        }
      }

      // ---- Stripe: webhook (the source of truth that marks an order paid) -----
      // Stripe POSTs here after checkout. We verify the signature against the raw
      // body, then flip the matching order to `paid` with the PaymentIntent id.
      // ---- Unsubscribe --------------------------------------------------------
      // Three entry points, all keyed on the same signed token:
      //   GET  /unsubscribe?t=…              the link in the email footer
      //   POST /unsubscribe?t=…              Gmail/Outlook's own button (RFC 8058)
      //   POST /unsubscribe/resubscribe?t=…  the "that was a mistake" undo
      //
      // The GET unsubscribes IMMEDIATELY and then says so, rather than asking
      // "are you sure?" first. Deliberate: an extra step loses people who then
      // press the spam button instead, and one spam complaint does far more
      // damage to whether the rest of our email arrives than one unsubscribe.
      // They get a one-click undo on the page, which covers the misclick.
      if (path.endsWith("/unsubscribe/resubscribe") && request.method === "POST") {
        const addr = await unsubVerify(env, url.searchParams.get("t"));
        if (!addr) return new Response(unsubPage({ state: "error" }), { status: 400, headers: { "Content-Type": "text/html; charset=utf-8" } });
        const rows = await sbGet(env, "contacts", `email=eq.${encodeURIComponent(lc(addr))}&select=*`);
        const contact = rows && rows[0];
        if (contact) {
          await sbPatch(env, "contacts", `id=eq.${encodeURIComponent(contact.id)}`, {
            unsubscribed_at: null, unsubscribe_source: null, dnd_email: false, marketing_opt_in: true,
          });
          await logEmailEvent(env, { contact, email: addr, event: "unsubscribed", provider: "internal", detail: "resubscribed by the recipient" });
          await logConsent(env, {
            contact, email: addr, action: "opted_in", basis: "consent", source: "resubscribe",
            detail: "Changed their mind and resubscribed from the unsubscribe page.",
          });
        }
        return new Response(unsubPage({ email: addr, state: "resubscribed" }), { status: 200, headers: { "Content-Type": "text/html; charset=utf-8" } });
      }

      if (path.endsWith("/unsubscribe") && (request.method === "GET" || request.method === "POST")) {
        const token = url.searchParams.get("t");
        const addr = await unsubVerify(env, token);
        const oneClick = request.method === "POST";   // the mailbox provider's button

        if (!addr) {
          // A provider POSTing gets a plain response; a person gets the page.
          if (oneClick) return new Response("invalid token", { status: 400 });
          return new Response(unsubPage({ state: "error" }), { status: 400, headers: { "Content-Type": "text/html; charset=utf-8" } });
        }

        /* A GET only ASKS. Link scanners fetch every URL in an email before
           anyone sees it, so an unsubscribe that acts on being fetched removes
           people who never asked to go — which is exactly what happened on
           22 Sep 2026: a mail released from quarantine, Defender scanning its
           links, and a contact card saying she had unsubscribed.
           A genuine one-click from the mailbox provider is a POST (RFC 8058),
           and the button on the page posts too, so nothing a person does is
           lost. */
        if (!oneClick) {
          return new Response(unsubPage({ email: addr, state: "confirm", token }), {
            status: 200, headers: { "Content-Type": "text/html; charset=utf-8" },
          });
        }

        // Our own page posts a form; the provider's one-click doesn't.
        const fromPage = (request.headers.get("content-type") || "").includes("form");
        const rows = await sbGet(env, "contacts", `email=eq.${encodeURIComponent(lc(addr))}&select=*`);
        const contact = rows && rows[0];
        if (contact) {
          // Only the first click counts: a second visit to the same link (or the
          // mailbox's one-click after the footer link) isn't a second unsubscribe.
          const already = !!contact.unsubscribed_at;
          await unsubscribeContact(env, contact, fromPage ? "footer_link" : "list_unsubscribe");
          if (!already) {
            const aidRaw = url.searchParams.get("a"), sidRaw = url.searchParams.get("s");
            const uuidish = (v) => /^[0-9a-f-]{8,40}$/i.test(String(v || ""));
            await logEmailEvent(env, {
              contact, email: addr, event: "unsubscribed", provider: "internal",
              detail: fromPage ? "the button on the unsubscribe page" : "one-click via the mailbox provider",
              automationId: uuidish(aidRaw) ? aidRaw : null,
              nodeId: sidRaw ? String(sidRaw).slice(0, 80) : null,
            });
          }
        }
        // Unknown address: still report success. Confirming whether an address is
        // on the list would leak it, and there's nothing for them to fix anyway.

        // RFC 8058 wants a bare 200 for the one-click POST — no page, no redirect.
        if (!fromPage) return new Response("unsubscribed", { status: 200 });
        return new Response(unsubPage({ email: addr, state: "done", resubToken: token }), {
          status: 200, headers: { "Content-Type": "text/html; charset=utf-8" },
        });
      }

      // ---- Public: pay an invoice by card ---------------------------------
      // The client clicks this from their invoice email. No auth: the HMAC in
      // the token is the credential. Mints a fresh Checkout Session per click,
      // because Stripe sessions expire in 24 hours and invoices do not.
      if (path.endsWith("/invoicing/pay") && request.method === "GET") {
        const htmlPage = (title, msg, status) => new Response(invoicePayPage(title, msg), {
          status: status || 200, headers: { "Content-Type": "text/html; charset=utf-8" },
        });
        const invId = await invoicePayVerify(env, url.searchParams.get("t"));
        if (!invId) return htmlPage("That payment link isn't valid", "Please use the link in your most recent invoice email, or reply to that email and we'll sort it out.", 400);

        const rows = await sbGet(env, "invoices", `id=eq.${encodeURIComponent(invId)}&select=*`);
        const inv = rows && rows[0];
        if (!inv) return htmlPage("We couldn't find that invoice", "Please reply to your invoice email and we'll look into it.", 404);
        if (inv.status === "paid") return htmlPage("This invoice is already paid", `Invoice ${inv.number} has been settled - there's nothing more to do. Thank you.`);
        if (inv.status === "void") return htmlPage("This invoice has been cancelled", `Invoice ${inv.number} was voided, so there's nothing to pay.`);
        if (!env.STRIPE_SECRET_KEY) return htmlPage("Card payment isn't available yet", "Please pay by bank transfer using the details on your invoice, or reply to the email and we'll help.", 503);
        const amount = Math.round(Number(inv.total_pence) || 0);
        if (amount <= 0) return htmlPage("There's nothing to pay on this invoice", "Please reply to your invoice email if you think that's wrong.");

        const st = (await sbGet(env, "invoice_settings", "id=eq.1&select=*"))?.[0] || {};
        try {
          const session = await stripeApi(env, "checkout/sessions", {
            mode: "payment",
            "payment_method_types[0]": "card",
            success_url: `${unsubBase(env)}/invoicing/paid?t=${encodeURIComponent(url.searchParams.get("t") || "")}`,
            cancel_url: await invoicePayUrl(env, inv.id),
            customer_email: inv.bill_to_email || undefined,
            client_reference_id: inv.id,
            "metadata[invoice_id]": inv.id,
            "metadata[invoice_number]": inv.number || "",
            "line_items[0][quantity]": 1,
            "line_items[0][price_data][currency]": "gbp",
            "line_items[0][price_data][unit_amount]": amount,
            "line_items[0][price_data][product_data][name]": `Invoice ${inv.number}${st.company_name ? " - " + st.company_name : ""}`,
          });
          // Stored for tracing a payment back, not for reuse - it expires.
          await sbPatch(env, "invoices", `id=eq.${encodeURIComponent(inv.id)}`, { stripe_session_id: session.id });
          return Response.redirect(session.url, 302);
        } catch (e) {
          return htmlPage("We couldn't open the payment page", "Please try again in a moment, or reply to your invoice email and we'll take payment another way.", 502);
        }
      }

      // Where Stripe sends the client back. The webhook is what actually marks
      // the invoice paid; this page only reports, and says so honestly if the
      // webhook hasn't landed yet rather than claiming success it can't see.
      if (path.endsWith("/invoicing/paid") && request.method === "GET") {
        const invId = await invoicePayVerify(env, url.searchParams.get("t"));
        const inv = invId ? ((await sbGet(env, "invoices", `id=eq.${encodeURIComponent(invId)}&select=number,status`)) || [])[0] : null;
        const paid = inv && inv.status === "paid";
        return new Response(invoicePayPage(
          "Thank you - your payment went through",
          paid
            ? `Invoice ${inv.number} is now marked as paid. A receipt is on its way from Stripe.`
            : "Your receipt is on its way from Stripe. Our records can take a moment to catch up, so the invoice may still show as unpaid for a minute or two.",
        ), { status: 200, headers: { "Content-Type": "text/html; charset=utf-8" } });
      }

      if (path.endsWith("/stripe/webhook") && request.method === "POST") {
        const raw = await request.text();
        const ok = await stripeVerify(raw, request.headers.get("Stripe-Signature") || "", env.STRIPE_WEBHOOK_SECRET);
        if (!ok) return json({ error: "Bad signature" }, 400, request, env);
        let event;
        try { event = JSON.parse(raw); } catch (_) { return json({ error: "Bad JSON" }, 400, request, env); }
        if (event.type === "checkout.session.completed") {
          const s = event.data && event.data.object;
          const pi = s && (typeof s.payment_intent === "string" ? s.payment_intent : (s.payment_intent && s.payment_intent.id));

          // Invoices and orders both come through here, so tell them apart by
          // which metadata key is set rather than assuming everything is an
          // order. client_reference_id is NOT a safe fallback any more - both
          // paths set it.
          const invoiceId = s && s.metadata && s.metadata.invoice_id;
          if (invoiceId) {
            // status=neq.paid keeps this idempotent across Stripe's retries.
            const sel = `id=eq.${encodeURIComponent(invoiceId)}&status=neq.paid`;
            const paidAt = new Date().toISOString().slice(0, 10);
            try {
              const irows = await sbGet(env, "invoices", `id=eq.${encodeURIComponent(invoiceId)}&select=number,client_name,total_pence,status&limit=1`);
              const iv = (irows && irows[0]) || {};
              if (String(iv.status || "") !== "paid") {
                await notifyAdmins(env, {
                  area: "money", event: "invoice_paid",
                  title: `Invoice ${iv.number || ""} paid`.trim(),
                  body: [iv.client_name, gbpW(iv.total_pence)].filter(Boolean).join(" · "),
                  href: "/admin/invoicing", key: String(invoiceId),
                  meta: { invoice_id: invoiceId },
                });
              }
            } catch (_) {}
            let pr = await sbPatch(env, "invoices", sel, {
              status: "paid", paid_date: paidAt, payment_method: "card", payment_ref: pi || null,
            });
            // payment_ref only exists once supabase/invoicing_stripe.sql has run,
            // and PostgREST rejects the WHOLE patch for one unknown column. The
            // money has already left the client's account at this point, so fall
            // back to the columns that certainly exist rather than leaving the
            // invoice silently unpaid.
            if (!pr.ok) {
              pr = await sbPatch(env, "invoices", sel, { status: "paid", paid_date: paidAt, payment_method: "card" });
              if (!pr.ok) pr = await sbPatch(env, "invoices", sel, { status: "paid" });
              if (!pr.ok) {
                console.error("PAID BUT NOT RECORDED - invoice", invoiceId, "payment", pi,
                  "- run supabase/invoicing_stripe.sql and mark it paid by hand:",
                  await pr.text().catch(() => ""));
              }
            }
            // Invoices raised from a booking carry booking_id. Mark the shoot
            // paid too, so PIN release keys off something that actually
            // happened rather than someone remembering to tick a box.
            try {
              const irows = await sbGet(env, "invoices", `id=eq.${encodeURIComponent(invoiceId)}&select=booking_id,booking_source`);
              const iv = irows && irows[0];
              if (iv && iv.booking_id && iv.booking_source === "videography") {
                await sbPatch(env, "videography_bookings", `id=eq.${encodeURIComponent(iv.booking_id)}&paid_at=is.null`, {
                  paid_at: new Date().toISOString(),
                });
                // They may already have the gallery without the PIN. Close that
                // loop now rather than leaving it to someone noticing.
                await sendGalleryPinEmail(env, iv.booking_id);
              }
            } catch (_) { /* the invoice is paid either way; don't fail the webhook */ }
            return json({ received: true }, 200, request, env);
          }

          const editRequestId = s && s.metadata && s.metadata.edit_request_id;
          if (editRequestId) {
            // status=neq.paid keeps this idempotent across Stripe's retries.
            await sbPatch(env, "videography_edit_requests", `id=eq.${encodeURIComponent(editRequestId)}&status=neq.paid`, {
              status: "paid", paid_at: new Date().toISOString(), stripe_session_id: s.id || null,
            });
            await notifyEditRequest(env, editRequestId);
            return json({ received: true }, 200, request, env);
          }

          const orderId = (s && s.metadata && s.metadata.order_id) || (s && s.client_reference_id);
          if (orderId) {
            // Only existing columns here, so this can't fail if orders_stripe.sql
            // hasn't run yet. status=neq.paid keeps it idempotent on Stripe retries.
            await sbPatch(env, "orders", `id=eq.${encodeURIComponent(orderId)}&status=neq.paid`, {
              status: "paid", payment_ref: pi || null,
            });
            // Pack purchaser → make/merge a CRM contact.
            const orows = await sbGet(env, "orders", `id=eq.${encodeURIComponent(orderId)}&select=buyer_name,buyer_email,buyer_company,buyer_phone,pack_title,pack_slug,total_pence,user_id&limit=1`);
            await contactFromOrder(env, orows && orows[0]);
            /* Somebody bought something. Until now that told nobody at all --
               a pack could sell and the first anyone knew was opening Stripe. */
            try {
              const o0 = (orows && orows[0]) || {};
              await notifyAdmins(env, {
                area: "money", event: "pack_paid",
                title: `Pack bought — ${o0.pack_title || "a pack"}`,
                body: [o0.buyer_name || o0.buyer_email, o0.buyer_company, gbpW(o0.total_pence)].filter(Boolean).join(" · "),
                href: "/admin/orders", key: String(orderId),
                meta: { order_id: orderId, email: o0.buyer_email || null },
              });
            } catch (_) {}
            // …and start the "Order placed" automation. Gifting a pack from the
            // admin did this; a card purchase never did, so a real buyer got no
            // purchase email and no automation ran for them.
            const o = orows && orows[0];
            if (o && o.buyer_email) {
              const parts = String(o.buyer_name || "").trim().split(/\s+/);
              try {
                await fireTrigger(env, "order_placed", {
                  email: o.buyer_email,
                  first_name: parts.shift() || o.buyer_name || null,
                  last_name: parts.join(" ") || null,
                  phone: o.buyer_phone || null,
                  company: o.buyer_company || null,
                  source: "pack_purchase",
                  lifecycle: "customer",
                  tags: crmTags(o.buyer_email, ["Pack-Purchased", o.pack_title ? `Pack Name: ${o.pack_title}` : null], { member: !!o.user_id }),
                  user_id: o.user_id || null,
                }, { pack: o.pack_title || null, pack_slug: o.pack_slug || null, amount_pence: o.total_pence || 0 });
              } catch (e) { console.error("order_placed trigger", String((e && e.message) || e).slice(0, 200)); }
            }
          }
        }
        return json({ received: true }, 200, request, env);
      }

      // ---- Public: sign up, with a confirmation link that survives a scanner --
      //
      // Same reasoning as /auth/reset-link below. supabase.auth.signUp() sends
      // Supabase's own confirmation email, whose link a Microsoft mail scanner
      // consumes before the recipient sees it - so new members could not confirm
      // their account at all. generate_link creates the user AND hands back the
      // hashed_token, so we send our own branded email pointing at
      // /auth/callback, which verifies only once a human clicks.
      if (path.endsWith("/auth/signup") && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        const email = String((b && b.email) || "").trim().toLowerCase();
        const password = String((b && b.password) || "");
        const fullName = String((b && b.full_name) || "").trim().slice(0, 120);

        if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return json({ error: "Please enter a valid email address." }, 400, request, env);
        if (password.length < 8) return json({ error: "Choose a password of at least 8 characters." }, 400, request, env);

        // Said plainly rather than hidden. The sign-up form already tells people
        // when an address is taken - it has to, or they cannot act on it - so
        // pretending otherwise here would only make the form lie.
        const existing = await findUserByEmail(env, email);
        if (existing && existing.id) return json({ existing: true }, 200, request, env);

        const now = Date.now();
        const last = RESET_COOLDOWN.get("signup:" + email) || 0;
        if (now - last < 60_000) return json({ ok: true, needsConfirm: true }, 200, request, env);
        RESET_COOLDOWN.set("signup:" + email, now);

        try {
          const site = String(env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "");
          const gl = await fetch(`${env.SUPABASE_URL}/auth/v1/admin/generate_link`, {
            method: "POST",
            headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json" },
            body: JSON.stringify({
              type: "signup", email, password,
              options: { data: { full_name: fullName || null }, redirect_to: `${site}/account` },
            }),
          });
          if (!gl.ok) {
            const t = await gl.text().catch(() => "");
            if (/already|registered|exists/i.test(t)) return json({ existing: true }, 200, request, env);
            console.error("signup generate_link", gl.status, t.slice(0, 200));
            return json({ error: "Something went wrong creating your account. Please try again." }, 502, request, env);
          }
          const gj = await gl.json().catch(() => ({}));
          const hashed = (gj && (gj.hashed_token || (gj.properties && gj.properties.hashed_token))) || "";
          if (!hashed) {
            console.error("signup: no hashed_token in generate_link reply");
            return json({ error: "Something went wrong creating your account. Please try again." }, 502, request, env);
          }

          // The account exists now, so the person exists in the CRM now. This
          // used to happen only if they ticked the marketing box (via
          // /newsletter), so anyone who left it unticked had an account and no
          // contact — invisible in Contacts. Linked to the auth user, tagged as
          // a member, consent recorded either way. Best-effort: a CRM hiccup
          // must not stop the confirmation email going out.
          // The name has to be written onto the account by hand. generate_link
          // is handed it in `options.data` and does not keep it — Angel's
          // account came out as {"email_verified": true} and nothing else,
          // so nothing downstream (the hub greeting, the CRM, a personalised
          // email) had a name to use. Look the user up if the reply doesn't
          // carry the id, then set the metadata the way every other door does.
          let newUserId = (gj && ((gj.user && gj.user.id) || gj.id)) || null;
          try {
            if (!newUserId) { const found = await findUserByEmail(env, email); newUserId = (found && found.id) || null; }
            if (newUserId && fullName) {
              await fetch(`${env.SUPABASE_URL}/auth/v1/admin/users/${newUserId}`, {
                method: "PUT",
                headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json" },
                body: JSON.stringify({ user_metadata: { full_name: fullName } }),
              });
            }
          } catch (e) { console.error("signup: set name", String((e && e.message) || e).slice(0, 200)); }

          try {
            const nameParts = fullName.split(/\s+/).filter(Boolean);
            const optedIn = !!(b && b.marketing);
            await fireTrigger(env, "member_signup", {
              email, first_name: nameParts.shift() || null, last_name: nameParts.join(" ") || null,
              source: "signup", lifecycle: "member", marketing_opt_in: optedIn,
              tags: crmTags(email, [], { optIn: optedIn, member: true }),
              user_id: newUserId,
            }, { form: "signup" }, "join_signup");
            /* Their brand kit, now rather than whenever they happen to open
               the brand-kit page. An agent's first design should already be
               in their brand; a kit that fills itself in later is a kit that
               was empty exactly when it mattered. */
            await seedBrandKit(env, { userId: newUserId, email });
          } catch (e) { console.error("signup: contact upsert", String((e && e.message) || e).slice(0, 200)); }

          // Where they were heading when they signed up (a report link, say),
          // so confirming lands them there. Paths on this site only.
          const nx = String((b && b.next) || "");
          const nextQ = /^\/(?![\/\\])[^\s]*$/.test(nx) ? `&next=${encodeURIComponent(nx)}` : "";
          const link = `${site}/auth/callback?token_hash=${encodeURIComponent(hashed)}&type=signup${nextQ}`;
          const esc = (v) => String(v ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
          const first = (fullName.split(/\s+/)[0] || "there").trim();
          const content = `
            <h1 style="${EM_H1}">Confirm your email</h1>
            <p style="${EM_P}">Hi ${esc(first)},</p>
            <p style="${EM_P}">Thanks for creating a TMKE account. Click below to confirm your email and open your member hub.</p>
            <p style="margin:0 0 24px;"><a href="${esc(link)}" style="${EM_BTN}">Confirm my email</a></p>
            <p style="${EM_P}">If the button doesn't work, paste this into your browser:<br><span style="color:#371e28;word-break:break-all;">${esc(link)}</span></p>
            <p style="${EM_SMALL}">Didn't sign up? Ignore this email &mdash; the account stays unconfirmed and can't be used.</p>`;
          const html = await wrapInBrandedBase(env, content);
          const sent = await sendEmail(env, { to: email, subject: "Confirm your email - TMKE", html });
          await logAccountEmail(env, email, "Confirm your email - TMKE", sent);
          if (!sent.ok) {
            // The account exists now, so saying "try again" would be a lie - a
            // second attempt hits "already registered". Say what is true.
            console.error("signup send failed", sent.error);
            return json({ ok: true, needsConfirm: true, emailFailed: true }, 200, request, env);
          }
          return json({ ok: true, needsConfirm: true }, 200, request, env);
        } catch (e) {
          console.error("signup", String((e && e.message) || e).slice(0, 200));
          return json({ error: "Something went wrong creating your account. Please try again." }, 502, request, env);
        }
      }

      // ---- Public: send a password-reset link that survives a mail scanner ---
      //
      // Not supabase.auth.resetPasswordForEmail(). That sends Supabase's own
      // template, whose link is .../auth/v1/verify?token=... - a plain GET that
      // verifies and BURNS the token the moment anything requests it. Microsoft
      // Safe Links requests it, to scan it, before the human ever clicks. So the
      // customer opens a link that is genuinely already used and is told it has
      // expired. Outlook recipients could not reset their password at all.
      //
      // generate_link hands back the hashed_token as well as that doomed URL, so
      // we build our own: /auth/callback?token_hash=... That page is static HTML
      // and does the verification in JavaScript, in a real browser, after load.
      // A scanner fetching it gets markup and leaves the token untouched.
      //
      // It also means the wording and the branding are ours, and nothing depends
      // on a dashboard template propagating.
      if (path.endsWith("/auth/reset-link") && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        const email = String((b && b.email) || "").trim().toLowerCase();

        // One reply for every outcome, always 200: no account, rate-limited,
        // send failed, sent. This endpoint is public, so any difference between
        // those is a way of asking us which addresses have accounts.
        const same = () => json({ ok: true }, 200, request, env);
        if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return same();

        // Per-isolate, so it is a speed bump rather than a guarantee - Workers
        // spin up many isolates and this map dies with each one. It is enough to
        // stop a form being leant on, and the mail only ever goes to the account
        // holder, so the worst case is one person's inbox. A real limiter wants
        // KV, which this Worker has no binding for yet.
        const now = Date.now();
        const last = RESET_COOLDOWN.get(email) || 0;
        if (now - last < 60_000) return same();
        RESET_COOLDOWN.set(email, now);
        if (RESET_COOLDOWN.size > 5000) RESET_COOLDOWN.clear();   // crude, but unbounded is worse

        try {
          const u = await findUserByEmail(env, email);
          if (!u || !u.id) return same();

          const site = String(env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "");
          const gl = await fetch(`${env.SUPABASE_URL}/auth/v1/admin/generate_link`, {
            method: "POST",
            headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json" },
            body: JSON.stringify({ type: "recovery", email, options: { redirect_to: `${site}/reset-password` } }),
          });
          if (!gl.ok) { console.error("reset-link generate_link", gl.status, (await gl.text().catch(() => "")).slice(0, 200)); return same(); }
          const gj = await gl.json().catch(() => ({}));
          const hashed = (gj && (gj.hashed_token || (gj.properties && gj.properties.hashed_token))) || "";
          if (!hashed) { console.error("reset-link: no hashed_token in generate_link reply"); return same(); }

          const link = `${site}/auth/callback?token_hash=${encodeURIComponent(hashed)}&type=recovery`;
          const esc = (v) => String(v ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
          const content = `
            <h1 style="${EM_H1}">Set a new password</h1>
            <p style="${EM_P}">Someone asked to reset the password on your TMKE account. Click below to choose a new one.</p>
            <p style="margin:0 0 24px;"><a href="${esc(link)}" style="${EM_BTN}">Set a new password</a></p>
            <p style="${EM_P}">If the button doesn't work, paste this into your browser:<br><span style="color:#371e28;word-break:break-all;">${esc(link)}</span></p>
            <p style="${EM_SMALL}">The link works once and expires after an hour. If you didn't ask for this, ignore this email &mdash; your password stays exactly as it is.</p>`;
          const html = await wrapInBrandedBase(env, content);
          const sent = await sendEmail(env, { to: email, subject: "Set a new password - TMKE", html });
          await logAccountEmail(env, email, "Set a new password - TMKE", sent);
          // Logged, not returned: the caller is told the same thing either way.
          if (!sent.ok) console.error("reset-link send failed", sent.error);
        } catch (e) {
          console.error("reset-link", String((e && e.message) || e).slice(0, 200));
        }
        return same();
      }

      // ---- Admin: a receipt for one payment, as a PDF -----------------------
      //
      // Downloaded or emailed to accounts, not printed. The browser's print
      // dialog was losing the top of the document and produced something nobody
      // would want to send anyone.
      //
      // Stripe is asked again for the money. The label and the VAT split come
      // from the caller (that context is ours, and was computed by
      // /admin/payments moments earlier), but the amount, the fee and the date
      // are re-read from the charge so the figures on a document that reaches
      // an accounts team cannot be whatever a page happened to be holding.
      if (path.endsWith("/admin/payments/receipt") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        // Takings are management only, like the invoice ledger.
        if (!(await isManagement(env, user))) return json({ error: "Payments are management only." }, 403, request, env);
        if (!env.STRIPE_SECRET_KEY) return json({ error: "Stripe isn't configured on the Worker." }, 503, request, env);

        const b = await request.json().catch(() => ({}));
        const rowId = String((b && b.id) || "").trim();
        const action = (b && b.action) === "email" ? "email" : "download";
        // Two kinds of payment reach this page, so two sources of truth. A
        // Stripe charge is re-read from Stripe; an invoice settled by bank
        // transfer or direct debit never touched Stripe, so its own row is the
        // authority. Either way the money is re-read rather than trusted from
        // the browser.
        const offStripe = /^inv_[0-9a-f-]{36}$/i.test(rowId);
        if (!offStripe && !/^ch_[A-Za-z0-9]+$/.test(rowId)) return json({ error: "Missing or malformed payment id." }, 400, request, env);

        try {
          let gross, fee, refunded, paidAt, reference;
          if (offStripe) {
            const invId = rowId.slice(4);
            const inv = (await sbGet(env, "invoices", `id=eq.${encodeURIComponent(invId)}&select=id,number,total_pence,paid_date,payment_method&limit=1`))?.[0];
            if (!inv) return json({ error: "No such invoice." }, 404, request, env);
            gross = Number(inv.total_pence) || 0;
            fee = 0;                       // never went through Stripe
            refunded = 0;
            paidAt = new Date(`${inv.paid_date || new Date().toISOString().slice(0, 10)}T12:00:00Z`);
            reference = `${inv.number || invId}${inv.payment_method ? " · " + String(inv.payment_method).replace(/_/g, " ") : ""}`;
          } else {
            const charge = await stripeGet(env, `charges/${encodeURIComponent(rowId)}`, { "expand[]": "balance_transaction" });
            if (!charge || !charge.id) return json({ error: "No such payment." }, 404, request, env);
            const bt = charge.balance_transaction && typeof charge.balance_transaction === "object" ? charge.balance_transaction : null;
            gross = Number(charge.amount) || 0;
            fee = bt ? Number(bt.fee) || 0 : null;
            refunded = Number(charge.amount_refunded) || 0;
            paidAt = new Date((Number(charge.created) || 0) * 1000);
            reference = charge.id;
          }

          // Context from the caller, clamped: never wider than the money.
          const label    = String((b && b.label) || "Payment").slice(0, 160);
          const customer = String((b && b.customer) || "").slice(0, 160);
          const source   = String((b && b.source) || "").slice(0, 40);
          const derived  = !!(b && b.vat_derived);
          let vat = Number(b && b.vat_pence);
          if (!Number.isFinite(vat) || vat < 0 || vat > gross) vat = 0;
          const net = gross - vat;

          const st = (await sbGet(env, "invoice_settings", "id=eq.1&select=*"))?.[0] || {};
          const esc = (v) => String(v ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
          const money = (p) => (p == null ? "&mdash;" : "£" + (p / 100).toLocaleString("en-GB", { minimumFractionDigits: 2, maximumFractionDigits: 2 }));
          const when = paidAt.toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric", timeZone: "Europe/London" });
          const est = derived ? ' <span style="font-size:9pt;color:#8a6a3c;">est</span>' : "";
          const row = (k, v, strong) => `<tr>
            <td style="padding:7px 0;color:#6b5c61;font-size:10pt;">${esc(k)}</td>
            <td style="padding:7px 0;text-align:right;font-size:${strong ? "13pt;font-weight:700" : "10pt"};color:#241419;">${v}</td></tr>`;

          const html = `<!doctype html><html><head><meta charset="utf-8">
            <style>
              @page { size: A4; margin: 20mm; }
              body { font-family: Verdana, Geneva, sans-serif; color:#241419; margin:0; }
              .eyebrow { font-size:9pt; letter-spacing:0.18em; text-transform:uppercase; color:#8a8796; margin:0 0 6px; }
              h1 { font-size:20pt; font-weight:400; margin:0 0 4px; }
              .sub { font-size:10pt; color:#6b5c61; margin:0 0 26px; }
              table { width:100%; border-collapse:collapse; }
              .rule td { border-top:1px solid #e4dedf; }
              .total td { border-top:2px solid #371e28; padding-top:12px; }
              .foot { margin-top:28px; font-size:8.5pt; line-height:1.6; color:#8a8796; border-top:1px solid #e4dedf; padding-top:14px; }
            </style></head><body>
            <p class="eyebrow">${esc((st.company_name || "The Marketing Experts").toUpperCase())} &middot; Payment received</p>
            <h1>${esc(label)}</h1>
            <p class="sub">${esc(when)}${source ? " &middot; " + esc(source) : ""}</p>
            <table>
              ${row("Received from", esc(customer || "&mdash;"))}
              ${row("Date", esc(when))}
              ${source ? row("Source", esc(source)) : ""}
              <tr class="rule"><td colspan="2" style="height:8px;"></td></tr>
              ${row("Net", money(net) + est)}
              ${row("VAT", money(vat) + est)}
              <tr class="total">${`<td style="padding:12px 0 0;font-size:13pt;font-weight:700;">Gross paid</td><td style="padding:12px 0 0;text-align:right;font-size:13pt;font-weight:700;">${money(gross)}</td>`}</tr>
              <tr class="rule"><td colspan="2" style="height:8px;"></td></tr>
              ${offStripe ? "" : row("Stripe fee", money(fee))}
              ${row("Received in bank", money(fee == null ? null : gross - fee))}
              ${refunded ? row("Refunded", money(refunded)) : ""}
              ${row(offStripe ? "Reference" : "Stripe reference", esc(reference))}
            </table>
            <p class="foot">
              ${derived
                ? "The VAT shown was worked back from the total at the standard rate. This payment was taken outside the Hub, so no split was recorded at the time &mdash; confirm against the source before relying on it for a return."
                : "The VAT split shown is the one recorded when the payment was taken."}
              <br>A record of a payment received, not a VAT invoice.
              ${st.vat_number ? "<br>VAT number " + esc(st.vat_number) : ""}
            </p></body></html>`;

          const browser = await puppeteer.launch(env.BROWSER);
          let pdf;
          try {
            const page = await browser.newPage();
            await page.setContent(html, { waitUntil: "networkidle0" });
            pdf = await page.pdf({ printBackground: true, preferCSSPageSize: true });
          } finally { await browser.close(); }

          const stamp = paidAt.toISOString().slice(0, 10);
          const filename = `TMKE-receipt-${stamp}-${rowId}.pdf`;

          if (action === "email") {
            const to = String((b && b.to) || env.ACCOUNTS_PAYABLE_EMAIL || env.ACCOUNTS_NOTIFY || "").trim();
            if (!to) return json({ error: "No accounts address configured (ACCOUNTS_NOTIFY)." }, 503, request, env);
            const sent = await sendEmail(env, {
              to,
              subject: `Payment received - ${label} - ${money(gross).replace("&mdash;", "-")}`,
              html: await wrapInBrandedBase(env, `
                <h1 style="${EM_H1}">Payment received</h1>
                <p style="${EM_P}">${esc(label)}${customer ? " &mdash; " + esc(customer) : ""}, ${esc(when)}.</p>
                <p style="${EM_P}">Gross ${money(gross)}, of which VAT ${money(vat)}${derived ? " (estimated)" : ""}. ${offStripe ? "Settled outside Stripe, so the full amount reached the bank." : `Stripe fee ${money(fee)}, so ${money(fee == null ? null : gross - fee)} reached the bank.`}</p>
                <p style="${EM_P}">The receipt is attached, and the reference is <strong>${esc(reference)}</strong>.</p>`),
              attachments: [{ filename, content: bufToBase64(pdf), contentType: "application/pdf" }],
            });
            if (!sent.ok) return json({ error: sent.error || "The receipt didn't send." }, 502, request, env);
            return json({ ok: true, sent_to: to }, 200, request, env);
          }

          return new Response(pdf, {
            status: 200,
            headers: {
              ...corsHeaders(request, env),
              "Content-Type": "application/pdf",
              "Content-Disposition": `attachment; filename="${filename}"`,
            },
          });
        } catch (e) {
          console.error("payments/receipt", String((e && e.message) || e).slice(0, 300));
          return json({ error: "Couldn't build that receipt." }, 502, request, env);
        }
      }

      // ---- Admin: every payment, read from Stripe ---------------------------
      //
      // The one place that sees all of it. Packs, invoices and videography
      // upsells are already in our own tables - but Pixieset sells straight
      // into this same Stripe account and never touches the Hub, so our tables
      // can never be the complete list and Stripe always is.
      //
      // READ-ONLY on purpose. Nothing here writes back. There is exactly one
      // record of each payment (Stripe's), annotated with whatever context we
      // already hold, so nothing on this page can duplicate an order we
      // recorded ourselves.
      if (path.endsWith("/admin/payments") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        // Takings are management only, like the invoice ledger.
        if (!(await isManagement(env, user))) return json({ error: "Payments are management only." }, 403, request, env);
        if (!env.STRIPE_SECRET_KEY) return json({ error: "Stripe isn't configured on the Worker." }, 503, request, env);

        const u = new URL(request.url);
        const days = Math.min(Math.max(parseInt(u.searchParams.get("days") || "90", 10) || 90, 1), 3650);
        const since = Math.floor(Date.now() / 1000) - days * 86400;

        try {
          // Charges are the complete set (Pixieset's included). The balance
          // transaction is expanded so every row carries the fee Stripe
          // actually took, rather than a percentage we guessed at.
          const { rows: charges, truncated } = await stripeList(env, "charges", {
            "created[gte]": since, "expand[]": "data.balance_transaction",
          });

          // Our metadata rides on the Checkout Session, not the charge - Stripe
          // does not copy session metadata onto the PaymentIntent. Joining on
          // the payment intent is what tells us which of these charges were
          // ours and what they were for. Anything with no session is external.
          const { rows: sessions } = await stripeList(env, "checkout/sessions", { "created[gte]": since });
          const byPaymentIntent = new Map();
          for (const sess of sessions) {
            if (sess && sess.payment_intent) byPaymentIntent.set(String(sess.payment_intent), sess);
          }

          const paid = charges.filter((c) => c && c.status === "succeeded");

          // Classify first, then fetch the splits we hold in one query per kind
          // rather than one per row.
          const classify = (c) => {
            const sess = c.payment_intent ? byPaymentIntent.get(String(c.payment_intent)) : null;
            const md = (sess && sess.metadata) || {};
            if (md.edit_request_id) return { source: "videography", ref: String(md.edit_request_id), kind: md.upsell_type || null };
            if (md.invoice_id)      return { source: "invoice",     ref: String(md.invoice_id),     number: md.invoice_number || null };
            if (md.order_id)        return { source: "pack",        ref: String(md.order_id) };
            return { source: "external", ref: null };
          };
          const tagged = paid.map((c) => ({ charge: c, ...classify(c) }));

          const idsFor = (src) => [...new Set(tagged.filter((t) => t.source === src && t.ref).map((t) => t.ref))];
          const inList = (ids) => `(${ids.map((i) => `"${i}"`).join(",")})`;
          const fetchSplits = async (src, table, select) => {
            const ids = idsFor(src);
            if (!ids.length) return new Map();
            try {
              const rows = await sbGet(env, table, `id=in.${inList(ids)}&select=${select}`);
              return new Map((rows || []).map((r) => [String(r.id), r]));
            } catch (_) { return new Map(); }   // a missing split is worth less than a missing page
          };
          const [orderById, invoiceById, editById] = await Promise.all([
            fetchSplits("pack", "orders", "id,pack_title,buyer_name,buyer_email,amount_pence,vat_pence,total_pence"),
            fetchSplits("invoice", "invoices", "id,number,booking_source,subtotal_pence,vat_pence,total_pence"),
            fetchSplits("videography", "videography_edit_requests", "id,booking_id,twilight_items,extra_images_qty,vat_pence,total_pence"),
          ]);

          // The rate only matters for payments we hold no split for - Pixieset
          // quotes tax-inclusive, so its gross is worked backwards at the same
          // rate the invoices use. Flagged as derived so nobody files a VAT
          // return off a number we inferred.
          let vatRate = 20;
          try {
            const st = (await sbGet(env, "invoice_settings", "id=eq.1&select=vat_rate"))?.[0];
            if (st && st.vat_rate != null) vatRate = Number(st.vat_rate);
          } catch (_) {}

          // An invoice is a billing mechanism, not a category of work. What
          // matters when you're splitting income is which service earned it, so
          // a shoot invoice counts as videography and a social one as social -
          // landing in the same bucket as a card payment for the same thing.
          // "Invoice" is left for genuinely ad-hoc billing that belongs to
          // neither, which is what booking_source not being set means.
          const invoiceSource = (v) => v === "smm" ? "social" : v === "videography" ? "videography" : "invoice";

          const out = tagged.map(({ charge: c, source, ref, kind, number }) => {
            const bt = c.balance_transaction && typeof c.balance_transaction === "object" ? c.balance_transaction : null;
            const gross = Number(c.amount) || 0;
            const refunded = Number(c.amount_refunded) || 0;
            const fee = bt ? Number(bt.fee) || 0 : null;

            let net = null, vat = null, derived = true, label = c.description || "Payment", customer = null;
            // What the row is filed under. Only invoices move; everything else
            // is already the category it belongs to.
            let emitSource = source;
            if (source === "pack") {
              const r = orderById.get(ref);
              if (r) {
                label = r.pack_title || "Pack";
                customer = r.buyer_name || r.buyer_email || null;
                if (r.vat_pence != null) { net = Number(r.amount_pence) || 0; vat = Number(r.vat_pence) || 0; derived = false; }
              }
            } else if (source === "invoice") {
              const r = invoiceById.get(ref);
              label = `Invoice ${(r && r.number) || number || ""}`.trim();
              emitSource = invoiceSource(r && r.booking_source);
              if (r && r.vat_pence != null) { net = Number(r.subtotal_pence) || 0; vat = Number(r.vat_pence) || 0; derived = false; }
            } else if (source === "videography") {
              const r = editById.get(ref);
              if (r) {
                const tw = Array.isArray(r.twilight_items) ? r.twilight_items.length : 0;
                label = tw ? `Faux twilight - ${tw} image${tw === 1 ? "" : "s"}`
                     : r.extra_images_qty ? `${r.extra_images_qty} extra images` : "Videography upsell";
                if (r.vat_pence != null) { vat = Number(r.vat_pence) || 0; net = (Number(r.total_pence) || gross) - vat; derived = false; }
              } else if (kind) {
                label = kind === "twilight" ? "Faux twilight" : "Extra images";
              }
            }
            // No split of our own: treat what was charged as tax-inclusive.
            if (net == null || vat == null) {
              net = Math.round(gross / (1 + vatRate / 100));
              vat = gross - net;
              derived = true;
            }

            return {
              id: c.id,
              paid_at: new Date((Number(c.created) || 0) * 1000).toISOString(),
              source: emitSource, ref, label,
              customer: customer || (c.billing_details && c.billing_details.name) || (c.billing_details && c.billing_details.email) || null,
              gross_pence: gross,
              net_pence: net,
              vat_pence: vat,
              vat_derived: derived,
              fee_pence: fee,
              received_pence: fee == null ? null : gross - fee,
              refunded_pence: refunded,
              receipt_url: c.receipt_url || null,
            };
          });

          // ---- Money that never went through Stripe ------------------------
          // An invoice settled by bank transfer or direct debit is real income
          // that Stripe has never heard of, so a page reading Stripe alone is
          // not "all the money in" - which is the only thing this page is for.
          //
          // Invoices PAID BY CARD are already above, as charges carrying
          // metadata.invoice_id. Those are matched by id and skipped, so a card
          // invoice appears once, not twice.
          try {
            const sinceDate = new Date(since * 1000).toISOString().slice(0, 10);
            // Card-paid invoices are already above, but they may be filed as
            // videography or social now - so match on the id, not the category.
            const seenInvoices = new Set(out.filter((r) => r.ref).map((r) => String(r.ref)));
            const paidInvoices = await sbGet(env, "invoices",
              `status=eq.paid&paid_date=gte.${sinceDate}`
              + "&select=id,number,booking_source,bill_to_name,subtotal_pence,vat_pence,total_pence,paid_date,payment_method&limit=1000");
            for (const inv of paidInvoices || []) {
              if (seenInvoices.has(String(inv.id))) continue;
              const gross = Number(inv.total_pence) || 0;
              if (!gross) continue;
              const vat = Number(inv.vat_pence);
              const hasSplit = Number.isFinite(vat);
              const method = String(inv.payment_method || "").replace(/_/g, " ").trim();
              out.push({
                id: `inv_${inv.id}`,
                paid_at: new Date(`${inv.paid_date}T12:00:00Z`).toISOString(),
                source: invoiceSource(inv.booking_source), ref: String(inv.id),
                label: `Invoice ${inv.number || ""}`.trim() + (method && method !== "card" ? ` (${method})` : ""),
                customer: inv.bill_to_name || null,
                gross_pence: gross,
                net_pence: hasSplit ? (Number(inv.subtotal_pence) || gross - vat) : Math.round(gross / (1 + vatRate / 100)),
                vat_pence: hasSplit ? vat : gross - Math.round(gross / (1 + vatRate / 100)),
                vat_derived: !hasSplit,
                // No Stripe, so no Stripe fee, and the whole amount arrived.
                fee_pence: 0,
                received_pence: gross,
                refunded_pence: 0,
                off_stripe: true,
                receipt_url: null,
              });
            }
          } catch (e) {
            // Better a Stripe-only list than none - but say so, loudly, because
            // a payments page quietly missing payments is the worst outcome here.
            console.error("payments: off-Stripe invoices", String((e && e.message) || e).slice(0, 200));
          }

          // Which sector each payment goes under (Revenue, Dani 5 Nov).
          try {
            const overrides = await revenueOverrides(env);
            const isInvoice = (r) => r.off_stripe || (tagged.find((t) => t.charge.id === r.id) || {}).source === "invoice";
            const invIds = [...new Set(out.filter((r) => r.ref && isInvoice(r)).map((r) => String(r.ref)))];
            const invRows = [];
            for (const part of chunks(invIds, 80)) {
              const rows = (await sbGet(env, "invoices", `id=in.(${part.join(",")})&select=${BOOK_COLS}`)) || (await sbGet(env, "invoices", `id=in.(${part.join(",")})&select=id,booking_id,booking_source,recurring_id,billing_month,bill_to_name,bill_to_email,status`)) || [];
              invRows.push(...rows);
            }
            const ctx = invRows.length ? await invoiceContext(env, invRows) : null;
            const byInv = new Map(invRows.map((v) => [String(v.id), invoiceBookRow(v, ctx)]));
            for (const r of out) {
              const v = isInvoice(r) ? byInv.get(String(r.ref)) : null;
              if (v) { r.sector = v.sector; r.rule = v.rule; continue; }
              r.rule = r.source === "pack" ? "packs" : r.source === "videography" ? "video-extras" : r.source === "external" ? "pixieset" : "other";
              r.sector = sectorForRule(r.rule, overrides);
            }
          } catch (e) { console.error("payments: sectors", String((e && e.message) || e).slice(0, 200)); }

          out.sort((a, b) => (a.paid_at < b.paid_at ? 1 : -1));

          return json({ ok: true, days, vat_rate: vatRate, truncated, payments: out }, 200, request, env);
        } catch (e) {
          return json({ error: String((e && e.message) || e).slice(0, 300) }, 502, request, env);
        }
      }

      // ---- AI: generate a social caption (+ hashtags) for a member's post ----
      // Two routes: a structured PROPERTY post, or a free-form "what's it about".
      // The voice rules live in CAPTION_RULES so the client's own captioning
      // guidelines can be dropped in later without touching the wiring.
      // ---- Admin: Claude drafts a Content calendar post's words (Dani, 9 Nov) -----
      // Reads the design (its picture and the words on it), the title and the team's
      // note. It only returns a draft: the page saves it, and only into empty boxes.
      if (path.endsWith("/calendar/draft-words") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!env.ANTHROPIC_API_KEY) return json({ error: "AI isn't configured - set the ANTHROPIC_API_KEY secret on the Worker." }, 503, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String((b && b.post_id) || "").trim();
        if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)) return json({ error: "Post not found." }, 404, request, env);
        const post = (await sbGet(env, "content_month_posts", `id=eq.${id}&select=title,post_type,pillar,note,occasion,date_tied,template_id,month_id&limit=1`))?.[0];
        if (!post) return json({ error: "Post not found." }, 404, request, env);
        if (!post.template_id) return json({ error: "Link a design first. Claude reads it to write the words." }, 400, request, env);
        const tpl = (await sbGet(env, "templates", `id=eq.${encodeURIComponent(post.template_id)}&select=name,thumb_url,elements,pages&limit=1`))?.[0];
        if (!tpl) return json({ error: "That post's design couldn't be found." }, 404, request, env);
        const month = (await sbGet(env, "content_months", `id=eq.${post.month_id}&select=intro&limit=1`))?.[0];
        const pages = Array.isArray(tpl.pages) && tpl.pages.length ? tpl.pages : [{ elements: tpl.elements || [] }];
        const onDesign = pages.map((pg, i) => { const words = (pg.elements || []).map((el) => el && (el.text || el.content)).filter((t) => typeof t === "string" && t.trim()).map((t) => t.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim()); return words.length ? `Page ${i + 1}: ${words.join(" | ")}` : ""; }).filter(Boolean).join("\n").slice(0, 3000);
        const content = [];
        try {
          if (tpl.thumb_url && /^https:/.test(tpl.thumb_url)) {
            const pic = await fetch(tpl.thumb_url);
            const type = (pic.headers.get("content-type") || "").split(";")[0];
            if (pic.ok && /^image\/(jpeg|png|webp|gif)$/.test(type)) {
              const buf = await pic.arrayBuffer();
              if (buf.byteLength < 4500000) content.push({ type: "image", source: { type: "base64", media_type: type, data: bufToBase64(buf) } });
            }
          }
        } catch (_) { /* the words on the design are still enough to draft from */ }
        if (!content.length && !onDesign) return json({ error: "That design has no picture or words to read yet. Save it in the Studio first." }, 400, request, env);
        const reel = post.post_type === "reel";
        const facts = [
          post.title ? `Post: ${post.title}` : "",
          `Format: ${reel ? "Reel" : post.post_type === "carousel" ? "Carousel" : "Single image"}`,
          post.pillar ? `Content pillar: ${post.pillar}` : "",
          post.date_tied && post.occasion ? `It's for: ${post.occasion}` : "",
          month && month.intro ? `This month is about: ${month.intro}` : "",
          post.note ? `Note from the team: ${post.note}` : "",
          onDesign ? `The words on the design (some may be guidance or sample text for the agent to replace):\n${onDesign}` : "",
        ].filter(Boolean).join("\n");
        const prompt = `TMKE writes a monthly content calendar for UK estate agents. Each post is a template the agent edits in the TMKE Studio and then posts as their own. Draft the words for this post, using the design${content.length ? " in the image" : ""} and these details.\n\n${facts}\n\nThree parts:\n\n` +
          `what_to_film: ${reel ? "what the agent should film and say for this Reel: the shots in order, and any lines to say. Practical, short, written to the agent." : "leave this empty, it isn't a Reel."}\n\n` +
          `how_to_edit: what the agent changes on this design before posting, based only on what's on it (for example the photo, the price, the street, the headline). Two or three short sentences, written to the agent as "you". No em dashes.\n\n` +
          `caption: the post's caption, following these rules:\n- ${CAPTION_RULES}\n\nThe caption has to work for any agent who uses it. Where the agent's own details belong, use exactly these tags, which fill in automatically: {company name}, {area}, {website}, {agent name}, {agent first name}, {telephone}, {email}. Where the agent must type something specific, use square brackets such as [price], [street] or [school name]. Never invent a place, price, name or statistic.`;
        content.push({ type: "text", text: prompt });
        const schema = { type: "object", properties: { what_to_film: { type: "string" }, how_to_edit: { type: "string" }, caption: { type: "string" } }, required: ["what_to_film", "how_to_edit", "caption"], additionalProperties: false };
        let res, out;
        try {
          res = await aiFetch(env, "write", { max_tokens: 2000, output_config: { format: { type: "json_schema", schema } }, messages: [{ role: "user", content }] });
          out = await res.json().catch(() => null);
        } catch (e) { return json({ error: "Couldn't reach Claude: " + (e.message || e) }, 502, request, env); }
        if (!res.ok || !out) {
          const why = (out && out.error && out.error.message) || "";
          if (/credit balance/i.test(why)) return json({ error: "The Claude API credit has run out. Top it up at console.anthropic.com, under Billing." }, 502, request, env);
          return json({ error: why || ("Claude said " + res.status) }, 502, request, env);
        }
        let r = null;
        try { r = JSON.parse((out.content || []).filter((c) => c.type === "text").map((c) => c.text).join("")); } catch (_) {}
        if (!r) return json({ error: "Claude didn't return a usable draft. Please try again." }, 502, request, env);
        return json({ what_to_film: reel ? r.what_to_film : "", how_to_edit: r.how_to_edit, caption: r.caption }, 200, request, env);
      }

      if (path.endsWith("/ai/caption") && request.method === "POST") {
        if (!cheapValid(request)) return json({ error: "Sign in to use AI." }, 401, request, env);
        if (!env.ANTHROPIC_API_KEY) return json({ error: "AI isn't configured - set the ANTHROPIC_API_KEY secret on the Worker." }, 503, request, env);
        let body; try { body = await request.json(); } catch (_) { return json({ error: "Bad JSON" }, 400, request, env); }
        const mode = body.mode === "property" ? "property" : "general";
        const clean = (v, n) => String(v == null ? "" : v).replace(/\s+/g, " ").trim().slice(0, n || 200);


        let brief;
        if (mode === "property") {
          const p = body.property || {};
          const angleMap = { "coming-soon": "Coming soon", "new-to-market": "New to market", "open-house": "Open house / viewing day", "price-adjustment": "Price adjustment", "just-sold": "Just sold / let" };
          const fields = [
            p.location ? `Location: ${clean(p.location, 120)}` : "",
            p.propertyType ? `Property type: ${clean(p.propertyType, 80)}` : "",
            p.beds ? `Bedrooms: ${clean(p.beds, 20)}` : "",
            p.price ? `Price: ${clean(p.price, 40)}` : "",
            (p.angle && angleMap[p.angle]) ? `Post angle: ${angleMap[p.angle]}` : "",
            p.features ? `Standout features: ${clean(p.features, 600)}` : "",
          ].filter(Boolean).join("\n");
          if (!fields) return json({ error: "Add at least a location or a couple of details." }, 400, request, env);
          brief = `Write a caption for a PROPERTY post (service-led content). Use only these details:\n${fields}`;
        } else {
          const topic = clean(body.topic, 900);
          if (!topic) return json({ error: "Tell us what the post is about." }, 400, request, env);
          brief = `Write a caption for a social post about the following. Judge from it whether this is service-led or personal/community content, and pitch the tone accordingly:\n${topic}`;
        }

        // Hashtags: off by default unless the member ticks "add hashtags"; max 4.
        const wantTags = body.hashtags === true;
        const tagsLine = wantTags
          ? "\n\nAlso provide UP TO FOUR genuinely relevant hashtags separately (location, property, estate agency, community). Fewer than four is fine; never a long block of generic tags."
          : "\n\nDo not include any hashtags; return an empty hashtags array.";
        /* Merge tags (Dani, 18 Oct): the member's agency and area come from
           their brand kit in the Hub, which fills these in, or leaves a
           [bracket] to fill when the kit doesn't say. So the AI never guesses
           a name or a town. */
        const mergeLine = "\n\nMERGE TAGS: never write an estate agency's name or the agent's general area yourself. Wherever the caption or a hashtag would name the agency, write {agency}; wherever it would name the agent's town or area (and no location was given above), write {area}. In hashtags use them inside the tag, e.g. #{area}Homes or #{agency}. A location given in the details above may be written as given.";

        // The member's own brand tone of voice (from their Brand Kit). Takes
        // priority on tone/personality, but the house rules above still hold —
        // especially the emoji limit.
        const tone = clean(body.tone, 800);
        const toneBlock = tone ? `\n\nThis client's own brand voice - match it closely for tone and personality (while still following every rule above, especially the one-emoji limit):\n${tone}` : "";
        const prompt = `- ${CAPTION_RULES}${toneBlock}\n\n${brief}${tagsLine}${mergeLine}\n\nReturn ONLY minified JSON, no markdown fences, exactly: {"caption": "caption text with line breaks as \\n", "hashtags": ["#tag1", "#tag2"]}.`;
        let aiRes;
        try {
          aiRes = await aiFetch(env, "write", { max_tokens: 4000, messages: [{ role: "user", content: prompt }] });
        } catch (e) { return json({ error: "Couldn't reach the AI service." }, 502, request, env); }
        if (!aiRes.ok) { const t = await aiRes.text().catch(() => ""); return json({ error: aiFailMessage(aiRes.status, t), detail: t.slice(0, 300) }, 502, request, env); }
        const dataRes = await aiRes.json();
        const text = (dataRes.content || []).filter((c) => c.type === "text").map((c) => c.text).join("").trim();
        let out;
        try { const s = text.indexOf("{"), e = text.lastIndexOf("}"); out = JSON.parse(text.slice(s, e + 1)); } catch (_) { out = { caption: text, hashtags: [] }; }
        const caption = String(out.caption || "").trim();
        let hashtags = (wantTags && Array.isArray(out.hashtags)) ? out.hashtags.map((h) => String(h).trim()).filter(Boolean).map((h) => (h[0] === "#" ? h : "#" + h.replace(/^#+/, ""))).slice(0, 4) : [];
        if (!caption) return json({ error: "Couldn't generate a caption - please try again." }, 502, request, env);
        return json({ ok: true, caption, hashtags }, 200, request, env);
      }

      // ---- AI: the helper on a design's Edit tab (Dani, 10 Nov) ----
      // Turned on per design by the author, with a brief. Reads each text
      // box's guidance and current words, plus what the member says, and
      // writes the words for each box. Never invents facts.
      if (path.endsWith("/ai/fields") && request.method === "POST") {
        if (!(await getUser(request, env))) return json({ error: "Sign in again to use the AI helper." }, 401, request, env);
        if (!env.ANTHROPIC_API_KEY) return json({ error: "AI isn't configured." }, 503, request, env);
        let body; try { body = await request.json(); } catch (_) { return json({ error: "Bad JSON" }, 400, request, env); }
        const clip = (v, n) => String(v == null ? "" : v).trim().slice(0, n);
        const fields = (Array.isArray(body.fields) ? body.fields : []).slice(0, 40).map((f) => ({
          key: clip(f && f.key, 80), page: Number(f && f.page) || 1, label: clip(f && f.label, 300), current: clip(f && f.current, 1500),
        })).filter((f) => f.key);
        if (!fields.length) return json({ error: "There's no text on this design for it to write." }, 400, request, env);
        const brief = clip(body.brief, 2000), notes = clip(body.notes, 2000), tone = clip(body.tone, 800);
        // The rest of what it reads (Dani, 10 Nov): the post's caption, title and
        // how-to-edit, the design's caption prompt, and every other word on it.
        const post = body.post && typeof body.post === "object" ? body.post : {};
        const postTitle = clip(post.title, 200), postCaption = clip(post.caption, 3000), postHow = clip(post.how_to_edit, 1500);
        const captionPrompt = clip(body.captionPrompt, 1000);
        const others = (Array.isArray(body.others) ? body.others : []).slice(0, 60)
          .map((o) => `- page ${Number(o && o.page) || 1}: ${JSON.stringify(clip(o && o.text, 400))}`).join("\n");
        const boxes = fields.map((f) => `- key: ${f.key}\n  page: ${f.page}\n  guidance from the designer: ${f.label || "(none)"}\n  words in the box now (${f.current.length} characters): ${JSON.stringify(f.current)}`).join("\n");
        const prompt = [
          "You help an estate agent fill in the text boxes on a social media design made for them by The Marketing Experts. Write the words that go in each box.",
          "RULES:",
          "- Follow the designer's guidance for each box, and the designer's brief, exactly: word counts, limits, what to leave alone.",
          "- Keep each box close to the length of the words in it now unless the guidance says otherwise, so the design still fits. A short heading stays a short heading.",
          "- Use only the facts the agent gives you. Never invent names, places, prices, numbers or events. Where a fact is needed and you weren't given it, write a short placeholder in square brackets, e.g. [street name].",
          "- A box that is a fixed heading or label, or that the guidance says to keep, comes back exactly as it is now.",
          "- Write as the agent, in the first person where it fits, in plain, warm, confident British English with contractions. No em dashes, no exclamation marks, no emoji, no hashtags.",
          "- Avoid AI-sounding phrases: in today's market, ever wondered, here's why, game changer, unlock, elevate, delve, seamless, dream home, forever home, your next chapter.",
          "- Keep line breaks only where the box has them now.",
          tone ? `\nThe agent's own brand voice, to match for tone:\n${tone}` : "",
          brief ? `\nThe designer's brief for this design:\n${brief}` : "",
          postTitle ? `\nThe post this design is for: ${postTitle}` : "",
          postCaption ? `\nThe caption that goes with this post (the design's words should sit well with it, not repeat it word for word):\n${postCaption}` : "",
          postHow ? `\nHow the agent is told to edit this design:\n${postHow}` : "",
          captionPrompt ? `\nWhat the caption is meant to be about:\n${captionPrompt}` : "",
          others ? `\nOther words already on the design, which stay as they are (for context only):\n${others}` : "",
          `\nWhat the agent has told you:\n${notes || "(nothing yet; write good general words and leave [brackets] for any facts)"}`,
          `\nThe text boxes, in order:\n${boxes}`,
          `\nReturn ONLY minified JSON, no markdown fences, exactly: {"fields":[{"key":"<key>","text":"<words, line breaks as \\n>"}]} with one entry for every box, in the same order.`,
        ].filter(Boolean).join("\n");
        let aiRes;
        try { aiRes = await aiFetch(env, "write", { max_tokens: 4000, messages: [{ role: "user", content: prompt }] }); }
        catch (_) { return json({ error: "Couldn't reach the AI service." }, 502, request, env); }
        if (!aiRes.ok) { const t = await aiRes.text().catch(() => ""); return json({ error: aiFailMessage(aiRes.status, t) }, 502, request, env); }
        const dataRes = await aiRes.json();
        const text = (dataRes.content || []).filter((c) => c.type === "text").map((c) => c.text).join("").trim();
        let out;
        try { const s0 = text.indexOf("{"), e0 = text.lastIndexOf("}"); out = JSON.parse(text.slice(s0, e0 + 1)); } catch (_) { out = null; }
        const keys = new Set(fields.map((f) => f.key));
        const list = (out && Array.isArray(out.fields) ? out.fields : [])
          .filter((r) => r && keys.has(String(r.key)))
          .map((r) => ({ key: String(r.key), text: String(r.text || "").replace(/—/g, ",").replace(/\s+,/g, ",").trim() }));
        if (!list.length) return json({ error: "It didn't come back with anything. Try again." }, 502, request, env);
        return json({ ok: true, fields: list }, 200, request, env);
      }

      // ---- AI: the Help Centre's "Ask first" (Dani, 17 Oct) ----
      // Pack support and Quick question open on a chat. It answers from what
      // the hub is and from the member's own account -- their packs, brand
      // kit, designs, bookings and managed socials -- read here with the
      // VERIFIED user's id and email, never from what the page claims (bar the
      // pack list, which the page works out by the same rules as the Studio
      // and is only ever their own). Nothing sensitive goes in: no payments,
      // phone numbers, addresses or anyone else's data. When it can't help it
      // says so and the member sends the message to the team instead.
      if (path.endsWith("/ai/help") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in to use this." }, 401, request, env);
        if (!env.ANTHROPIC_API_KEY) return json({ error: "AI isn't configured." }, 503, request, env);
        let body; try { body = await request.json(); } catch (_) { return json({ error: "Bad JSON" }, 400, request, env); }
        const clean = (v, n) => String(v == null ? "" : v).replace(/\s+/g, " ").trim().slice(0, n || 200);
        const line = body.line === "pack_support" ? "Pack support" : "Quick question";
        const turns = (Array.isArray(body.messages) ? body.messages : [])
          .filter((m) => m && (m.role === "user" || m.role === "assistant") && String(m.content || "").trim())
          .slice(-8)
          .map((m) => ({ role: m.role, content: String(m.content).slice(0, 1500) }));
        if (!turns.length || turns[turns.length - 1].role !== "user") return json({ error: "Ask a question first." }, 400, request, env);
        if (turns[0].role !== "user") turns.shift();

        // Their account, briefly. Each read on its own: one failing costs that
        // line of context, not the answer.
        const uid = encodeURIComponent(user.id);
        const em = encodeURIComponent(String(user.email || "").toLowerCase());
        const safe = (p) => p.then((r) => r || []).catch(() => []);
        const [designs, kits, vids, leads] = await Promise.all([
          safe(sbGet(env, "user_designs", `user_id=eq.${uid}&select=name,updated_at,canvas->>width,canvas->>height&order=updated_at.desc&limit=200`)),
          safe(sbGet(env, "member_brand_kits", `user_id=eq.${uid}&select=kit,updated_at&limit=1`)),
          safe(sbGet(env, "videography_bookings", `or=(account_user_id.eq.${uid},client_email.ilike.${em})&select=kind,service,service_type,package,shoot_date,stage&order=shoot_date.desc.nullslast&limit=10`)),
          safe(sbGet(env, "smm_leads", `or=(account_user_id.eq.${uid},email.ilike.${em})&select=kind,pipeline_stage,client_status,package_name,platforms,start_date,call_at&order=created_at.desc&limit=5`)),
        ]);
        const kit = (kits[0] && kits[0].kit) || {};
        const packs = (Array.isArray(body.packs) ? body.packs : []).slice(0, 40).map((p) => clean(p, 80)).filter(Boolean);
        const ctx = [];
        ctx.push(`Packs they have in their Studio: ${packs.length ? packs.join("; ") : "none listed"}.`);
        ctx.push(`Saved Studio designs: ${designs.length}${designs.length ? ` (most recent: ${designs.slice(0, 5).map((d) => `"${clean(d.name || "Untitled", 60)}"${d.width && d.height ? ` ${d.width}x${d.height}` : ""}`).join(", ")})` : ""}.`);
        const colours = Array.isArray(kit.colors) ? kit.colors.length : 0;
        const logos = Array.isArray(kit.logos) ? kit.logos.length : 0;
        const fonts = kit.fonts ? [kit.fonts.heading, kit.fonts.subheading, kit.fonts.body].map((f) => (f && (f.family || f.name || f)) || "").filter((f) => typeof f === "string" && f).join(", ") : "";
        ctx.push(kits.length
          ? `Brand Kit: company "${clean(kit.company, 80) || "not set"}", ${colours} colour${colours === 1 ? "" : "s"}, ${logos} logo${logos === 1 ? "" : "s"}, fonts: ${fonts || "not set"}, their name ${kit.about && kit.about.name ? "set" : "not set"}, tone of voice ${kit.tone ? "set" : "not set"}.`
          : "Brand Kit: not set up yet.");
        ctx.push(vids.length
          ? `Videography bookings: ${vids.map((b) => `${clean(b.package || b.service || b.service_type || b.kind, 60)}${b.shoot_date ? " on " + String(b.shoot_date).slice(0, 10) : ""} (stage: ${clean(b.stage, 30)})`).join("; ")}.`
          : "Videography bookings: none.");
        const client = leads.find((l) => l.kind !== "discovery" && (l.client_status || l.package_name));
        const call = leads.find((l) => l.kind === "discovery");
        ctx.push(client
          ? `Managed social media: ${clean(client.package_name, 60) || "a package"}${Array.isArray(client.platforms) && client.platforms.length ? " on " + client.platforms.join(", ") : ""}, status ${clean(client.client_status || client.pipeline_stage, 30)}${client.start_date ? ", started " + String(client.start_date).slice(0, 10) : ""}.`
          : call ? `Managed social media: a discovery call${call.call_at ? " on " + String(call.call_at).slice(0, 10) : ""}, not a client yet.` : "Managed social media: not a client.");

        const HUB = [
          "Dashboard (/account): their week, inspiration, the Training Studio and what's new in the Studio.",
          "The Studio (/account/studio): 'Your packs' are the template packs they have; 'Your designs' are designs they've saved (all of them at /account/editor, filterable All / Digital / Print); 'Create new design' starts one; Design tools are the Caption Generator (AI captions), the QR Code Generator, the Brand Kit and Templates.",
          "Brand Kit (/account/profile): their colours, fonts, logos, details and tone of voice, used across their designs.",
          "Marketing Planner (/account/schedule): every marketing activity and social post on its day, with key dates and post ideas. Two views: Marketing Planner (everything) and Content Calendar (just posts, post ideas and key dates).",
          "Shop, The Edit (/edit): where packs are bought.",
          "Orders (/account/orders): their orders and invoices. Bookings (/account/bookings): videography shoots and calls, with reschedule and cancel there.",
          "Your SMM (/account/social): managed social media, with monthly reports.",
          "Training Studio (/account/guides): guides and lessons, with a search. Blog (/account/blog).",
          "Community (/account/community): this fortnight's topic, conversations with other members, and a request board for things to add or change.",
          "Help Centre (/account/help) and Contact (/account/contact). TMKE's hours are Monday to Friday, 09:00 to 17:30 UK time.",
        ].join("\n- ");
        const system = `You are the help assistant in the TMKE Member Hub, the member area of The Marketing Experts, a UK marketing agency for estate agents. A member has opened "${line}" in the Help Centre. Answer their question briefly and practically, in British English, warm and plain, like a helpful person on the TMKE team. No em dashes. Two to five short sentences, or a few short steps, unless more is truly needed. Point them to the right place in the hub by name.

What the hub has:
- ${HUB}

About this member's own account (use it to make the answer specific to them; never repeat it back unasked):
- ${ctx.join("\n- ")}

Rules:
- Only use the facts above and general marketing common sense. Never invent features, prices, policies, timings, refunds or anything about their account you weren't told. If you don't know, say so plainly.
- If they need something only the team can do (a missing or broken file, a fault, a refund, a change to an order or booking, access to a pack they think they should have, anything about money), say so and tell them to send it to the team with the button below.
- Stay on TMKE, the hub and their marketing. Politely decline anything else.

Return ONLY minified JSON, no markdown: {"answer": "your reply, with line breaks as \\n", "handoff": true or false}. Set handoff true when the team should pick it up.`;
        let aiRes;
        try {
          aiRes = await aiFetch(env, "help", { max_tokens: 3000, system, messages: turns });
        } catch (e) { return json({ error: "Couldn't reach the AI service." }, 502, request, env); }
        if (!aiRes.ok) { const t = await aiRes.text().catch(() => ""); return json({ error: aiFailMessage(aiRes.status, t), detail: t.slice(0, 300) }, 502, request, env); }
        const dataRes = await aiRes.json();
        const text = (dataRes.content || []).filter((c) => c.type === "text").map((c) => c.text).join("").trim();
        let out;
        try { const s = text.indexOf("{"), e = text.lastIndexOf("}"); out = JSON.parse(text.slice(s, e + 1)); } catch (_) { out = { answer: text, handoff: false }; }
        const answer = String(out.answer || "").trim();
        if (!answer) return json({ error: "No answer came back. Try again, or send it to the team." }, 502, request, env);
        return json({ ok: true, answer, handoff: out.handoff === true }, 200, request, env);
      }

      // ---- AI: read text + positions from a finished design image ----
      // Powers the studio's "Read text with AI" (Canva import). Holds the
      // Anthropic key as a Worker secret so it never reaches the browser.
      if (path.endsWith("/ai/parse") && request.method === "POST") {
        if (!cheapValid(request)) return json({ error: "Sign in to use AI." }, 401, request, env);
        if (!env.ANTHROPIC_API_KEY) return json({ error: "AI isn't configured - set the ANTHROPIC_API_KEY secret on the Worker (wrangler secret put ANTHROPIC_API_KEY)." }, 503, request, env);
        let body;
        try { body = await request.json(); } catch (_) { return json({ error: "Bad JSON" }, 400, request, env); }
        const W = Math.max(1, Math.round(body.width || 1080));
        const H = Math.max(1, Math.round(body.height || 1350));
        const raw = String(body.image || "");
        const m = /^data:(image\/[a-z0-9.+-]+);base64,(.+)$/i.exec(raw);
        const mediaType = m ? m[1] : "image/jpeg";
        const b64 = m ? m[2] : raw;
        if (!b64) return json({ error: "Missing image" }, 400, request, env);
        const clampN = (v, lo, hi) => { const n = Number(v); return Number.isFinite(n) ? Math.max(lo, Math.min(hi, Math.round(n))) : lo; };
        const prompt =
          "The attached image is a finished social-media graphic, exactly " + W + "x" + H + " pixels. " +
          "Identify every distinct piece of TEXT visible in it and report it so it can be recreated as editable layers. " +
          "Respond with ONLY a JSON array (no prose, no markdown fences). Each item: " +
          '{"text": string (the exact words; keep line breaks as \\n), ' +
          '"x": number (left edge in px), "y": number (top edge in px), ' +
          '"w": number (block width px), "h": number (block height px), ' +
          '"fontSize": number (approx px), "color": "#rrggbb", "weight": 400 or 700, ' +
          '"align": "left"|"center"|"right"}. ' +
          "All coordinates are in the " + W + "x" + H + " pixel space of the image. " +
          "Group words that share a line/paragraph and style into one block. " +
          "Only include real text - ignore logos drawn as images, photographic content, and decorative graphics. " +
          "If there is no text, return [].";
        let aiRes;
        try {
          aiRes = await aiFetch(env, "write", {
            max_tokens: 10000,
            messages: [{ role: "user", content: [
              { type: "image", source: { type: "base64", media_type: mediaType, data: b64 } },
              { type: "text", text: prompt },
            ] }],
          });
        } catch (e) { return json({ error: "Couldn't reach the AI service." }, 502, request, env); }
        if (!aiRes.ok) {
          const t = await aiRes.text().catch(() => "");
          return json({ error: aiFailMessage(aiRes.status, t), detail: t.slice(0, 300) }, 502, request, env);
        }
        const data = await aiRes.json();
        const text = (data.content || []).filter((c) => c.type === "text").map((c) => c.text).join("");
        let parsed = [];
        try {
          const s = text.indexOf("["), e = text.lastIndexOf("]");
          parsed = JSON.parse(text.slice(s, e + 1));
        } catch (_) { return json({ error: "Couldn't read the AI output.", raw: text.slice(0, 200) }, 502, request, env); }
        const blocks = (Array.isArray(parsed) ? parsed : [])
          .filter((b) => b && typeof b.text === "string" && b.text.trim())
          .map((b) => ({
            text: String(b.text),
            x: clampN(b.x, 0, W), y: clampN(b.y, 0, H),
            w: clampN(b.w, 12, W), h: clampN(b.h, 12, H),
            fontSize: clampN(b.fontSize != null ? b.fontSize : b.size, 6, 400),
            color: /^#[0-9a-f]{6}$/i.test(b.color || "") ? b.color : "#1c1d22",
            weight: parseInt(b.weight, 10) >= 600 ? 700 : 400,
            align: ["left", "center", "right"].includes(b.align) ? b.align : "left",
          }));
        return json({ blocks, usage: data.usage || null }, 200, request, env);
      }

      // ---- Email a planned post to the signed-in member now ------------------
      // The "Email it to me now" button in the editor's plan modal — sends the
      // caption + image to their own inbox straight away (grab it on your phone).
      /* The 8am reminder for one training entry, sent now (16 Oct): so the
         test run can check the email each kind of entry produces. Admins
         only, training entries only, to the admin's own address. */
      if (path.endsWith("/calendar/test-reminder") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !user._isAdmin) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String((b && b.id) || "");
        if (!/^[0-9a-f-]{36}$/.test(id)) return json({ error: "Which entry?" }, 400, request, env);
        const rows = await sbGet(env, "training_calendar_items", `select=*&id=eq.${id}&user_id=eq.${user.id}`);
        const item = rows && rows[0];
        if (!item) return json({ error: "No such training entry." }, 404, request, env);
        const isPost = !item.activity || item.activity === "social_post";
        const ok = isPost
          ? await sendPostEmail(env, { email: user.email, item, subject: `[Test] Your ${item.platform_hint || "instagram"} post is planned for today` })
          : await sendActivityEmail(env, { email: user.email, item });
        return json({ ok: !!ok, to: user.email, kind: isPost ? "post" : "activity" }, ok ? 200 : 502, request, env);
      }

      if (path.endsWith("/calendar/send-now") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !user.email) return json({ error: "Sign in first." }, 401, request, env);
        if (!env.RESEND_API_KEY) return json({ error: "Email isn't configured on the Worker." }, 503, request, env);
        const b = await request.json().catch(() => ({}));
        const item = { asset_url: String((b && b.asset_url) || ""), caption: (b && b.caption) || "", title: (b && b.title) || "", platform_hint: (b && b.platform) || "instagram" };
        /* An uploaded post's files and links (Dani, 16 Oct). Only files from
           our own storage are fetched and attached; anything else is dropped. */
        const ours = `${env.SUPABASE_URL}/storage/v1/object/public/calendar-assets/`;
        const files = (Array.isArray(b && b.files) ? b.files : []).filter((x) => x && typeof x.url === "string" && x.url.startsWith(ours)).slice(0, 10)
          .map((x) => ({ name: String(x.name || "File").slice(0, 120), url: x.url }));
        const links = (Array.isArray(b && b.links) ? b.links : []).filter((u) => typeof u === "string" && /^https?:\/\//.test(u)).slice(0, 10);
        if (files.length || links.length) item.details = { files, links };
        if (!item.asset_url && !files.length && !links.length) return json({ error: "Nothing to send." }, 400, request, env);
        const ok = await sendPostEmail(env, { email: user.email, item, subject: `Your ${item.platform_hint} post - ready to go` });
        if (!ok) return json({ error: "Couldn't send the email - try again." }, 502, request, env);
        return json({ ok: true, to: user.email }, 200, request, env);
      }

      // ---- Client portal: open it with the passcode (public) ----
      // Says which of four things went wrong, so the page can say it plainly:
      // unknown link, switched off, locked after too many tries, wrong passcode.
      if (path.endsWith("/portal/open") && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        const p = await portalByToken(env, String((b && b.token) || ""));
        if (!p) return json({ code: "unknown" }, 404, request, env);
        if (!p.enabled) return json({ code: "closed" }, 403, request, env);
        const lockedFor = p.locked_until ? Date.parse(p.locked_until) - Date.now() : 0;
        if (lockedFor > 0) return json({ code: "locked", minutes: Math.ceil(lockedFor / 60000) }, 429, request, env);
        const at = `id=eq.${encodeURIComponent(p.id)}`;
        if (portalCode(b && b.passcode) !== p.passcode) {
          const tries = (p.failed_tries || 0) + 1;
          if (tries >= PORTAL_TRIES) {
            await sbPatch(env, "client_portals", at, { failed_tries: 0, locked_until: new Date(Date.now() + PORTAL_LOCK_MIN * 60000).toISOString() });
            return json({ code: "locked", minutes: PORTAL_LOCK_MIN }, 429, request, env);
          }
          await sbPatch(env, "client_portals", at, { failed_tries: tries });
          return json({ code: "wrong", left: PORTAL_TRIES - tries }, 401, request, env);
        }
        const exp = Date.now() + PORTAL_DAYS * 24 * 60 * 60 * 1000;
        const sig = await portalSig(env, p.token, p.passcode, exp);
        if (!sig) return json({ error: "The portal isn't configured on the Worker." }, 503, request, env);
        await sbPatch(env, "client_portals", at, { failed_tries: 0, locked_until: null, last_opened_at: new Date().toISOString() });
        return json({ session: `${p.token}.${exp}.${sig}`, expires: exp, ...(await portalHomeShown(env, p)) }, 200, request, env);
      }

      // ---- Client portal: who it's for and the folders shared with them ----
      if (path.endsWith("/portal/home") && request.method === "GET") {
        const p = await portalFromSession(env, request);
        if (!p) return json({ code: "signed_out" }, 401, request, env);
        return json(await portalHomeShown(env, p), 200, request, env);
      }

      // ---- Client portal: one shared folder, with links to play and download ----
      // Only inside a ticked folder. Each file comes with links signed for six
      // hours, served by /download like the Library's.
      if (path.endsWith("/portal/list") && request.method === "GET") {
        const p = await portalFromSession(env, request);
        if (!p) return json({ code: "signed_out" }, 401, request, env);
        const prefix = archivePrefix(url.searchParams.get("prefix"));
        const root = (await portalShownFolders(env, p)).find((f) => prefix.startsWith(f));
        if (!root) return json({ code: "not_shared" }, 403, request, env);
        const out = await listArchive(env, prefix);
        const exp = portalLinkExpiry();
        const base = String(env.WORKER_PUBLIC_URL || url.origin).replace(/\/+$/, "");
        const link = async (key, dl) => {
          const sig = await mediaSig(env, key, exp);
          return sig ? `${base}/download?key=${encodeURIComponent(key)}&exp=${exp}&sig=${encodeURIComponent(sig)}${dl ? "&dl=1" : ""}` : "";
        };
        for (const f of out.files) {
          f.url = await link(f.key, false);
          f.downloadUrl = await link(f.key, true);
          if (f.thumb) f.thumbUrl = await link(f.thumb, false);
          if (PREVIEWABLE.test(f.name)) f.previewUrl = f.url.replace("/download?", "/preview?");
          // No small picture yet: one is made the first time it's asked for, rather
          // than the Gallery loading every full-size original (Dani, 7 Nov).
          if (!f.thumbUrl && f.previewUrl) f.thumbUrl = f.previewUrl + "&size=thumb";
          // A photo saved over in Creative Studio gets new links, so nobody keeps the old one.
          const fresh = `&v=${new Date(f.uploaded).getTime()}`;
          f.url += fresh; if (f.thumbUrl) f.thumbUrl += fresh; if (f.previewUrl) f.previewUrl += fresh;
          delete f.key; delete f.thumb;
        }
        return json({ ...out, root }, 200, request, env);
      }

      // ---- Client portal: one shoot's folders, counted, each with a picture ----
      if (path.endsWith("/portal/shoot") && request.method === "GET") {
        const p = await portalFromSession(env, request);
        if (!p) return json({ code: "signed_out" }, 401, request, env);
        const prefix = archivePrefix(url.searchParams.get("prefix"));
        const root = (await portalShownFolders(env, p)).find((f) => prefix === f);
        if (!root) return json({ code: "not_shared" }, 403, request, env);
        const exp = portalLinkExpiry();
        const base = String(env.WORKER_PUBLIC_URL || url.origin).replace(/\/+$/, "");
        const sign = async (key) => {
          const sig = await mediaSig(env, key, exp);
          return sig ? `${base}/download?key=${encodeURIComponent(key)}&exp=${exp}&sig=${encodeURIComponent(sig)}` : "";
        };
        const isVid = (f) => /^video\//.test(f.contentType || "") || /\.(mp4|mov|m4v|webm)$/i.test(f.name || "");
        const isPic = (f) => /^image\/(jpeg|png|webp|gif|avif)/.test(f.contentType || "") || /\.(jpe?g|png|webp|avif|gif)$/i.test(f.name || "");
        const part = async (pre, name, list) => {
          const files = list.files || [];
          const pics = files.filter(isPic), vids = files.filter(isVid);
          const c = pics.find((f) => f.thumb) || vids.find((f) => f.thumb) || pics[0];
          // The tiles are big, so a photo's tile gets the preview size, with the small
          // picture to show until that arrives (Dani, 7 Nov). A film's picture is all it has.
          const full = c && PREVIEWABLE.test(c.name) ? (await sign(c.key)).replace("/download?", "/preview?") : "";
          const small = c && c.thumb ? await sign(c.thumb) : full ? full + "&size=thumb" : "";
          return { prefix: pre, name, images: pics.length, videos: vids.length, others: files.length - pics.length - vids.length, coverUrl: full || small || (c ? await sign(c.key) : ""), coverThumb: small };
        };
        const top = await listArchive(env, prefix);
        const parts = [];
        for (const sub of top.folders || []) {
          parts.push(await part(sub, sub.slice(0, -1).split("/").pop(), await listArchive(env, sub)));
        }
        if ((top.files || []).length) parts.unshift(await part(prefix, parts.length ? "Main" : "All files", top));
        return json({ parts: parts.filter((x) => x.images + x.videos + x.others > 0) }, 200, request, env);
      }

    // ---- PUBLIC client gallery (token-gated, NO login required) ----
      if (path.endsWith("/g/meta") && request.method === "GET") {
        const token = url.searchParams.get("token") || "";
        const rows = token
          ? await sbGet(env, "videography_deliveries", `token=eq.${encodeURIComponent(token)}&select=*`)
          : null;
        const d = rows && rows[0];
        if (!d) return json({ error: "Not found" }, 404, request, env);
        const files =
          (await sbGet(env, "videography_deliverables",
            `booking_id=eq.${d.booking_id}&select=r2_key,file_name,kind,size_bytes,category&order=created_at.asc`)) || [];
        const teasers = teaserKeys(files, d.teaser_count);
        const paid = d.status === "paid";
        return json({
          clientName: d.client_name, message: d.message, status: d.status,
          basePence: d.base_pence, extras: d.extras || [], totalPence: d.total_pence,
          teaserCount: d.teaser_count, paid,
          files: files.map((f) => ({
            key: f.r2_key, name: f.file_name, kind: f.kind, size: f.size_bytes,
            category: f.category || null,
            unlocked: paid || teasers.has(f.r2_key),
          })),
        }, 200, request, env);
      }

      if (path.endsWith("/g/file") && request.method === "GET") {
        const token = url.searchParams.get("token") || "";
        const key = url.searchParams.get("key") || "";
        const dl = url.searchParams.get("dl") === "1";
        const rows = token
          ? await sbGet(env, "videography_deliveries", `token=eq.${encodeURIComponent(token)}&select=*`)
          : null;
        const d = rows && rows[0];
        if (!d || !key) return json({ error: "Forbidden" }, 403, request, env);
        const files =
          (await sbGet(env, "videography_deliverables",
            `booking_id=eq.${d.booking_id}&select=r2_key,kind&order=created_at.asc`)) || [];
        if (!files.some((f) => f.r2_key === key)) return json({ error: "Not found" }, 404, request, env);
        const allowed = d.status === "paid" || teaserKeys(files, d.teaser_count).has(key);
        if (!allowed) return json({ error: "Locked" }, 403, request, env);
        const obj = await env.BUCKET.get(key);
        if (!obj) return json({ error: "Not found" }, 404, request, env);
        const headers = new Headers(corsHeaders(request, env));
        obj.writeHttpMetadata(headers);
        headers.set("etag", obj.httpEtag);
        const name = key.split("/").pop();
        headers.set("Content-Disposition", `${dl ? "attachment" : "inline"}; filename="${name}"`);
        return new Response(obj.body, { headers });
      }

      // Available hours for a weekday row: prefer hours[] (new block model),
      // fall back to the old start_time/end_time range. Returns a sorted int[].
      const rowHours = (row) => {
        let h = Array.isArray(row && row.hours) ? row.hours.slice() : [];
        if (!h.length && row && row.is_available !== false && row.start_time && row.end_time) {
          const s = Math.floor(hmToMin(row.start_time) / 60), e = Math.ceil(hmToMin(row.end_time) / 60);
          for (let x = s; x < e; x++) h.push(x);
        }
        return h.filter((n) => Number.isFinite(n)).sort((a, b) => a - b);
      };

      // ---- Which weekdays are bookable (for the booking calendar) ----
      /* ---- Which days in a range have a time for this service ----
         So the booking calendar can grey out a day that's taken instead of
         letting someone click it to be told no (Danielle, 7 Oct 2026). The
         same three checks as /ms/availability - Jack's hours, his 365
         calendar, the bookings board - but one calendar read for the range. */
      if (path.endsWith("/ms/days") && request.method === "GET") {
        const from = url.searchParams.get("from") || "", to = url.searchParams.get("to") || "";
        const service = url.searchParams.get("service") || "";
        const duration = Math.max(15, parseInt(url.searchParams.get("duration") || "60", 10));
        const skip = url.searchParams.get("skip") || "";
        const ymdOk = (x) => /^\d{4}-\d{2}-\d{2}$/.test(x);
        if (!ymdOk(from) || !ymdOk(to) || to < from) return json({ error: "from and to are YYYY-MM-DD" }, 400, request, env);
        const spanDays = Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86400000);
        if (spanDays > 60) return json({ error: "60 days at most" }, 400, request, env);
        const avail = (await sbGet(env, "videography_availability", "select=*")) || [];
        const byWd = {}; avail.forEach((r) => { byWd[r.weekday] = rowHours(r); });
        const rows = await boardRows(env, from, to);
        // One getSchedule in UTC for the whole range; each day's London hours
        // are placed on it by that day's offset, so the clocks changing on the
        // last Sunday of October doesn't shift anything.
        const STEP = 30;
        const t0 = Date.parse(`${from}T00:00:00Z`) - 3600000;
        const t1 = Date.parse(`${to}T00:00:00Z`) + 86400000 + 3600000;
        const iso = (ms) => new Date(ms).toISOString().slice(0, 19);
        let view = "";
        try {
          const sched = await graph(env, "POST", `/users/${encodeURIComponent(env.JACK_UPN)}/calendar/getSchedule`, {
            schedules: [env.JACK_UPN], startTime: { dateTime: iso(t0), timeZone: "UTC" }, endTime: { dateTime: iso(t1), timeZone: "UTC" },
            availabilityViewInterval: STEP,
          });
          view = (sched.value && sched.value[0] && sched.value[0].availabilityView) || "";
        } catch (_) { return json({ error: "Calendar unavailable" }, 502, request, env); }
        const days = [];
        for (let i = 0; i <= spanDays; i++) {
          const d = new Date(Date.parse(`${from}T00:00:00Z`) + i * 86400000).toISOString().slice(0, 10);
          const hours = byWd[new Date(`${d}T12:00:00Z`).getUTCDay()] || [];
          if (!hours.length) continue;
          const blocks = diaryBlocksFrom(rows, d, service, skip);
          if (blocks.day) continue;
          const offset = londonParts(`${d}T12:00:00Z`).min - 720;   // 60 in BST, 0 in GMT
          const openHours = new Set(hours);
          const dayStart = Math.min(...hours) * 60, dayEnd = (Math.max(...hours) + 1) * 60;
          const idx = (min) => Math.floor((Date.parse(`${d}T00:00:00Z`) + (min - offset) * 60000 - t0) / (STEP * 60000));
          let free = false;
          for (let at = dayStart; !free && at + duration <= dayEnd; at += STEP) {
            let ok = true;
            for (let m = at; m < at + duration; m += STEP) {
              const c = view[idx(m)];
              if (!openHours.has(Math.floor(m / 60)) || (c && c !== "0")) { ok = false; break; }
            }
            if (ok && !overlapsAny(blocks.ranges, at, at + duration)) free = true;
          }
          if (free) days.push(d);
        }
        return json({ days, service, duration }, 200, request, env);
      }

      /* ---- The admin calendar's view of the diary (Danielle, 22 Oct 2026) ----
         For each day in a range, why it isn't fully open to new bookings, in
         the same terms the booking flow uses (diaryBlocksFrom, Jack's hours,
         his 365 calendar, the new-starter Studio Days), so the calendar shows
         what a client would find. Staff only. Each day:
           { date, closed, notes: [{ kind, text }] }
         kind: starter | shoot | editing | studio | off | busy
         closed: nothing at all can be booked that day. */
      if (path.endsWith("/videography/diary") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const from = url.searchParams.get("from") || "", to = url.searchParams.get("to") || "";
        const ymdOk = (x) => /^\d{4}-\d{2}-\d{2}$/.test(x);
        if (!ymdOk(from) || !ymdOk(to) || to < from) return json({ error: "from and to are YYYY-MM-DD" }, 400, request, env);
        const span = Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86400000);
        if (span > 62) return json({ error: "62 days at most" }, 400, request, env);
        const dates = [];
        for (let i = 0; i <= span; i++) dates.push(new Date(Date.parse(`${from}T00:00:00Z`) + i * 86400000).toISOString().slice(0, 10));
        const DOW = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
        const t12 = (min) => nsTime12(minToHm(Math.max(0, Math.min(1439, min))));
        const dayLong = (d) => new Date(`${d}T12:00:00Z`).toLocaleDateString("en-GB", { weekday: "short", day: "numeric", month: "short" });

        const avail = (await sbGet(env, "videography_availability", "select=*")) || [];
        const byWd = {}; avail.forEach((r) => { byWd[r.weekday] = rowHours(r); });
        const lo = new Date(`${from}T00:00:00Z`); lo.setUTCDate(lo.getUTCDate() - EDITING_LOOKBACK_DAYS);
        const hi = new Date(`${to}T00:00:00Z`); hi.setUTCDate(hi.getUTCDate() + 2);
        const rows = (await sbGet(env, "videography_bookings",
          `shoot_date=gte.${lo.toISOString()}&shoot_date=lt.${hi.toISOString()}&select=${BOARD_COLS}`)) || [];
        rows.workdays = workdaysFrom(avail);
        const live = rows.filter((r) => r.shoot_date && r.stage !== "cancelled" && r.stage !== "discovery_call_booked" && r.service_type !== "discovery");
        const dayOfRow = (r) => (r.kind === "booking" ? String(r.shoot_date).slice(0, 10) : londonParts(r.shoot_date).ymd);
        const ourEvents = new Set(rows.map((r) => r.ms_event_id).filter(Boolean));
        const editing = editingDaysFrom(rows, to, null);

        // Jack's calendar, less the events our own bookings put there and the
        // Studio Day blocks (shown as Studio Days instead).
        const busy = {};
        let calError = null;
        try {
          let next = `/users/${encodeURIComponent(env.JACK_UPN)}/calendarView?startDateTime=${from}T00:00:00Z&endDateTime=${nsNextDay(to)}T01:00:00Z&$select=id,subject,start,end,showAs,isAllDay,sensitivity&$top=250`;
          for (let page = 0; next && page < 4; page++) {
            const r = await graph(env, "GET", next);
            next = r && r["@odata.nextLink"] ? r["@odata.nextLink"].replace("https://graph.microsoft.com/v1.0", "") : null;
            for (const ev of (r && r.value) || []) {
              if (ourEvents.has(ev.id) || ev.subject === NEW_STARTER_BLOCK_SUBJECT || (ev.showAs === "free" && !ev.isAllDay)) continue;
              const s0 = ev.start && ev.start.dateTime, e0 = ev.end && ev.end.dateTime;
              if (!s0 || !e0) continue;
              const a = ev.isAllDay ? { ymd: s0.slice(0, 10), min: 0 } : londonParts(s0.replace(/\.\d+$/, "") + "Z");
              const b = ev.isAllDay ? { ymd: e0.slice(0, 10), min: 0 } : londonParts(e0.replace(/\.\d+$/, "") + "Z");
              for (const d of dates) {
                if (a.ymd > d || b.ymd < d || (b.ymd === d && b.min === 0 && a.ymd < d)) continue;
                const x = a.ymd < d ? 0 : a.min, y = b.ymd > d ? 1440 : b.min;
                // What it is (Danielle, 5 Nov): the event's own title, or
                // "Private" for one Jack has marked private.
                const what = ev.sensitivity && ev.sensitivity !== "normal" ? "Private" : String(ev.subject || "").trim() || "Busy";
                if (y > x) (busy[d] = busy[d] || []).push([x, y, what]);
              }
            }
          }
        } catch (e) { calError = "Jack's calendar couldn't be read, so his own appointments aren't shown."; }

        // New-starter Studio Days for each month the range touches.
        const starter = {};
        for (const m of [...new Set(dates.map((d) => d.slice(0, 7)))]) {
          try {
            const plan = await newStarterPlan(env, m);
            plan.days.forEach((d) => { starter[d.date] = d.sessions; });
          } catch (_) {}
        }

        const days = dates.map((d) => {
          const notes = [];
          let closed = false;
          const hours = byWd[new Date(`${d}T12:00:00Z`).getUTCDay()] || [];
          if (starter[d]) {
            const free = starter[d].filter((x) => !x.taken).length;
            notes.push({ kind: "starter", text: `TEG new-starter Studio Day: ${free ? `${free} of ${starter[d].length} sessions free` : "every session taken"}.` });
            closed = true;
          }
          const today = live.filter((r) => dayOfRow(r) === d);
          const onLocation = today.filter((r) => { const k = bookingKindOf(r); return k && k !== "content-studio"; });
          const studio = today.filter((r) => bookingKindOf(r) === "content-studio" && !/new-starter/i.test(String(r.service || "")));
          if (onLocation.length) { notes.push({ kind: "shoot", text: "Out on a shoot." }); closed = true; }
          else if (studio.length && !starter[d]) notes.push({ kind: "studio", text: "Studio sessions booked: studio bookings only." });
          if (editing[d]) {
            const seen = new Set();
            const who = editing[d].filter((x) => { const k = x.studioDay ? `sd:${x.day}` : `${x.client}:${x.day}`; if (seen.has(k)) return false; seen.add(k); return true; })
              .map((x) => x.studioDay ? `the Studio Day (${dayLong(x.day)})` : `${x.client || "a client"} (${dayLong(x.day)})`).join(" and ");
            notes.push({ kind: "editing", text: `Editing after ${who}.` });
            if (!starter[d]) closed = true;
          }
          if (!hours.length) { notes.push({ kind: "off", text: `Jack doesn't work ${DOW[new Date(`${d}T12:00:00Z`).getUTCDay()]}s.` }); closed = true; }
          else if (busy[d] && busy[d].length) {
            const open0 = Math.min(...hours) * 60, open1 = (Math.max(...hours) + 1) * 60;
            const merged = busy[d].map(([x, y]) => [Math.max(x, open0), Math.min(y, open1)]).filter(([x, y]) => y > x).sort((p, q) => p[0] - q[0])
              .reduce((acc, r) => { const last = acc[acc.length - 1]; if (last && r[0] <= last[1]) last[1] = Math.max(last[1], r[1]); else acc.push(r.slice()); return acc; }, []);
            if (merged.length) {
              const whole = merged.length === 1 && merged[0][0] <= open0 && merged[0][1] >= open1;
              // Each thing in his calendar that day, by name, longest first.
              const named = busy[d].filter(([x, y]) => Math.min(y, open1) > Math.max(x, open0)).sort((p, q) => (q[1] - q[0]) - (p[1] - p[0]));
              const seenW = new Set(), whats = named.map((e) => e[2]).filter((w) => !seenW.has(w) && seenW.add(w));
              const allDay = (e) => e[0] <= open0 && e[1] >= open1;
              notes.push({ kind: "busy", short: whats[0] || "Busy",
                text: whole && named.length && allDay(named[0]) ? `${whats.join(", ")}: all day in Jack's calendar.`
                  : named.map((e) => allDay(e) ? `${e[2]}: all day.` : `${e[2]}: ${t12(Math.max(e[0], open0))} to ${t12(Math.min(e[1], open1))}.`).filter((t, i, a) => a.indexOf(t) === i).join(" ") });
              if (whole) closed = true;
            }
          }
          return { date: d, closed, notes };
        });
        return json({ days, calError }, 200, request, env);
      }

      if (path.endsWith("/ms/config") && request.method === "GET") {
        const rows = (await sbGet(env, "videography_availability", `select=weekday,hours,is_available,start_time,end_time`)) || [];
        const weekdays = {};
        rows.forEach((r) => { const h = rowHours(r); if (h.length) weekdays[r.weekday] = h; });
        return json({ weekdays }, 200, request, env);
      }

      // ---- Travel distance + surcharge (Property / Agent shoots) ----
      // Geocodes Jack's base + the shoot postcode and returns the driving
      // distance and travel surcharge. Settings (base postcode, free radius,
      // per-mile rate) come from `videography_settings`; the Maps key is a
      // secret (`wrangler secret put GOOGLE_MAPS_API_KEY`). Without the key we
      // fall back to a straight-line estimate via postcodes.io (free, no key).
      if (path.endsWith("/videography/distance") && request.method === "GET") {
        const to = (url.searchParams.get("to") || "").trim();
        if (!to) return json({ error: "Missing destination postcode" }, 400, request, env);
        let base = "NN14 1AA", freeRadius = 40, perMile = 55;
        try {
          const s = await sbGet(env, "videography_settings", "id=eq.1&select=base_postcode,free_radius_miles,surcharge_pence_per_mile");
          if (s && s[0]) {
            base = s[0].base_postcode || base;
            if (s[0].free_radius_miles != null) freeRadius = s[0].free_radius_miles;
            if (s[0].surcharge_pence_per_mile != null) perMile = s[0].surcharge_pence_per_mile;
          }
        } catch (_) {}
        let miles = null, source = null, driveError = null;
        if (env.GOOGLE_MAPS_API_KEY) {
          try {
            const u = `https://maps.googleapis.com/maps/api/distancematrix/json?units=imperial&region=uk&origins=${encodeURIComponent(base)}&destinations=${encodeURIComponent(to)}&key=${env.GOOGLE_MAPS_API_KEY}`;
            const d = await (await fetch(u)).json();
            const el = d && d.rows && d.rows[0] && d.rows[0].elements && d.rows[0].elements[0];
            if (el && el.status === "OK" && el.distance) { miles = el.distance.value / 1609.344; source = "drive"; }
            // Why Google said no, when it did (its status words, never the key),
            // so a fall back to the straight-line estimate can be diagnosed.
            else driveError = [d && d.status, el && el.status, d && d.error_message].filter(Boolean).join(": ").slice(0, 200) || "no distance";
          } catch (e) { driveError = String((e && e.message) || e).slice(0, 120); }
        } else driveError = "no GOOGLE_MAPS_API_KEY";
        if (miles == null) {
          try {
            const clean = (p) => encodeURIComponent(p.replace(/\s+/g, ""));
            const [b, t] = await Promise.all([
              fetch("https://api.postcodes.io/postcodes/" + clean(base)).then((r) => r.json()),
              fetch("https://api.postcodes.io/postcodes/" + clean(to)).then((r) => r.json()),
            ]);
            if (b.result && t.result) {
              const R = 3958.8, rad = (x) => (x * Math.PI) / 180;
              const dLa = rad(t.result.latitude - b.result.latitude), dLo = rad(t.result.longitude - b.result.longitude);
              const a = Math.sin(dLa / 2) ** 2 + Math.cos(rad(b.result.latitude)) * Math.cos(rad(t.result.latitude)) * Math.sin(dLo / 2) ** 2;
              miles = 2 * R * Math.asin(Math.sqrt(a)); source = "estimate";
            }
          } catch (_) {}
        }
        if (miles == null) return json({ error: "Couldn't resolve that postcode" }, 422, request, env);
        // There and back (Danielle, 21 Oct 2026): the first freeRadius miles
        // each way are free, every mile over is charged going and coming
        // back. Keep in step with travelCharge in src/lib/videography-config.js.
        const over_each_way = Math.max(0, Math.ceil(miles - freeRadius));
        const chargeable_miles = over_each_way * 2;
        const surcharge_pence = chargeable_miles * perMile;
        return json({ miles: Math.round(miles * 10) / 10, return_miles: Math.round(miles * 20) / 10, over_each_way, chargeable_miles, surcharge_pence, free_radius_miles: freeRadius, pence_per_mile: perMile, source, ...(source === "estimate" && driveError ? { drive_error: driveError } : {}) }, 200, request, env);
      }

      // ---- Live media listing: images + videos in an assets folder, newest
      // first. Public GET; powers the auto-updating videography galleries. The
      // ?prefix= param selects the folder (defaults to the whole headshots
      // folder for backward compatibility). Returns videos first so a gallery
      // can lead with its film. ----
      /* The photos behind the review page. Public on purpose: the page itself is
         public, and everything it returns is already readable by anyone at
         assets.tmke.co.uk - listing them adds no access, it only saves hard-
         coding two dozen filenames into the site.

         The prefix is fixed here rather than taken from the query, so this
         cannot be turned into a way to enumerate the rest of the bucket. */
      if (path.endsWith("/assets/review-grid") && request.method === "GET") {
        if (!env.ASSETS) return json({ images: [] }, 200, request, env);
        const listed = await env.ASSETS.list({ prefix: "TMKE Review Grid Images/" });
        const images = (listed.objects || [])
          .filter((o) => !o.key.endsWith("/"))
          .filter((o) => /\.(jpe?g|png|webp|avif)$/i.test(o.key))
          .sort((a, b) => a.key.localeCompare(b.key, undefined, { numeric: true }))
          .map((o) => "https://assets.tmke.co.uk/" + o.key.split("/").map(encodeURIComponent).join("/"));
        return json({ images }, 200, request, env);
      }

      if (path.endsWith("/headshots") && request.method === "GET") {
        if (!env.ASSETS) return json({ images: [], videos: [], items: [] }, 200, request, env);
        const limit = Math.min(200, Math.max(1, parseInt(url.searchParams.get("limit") || "60", 10)));
        const prefix = url.searchParams.get("prefix") || "Jack - headshots/";
        const toUrl = (o) => "https://assets.tmke.co.uk/" + o.key.split("/").map(encodeURIComponent).join("/");
        const listed = await env.ASSETS.list({ prefix });
        const rows = (listed.objects || [])
          .filter((o) => !o.key.endsWith("/"))                              // skip folder markers
          .filter((o) => /\.(jpe?g|png|webp|avif|mp4|mov|webm|m4v)$/i.test(o.key))
          .sort((a, b) => new Date(b.uploaded) - new Date(a.uploaded));     // newest first
        const videos = rows.filter((o) => /\.(mp4|mov|webm|m4v)$/i.test(o.key)).map(toUrl);
        const images = rows.filter((o) => /\.(jpe?g|png|webp|avif)$/i.test(o.key)).map(toUrl);
        const items = [
          ...videos.map((u) => ({ url: u, type: "video" })),
          ...images.map((u) => ({ url: u, type: "image" })),
        ].slice(0, limit);
        return json({ images: images.slice(0, limit), videos, items }, 200, request, env);
      }

      // ---- Bookable slots for a day (Jack's diary hours minus 365 busy) ----
      if (path.endsWith("/ms/availability") && request.method === "GET") {
        const date = url.searchParams.get("date"); // YYYY-MM-DD
        const duration = parseInt(url.searchParams.get("duration") || "60", 10);
        const service = url.searchParams.get("service") || "";
        const skip = url.searchParams.get("skip") || "";
        if (!date) return json({ error: "Missing date" }, 400, request, env);

        // The bookings board, before the calendar: a day with a shoot on it
        // (or anything hand-added) is gone, and studio sessions take their
        // hours. See diaryBlocks.
        const blocks = await diaryBlocks(env, date, service, skip);
        if (blocks.day) return json({ slots: [], duration, reason: blocks.reason }, 200, request, env);
        const wd = new Date(date + "T12:00:00Z").getUTCDay(); // 0=Sun..6=Sat
        const rows = (await sbGet(env, "videography_availability", `weekday=eq.${wd}&select=*`)) || [];
        const hours = rowHours(rows[0]);
        if (!hours.length) return json({ slots: [], duration }, 200, request, env);
        const STEP = 30;
        const openHours = new Set(hours);
        const dayStartMin = Math.min(...hours) * 60;
        const dayEndMin = (Math.max(...hours) + 1) * 60;
        const need = Math.max(1, Math.ceil(duration / STEP));
        const sched = await graph(env, "POST", `/users/${encodeURIComponent(env.JACK_UPN)}/calendar/getSchedule`, {
          schedules: [env.JACK_UPN],
          startTime: { dateTime: `${date}T${minToHm(dayStartMin)}:00`, timeZone: "Europe/London" },
          endTime: { dateTime: `${date}T${minToHm(dayEndMin)}:00`, timeZone: "Europe/London" },
          availabilityViewInterval: STEP,
        });
        const view = (sched.value && sched.value[0] && sched.value[0].availabilityView) || "";
        const totalSlots = Math.floor((dayEndMin - dayStartMin) / STEP);
        const slots = [];
        for (let i = 0; i + need <= totalSlots; i++) {
          let ok = true;
          for (let k = 0; k < need; k++) {
            const slotMin = dayStartMin + (i + k) * STEP;
            const busy = view[i + k];
            if (!openHours.has(Math.floor(slotMin / 60)) || (busy && busy !== "0")) { ok = false; break; }
          }
          const at = dayStartMin + i * STEP;
          if (ok && overlapsAny(blocks.ranges, at, at + duration)) ok = false;
          if (ok) slots.push(minToHm(at));
        }
        return json({ slots, duration }, 200, request, env);
      }

      // ---- Create a booking (writes to Jack's calendar + pipeline) ----
      if (path.endsWith("/ms/book") && request.method === "POST") {
        const b = await request.json();
        const { date, start, duration, name, email, phone, service, notes } = b || {};
        if (!date || !start || !name) return json({ error: "Missing booking details" }, 400, request, env);
        const dur = parseInt(duration || "60", 10);
        const endHm = minToHm(hmToMin(start) + dur);
        // Re-check the slot is still free (guards against double-booking)
        const check = await graph(env, "POST", `/users/${encodeURIComponent(env.JACK_UPN)}/calendar/getSchedule`, {
          schedules: [env.JACK_UPN],
          startTime: { dateTime: `${date}T${start}:00`, timeZone: "Europe/London" },
          endTime: { dateTime: `${date}T${endHm}:00`, timeZone: "Europe/London" },
          availabilityViewInterval: Math.max(15, dur),
        });
        const view = (check.value && check.value[0] && check.value[0].availabilityView) || "";
        if (view && /[^0]/.test(view)) return json({ error: "That time was just taken - please choose another." }, 409, request, env);
        const ev = await graph(env, "POST", `/users/${encodeURIComponent(env.JACK_UPN)}/events`, {
          subject: `${service || "Shoot"} - ${name}`,
          body: { contentType: "text", content: [notes && `Notes: ${notes}`, phone && `Phone: ${phone}`, email && `Email: ${email}`].filter(Boolean).join("\n") },
          start: { dateTime: `${date}T${start}:00`, timeZone: "Europe/London" },
          end: { dateTime: `${date}T${endHm}:00`, timeZone: "Europe/London" },
          attendees: email ? [{ emailAddress: { address: email, name }, type: "required" }] : [],
        });
        await sbPost(env, "videography_bookings", {
          client_name: name, client_email: email || null, client_phone: phone || null,
          service: service || null, shoot_date: `${date}T${start}:00`, stage: "booked", notes: notes || null,
        });
        return json({ ok: true, eventId: ev.id }, 200, request, env);
      }

      // ---- Full booking (account + record + confirmation emails + pipeline) --
      // Public: the booking flow's final step. Creates/links a Supabase account
      // (never overwrites an existing one), books Jack's 365 diary, writes the
      // full pipeline row, and emails the client (with an .ics) + Jack.
      if (path.endsWith("/videography/book") && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        const {
          date, start, duration, service, service_type, audience, brand,
          add_ons, postcode, distance_miles, surcharge_pence, property_address,
          name, email: bodyEmail, phone, company, notes, signed_name, signed_at,
          marketing_opt_in, password, total_pence, account_exists, promo_code, discount_pence,
        } = b || {};
        const pkg = b && b.package;
        /* A booking sent with a signed-in member's login (the hub's Marketing
           Calendar, or anyone already signed in on the site) is theirs: the
           email and the account come from the login itself, not from what the
           form says. Without one, the form's email stands, as before. */
        const booker = await getUser(request, env);
        const email = (booker && booker.email) || bodyEmail;
        if (!date || !start || !name || !email) return json({ error: "Missing booking details" }, 400, request, env);
        // New customers create an account (password required). Existing members
        // sign in client-side first and send account_exists, so no password here.
        if (!booker && !account_exists && (!password || String(password).length < 8)) return json({ error: "A password of at least 8 characters is required." }, 400, request, env);
        const dur = parseInt(duration || "60", 10);
        const endHm = minToHm(hmToMin(start) + dur);

        // 1) Re-check the slot is still free (guards against double-booking).
        const check = await graph(env, "POST", `/users/${encodeURIComponent(env.JACK_UPN)}/calendar/getSchedule`, {
          schedules: [env.JACK_UPN],
          startTime: { dateTime: `${date}T${start}:00`, timeZone: "Europe/London" },
          endTime: { dateTime: `${date}T${endHm}:00`, timeZone: "Europe/London" },
          availabilityViewInterval: Math.max(15, dur),
        });
        const view = (check.value && check.value[0] && check.value[0].availabilityView) || "";
        if (view && /[^0]/.test(view)) return json({ error: "That time was just taken - please choose another." }, 409, request, env);

        // ...and against the bookings board, which the calendar may not show.
        {
          const blocks = await diaryBlocks(env, date, service_type || "");
          if (blocks.day || overlapsAny(blocks.ranges, hmToMin(start), hmToMin(start) + dur)) {
            return json({ error: "That date has just been taken - please choose another." }, 409, request, env);
          }
        }

        // 2) Create or link the Supabase account (never overwrite an existing one).
        let accountUserId = null, accountCreated = false;
        try {
          if (booker) {
            accountUserId = booker.id;   // signed in: the login is the account
          } else if (account_exists) {
            // Existing member (already signed in client-side) — just link the id.
            const u = await findUserByEmail(env, email);
            if (u) accountUserId = u.id;
          } else {
            const cr = await fetch(`${env.SUPABASE_URL}/auth/v1/admin/users`, {
              method: "POST",
              headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json" },
              body: JSON.stringify({ email, password, email_confirm: true, user_metadata: { full_name: name, company: company || null, phone: phone || null } }),
            });
            if (cr.ok) { const u = await cr.json(); accountUserId = (u && u.id) || null; accountCreated = true; }
            else {
              // Already registered — find their id so the booking still links (best-effort).
              const u = await findUserByEmail(env, email);
              if (u) accountUserId = u.id;
            }
          }
        } catch (_) { /* account is best-effort; the booking still proceeds */ }

        // If a promo code was applied, redeem it (increments redemptions; best-effort).
        if (promo_code) {
          try {
            await fetch(`${env.SUPABASE_URL}/rest/v1/rpc/redeem_promo_code`, {
              method: "POST",
              headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json" },
              body: JSON.stringify({ p_code: String(promo_code).toUpperCase() }),
            });
          } catch (_) {}
        }

        // 3) Book Jack's 365 calendar. This event is also the invite the
        //    client receives, so it carries the details and the manage link.
        const rescheduleToken = (crypto.randomUUID && crypto.randomUUID()) || `${date}-${Math.abs(hmToMin(start))}-${Date.now()}`;
        const siteUrl = (env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "");
        const manageUrl = `${siteUrl}/manage?token=${encodeURIComponent(rescheduleToken)}`;
        const invite = shootInvite({ serviceType: service_type, service, name, company, email, phone, pkgKey: pkg, packageLabel: b.package_label,
          address: property_address, postcode, addOns: add_ons, distanceMiles: distance_miles, surchargePence: surcharge_pence, totalPence: total_pence, notes, manageUrl });
        const ev = await graph(env, "POST", `/users/${encodeURIComponent(env.JACK_UPN)}/events`, {
          subject: invite.subject,
          body: { contentType: "html", content: invite.html },
          start: { dateTime: `${date}T${start}:00`, timeZone: "Europe/London" },
          end: { dateTime: `${date}T${endHm}:00`, timeZone: "Europe/London" },
          // The full address where we have it, the studio for studio sessions.
          location: invite.where ? { displayName: invite.where } : undefined,
          attendees: [{ emailAddress: { address: email, name }, type: "required" }],
        });

        // 4) Write the full pipeline row (capture the id so we can thread the
        //    confirmation into the member's booking correspondence).
        let newBookingId = null;
        try {
          // The invoice route belongs to Fine & Country property bookings only.
          // Decided here from the address, not taken from the request: the
          // browser could claim anything, and this one decides who gets billed.
          const fcProperty = service_type === "property"
            && String(email || "").toLowerCase().split("@")[1] === "fineandcountry.com";
          const bookingRow = {
            kind: "booking", service_type: service_type || null, audience: audience || null, brand: brand || null,
            package: pkg || null, add_ons: Array.isArray(add_ons) ? add_ons : [], postcode: postcode || null,
            // The address of the property itself, as opposed to the postcode we
            // took to work out travel. Property shoots only.
            property_address: property_address || null,
            distance_miles: distance_miles ?? null, surcharge_pence: surcharge_pence || 0,
            client_name: name, client_email: email, client_phone: phone || null, company: company || null,
            service: BOOKING_SERVICE_BY_TYPE[service_type] || service || null, shoot_date: `${date}T${start}:00`, stage: "booked", notes: notes || null,
            signed_name: signed_name || null, signed_at: signed_at || null, marketing_opt_in: !!marketing_opt_in,
            promo_code: promo_code || null, discount_pence: discount_pence || 0,
            account_user_id: accountUserId, reschedule_token: rescheduleToken, total_pence: total_pence ?? null,
            ms_event_id: ev.id || null, duration_min: dur,
            // Who settles this booking. Validated rather than trusted.
            payment_route: fcProperty && b.payment_route === "brand_invoice" ? "brand_invoice" : "agent_card",
            marketing_fee_claimed: fcProperty ? (b.marketing_fee_claimed === true) : null,
            fc_office: fcProperty && b.payment_route === "brand_invoice" ? (b.fc_office || null) : null,
          };
          let insRes = await sbPost(env, "videography_bookings", bookingRow, "return=representation");
          // PostgREST rejects the whole insert for one unknown column, and this
          // block sits inside a swallowing catch - so a booking made against a
          // database missing a column used to vanish silently while the client
          // still got their confirmation. Retry without it rather than lose it.
          if (!insRes.ok) {
            const errText = await insRes.clone().text().catch(() => "");
            if (/property_address/.test(errText)) {
              const { property_address: _pa, ...rowNoAddr } = bookingRow;
              insRes = await sbPost(env, "videography_bookings", rowNoAddr, "return=representation");
            }
            if (!insRes.ok) console.error("BOOKING NOT SAVED - calendar and emails went out anyway:", errText.slice(0, 400));
          }
          const arr = await insRes.json();
          newBookingId = Array.isArray(arr) && arr[0] ? arr[0].id : null;
        } catch (err) {
          console.error("BOOKING NOT SAVED - calendar and emails went out anyway:", err && err.message);
        }

        // 5) Confirmation emails (best-effort, never block the booking).
        const dateNice = (() => { try { return new Date(`${date}T12:00:00`).toLocaleDateString("en-GB", { weekday: "long", day: "numeric", month: "long", year: "numeric" }); } catch (_) { return date; } })();
        const packageLabel = service && service.toLowerCase().includes("content") ? (pkg || "") : (b.package_label || pkg || "");
        const ics = buildICS({
          uid: `${ev.id || rescheduleToken}@tmke.co.uk`, date, start, endHm,
          summary: invite.subject, description: invite.text,
          location: invite.where || "", organizer: env.JACK_UPN, attendeeEmail: email, attendeeName: name,
        });
        const icsB64 = bufToBase64(new TextEncoder().encode(ics).buffer);
        await sendEmail(env, {
          to: email, subject: `Booking confirmed - ${service || "TMKE"}`,
          html: await wrapInBrandedBase(env, bookingConfirmHtml({ name, service, serviceType: service_type, packageLabel, dateNice, time: start, addOns: add_ons, postcode, surchargePence: surcharge_pence, totalPence: total_pence, manageUrl })),
          attachments: [{ filename: "booking.ics", content: icsB64, contentType: "text/calendar" }],
        });
        await sendEmail(env, {
          to: env.JACK_NOTIFY || env.JACK_UPN, subject: `New booking - ${service || "Shoot"} - ${name}`,
          html: jackNotifyHtml({ name, company, email, phone, service, packageLabel, addOns: add_ons, postcode, distanceMiles: distance_miles, surchargePence: surcharge_pence, dateNice, time: start, totalPence: total_pence, signedName: signed_name, marketingOptIn: marketing_opt_in }),
        });
        try {
          await notifyAdmins(env, {
            area: "videography", event: "shoot_booked",
            title: `Shoot booked — ${service || "Shoot"}`,
            body: [name, dateNice, start].filter(Boolean).join(" · "),
            href: "/admin/videography", key: newBookingId || undefined,
            // `email`, not `em`: the undefined name threw inside this try, so
            // the admin centre never heard about a shoot booking (15 Oct).
            meta: { booking_id: newBookingId || null, email: email || null },
          });
        } catch (_) {}

        // Thread the confirmation into the member's booking correspondence.
        await logBookingMessage(env, {
          booking_id: newBookingId, booking_source: "videography",
          account_user_id: accountUserId, client_email: email,
          kind: "confirmation", subject: `Booking confirmed - ${service || "TMKE"}`,
          body: `Your ${service || "booking"} is confirmed for ${dateNice} at ${start}.`
            + (postcode ? ` Location: ${postcode}.` : "")
            + (total_pence != null ? ` Total ${gbpW(total_pence)} inc. VAT, invoiced on delivery.` : "")
            + ` We'll be in touch the day before to confirm the details.`,
        });

        // CRM + automations: upsert the contact; a brand-new account kicks off
        // any "account created" automation (e.g. the welcome series).
        try {
          const fn = String(name || "").trim().split(/\s+/);
          const bkTags = crmTags(email, ["Videography-Client", videographyProductTag(service_type)], { optIn: !!marketing_opt_in, member: !!(accountCreated || accountUserId) });
          const ci = { email, first_name: fn.shift() || name, last_name: fn.join(" ") || null, phone, company,
            source: "videography_" + (service_type || "booking"), lifecycle: "customer",
            marketing_opt_in: !!marketing_opt_in, tags: bkTags, user_id: accountUserId };
          if (accountCreated) await fireTrigger(env, "account_created", ci, { service, package: pkg });
          else await sbRpc(env, "upsert_contact", { p_email: email, p_first_name: ci.first_name, p_last_name: ci.last_name, p_phone: phone || null, p_company: company || null, p_source: ci.source, p_lifecycle: "customer", p_marketing_opt_in: !!marketing_opt_in, p_tags: bkTags, p_user_id: accountUserId });
        } catch (_) {}

        return json({ ok: true, eventId: ev.id, account_created: accountCreated }, 200, request, env);
      }

      // ---- TEG new-starter "Studio Day" booking (free to them; bill-to-TPE) ----
      // Reuses the normal booking machinery (account, Jack's calendar, code
      // redemption, confirmation email) but takes no payment and marks the row
      // bill_to='TPE'. Also flips the agent's TEG record to 'booked'.
      // ---- New-starter Studio Days for a shoot month (the booking page) ----
      // Which days are open, their sessions, and which are taken. See
      // newStarterPlan. Public: the page is reached from an emailed link.
      if (path.endsWith("/new-starter/days") && request.method === "GET") {
        let month = url.searchParams.get("month") || "";
        if (!/^\d{4}-\d{2}$/.test(month)) month = londonParts(new Date().toISOString()).ymd.slice(0, 7);
        try {
          const plan = await newStarterPlan(env, month);
          // Staff see why each session is taken; the page only needs taken.
          const u = await getUser(request, env).catch(() => null);
          if (u && isAdminEmail(u)) return json({ month, waiting: plan.waiting, blocks: Object.keys(plan.blocks), days: plan.days }, 200, request, env);
          return json({ month, days: plan.days.map((d) => ({ date: d.date, sessions: d.sessions.map(({ start, minutes, label, taken }) => ({ start, minutes, label, taken })) })) }, 200, request, env);
        } catch (e) {
          return json({ error: "The studio days couldn't be loaded." }, 502, request, env);
        }
      }

      if (path.endsWith("/new-starter/book") && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        const { date, start, name, phone, notes, password, code } = b || {};
        const em = String((b && b.email) || "").trim().toLowerCase();
        if (!date || !start || !name || !em) return json({ error: "Missing booking details." }, 400, request, env);
        if (!password || String(password).length < 8) return json({ error: "A password of at least 8 characters is required." }, 400, request, env);
        // The day and session must be one the booking page offers this month,
        // and still free (newStarterPlan reads the board and Jack's calendar,
        // leaving out the day's own block).
        let plan;
        try { plan = await newStarterPlan(env, String(date).slice(0, 7)); }
        catch (_) { return json({ error: "We couldn't check the studio diary just then. Please try again." }, 502, request, env); }
        const day = plan.days.find((d) => d.date === date);
        if (!day) return json({ error: "That date isn't a studio day this month. Please pick from the dates shown." }, 400, request, env);
        const session = day.sessions.find((x) => x.start === start);
        if (!session) return json({ error: "That time isn't a session on this studio day. Please pick from the times shown." }, 400, request, env);
        if (session.taken) return json({ error: "That session has just been taken. Please choose another." }, 409, request, env);
        const dur = session.minutes;
        const endHm = minToHm(hmToMin(start) + dur);
        const durWords = dur % 60 ? `${Math.floor(dur / 60)} and a half hours` : `${dur / 60} hours`;

        // 0) The single-use code must exist and still be live. It's voided when an
        // induction is cancelled, so this blocks a cancelled starter from booking.
        if (!code) return json({ error: "A booking code is required - please use the personalised link from your email." }, 400, request, env);
        {
          const pcRows = await sbGet(env, "videography_promo_codes", `code=ilike.${encodeURIComponent(String(code))}&select=active,redemptions,max_redemptions`);
          const pc = pcRows && pcRows[0];
          if (!pc || pc.active !== true || (pc.max_redemptions != null && (pc.redemptions || 0) >= pc.max_redemptions)) {
            return json({ error: "This booking code is no longer valid. If you think this is a mistake, please contact us." }, 403, request, env);
          }
        }

        // 2) Account: existing → verify their password and link; new → create.
        let accountUserId = null, accountCreated = false;
        const existing = await findUserByEmail(env, em);
        if (existing) {
          let ok = false;
          try {
            const tr = await fetch(`${env.SUPABASE_URL}/auth/v1/token?grant_type=password`, {
              method: "POST", headers: { apikey: env.SUPABASE_ANON_KEY, "Content-Type": "application/json" },
              body: JSON.stringify({ email: em, password }),
            });
            ok = tr.ok;
          } catch (_) {}
          if (!ok) return json({ error: "That email already has a TMKE account - the password didn't match. Use your existing password, or reset it on the sign-in page." }, 401, request, env);
          accountUserId = existing.id;
        } else {
          try {
            const cr = await fetch(`${env.SUPABASE_URL}/auth/v1/admin/users`, {
              method: "POST", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json" },
              body: JSON.stringify({ email: em, password, email_confirm: true, user_metadata: { full_name: name, phone: phone || null } }),
            });
            if (cr.ok) { const u = await cr.json(); accountUserId = (u && u.id) || null; accountCreated = true; }
            else { const u = await findUserByEmail(env, em); if (u) accountUserId = u.id; }
          } catch (_) {}
        }

        // 3) Redeem their single-use code (best-effort).
        if (code) {
          try {
            await fetch(`${env.SUPABASE_URL}/rest/v1/rpc/redeem_promo_code`, {
              method: "POST", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json" },
              body: JSON.stringify({ p_code: String(code).toUpperCase() }),
            });
          } catch (_) {}
        }

        // 4) Block Jack's calendar (studio session).
        const rescheduleToken = (crypto.randomUUID && crypto.randomUUID()) || `${date}-${start}-${Date.now()}`;
        const invite = shootInvite({ serviceType: "content-studio", service: "New-starter Studio Day", name, email: em, phone,
          lead: `New-starter Studio Day: ${durWords}, billed to The Property Experts.`, notes: notes || "",
          manageUrl: `${(env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "")}/manage?token=${encodeURIComponent(rescheduleToken)}` });
        let ev = {};
        try {
          ev = await graph(env, "POST", `/users/${encodeURIComponent(env.JACK_UPN)}/events`, {
            subject: invite.subject,
            body: { contentType: "html", content: invite.html },
            start: { dateTime: `${date}T${start}:00`, timeZone: "Europe/London" },
            end: { dateTime: `${date}T${endHm}:00`, timeZone: "Europe/London" },
            location: { displayName: invite.where },
            attendees: [{ emailAddress: { address: em, name }, type: "required" }],
          });
        } catch (_) {}

        // 5) Insert the booking row — bill-to-TPE, £295 + VAT (£354 inc).
        let newBookingId = null;
        try {
          const insRes = await sbPost(env, "videography_bookings", {
            kind: "booking", service_type: "content-studio", service: "New-starter Studio Day",
            client_name: name, client_email: em, client_phone: phone || null,
            shoot_date: `${date}T${start}:00`, stage: "booked", notes: notes || null,
            promo_code: code || null, discount_pence: 0, bill_to: "TPE", total_pence: 35400,
            // Every new-starter Studio Day is paid for out of The Property
            // Experts' induction package, not by the starter themselves - so
            // this books straight into the TEG invoicing route rather than
            // defaulting to card payment. bill_to is kept alongside for
            // continuity, but this is what actually drives the invoice now.
            payment_route: "brand_invoice_teg", teg_brand: "property_experts", teg_reason: "induction",
            account_user_id: accountUserId, reschedule_token: rescheduleToken,
            ms_event_id: ev.id || null, duration_min: dur, marketing_opt_in: false,
          }, "return=representation");
          const arr = await insRes.json();
          newBookingId = Array.isArray(arr) && arr[0] ? arr[0].id : null;
        } catch (_) {}

        // 6) CRM: tag like a normal videography booking + flip the TEG record to booked.
        // The "Videography-Booked" tag is the funnel's exit signal — an If/else on
        // it drops them out of the email sequence once they've booked.
        try {
          const fn = String(name || "").trim().split(/\s+/);
          const tags = crmTags(em, ["Videography-Client", videographyProductTag("content-studio"), "Videography-Booked"], { member: true });
          await sbRpc(env, "upsert_contact", { p_email: em, p_first_name: fn.shift() || name, p_last_name: fn.join(" ") || null, p_phone: phone || null, p_source: "new_starter_booking", p_lifecycle: "customer", p_tags: tags, p_user_id: accountUserId });
          const cRows = await sbGet(env, "contacts", `email=eq.${encodeURIComponent(lc(em))}&select=id`);
          const cid = cRows && cRows[0] && cRows[0].id;
          if (cid) {
            await fetch(`${env.SUPABASE_URL}/rest/v1/agent_profiles?contact_id=eq.${encodeURIComponent(cid)}`, {
              method: "PATCH", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=minimal" },
              body: JSON.stringify({ status: "booked", shoot_booked_at: `${date}T${start}:00` }),
            });
            // Belt-and-braces: pull them out of any running videography funnel now,
            // so no email fires between booking and the next If/else check.
            try {
              const funnels = await sbGet(env, "automations", `trigger_type=eq.new_starter_videography&select=id`);
              const fids = (funnels || []).map((a) => a.id);
              if (fids.length) await sbPatch(env, "automation_enrollments", `contact_id=eq.${cid}&status=eq.active&automation_id=in.(${fids.join(",")})`, { status: "stopped" });
            } catch (_) {}
          }
        } catch (_) {}

        // 7) Confirmation email to the starter + heads-up to Jack (best-effort).
        const dateNice = (() => { try { return new Date(`${date}T12:00:00`).toLocaleDateString("en-GB", { weekday: "long", day: "numeric", month: "long", year: "numeric" }); } catch (_) { return date; } })();
        const first = String(name || "there").trim().split(/\s+/)[0];
        const cHtml = `<div style="${EM_WRAP}">
          <div style="font-size:24px;font-weight:800;letter-spacing:0.14em;color:#371e28;margin:0 0 18px;">TMKE</div>
          <p style="${EM_P}">Hi ${first},</p>
          <p style="${EM_P}">Your <strong>Studio Day</strong> is booked. Here are the details:</p>
          <p style="${EM_P}"><strong>${dateNice}</strong> at <strong>${start}</strong> (${durWords})</p>
          <p style="${EM_P}">at the <strong>TMKE Content Studio</strong>. We'll confirm the full address and how to prepare in a reminder before the day.</p>
          <p style="${EM_P}">There's nothing for you to pay - your session is part of your induction package.</p>
          <p style="${EM_SMALL}">Need to change it? Just reply to this email.</p>
        </div>`;
        try { await sendEmail(env, { to: em, subject: "Your Studio Day is booked - TMKE", html: await wrapInBrandedBase(env, cHtml) }); } catch (_) {}
        try { await sendEmail(env, { to: env.JACK_NOTIFY || env.JACK_UPN, subject: `New Studio Day booking - ${name}`, html: `<p>New-starter Studio Day booked.</p><p><strong>${name}</strong> - ${dateNice} at ${start} (${durWords}), TMKE Content Studio.</p><p>${em}${phone ? " · " + phone : ""}</p><p>Bill to <strong>TPE</strong> - £295 + VAT.</p>` });
        try {
          await notifyAdmins(env, {
            area: "videography", event: "studio_day_booked",
            title: "Studio Day booked",
            body: [name, dateNice, start].filter(Boolean).join(" · "),
            href: "/admin/videography",
          });
        } catch (_) {} } catch (_) {}

        await logBookingMessage(env, {
          booking_id: newBookingId, booking_source: "videography", account_user_id: accountUserId, client_email: em,
          kind: "confirmation", subject: "Studio Day booked",
          body: `New-starter Studio Day booked for ${dateNice} at ${start}. Billed to TPE.`,
        });

        // Write the booked slot back to the TEG sheet's "Shoot Booked" column
        // (best-effort — needs the sheet shared with EDIT access to the service account).
        try { await agentSheetWriteBooked(env, em, `${dateNice}, ${start}`); } catch (_) {}

        return json({ ok: true, account_created: accountCreated }, 200, request, env);
      }

      // ---- Non-member enquiry (Property / Agent) — lands in the Enquiries inbox
      // (/admin/enquiries), tagged with a videography source, plus an FYI email
      // to Jack. It is NOT added to Jack's videography pipeline (that's bookings).
      if (path.endsWith("/videography/enquiry") && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        const { service, service_type, name, email, phone, company, postcode, message, marketing_opt_in } = b || {};
        if (!name || !email) return json({ error: "Please add your name and email." }, 400, request, env);
        // Split the full name — the enquiries table needs a non-empty last name.
        const nameParts = String(name).trim().split(/\s+/);
        const firstName = nameParts.shift() || name;
        const lastName = nameParts.join(" ") || "-";
        // Fold the fields the enquiries table has no column for into the message.
        const fullMessage = [
          message || "",
          postcode ? `Property / shoot postcode: ${postcode}` : "",
          `Marketing opt-in: ${marketing_opt_in ? "yes" : "no"}`,
        ].filter(Boolean).join("\n\n");
        // Hardened: don't fake success if the insert is rejected.
        const saved = await sbPost(env, "enquiries", {
          first_name: firstName, last_name: lastName, email,
          phone: phone || null, business_name: company || null,
          industry: service || null, message: fullMessage,
          source: `videography_${service_type || "general"}`, status: "new",
        });
        if (!saved.ok) {
          const detail = await saved.text().catch(() => "");
          console.error("videography enquiry insert failed", saved.status, detail);
          return json({ error: "We couldn't save your enquiry just then - please try again, or email hello@tmke.co.uk." }, 502, request, env);
        }
        const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
        await sendEmail(env, {
          to: email, subject: `Thanks for your enquiry - ${service || "TMKE"}`,
          html: await wrapInBrandedBase(env, `
            <h1 style="${EM_H1}">Thanks - we'll be in touch</h1>
            <p style="${EM_P}">Hi ${esc(name)}, thanks for your interest in ${esc(service || "our videography")}. Jack will be in touch shortly to talk through what you need and put a quote together.</p>
            ${message ? `<div style="${EM_QUOTE_TEXT}">${esc(message)}</div>` : ""}`),
        });
        await sendEmail(env, {
          to: env.JACK_NOTIFY || env.JACK_UPN, subject: `New enquiry - ${service || "Videography"} - ${name}`,
          html: `<div style="${EM_WRAP}">
            <h1 style="${EM_H1}">New enquiry - ${esc(service || "Videography")}</h1>
            <div style="${EM_QUOTE}">
              <div><span style="color:#888">Client:</span> ${esc(name)}</div>
              ${company ? `<div><span style="color:#888">Company:</span> ${esc(company)}</div>` : ""}
              <div><span style="color:#888">Email:</span> ${esc(email)}</div>
              ${phone ? `<div><span style="color:#888">Phone:</span> ${esc(phone)}</div>` : ""}
              ${postcode ? `<div><span style="color:#888">Location:</span> ${esc(postcode)}</div>` : ""}
              ${message ? `<div><span style="color:#888">Message:</span> ${esc(message)}</div>` : ""}
            </div>
            <p style="${EM_SMALL}">Saved to the Enquiries inbox (/admin/enquiries).</p></div>`,
        });
        try {
          await notifyAdmins(env, {
            area: "videography", event: "videography_enquiry",
            title: `Enquiry — ${service || "Videography"}`,
            body: [name, email, phone].filter(Boolean).join(" · "),
            href: "/admin/enquiries",
          });
        } catch (_) {}
        // CRM + automations: this is a form submission — upsert the lead and fire
        // any "form submitted" automation.
        try {
          await fireTrigger(env, "form_submitted", {
            email, first_name: firstName, last_name: lastName === "-" ? null : lastName,
            phone: phone || null, company: company || null, source: "videography_enquiry",
            lifecycle: "lead", marketing_opt_in: !!marketing_opt_in,
            tags: crmTags(email, "Interest: Videography", { optIn: !!marketing_opt_in }),
          }, { form: service_type || "videography" });
        } catch (_) {}
        return json({ ok: true }, 200, request, env);
      }

      // ---- Social Media — Get in Touch (Form 3): a general enquiry, optional
      //      account. Tag "General Enquiry". Auto-ack on every submit. ----------
      if (path.endsWith("/smm/enquiry") && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        const { first_name, last_name, business, email, phone, message, password, marketing_opt_in, turnstile_token, hp } = b || {};
        // Honeypot — a bot filled the hidden field. Pretend success, drop silently.
        if (hp) return json({ ok: true }, 200, request, env);
        // Spam protection (no-ops until TURNSTILE_SECRET_KEY is set).
        const ip = request.headers.get("CF-Connecting-IP") || "";
        if (!(await verifyTurnstile(env, turnstile_token, ip))) return json({ error: "Spam check failed - please try again." }, 400, request, env);
        if (!first_name || !last_name || !business || !email || !message)
          return json({ error: "Please complete all required fields." }, 400, request, env);
        const fullName = `${first_name} ${last_name}`.trim();

        // Signed-in members are identified by their session token — the enquiry
        // links straight to their account, no password prompt needed.
        const authedUser = await getUser(request, env);

        // Optional account creation (password is optional on this form).
        let accountUserId = authedUser ? authedUser.id : null, accountCreated = false;
        if (!authedUser && password) {
          if (!smmPasswordOk(password)) return json({ error: "Password must be at least 8 characters and include a number and a special character." }, 400, request, env);
          try {
            const cr = await fetch(`${env.SUPABASE_URL}/auth/v1/admin/users`, {
              method: "POST",
              headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json" },
              body: JSON.stringify({ email, password, email_confirm: true, user_metadata: { full_name: fullName, company: business || null, phone: phone || null } }),
            });
            if (cr.ok) { const u = await cr.json(); accountUserId = (u && u.id) || null; accountCreated = true; }
            else {
              const u = await findUserByEmail(env, email);
              if (u) accountUserId = u.id;
            }
          } catch (_) { /* account is best-effort; the enquiry still saves */ }
        }

        // Persist the lead — merged onto the existing card if this email is known.
        const up = await upsertSmmLead(env, email, {
          kind: "enquiry", tag: "General Enquiry", stage: "general_enquiry",
          first_name, last_name, full_name: fullName, email, phone: phone || null,
          business: business || null, message: message || null,
          marketing_opt_in: !!marketing_opt_in,
          account_user_id: accountUserId, account_created: accountCreated,
        });
        if (!up.id) {
          console.error("smm enquiry upsert failed", up.error || "");
          return json({ error: "We couldn't save your message just then - please try again, or email hello@tmke.co.uk." }, 502, request, env);
        }
        const smmEnquiryId = up.id;
        await logBookingMessage(env, { booking_id: smmEnquiryId, booking_source: "smm", account_user_id: accountUserId, client_email: email, channel: "note", kind: "note", subject: "Enquiry received", body: smmEnquiryNote({ route: "the website enquiry form", name: fullName, email, phone, business, message }) });

        const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

        // Auto-acknowledgement to the sender — ALWAYS (per brief).
        await sendEmail(env, {
          to: email, subject: "Thanks - we've got your message",
          html: await wrapInBrandedBase(env, `
            <h1 style="${EM_H1}">Thanks, ${esc(first_name)} - message received</h1>
            <p style="${EM_P}">We've received your enquiry and a member of the TMKE team will be in touch within one working day.</p>
            ${message ? `<div style="${EM_QUOTE_TEXT}">${esc(message)}</div>` : ""}
            ${accountCreated ? `<p style="${EM_P}">We've also created your TMKE account - sign in any time at <a href="https://tmke.co.uk/login" style="color:#371e28">tmke.co.uk/login</a>.</p>` : ""}`),
        });
        await logBookingMessage(env, {
          booking_id: smmEnquiryId, booking_source: "smm",
          account_user_id: accountUserId, client_email: email,
          kind: "confirmation", subject: "Thanks - we've got your message",
          body: `Auto-acknowledgement sent: we've received ${first_name}'s enquiry and will be in touch within one working day.`,
        });

        // Notify the SMM team.
        await sendEmail(env, {
          to: smmNewBusiness(env) || env.JACK_NOTIFY, subject: `New enquiry - Social Media - ${fullName}`,
          html: `<div style="${EM_WRAP}">
            <h1 style="${EM_H1}">New Social Media enquiry</h1>
            <div style="${EM_QUOTE}">
              <div><span style="color:#888">Name:</span> ${esc(fullName)}</div>
              <div><span style="color:#888">Business:</span> ${esc(business)}</div>
              <div><span style="color:#888">Email:</span> ${esc(email)}</div>
              ${phone ? `<div><span style="color:#888">Phone:</span> ${esc(phone)}</div>` : ""}
              <div><span style="color:#888">Message:</span> ${esc(message)}</div>
              <div><span style="color:#888">Marketing:</span> ${marketing_opt_in ? "Opted in" : "No"}</div>
              <div><span style="color:#888">Account:</span> ${accountCreated ? "Created" : (accountUserId ? "Existing" : "None")}</div>
            </div>
            <p style="${EM_SMALL}">In the SMM pipeline as a lead (general_enquiry).</p></div>`,
        });
        /* Not a client yet, so it goes to whoever is picking up new business
           rather than to an account manager who does not have one. */
        try {
          await notifyAdmins(env, {
            area: "social", event: "smm_enquiry",
            title: "Social media enquiry",
            body: [fullName, email, company].filter(Boolean).join(" · "),
            href: "/admin/social",
            also: [smmNewBusiness(env)],
          });
        } catch (_) {}

        // CRM + automations: upsert the contact + fire any "form submitted" flow.
        try {
          await fireTrigger(env, "form_submitted", {
            email, first_name, last_name, phone: phone || null, company: business || null,
            source: "smm_enquiry", lifecycle: "lead", marketing_opt_in: !!marketing_opt_in,
            tags: crmTags(email, "Interest: SMM", { optIn: !!marketing_opt_in, member: !!(accountUserId || accountCreated) }), user_id: accountUserId || null,
          }, { form: "smm_enquiry", tag: "General Enquiry" });
        } catch (_) {}

        return json({ ok: true, account_created: accountCreated }, 200, request, env);
      }

      /* ---- Social Media Management — join the waitlist -----------------------
         Management is full, so the ask is "tell me when there is a space", not
         "sell me". One endpoint for all three funnels — the public site, the
         member hub's Your SMM page, and eventually a link in a marketing email
         — because they differ only in where the person was standing. `source`
         records which, so we can tell later which funnel actually works.

         Everything the enquiry form does, for the same reasons: honeypot and
         Turnstile, one merged lead per email rather than a duplicate per
         submit, a note on their file, an acknowledgement to them, an alert to
         us, and a CRM contact carrying the interest tag. */
      if (path.endsWith("/smm/waitlist") && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        const { message, marketing_opt_in, turnstile_token, hp } = b || {};
        if (hp) return json({ ok: true }, 200, request, env);   // bot; look successful, save nothing

        // A signed-in member is identified by their token; nobody is asked to
        // make an account to join a list.
        const authedUser = await getUser(request, env);
        const accountUserId = authedUser ? authedUser.id : null;

        // Turnstile guards the public form. A member has already passed a real
        // auth check and the hub sends a confirmation with no widget on it, so
        // demanding a token there would reject every member.
        if (!authedUser) {
          const ip = request.headers.get("CF-Connecting-IP") || "";
          if (!(await verifyTurnstile(env, turnstile_token, ip))) return json({ error: "Spam check failed - please try again." }, 400, request, env);
        }

        /* A member in the hub has told us all of this once already, so that
           funnel sends a confirmation rather than a form and the details come
           from their account and their existing records — never from the
           request body, which for a signed-in user would let anyone file a
           waitlist entry in somebody else's name. The website's form still
           supplies its own, because there is nobody to look up. */
        let known = {};
        if (authedUser) {
          const meta = authedUser.user_metadata || {};
          const prior = (await sbGet(env, "smm_leads", `email=ilike.${encodeURIComponent(authedUser.email)}&select=full_name,business,phone&order=created_at.desc&limit=1`))?.[0] || {};
          const contact = (await sbGet(env, "contacts", `email=ilike.${encodeURIComponent(authedUser.email)}&select=first_name,last_name,company,phone&limit=1`))?.[0] || {};
          known = {
            email: authedUser.email,
            full_name: meta.name || meta.full_name || prior.full_name || [contact.first_name, contact.last_name].filter(Boolean).join(" ").trim(),
            business: meta.company || prior.business || contact.company || "",
            phone: meta.phone || prior.phone || contact.phone || "",
          };
        }
        const email    = authedUser ? known.email : b.email;
        const business = (authedUser ? known.business : b.business) || null;
        const phone    = (authedUser ? known.phone : b.phone) || null;

        /* One "Full name" field on the public form, because asking a waitlist
           to fill two boxes for a name is friction for nothing. The lead table
           wants the halves, so the last word is the surname and everything
           before it is the first name — which handles "Anne Marie Smith" and
           leaves a single-word name as a first name rather than inventing a
           surname. A member with no name saved anywhere falls back to the part
           of their email before the @, so the lead is never nameless. */
        const rawName = String((authedUser ? known.full_name : b.full_name) || `${b.first_name || ""} ${b.last_name || ""}`).trim().replace(/\s+/g, " ");
        if (!email) return json({ error: "Please give us your email." }, 400, request, env);
        if (!rawName && !authedUser) return json({ error: "Please give us your name." }, 400, request, env);
        const fullName = rawName || String(email).split("@")[0];
        const nameBits = fullName.split(" ");
        const first_name = nameBits.length > 1 ? nameBits.slice(0, -1).join(" ") : fullName;
        const last_name = nameBits.length > 1 ? nameBits[nameBits.length - 1] : "";
        const source = ["website", "hub", "email"].includes(String(b.source || "")) ? b.source : (authedUser ? "hub" : "website");
        const SOURCE_LABEL = { website: "the website", hub: "the member hub", email: "an email link" };

        const up = await upsertSmmLead(env, email, {
          kind: "waitlist", tag: "SMM Waitlist", stage: "waitlist",
          first_name, last_name, full_name: fullName, email, phone: phone || null,
          business: business || null, message: message || null,
          marketing_opt_in: !!marketing_opt_in, account_user_id: accountUserId,
        });
        if (!up.id) {
          console.error("smm waitlist upsert failed", up.error || "");
          return json({ error: "We couldn't add you to the list just then - please try again, or email hello@tmke.co.uk." }, 502, request, env);
        }
        const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
        await logBookingMessage(env, {
          booking_id: up.id, booking_source: "smm", account_user_id: accountUserId, client_email: email,
          channel: "note", kind: "note", subject: "Enquiry received",
          body: smmEnquiryNote({ route: `the waitlist, via ${SOURCE_LABEL[source]}`, name: fullName, email, phone, business, message }),
        });

        // To them.
        await sendEmail(env, {
          to: email, subject: "You're on the list - TMKE Social Media Management",
          html: await wrapInBrandedBase(env, `
            <h1 style="${EM_H1}">You're on the list, ${esc(first_name)}</h1>
            <p style="${EM_P}">Social Media Management is full at the moment - we cap how many agencies we take so the ones we have get the attention they pay for. You're on the waitlist now, and we'll come to you the moment a space opens.</p>
            <p style="${EM_P}">In the meantime, our <strong>Social Media Marketing</strong> service does have space. It's a shoot day every quarter with our videographer, then we edit, caption and schedule everything across the three months. If that sounds closer to what you need, just reply and we'll talk it through.</p>`),
        });
        await logBookingMessage(env, {
          booking_id: up.id, booking_source: "smm", account_user_id: accountUserId, client_email: email,
          kind: "confirmation", subject: "You're on the list - TMKE Social Media Management",
          body: `Auto-acknowledgement sent: confirmed ${first_name} is on the Social Media Management waitlist, and mentioned Social Media Marketing has space.`,
        });

        // To us — Sam runs social, so she is on this one by name rather than
        // relying on whoever happens to read the shared inbox.
        const fileLink = `${unsubBase(env)}/admin/social?lead=${encodeURIComponent(up.id)}`;
        const notify = [...new Set([smmNewBusiness(env), "samantha@themarketingexperts.co.uk"].filter(Boolean))].join(",");
        await sendEmail(env, {
          to: notify, subject: `SMM waitlist - ${fullName}`,
          html: `<div style="${EM_WRAP}">
            <h1 style="${EM_H1}">Someone joined the SMM waitlist</h1>
            <div style="${EM_QUOTE}">
              <div><span style="color:#888">Name:</span> ${esc(fullName)}</div>
              ${business ? `<div><span style="color:#888">Business:</span> ${esc(business)}</div>` : ""}
              <div><span style="color:#888">Email:</span> ${esc(email)}</div>
              ${phone ? `<div><span style="color:#888">Phone:</span> ${esc(phone)}</div>` : ""}
              ${message ? `<div><span style="color:#888">Message:</span> ${esc(message)}</div>` : ""}
              <div><span style="color:#888">Came from:</span> ${esc(SOURCE_LABEL[source])}</div>
              <div><span style="color:#888">Marketing:</span> ${marketing_opt_in ? "Opted in" : "No"}</div>
              <div><span style="color:#888">Account:</span> ${accountUserId ? "Signed-in member" : "None"}</div>
            </div>
            <p style="${EM_P}"><a href="${fileLink}" style="color:#371e28">Open their file in the admin centre &rarr;</a></p>
            <p style="${EM_SMALL}">They are in the SMM pipeline at the Waitlist stage.</p></div>`,
        });

        // CRM: the contact, tagged with what they actually want.
        try {
          await fireTrigger(env, "form_submitted", {
            email, first_name, last_name, phone: phone || null, company: business || null,
            source: "smm_waitlist", lifecycle: "lead", marketing_opt_in: !!marketing_opt_in,
            tags: crmTags(email, ["Interest: SMM", "Interest: Social Media Management"], { optIn: !!marketing_opt_in, member: !!accountUserId }),
            user_id: accountUserId || null,
          }, { form: "smm_waitlist", tag: "SMM Waitlist" });
        } catch (_) {}

        return json({ ok: true, existed: up.existed }, 200, request, env);
      }

      // ---- Social Media — the brochure file itself. Streams the PDF out of the
      //      public assets bucket with Content-Disposition: attachment, so the
      //      browser downloads it instead of opening it in a tab. The bucket's
      //      own URL cannot do that (it is a different origin, so a link's
      //      `download` attribute is ignored). The form's done state and the
      //      brochure email both point here. -------------------------------
      if (path.endsWith("/smm/brochure.pdf") && request.method === "GET") {
        const src = env.SMM_BROCHURE_URL || SMM_BROCHURE_FALLBACK;
        const filename = "TMKE - Services Brochure 2026.pdf";
        const headers = {
          "Content-Type": "application/pdf",
          "Content-Disposition": `attachment; filename="${filename}"`,
          "Cache-Control": "public, max-age=3600",
        };
        // Native R2 read when the object is in our bucket; plain fetch otherwise.
        const key = (() => { try { const u = new URL(src); return u.hostname === "assets.tmke.co.uk" ? decodeURIComponent(u.pathname.slice(1)) : null; } catch (_) { return null; } })();
        if (env.ASSETS && key) {
          const obj = await env.ASSETS.get(key);
          if (obj) {
            if (obj.size) headers["Content-Length"] = String(obj.size);
            if (obj.httpEtag) headers["ETag"] = obj.httpEtag;
            return new Response(obj.body, { status: 200, headers });
          }
        }
        const upstream = await fetch(src);
        if (!upstream.ok) return new Response("The brochure isn't available right now.", { status: 502, headers: { "Content-Type": "text/plain" } });
        return new Response(upstream.body, { status: 200, headers });
      }

      // ---- Social Media — Download a Brochure (Form 1): emails the brochure,
      //      stores the email as a lead, optional account. Brochure goes out on
      //      EVERY submit regardless of account creation. ---------------------
      if (path.endsWith("/smm/brochure") && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        const { full_name, email, password, marketing_opt_in, turnstile_token, hp } = b || {};
        if (hp) return json({ ok: true }, 200, request, env);
        const ip = request.headers.get("CF-Connecting-IP") || "";
        if (!(await verifyTurnstile(env, turnstile_token, ip))) return json({ error: "Spam check failed - please try again." }, 400, request, env);
        if (!full_name || !email) return json({ error: "Please add your name and email." }, 400, request, env);

        // Optional account creation (password is optional on this form).
        let accountUserId = null, accountCreated = false;
        if (password) {
          if (!smmPasswordOk(password)) return json({ error: "Password must be at least 8 characters and include a number and a special character." }, 400, request, env);
          try {
            const cr = await fetch(`${env.SUPABASE_URL}/auth/v1/admin/users`, {
              method: "POST",
              headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json" },
              body: JSON.stringify({ email, password, email_confirm: true, user_metadata: { full_name } }),
            });
            if (cr.ok) { const u = await cr.json(); accountUserId = (u && u.id) || null; accountCreated = true; }
            else {
              const u = await findUserByEmail(env, email);
              if (u) accountUserId = u.id;
            }
          } catch (_) { /* account is best-effort; the brochure still sends */ }
        }

        const up = await upsertSmmLead(env, email, {
          kind: "brochure", tag: "Brochure Download", stage: "brochure_downloaded", brochure_sent: true,
          full_name, email, marketing_opt_in: !!marketing_opt_in,
          account_user_id: accountUserId, account_created: accountCreated,
        });
        if (!up.id) {
          console.error("smm brochure upsert failed", up.error || "");
          return json({ error: "We couldn't process that just then - please try again, or email hello@tmke.co.uk." }, 502, request, env);
        }
        const smmBrochureId = up.id;
        await logBookingMessage(env, { booking_id: smmBrochureId, booking_source: "smm", account_user_id: accountUserId, client_email: email, channel: "note", kind: "note", subject: "Enquiry received", body: smmEnquiryNote({ route: "a brochure download", name: full_name, email }) });

        const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
        // The Worker's own download route (see GET /smm/brochure.pdf above), so
        // the email button and the form's link save the file rather than open it.
        const brochureUrl = url.origin + path.replace(/\/smm\/brochure$/, "/smm/brochure.pdf");
        const firstName = String(full_name).trim().split(/\s+/)[0] || "there";

        // Email the brochure (a link — works the moment the PDF is uploaded).
        await sendEmail(env, {
          to: email, subject: "Your TMKE social media brochure",
          html: await wrapInBrandedBase(env, `
            <h1 style="${EM_H1}">Here's your brochure, ${esc(firstName)}</h1>
            <p style="${EM_P}">Thanks for your interest in TMKE social media management. Everything's in the brochure below - what's included, how it works, and what it costs.</p>
            <p style="margin:0 0 22px"><a href="${esc(brochureUrl)}" style="${EM_BTN}">Download the brochure &rarr;</a></p>
            ${accountCreated ? `<p style="${EM_P}">We've also created your TMKE account so you can manage your downloads and bookings in one place - sign in any time at <a href="https://tmke.co.uk/login" style="color:#371e28">tmke.co.uk/login</a>.</p>` : ""}`),
        });
        await logBookingMessage(env, {
          booking_id: smmBrochureId, booking_source: "smm",
          account_user_id: accountUserId, client_email: email,
          kind: "confirmation", subject: "Your TMKE social media brochure",
          body: `Brochure sent to ${firstName}. Link: ${brochureUrl}`,
        });

        // CRM + automations: upsert the contact + fire any "form submitted" flow.
        try {
          const bparts = String(full_name).trim().split(/\s+/);
          await fireTrigger(env, "form_submitted", {
            email, first_name: bparts.shift() || full_name, last_name: bparts.join(" ") || null,
            source: "smm_brochure", lifecycle: "lead", marketing_opt_in: !!marketing_opt_in,
            tags: crmTags(email, "Interest: SMM", { optIn: !!marketing_opt_in, member: !!(accountUserId || accountCreated) }), user_id: accountUserId || null,
          }, { form: "smm_brochure", tag: "Brochure Download" });
        } catch (_) {}

        return json({ ok: true, account_created: accountCreated, brochure_url: brochureUrl }, 200, request, env);
      }

      // ---- Social Media — Discovery-call availability (Form 2). Slots for the
      //      SMM account manager's diary (SMM_MANAGER_UPN). Reuses the shared
      //      working-hours in videography_availability. Gated until the manager
      //      mailbox is set. -----------------------------------------------------
      if (path.endsWith("/smm/availability") && request.method === "GET") {
        const cal = env.SMM_MANAGER_UPN;
        if (!cal) return json({ slots: [], not_configured: true }, 200, request, env);
        const date = url.searchParams.get("date");
        const duration = parseInt(url.searchParams.get("duration") || "30", 10);
        if (!date) return json({ error: "Missing date" }, 400, request, env);
        const wd = new Date(date + "T12:00:00Z").getUTCDay();
        const rows = (await sbGet(env, "videography_availability", `weekday=eq.${wd}&select=*`)) || [];
        const hours = rowHours(rows[0]);
        if (!hours.length) return json({ slots: [], duration }, 200, request, env);
        const STEP = 30;
        const openHours = new Set(hours);
        const dayStartMin = Math.min(...hours) * 60;
        const dayEndMin = (Math.max(...hours) + 1) * 60;
        const need = Math.max(1, Math.ceil(duration / STEP));
        const sched = await graph(env, "POST", `/users/${encodeURIComponent(cal)}/calendar/getSchedule`, {
          schedules: [cal],
          startTime: { dateTime: `${date}T${minToHm(dayStartMin)}:00`, timeZone: "Europe/London" },
          endTime: { dateTime: `${date}T${minToHm(dayEndMin)}:00`, timeZone: "Europe/London" },
          availabilityViewInterval: STEP,
        });
        const view = (sched.value && sched.value[0] && sched.value[0].availabilityView) || "";
        const totalSlots = Math.floor((dayEndMin - dayStartMin) / STEP);
        const slots = [];
        for (let i = 0; i + need <= totalSlots; i++) {
          let ok = true;
          for (let k = 0; k < need; k++) {
            const slotMin = dayStartMin + (i + k) * STEP;
            const busy = view[i + k];
            if (!openHours.has(Math.floor(slotMin / 60)) || (busy && busy !== "0")) { ok = false; break; }
          }
          if (ok) slots.push(minToHm(dayStartMin + i * STEP));
        }
        return json({ slots, duration }, 200, request, env);
      }

      // ---- Social Media — Book a Discovery Call (Form 2). Mandatory account.
      //      Books the SMM manager's calendar, stores the lead, confirms by
      //      email with an ICS. ------------------------------------------------
      if (path.endsWith("/smm/discovery") && request.method === "POST") {
        const cal = env.SMM_MANAGER_UPN;
        if (!cal) return json({ error: "Discovery call booking is being set up - please check back shortly." }, 503, request, env);
        const b = await request.json().catch(() => ({}));
        const { first_name, last_name, business, email, phone, password, marketing_opt_in, date, start, duration, turnstile_token, hp } = b || {};
        if (hp) return json({ ok: true }, 200, request, env);
        const ip = request.headers.get("CF-Connecting-IP") || "";
        if (!(await verifyTurnstile(env, turnstile_token, ip))) return json({ error: "Spam check failed - please try again." }, 400, request, env);
        if (!first_name || !last_name || !business || !email || !date || !start) return json({ error: "Please complete all required fields and pick a time." }, 400, request, env);
        // Signed-in members are identified by their session token and book
        // straight onto their existing account; everyone else must set a
        // password (account creation is part of booking a call).
        const authedUser = await getUser(request, env);
        if (!authedUser && (!password || !smmPasswordOk(password))) return json({ error: "A password of at least 8 characters including a number and a special character is required." }, 400, request, env);
        const fullName = `${first_name} ${last_name}`.trim();
        const dur = parseInt(duration || "30", 10);
        const endHm = minToHm(hmToMin(start) + dur);

        // Slot still free?
        const check = await graph(env, "POST", `/users/${encodeURIComponent(cal)}/calendar/getSchedule`, {
          schedules: [cal],
          startTime: { dateTime: `${date}T${start}:00`, timeZone: "Europe/London" },
          endTime: { dateTime: `${date}T${endHm}:00`, timeZone: "Europe/London" },
          availabilityViewInterval: Math.max(15, dur),
        });
        const view = (check.value && check.value[0] && check.value[0].availabilityView) || "";
        if (view && /[^0]/.test(view)) return json({ error: "That time was just taken - please choose another." }, 409, request, env);

        // Account creation is mandatory at this step (signed-in members already
        // have one — their verified id is used directly).
        let accountUserId = authedUser ? authedUser.id : null, accountCreated = false;
        if (!authedUser) try {
          const cr = await fetch(`${env.SUPABASE_URL}/auth/v1/admin/users`, {
            method: "POST",
            headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json" },
            body: JSON.stringify({ email, password, email_confirm: true, user_metadata: { full_name: fullName, company: business || null, phone: phone || null } }),
          });
          if (cr.ok) { const u = await cr.json(); accountUserId = (u && u.id) || null; accountCreated = true; }
          else {
            const u = await findUserByEmail(env, email);
            if (u) accountUserId = u.id;
          }
        } catch (_) { /* account is best-effort; the booking still proceeds */ }

        const ev = await graph(env, "POST", `/users/${encodeURIComponent(cal)}/events`, {
          subject: `Discovery Call - ${fullName}`,
          body: { contentType: "text", content: [business && `Business: ${business}`, phone && `Phone: ${phone}`].filter(Boolean).join("\n") },
          start: { dateTime: `${date}T${start}:00`, timeZone: "Europe/London" },
          end: { dateTime: `${date}T${endHm}:00`, timeZone: "Europe/London" },
          attendees: [
            { emailAddress: { address: email, name: fullName }, type: "required" },
            // The SMM manager (Abigail) — gets the invite in her own calendar even
            // though her mailbox is on a different tenant. Skipped if it equals the
            // host mailbox (avoids inviting hello@ to its own event).
            ...(env.SMM_NOTIFY && env.SMM_NOTIFY.toLowerCase() !== cal.toLowerCase()
              ? [{ emailAddress: { address: env.SMM_NOTIFY, name: "TMKE Social Media" }, type: "required" }] : []),
          ],
          isOnlineMeeting: true,
        });
        const token = (crypto.randomUUID && crypto.randomUUID()) || `${date}-${start}`;

        const up = await upsertSmmLead(env, email, {
          kind: "discovery", tag: "Discovery Call", stage: "discovery_call_booked",
          // Booked is enough to be at Discovery call (Danielle, 5 Nov 2026); the
          // call itself is the file's meeting.
          pipeline_stage: "meeting_set", meeting_at: `${date}T${start}:00`,
          first_name, last_name, full_name: fullName, email, phone: phone || null, business: business || null,
          call_at: `${date}T${start}:00`, duration_min: dur, reschedule_token: token, ms_event_id: ev.id || null,
          marketing_opt_in: !!marketing_opt_in, account_user_id: accountUserId, account_created: accountCreated,
        });
        const smmDiscoveryId = up.id;
        if (!smmDiscoveryId) console.error("smm discovery upsert failed", up.error || "");  // calendar event still created - don't fake failure

        const dateNice = (() => { try { return new Date(`${date}T12:00:00`).toLocaleDateString("en-GB", { weekday: "long", day: "numeric", month: "long", year: "numeric" }); } catch (_) { return date; } })();
        const ics = buildICS({ uid: `${ev.id || token}@tmke.co.uk`, date, start, endHm, summary: "Discovery Call - TMKE Social Media", description: "A call with TMKE to talk through your social media.", location: "Online / phone", organizer: cal, attendeeEmail: email, attendeeName: fullName });
        const icsB64 = bufToBase64(new TextEncoder().encode(ics).buffer);
        const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
        await sendEmail(env, {
          to: email, subject: `Your call is booked - ${dateNice}`,
          html: await wrapInBrandedBase(env, `
            <h1 style="${EM_H1}">Your call is booked</h1>
            <p style="${EM_P}">Hi ${esc(first_name)}, your call with the TMKE team is confirmed for <strong>${esc(dateNice)} at ${esc(start)}</strong>. We've attached a calendar invite - no prep needed, just bring your questions.</p>
            ${accountCreated ? `<p style="${EM_P}">We've created your TMKE account so your call details, documents, and future bookings live in one place - sign in any time at <a href="https://tmke.co.uk/login" style="color:#371e28">tmke.co.uk/login</a>.</p>` : ""}
            <p style="${EM_P}">Need to change it? Just reply to this email or contact <a href="mailto:hello@tmke.co.uk" style="color:#371e28">hello@tmke.co.uk</a>.</p>`),
          attachments: [{ filename: "discovery-call.ics", content: icsB64, contentType: "text/calendar" }],
        });
        await logBookingMessage(env, {
          booking_id: smmDiscoveryId, booking_source: "smm",
          account_user_id: accountUserId, client_email: email,
          kind: "confirmation", subject: `Your call is booked - ${dateNice}`,
          body: `Your social media discovery call is booked for ${dateNice} at ${start}. It's an online/phone call - no prep needed, just bring your questions.`,
        });
        await logBookingMessage(env, { booking_id: smmDiscoveryId, booking_source: "smm", account_user_id: accountUserId, client_email: email, channel: "note", kind: "note", subject: "Enquiry received", body: smmEnquiryNote({ route: "a discovery call booking on the website", name: fullName, email, phone, business, extra: `Discovery call booked for ${dateNice} at ${start}.` }) });
        await sendEmail(env, {
          to: smmNewBusiness(env) || env.JACK_NOTIFY, subject: `New discovery call - Social Media - ${fullName} - ${dateNice} ${start}`,
          html: `<div style="${EM_WRAP}">
            <h1 style="${EM_H1}">Discovery call booked (Social Media)</h1>
            <div style="${EM_QUOTE}">
              <div><span style="color:#888">Client:</span> ${esc(fullName)}</div>
              <div><span style="color:#888">Business:</span> ${esc(business)}</div>
              <div><span style="color:#888">Email:</span> ${esc(email)}</div>
              ${phone ? `<div><span style="color:#888">Phone:</span> ${esc(phone)}</div>` : ""}
              <div><span style="color:#888">When:</span> ${esc(dateNice)} at ${esc(start)}</div>
            </div></div>`,
        });
        try {
          await notifyAdmins(env, {
            area: "social", event: "smm_discovery_booked",
            title: "Discovery call booked — social",
            body: [fullName, dateNice, start].filter(Boolean).join(" · "),
            href: "/admin/social",
            also: [smmNewBusiness(env)],
          });
        } catch (_) {}
        // CRM + automations: upsert the contact + fire form-submitted (and
        // account-created, since a booking always makes an account).
        try {
          await fireTrigger(env, "form_submitted", {
            email, first_name, last_name, phone: phone || null, company: business || null,
            source: "smm_discovery", lifecycle: "lead", marketing_opt_in: !!marketing_opt_in,
            tags: crmTags(email, ["Interest: SMM", "Discovery-Call-Booked: SMM"], { optIn: !!marketing_opt_in, member: !!(accountUserId || accountCreated) }), user_id: accountUserId || null,
          }, { form: "smm_discovery", tag: "Discovery Call" });
          if (accountCreated) await fireTrigger(env, "account_created", {
            email, first_name, last_name, company: business || null, user_id: accountUserId || null, lifecycle: "lead",
          }, { form: "smm_discovery" });
        } catch (_) {}
        return json({ ok: true, account_created: accountCreated, eventId: ev.id }, 200, request, env);
      }

      // ---- Register interest (Content Studio non-members) --------------------
      if (path.endsWith("/videography/register-interest") && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        const email = String((b && b.email) || "").trim();
        const service = (b && b.service) || "content-studio";
        const optin = !!(b && b.marketing_opt_in);
        if (!email) return json({ error: "Please add your email." }, 400, request, env);
        await sbPost(env, "videography_bookings", {
          kind: "register_interest", service_type: service, audience: "non-member",
          client_email: email, service: "Content Studio", stage: "enquiry_non_member",
          notes: "Register interest (members-only service)", marketing_opt_in: optin,
        });
        try {
          await fireTrigger(env, "form_submitted", {
            email, source: "videography_register_interest", lifecycle: "lead",
            marketing_opt_in: optin, tags: crmTags(email, "Interest: Videography", { optIn: optin }),
          }, { form: "videography_register_interest" });
        } catch (_) {}
        return json({ ok: true }, 200, request, env);
      }

      // ---- Videography — Download a Brochure: emails the videography brochure,
      //      stores the lead, optional account creation (password only offered to
      //      people who don't already have a TMKE account — the form checks
      //      /videography/account-exists first). Brochure goes out on EVERY
      //      submit regardless of account creation. ----------------------------
      if (path.endsWith("/videography/brochure") && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        const { full_name, email, password, marketing_opt_in, hp } = b || {};
        if (hp) return json({ ok: true }, 200, request, env);
        if (!full_name || !email) return json({ error: "Please add your name and email." }, 400, request, env);

        // Optional account creation (password is optional; the form only shows
        // it to people who don't yet have an account).
        let accountUserId = null, accountCreated = false;
        if (password) {
          if (!smmPasswordOk(password)) return json({ error: "Password must be at least 8 characters and include a number and a special character." }, 400, request, env);
          try {
            const cr = await fetch(`${env.SUPABASE_URL}/auth/v1/admin/users`, {
              method: "POST",
              headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json" },
              body: JSON.stringify({ email, password, email_confirm: true, user_metadata: { full_name } }),
            });
            if (cr.ok) { const u = await cr.json(); accountUserId = (u && u.id) || null; accountCreated = true; }
            else {
              const u = await findUserByEmail(env, email);
              if (u) accountUserId = u.id;
            }
          } catch (_) { /* account is best-effort; the brochure still sends */ }
        }

        // NB videography_bookings has no account_created column — sending it
        // makes PostgREST reject the whole insert.
        await sbPost(env, "videography_bookings", {
          kind: "brochure", service_type: "brochure", audience: accountUserId ? "member" : "non-member",
          client_email: email, client_name: full_name, service: "Videography Brochure",
          stage: "brochure_downloaded", notes: "Brochure download", marketing_opt_in: !!marketing_opt_in,
          account_user_id: accountUserId,
        });

        const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
        const brochureUrl = env.VIDEOGRAPHY_BROCHURE_URL || "https://assets.tmke.co.uk/TMKE%20-%20Videography%20Services.pdf";
        const firstName = String(full_name).trim().split(/\s+/)[0] || "there";

        // Email the brochure (a link — works the moment the PDF is uploaded).
        await sendEmail(env, {
          to: email, subject: "Your TMKE videography brochure",
          html: await wrapInBrandedBase(env, `
            <h1 style="${EM_H1}">Here's your brochure, ${esc(firstName)}</h1>
            <p style="${EM_P}">Thanks for your interest in TMKE videography. Everything's in the brochure below - what's included, how it works, and what it costs.</p>
            <p style="margin:0 0 22px"><a href="${esc(brochureUrl)}" style="${EM_BTN}">Download the brochure &rarr;</a></p>
            ${accountCreated ? `<p style="${EM_P}">We've also created your TMKE account so you can manage your downloads and bookings in one place - sign in any time at <a href="https://tmke.co.uk/login" style="color:#371e28">tmke.co.uk/login</a>.</p>` : ""}`),
        });

        // CRM + automations: upsert the contact + fire any "form submitted" flow.
        try {
          const bparts = String(full_name).trim().split(/\s+/);
          await fireTrigger(env, "form_submitted", {
            email, first_name: bparts.shift() || full_name, last_name: bparts.join(" ") || null,
            source: "videography_brochure", lifecycle: "lead", marketing_opt_in: !!marketing_opt_in,
            tags: crmTags(email, "Interest: Videography", { optIn: !!marketing_opt_in, member: !!accountUserId }), user_id: accountUserId || null,
          }, { form: "videography_brochure", tag: "Brochure Download" });
        } catch (_) {}

        return json({ ok: true, account_created: accountCreated, brochure_url: brochureUrl }, 200, request, env);
      }

      // ---- Does this email already have a TMKE account? (booking gate) -------
      if (path.endsWith("/videography/account-exists") && request.method === "GET") {
        const email = (url.searchParams.get("email") || "").trim().toLowerCase();
        if (!email) return json({ exists: false }, 200, request, env);
        const u = await findUserByEmail(env, email);
        return json({ exists: !!u }, 200, request, env);
      }

      // ---- Validate a promo code (admin-managed table) -----------------------
      if (path.endsWith("/videography/promo") && request.method === "GET") {
        const code = (url.searchParams.get("code") || "").trim().toUpperCase();
        const service = (url.searchParams.get("service") || "").trim();
        if (!code) return json({ ok: false, error: "Enter a code." }, 200, request, env);
        const rows = await sbGet(env, "videography_promo_codes", `code=eq.${encodeURIComponent(code)}&select=*`);
        const p = rows && rows[0];
        if (!p) return json({ ok: false, error: "That code isn't recognised." }, 200, request, env);
        if (p.active === false) return json({ ok: false, error: "That code is no longer active." }, 200, request, env);
        if (p.expires_at && new Date(p.expires_at) < new Date()) return json({ ok: false, error: "That code has expired." }, 200, request, env);
        if (p.max_redemptions != null && p.redemptions != null && p.redemptions >= p.max_redemptions) return json({ ok: false, error: "That code has been fully redeemed." }, 200, request, env);
        if (Array.isArray(p.services) && p.services.length && service && !p.services.includes(service)) return json({ ok: false, error: "That code doesn't apply to this service." }, 200, request, env);
        return json({ ok: true, code: p.code, kind: p.kind, value: p.value, label: p.label || p.code }, 200, request, env);
      }

      // ---- Automations: fire a trigger (enrol a contact) --------------------
      // Called by trusted, signed-in surfaces (e.g. admin records an order, a new
      // customer signs up). Requires a valid session so it can't be spammed.
      if (path.endsWith("/automations/fire") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Unauthorised" }, 401, request, env);
        const b = await request.json().catch(() => ({}));
        if (!b || !b.trigger || !b.email) return json({ error: "Need a trigger and email." }, 400, request, env);
        const r = await fireTrigger(env, b.trigger, {
          email: b.email, first_name: b.first_name, last_name: b.last_name,
          phone: b.phone, company: b.company, source: b.source,
          lifecycle: b.lifecycle, marketing_opt_in: b.marketing_opt_in, tags: b.tags, user_id: b.user_id,
        }, b.payload || {});
        return json(r, 200, request, env);
      }

      // ---- Automations: manual tick (admin testing; cron runs it normally) ---
      if (path.endsWith("/automations/tick") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Unauthorised" }, 401, request, env);
        const n = await runAutomationsTick(env);
        return json({ ok: true, processed: n }, 200, request, env);
      }

      // ---- First-party tracking: open pixel + click-through -----------------
      // Unauthenticated by nature (recipients hit these), but every request
      // must carry a valid HMAC from injectTracking or it records nothing —
      // and the click redirect only forwards to a URL the signature vouches
      // for, so it can't be used as an open redirect.
      if (path.endsWith("/t/o") && request.method === "GET") {
        const p = url.searchParams.get("p") || "", s = url.searchParams.get("s") || "";
        if (p && s && s === await trackSig(env, p)) {
          try {
            const meta = JSON.parse(atob(p.replace(/-/g, "+").replace(/_/g, "/")));
            const addr = String(meta.e || "").toLowerCase();
            const cs = addr ? await sbGet(env, "contacts", `email=eq.${encodeURIComponent(lc(addr))}&select=id,email&limit=1`) : null;
            await logEmailEvent(env, { contact: cs && cs[0], email: addr, event: "opened", provider: "m365", messageId: meta.m || null, automationId: meta.a || null, enrollmentId: meta.n || null, nodeId: meta.s || null });
          } catch (_) {}
        }
        const gif = Uint8Array.from(atob("R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7"), (ch) => ch.charCodeAt(0));
        return new Response(gif, { headers: { "Content-Type": "image/gif", "Cache-Control": "no-store, private" } });
      }
      if (path.endsWith("/t/c") && request.method === "GET") {
        const p = url.searchParams.get("p") || "", s = url.searchParams.get("s") || "", u = url.searchParams.get("u") || "";
        let dest = "https://tmke.co.uk";
        if (p && s && u && s === await trackSig(env, `${p}|${u}`)) {
          dest = u;
          try {
            const meta = JSON.parse(atob(p.replace(/-/g, "+").replace(/_/g, "/")));
            const addr = String(meta.e || "").toLowerCase();
            const cs = addr ? await sbGet(env, "contacts", `email=eq.${encodeURIComponent(lc(addr))}&select=id,email&limit=1`) : null;
            await logEmailEvent(env, { contact: cs && cs[0], email: addr, event: "clicked", provider: "m365", messageId: meta.m || null, url: u, automationId: meta.a || null, enrollmentId: meta.n || null, nodeId: meta.s || null });
          } catch (_) {}
        }
        return Response.redirect(dest, 302);
      }

      // ---- Automations: AI insights summary ---------------------------------
      // A plain-English read on how a funnel is performing, plus anything that
      // needs doing before the next email goes out. Regenerated on each request
      // from the live numbers, so it keeps up as sends happen.
      // ---- Google Search Console: how the site does IN search ---------------
      // Clicks, impressions and position, by day, query and page. Uses the
      // service account the sheets already use, so the only setup is adding
      // that address as a user on the Search Console property - which is why
      // a refusal hands back the address to add.
      if (path.endsWith("/admin/insights/search") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        let sa = null;
        try { sa = JSON.parse(env.GOOGLE_SHEETS_SA_JSON || "null"); } catch (_) { sa = null; }
        if (!sa || !sa.client_email) {
          return json({ ok: false, configured: false, error: "No Google service account on the Worker (GOOGLE_SHEETS_SA_JSON)." }, 200, request, env);
        }
        const u = new URL(request.url);
        const days = Math.min(Math.max(parseInt(u.searchParams.get("days") || "30", 10) || 30, 1), 480);
        // Search Console data lags by 2-3 days; ask to yesterday and let it
        // return what it has rather than showing empty days as a fall.
        const end = new Date(Date.now() - 864e5).toISOString().slice(0, 10);
        const start = new Date(Date.now() - days * 864e5).toISOString().slice(0, 10);
        const site = env.GSC_SITE || "sc-domain:tmke.co.uk";
        const api = `https://searchconsole.googleapis.com/webmasters/v3/sites/${encodeURIComponent(site)}/searchAnalytics/query`;
        try {
          const token = await googleAccessToken(env, "https://www.googleapis.com/auth/webmasters.readonly");
          const ask = async (dimensions, rowLimit) => {
            const r = await fetch(api, {
              method: "POST",
              headers: { Authorization: "Bearer " + token, "Content-Type": "application/json" },
              body: JSON.stringify({ startDate: start, endDate: end, dimensions, rowLimit, dataState: "all" }),
            });
            const j = await r.json().catch(() => ({}));
            if (!r.ok) {
              const msg = (j.error && j.error.message) || `Search Console returned ${r.status}`;
              const err = new Error(msg); err.status = r.status; throw err;
            }
            return j.rows || [];
          };
          const [byDay, byQuery, byPage] = await Promise.all([ask(["date"], 500), ask(["query"], 25), ask(["page"], 15)]);
          const tot = byDay.reduce((a, r) => ({ clicks: a.clicks + (r.clicks || 0), impressions: a.impressions + (r.impressions || 0) }), { clicks: 0, impressions: 0 });
          const posSource = byDay.length ? byDay : byQuery;
          const position = posSource.length
            ? posSource.reduce((a, r) => a + ((r.position || 0) * (r.impressions || 1)), 0) / Math.max(1, posSource.reduce((a, r) => a + (r.impressions || 1), 0))
            : null;
          return json({
            ok: true, configured: true, site, start, end,
            clicks: tot.clicks, impressions: tot.impressions,
            ctr: tot.impressions ? tot.clicks / tot.impressions : 0,
            position: position != null ? Math.round(position * 10) / 10 : null,
            days: byDay.map((r) => ({ date: (r.keys || [])[0], clicks: r.clicks || 0, impressions: r.impressions || 0 })),
            queries: byQuery.map((r) => ({ q: (r.keys || [])[0], clicks: r.clicks || 0, impressions: r.impressions || 0, position: Math.round((r.position || 0) * 10) / 10 })),
            pages: byPage.map((r) => ({ url: (r.keys || [])[0], clicks: r.clicks || 0, impressions: r.impressions || 0 })),
          }, 200, request, env);
        } catch (e) {
          const status = e && e.status;
          const raw = String((e && e.message) || "");
          // The commonest first-run stumble: the service account's Google Cloud
          // project has the Sheets API on but not this one. Google's message
          // carries the link that switches it on - pass it straight through.
          if (/has not been used in project|API has not been enabled|SERVICE_DISABLED/i.test(raw)) {
            const link = (raw.match(/https:\/\/console\.developers\.google\.com\S*?(?=\s|$)/) || [])[0] || "https://console.cloud.google.com/apis/library/searchconsole.googleapis.com";
            return json({ ok: false, configured: true, needs_api: true, enable_url: link.replace(/[.,]$/, ""),
              service_account: sa.client_email, site,
              error: "The Search Console API isn't switched on for this Google project yet.", raw: raw.slice(0, 300) }, 200, request, env);
          }
          const permission = status === 403 || /permission|not have access|forbidden/i.test(raw);
          const missingSite = status === 404 || /not found|does not exist/i.test(raw);
          return json({
            ok: false, configured: true,
            needs_access: !!(permission || missingSite),
            service_account: sa.client_email,
            site,
            error: permission
              ? "Google won't let this account read the Search Console property yet."
              : missingSite
                ? `Search Console has no property called ${site} that this account can see.`
                : raw || "Search Console didn't answer.",
            raw: raw.slice(0, 300),
          }, 200, request, env);
        }
      }

      // ---- Cloudflare: the visitors our own tracker can't see ---------------
      // Every request to tmke.co.uk passes through Cloudflare, which counts it
      // at the edge - no script on the page, no cookie, nothing to accept. So
      // this includes the people who decline cookies and never appear in
      // site_events, and it can't be blocked by an ad blocker.
      //
      // Needs two things on the Worker: CF_ANALYTICS_TOKEN (a read-only
      // Analytics token) and CF_ZONE_ID (the zone id from the Cloudflare
      // dashboard). Without them this says so rather than failing.
      if (path.endsWith("/admin/insights/cloudflare") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!env.CF_ANALYTICS_TOKEN) {
          return json({ ok: false, configured: false, error: "Cloudflare isn't connected yet - add CF_ANALYTICS_TOKEN to the Worker." }, 200, request, env);
        }
        // The zone id identifies the DOMAIN, and it looks exactly like the
        // account id sitting beside it in the dashboard - an easy swap to make.
        // So: ask Cloudflare for it by name, and only fall back to a saved
        // CF_ZONE_ID when the token isn't allowed to list zones.
        let zoneId = "";
        const zoneName = env.CF_ZONE_NAME || "tmke.co.uk";
        try {
          const zr = await fetch(`https://api.cloudflare.com/client/v4/zones?name=${encodeURIComponent(zoneName)}&status=active`, {
            headers: { Authorization: `Bearer ${env.CF_ANALYTICS_TOKEN}` },
          });
          const zj = await zr.json().catch(() => ({}));
          zoneId = (zj && zj.success && zj.result && zj.result[0] && zj.result[0].id) || "";
        } catch (_) { /* fall through to the saved id */ }
        const looksLikeZone = /^[0-9a-f]{32}$/i.test(String(env.CF_ZONE_ID || ""))
          && String(env.CF_ZONE_ID) !== String(env.CF_ACCOUNT_ID || "");
        if (!zoneId && looksLikeZone) zoneId = String(env.CF_ZONE_ID);
        if (!zoneId) {
          return json({ ok: false, configured: true,
            error: `Couldn't work out the zone id for ${zoneName}. The token needs access to that domain - check "Zone Resources" on it includes tmke.co.uk.`,
          }, 200, request, env);
        }
        const u = new URL(request.url);
        const days = Math.min(Math.max(parseInt(u.searchParams.get("days") || "30", 10) || 30, 1), 90);
        const since = new Date(Date.now() - (days - 1) * 864e5).toISOString().slice(0, 10);
        const query = `query ($zone: String!, $since: Date!) {
          viewer { zones(filter: { zoneTag: $zone }) {
            httpRequests1dGroups(limit: 90, filter: { date_geq: $since }, orderBy: [date_ASC]) {
              dimensions { date }
              sum { requests pageViews }
              uniq { uniques }
            }
          } }
        }`;
        try {
          const res = await fetch("https://api.cloudflare.com/client/v4/graphql", {
            method: "POST",
            headers: { Authorization: `Bearer ${env.CF_ANALYTICS_TOKEN}`, "Content-Type": "application/json" },
            body: JSON.stringify({ query, variables: { zone: zoneId, since } }),
          });
          const body = await res.json().catch(() => ({}));
          const problem = (body.errors && body.errors[0] && body.errors[0].message)
            || (Array.isArray(body.messages) && body.messages[0] && body.messages[0].message);
          if (!res.ok || problem) {
            // Say what Cloudflare actually said, plus the likely cause. Guessing
            // silently sent Dani hunting for the wrong thing once already.
            const zid = String(zoneId || "");
            let hint = "";
            if (zid && zid === String(env.CF_ACCOUNT_ID || "")) {
              hint = "That's the ACCOUNT id, not the zone id - they sit next to each other on the Cloudflare overview page. The zone id is the one under the domain name.";
            } else if (!/^[0-9a-f]{32}$/i.test(zid)) {
              hint = `The zone id doesn't look right: it should be 32 letters and numbers, and this one is ${zid.length}.`;
            } else if (/authentication|authorization|9109|permission|denied/i.test(String(problem || res.status))) {
              hint = "Cloudflare refused the token - it needs Zone / Analytics / Read, and access to tmke.co.uk.";
            } else if (/zone/i.test(String(problem || ""))) {
              hint = "Cloudflare doesn't recognise that zone id, or this token can't see that zone.";
            }
            return json({ ok: false, configured: true, error: hint, raw: String(problem || `Cloudflare returned ${res.status}`).slice(0, 200) }, 200, request, env);
          }
          const zone = ((((body.data || {}).viewer || {}).zones || [])[0]) || {};
          const days_out = (zone.httpRequests1dGroups || []).map((g) => ({
            date: g.dimensions && g.dimensions.date,
            visitors: (g.uniq && g.uniq.uniques) || 0,
            views: (g.sum && g.sum.pageViews) || 0,
            requests: (g.sum && g.sum.requests) || 0,
          }));
          return json({ ok: true, configured: true, days: days_out }, 200, request, env);
        } catch (e) {
          return json({ ok: false, configured: true, error: String((e && e.message) || "Couldn't reach Cloudflare.") }, 200, request, env);
        }
      }

      // ---- Funnel lifecycle ------------------------------------------------
      // Review: what reactivating a paused funnel would do. Nothing changes.
      if (path.endsWith("/automations/reactivation-review") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const aRows = b.automation_id ? await sbGet(env, "automations", `id=eq.${encodeURIComponent(b.automation_id)}&select=id,status,graph,trigger_type,trigger_config`) : null;
        const auto = aRows && aRows[0];
        if (!auto) return json({ error: "Automation not found." }, 404, request, env);
        if (auto.status !== "paused") return json({ error: "This funnel isn't paused." }, 400, request, env);
        const plan = await funnelReactivationPlan(env, auto);
        return json({ ok: true, missed: plan.missed, overdue: plan.overdue_count, joiners: plan.joiners.length, leavers: plan.leavers.length,
          in_funnel: plan.in_funnel, paused_at: plan.paused_at, audience: plan.audience }, 200, request, env);
      }

      // Change a funnel's status, applying what the change means.
      // Body: { automation_id, status, resume_at?, reschedule?: { [nodeId]: { send_on, send_at, at } } }
      if (path.endsWith("/automations/set-status") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const aRows = b.automation_id ? await sbGet(env, "automations", `id=eq.${encodeURIComponent(b.automation_id)}&select=id,status,graph,trigger_type,trigger_config`) : null;
        const auto = aRows && aRows[0];
        if (!auto) return json({ error: "Automation not found." }, 404, request, env);
        const from = auto.status || "draft", to = String(b.status || "");
        if (!FUNNEL_MOVES[from] || !FUNNEL_MOVES[from].includes(to)) {
          const why = from === "archived" ? "An archived funnel can't be changed - duplicate it to start a new one."
            : to === "draft" ? "A funnel that has been live can't go back to draft. Pause it to make changes, or archive it to end it."
            : `Can't go from ${from} to ${to}.`;
          return json({ error: why }, 409, request, env);
        }
        const aid = encodeURIComponent(auto.id);
        const graph = auto.graph || { nodes: [], edges: [] };
        graph.meta = { ...(graph.meta || {}) };
        const nowIso = nowISO();
        const out = { ok: true, status: to };

        if (to === "paused" && from !== "paused") {
          graph.meta.paused_at = nowIso;
        }
        if (to === "archived" && from !== "archived") {
          // The end of the funnel: everyone still in it leaves now.
          graph.meta.archived_at = nowIso;
          const r = await fetch(`${env.SUPABASE_URL}/rest/v1/automation_enrollments?automation_id=eq.${aid}&status=in.(active,waiting)`, {
            method: "PATCH",
            headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=representation" },
            body: JSON.stringify({ status: "stopped" }),
          });
          const stopped = r.ok ? await r.json().catch(() => []) : [];
          out.taken_out = Array.isArray(stopped) ? stopped.length : 0;
        }
        if (to === "active" && from === "draft") {
          graph.meta.went_live_at = graph.meta.went_live_at || nowIso;
        }
        if (to === "active" && from === "paused") {
          const plan = await funnelReactivationPlan(env, auto);
          const resumeAt = b.resume_at && !isNaN(new Date(b.resume_at)) ? new Date(b.resume_at).toISOString() : nowIso;
          // Missed fixed-date emails: move each to the date and time chosen.
          const re = b.reschedule || {};
          for (const m of plan.missed) {
            const pick = re[m.node_id] || {};
            const node = (graph.nodes || []).find((n) => n.id === m.node_id);
            if (!node) continue;
            node.config = node.config || {};
            if (/^\d{4}-\d{2}-\d{2}$/.test(String(pick.send_on || ""))) node.config.send_on = pick.send_on;
            if (/^([01]?\d|2[0-3]):[0-5]\d$/.test(String(pick.send_at || ""))) node.config.send_at = pick.send_at;
            // People already held at this email pick the new moment up now.
            const at = pick.at && !isNaN(new Date(pick.at)) ? new Date(pick.at).toISOString() : resumeAt;
            await sbPatch(env, "automation_enrollments", `automation_id=eq.${aid}&current_node_id=eq.${encodeURIComponent(m.node_id)}&status=eq.active`, { next_run_at: at });
          }
          // Waits that ran out during the pause carry on from the moment chosen.
          for (let i = 0; i < plan.overdue.length; i += 150) {
            const ids = plan.overdue.slice(i, i + 150).map(encodeURIComponent).join(",");
            await sbPatch(env, "automation_enrollments", `id=in.(${ids})`, { next_run_at: resumeAt });
          }
          // The audience, rechecked.
          if (plan.leavers.length) {
            for (let i = 0; i < plan.leavers.length; i += 150) {
              const ids = plan.leavers.slice(i, i + 150).map(encodeURIComponent).join(",");
              await sbPatch(env, "automation_enrollments", `id=in.(${ids})`, { status: "stopped" });
            }
          }
          let joined = 0;
          if (plan.joiners.length) {
            const firstId = autoEdgeTo(graph, "trigger", "next");
            const tags = Array.isArray((auto.trigger_config || {}).tags) ? auto.trigger_config.tags.filter(Boolean) : [];
            if (firstId) for (const cid of plan.joiners) {
              const res = await sbPost(env, "automation_enrollments", {
                automation_id: auto.id, contact_id: cid, status: "active",
                current_node_id: firstId, next_run_at: resumeAt, context: { audience: tags },
              });
              if (res && res.ok) joined++;
            }
          }
          delete graph.meta.paused_at;
          graph.meta.reactivated_at = nowIso;
          Object.assign(out, { rescheduled: plan.missed.length, carried_on: plan.overdue.length, joined, taken_out: plan.leavers.length });
        }

        const save = await sbPatch(env, "automations", `id=eq.${aid}`, { status: to, graph });
        if (!save || !save.ok) return json({ error: "Couldn't save the funnel's status." }, 502, request, env);
        return json(out, 200, request, env);
      }

      // ---- Resend the emails a funnel failed to send ------------------------
      // For when a send step errored for a reason that has since been fixed (a
      // bad API key, say). Finds every contact whose most recent attempt at a
      // send step ended in an error, and runs that step again for them - the
      // same template, the same marketing gate (so anyone who has since opted
      // out is still skipped). It does NOT move them in the funnel: the steps
      // after a send don't depend on it having arrived, so they are already
      // where they should be.
      // A contact whose send was skipped by the gate (no opt-in, unsubscribed)
      // is not a failure and is left alone. Works in small batches so no single
      // request runs long; the page calls it until nothing is left.
      // Body: { automation_id, dry_run?: true } -> { found, sent, failed, skipped, remaining }
      if (path.endsWith("/automations/retry-failed-sends") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        if (!b.automation_id) return json({ error: "No automation id." }, 400, request, env);
        const aid = encodeURIComponent(b.automation_id);
        const aRows = await sbGet(env, "automations", `id=eq.${aid}&select=id,name,status,graph`);
        const auto = aRows && aRows[0];
        if (!auto) return json({ error: "Automation not found." }, 404, request, env);
        if (auto.status === "paused" && !b.dry_run) return json({ error: "This funnel is paused - reactivate it first." }, 409, request, env);
        const nodes = ((auto.graph || {}).nodes) || [];
        const runs = (await sbGet(env, "automation_runs", `automation_id=eq.${aid}&node_type=eq.send_email&select=enrollment_id,contact_id,node_id,outcome,created_at&order=created_at.asc&limit=10000`)) || [];
        // The latest attempt per contact per send step decides it.
        const last = new Map();
        runs.forEach((r) => last.set(`${r.enrollment_id}|${r.node_id}`, r));
        let todo = [...last.values()].filter((r) => r.outcome === "error" && nodes.some((n) => n.id === r.node_id));
        // Someone taken out of the funnel on purpose isn't sent to.
        if (todo.length) {
          const ids = [...new Set(todo.map((r) => r.enrollment_id))];
          const live = new Set();
          for (let i = 0; i < ids.length; i += 150) {
            const rows = (await sbGet(env, "automation_enrollments", `id=in.(${ids.slice(i, i + 150).map(encodeURIComponent).join(",")})&select=id,status`)) || [];
            rows.filter((e) => e.status !== "stopped").forEach((e) => live.add(e.id));
          }
          todo = todo.filter((r) => live.has(r.enrollment_id));
        }
        if (b.dry_run) return json({ ok: true, found: todo.length }, 200, request, env);

        const BATCH = 15;
        const batch = todo.slice(0, BATCH);
        let sent = 0, failed = 0, skipped = 0, lastError = null;
        for (const r of batch) {
          const node = nodes.find((n) => n.id === r.node_id);
          const cRows = await sbGet(env, "contacts", `id=eq.${encodeURIComponent(r.contact_id)}&select=*`);
          const contact = cRows && cRows[0];
          let acted;
          if (!contact || !node) acted = { outcome: "skipped", detail: "contact or step no longer exists" };
          else acted = await autoExecAction(env, node, contact, { automationId: auto.id, enrollmentId: r.enrollment_id, nodeId: r.node_id, campaign: auto.name || null });
          const outcome = (acted && acted.outcome) || "ok";
          if (outcome === "ok") sent++; else if (outcome === "error") { failed++; lastError = acted.detail; } else skipped++;
          // Logged like any other run, marked as a resend, so the audit shows
          // it - and so this contact is not picked up again next time.
          await sbPost(env, "automation_runs", {
            enrollment_id: r.enrollment_id, automation_id: auto.id, contact_id: r.contact_id,
            node_id: r.node_id, node_type: "send_email", outcome,
            detail: "Resent: " + ((acted && acted.detail) || outcome),
          });
          // Stop at once if it is still failing - no point burning through the
          // list with the same error.
          if (outcome === "error") break;
        }
        const done = sent + failed + skipped;
        return json({ ok: true, found: todo.length, sent, failed, skipped, remaining: Math.max(0, todo.length - done), error: lastError }, 200, request, env);
      }

      // ---- A funnel just saved: re-time anyone waiting at its dated emails, and
      // say who's waiting at each step and when they next move (Danielle, 26 Oct).
      if (path.endsWith("/automations/retime") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        if (!b.automation_id) return json({ error: "No automation id." }, 400, request, env);
        try { await retimeDatedSends(env, b.automation_id); } catch (_) {}
        const rows = (await sbGetAll(env, "automation_enrollments", `automation_id=eq.${encodeURIComponent(b.automation_id)}&status=eq.active&select=current_node_id,next_run_at`)) || [];
        const steps = {};
        for (const r of rows) {
          const k = r.current_node_id || "";
          const st = steps[k] || (steps[k] = { waiting: 0, next_at: null });
          st.waiting += 1;
          if (r.next_run_at && (!st.next_at || r.next_run_at < st.next_at)) st.next_at = r.next_run_at;
        }
        return json({ ok: true, steps }, 200, request, env);
      }

      if (path.endsWith("/automations/insights") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!env.ANTHROPIC_API_KEY) return json({ error: "AI isn't configured - set the ANTHROPIC_API_KEY secret on the Worker." }, 503, request, env);
        const b = await request.json().catch(() => ({}));
        if (!b.automation_id) return json({ error: "No automation id." }, 400, request, env);
        const aid = encodeURIComponent(b.automation_id);
        const [aRows, enr, events] = await Promise.all([
          sbGet(env, "automations", `id=eq.${aid}&select=name,status,trigger_type,trigger_config,graph`),
          sbGet(env, "automation_enrollments", `automation_id=eq.${aid}&select=status,next_run_at`),
          sbGetAll(env, "email_events", `automation_id=eq.${aid}&select=event,detail,subject,occurred_at&order=occurred_at.desc,id.desc`),
        ]);
        const auto = aRows && aRows[0];
        if (!auto) return json({ error: "Automation not found." }, 404, request, env);
        const ev = events || [], en = enr || [];
        const n = (e) => ev.filter((x) => x.event === e).length;
        const byStatus = {}; en.forEach((x) => { byStatus[x.status] = (byStatus[x.status] || 0) + 1; });
        const nextRun = en.filter((x) => x.status === "active" && x.next_run_at).map((x) => x.next_run_at).sort()[0] || null;
        const problems = ev.filter((x) => x.event === "bounced" || x.event === "complained" || x.event === "blocked").slice(0, 12)
          .map((x) => `${x.event}${x.detail ? ` (${String(x.detail).slice(0, 80)})` : ""}`);
        const sendSteps = (((auto.graph || {}).nodes) || []).filter((x) => x.type === "send_email");
        const facts = {
          funnel: auto.name, status: auto.status,
          kind: ((auto.graph || {}).meta || {}).kind || "service",
          trigger: auto.trigger_type, chosen_tags: (auto.trigger_config || {}).tags || (auto.trigger_config || {}).tag || null,
          emails_in_funnel: sendSteps.length,
          scheduled_dates: sendSteps.map((x) => (x.config || {}).send_on).filter(Boolean),
          enrolments: byStatus, next_step_due: nextRun,
          sent: n("sent"), delivered: n("delivered"), opened_events: n("opened"), clicked_events: n("clicked"),
          bounced: n("bounced"), spam_complaints: n("complained"),
          unsubscribed: n("unsubscribed"),
          // Two very different things were being reported as one: people the
          // funnel is right not to email, and sends that actually failed.
          not_emailed_no_optin_or_unsubscribed: ev.filter((x) => x.event === "blocked" && /opt-?in|unsubscribed|do-not-contact|suppressed/i.test(x.detail || "")).length,
          failed_to_send: ev.filter((x) => x.event === "blocked" && !/opt-?in|unsubscribed|do-not-contact|suppressed/i.test(x.detail || "")).length,
          recent_problems: problems,
          now: new Date().toISOString(),
        };
        // The page's own counts, when it sends them: each person once, security
        // scanners left out, anyone who clicked counted as opened. They replace
        // the raw event tallies so the summary says what the boxes say (10 Nov 2026).
        const c = b.counted && typeof b.counted === "object" ? b.counted : null;
        if (c) {
          const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
          ["sent", "delivered", "opened_events", "clicked_events", "bounced", "spam_complaints", "unsubscribed", "not_emailed_no_optin_or_unsubscribed", "failed_to_send"].forEach((k) => delete facts[k]);
          Object.assign(facts, {
            note_on_counts: "Every figure counts people, each once, the same as Resend's own figures. Anyone who clicked also counts as opened. Work email filters (Microsoft's on TEG addresses) open and click links automatically and Resend counts those too, so some opens and clicks may not be people: the *_that_may_be_scanners figures say how many look like that. Came to the site counts everyone who arrived from the email's links (from 10 Nov 2026; before that only visitors who accepted cookies, so older emails show a minimum). It is the most reliable sign of a real person.",
            sent: num(c.sent), delivered: num(c.delivered), opened_people: num(c.opened_people), clicked_people: num(c.clicked_people),
            came_to_the_site: num(c.came_to_the_site), unsubscribed: num(c.unsubscribed), bounced: num(c.bounced), spam_complaints: num(c.spam_complaints),
            not_emailed_no_optin_or_unsubscribed: num(c.not_emailed_no_optin_or_unsubscribed), failed_to_send: num(c.failed_to_send),
            opened_that_may_be_scanners: num(c.opened_that_may_be_scanners), clicked_that_may_be_scanners: num(c.clicked_that_may_be_scanners),
          });
        }
        const prompt = `You are the email-marketing analyst for TMKE, a UK marketing agency. Below are the live numbers for one email funnel. Write a short plain-English summary for a non-technical marketer: first ONE paragraph (3-5 sentences, British English, no jargon, no bullet lists in this paragraph) on how the funnel is performing - be honest, specific and use the actual numbers, mention open/click rates only if delivery numbers exist (rates are out of delivered), use exactly the figures given and don't work out any of your own, and don't invent anything not in the data. Then a line "Actions:" followed by either "none needed." or 1-3 short bullet points of things to do BEFORE the next email goes out (e.g. bounces to investigate, spam complaints, many contacts blocked for missing opt-in, nothing scheduled). If very little has happened yet, say so simply. Contacts "not emailed" for no opt-in or unsubscribing are the funnel working as intended, not a fault - only "failed_to_send" is a problem. Write plain text only: no markdown, no asterisks, no bold; bullets start with "- ". Total under 160 words.\n\nDATA:\n${JSON.stringify(facts, null, 2)}`;
        let text = "";
        try {
          const aiRes = await aiFetch(env, "admin", { max_tokens: 4000, messages: [{ role: "user", content: prompt }] });
          const j = await aiRes.json().catch(() => ({}));
          if (!aiRes.ok) return json({ error: aiFailMessage(aiRes.status, j.error && j.error.message), detail: (j.error && j.error.message) || "" }, 502, request, env);
          text = ((j.content || []).find((p) => p.type === "text") || {}).text || "";
        } catch (_) { return json({ error: "AI request failed." }, 502, request, env); }
        // Belt and braces: the box shows plain text, so strip any markdown the
        // model adds anyway rather than showing literal asterisks.
        text = text.replace(/\*\*(.+?)\*\*/g, "$1").replace(/(^|\s)\*(\S.*?)\*(?=\s|$)/g, "$1$2").replace(/^#+\s*/gm, "");
        return json({ ok: true, summary: text.trim() }, 200, request, env);
      }

      // ---- Resend webhook: delivery events feed the CRM ---------------------
      // Resend calls this when an email is delivered / opened / clicked /
      // bounces / is reported as spam. Signature-verified (Svix scheme): without
      // the check, anyone who knew the URL could suppress the whole contact list.
      // Setup: Resend dashboard → Webhooks → add <worker>/resend/webhook, then
      // wrangler secret put RESEND_WEBHOOK_SECRET (the whsec_… signing secret).
      if (path.endsWith("/resend/webhook") && request.method === "POST") {
        if (!env.RESEND_WEBHOOK_SECRET) return json({ error: "Webhook secret not configured." }, 503, request, env);
        const bodyText = await request.text();
        const svixId = request.headers.get("svix-id"), svixTs = request.headers.get("svix-timestamp"), svixSig = request.headers.get("svix-signature");
        const fresh = svixTs && Math.abs(Date.now() / 1000 - Number(svixTs)) < 300;
        let verified = false;
        if (svixId && fresh && svixSig) {
          try {
            const keyBytes = Uint8Array.from(atob(env.RESEND_WEBHOOK_SECRET.replace(/^whsec_/, "")), (ch) => ch.charCodeAt(0));
            const key = await crypto.subtle.importKey("raw", keyBytes, { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
            const mac = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(`${svixId}.${svixTs}.${bodyText}`));
            const expected = btoa(String.fromCharCode(...new Uint8Array(mac)));
            verified = svixSig.split(" ").some((s) => s.split(",")[1] === expected);
          } catch (_) { verified = false; }
        }
        if (!verified) return json({ error: "Bad signature." }, 401, request, env);

        let evt = {}; try { evt = JSON.parse(bodyText); } catch (_) {}
        const map = {
          "email.sent": "sent", "email.delivered": "delivered", "email.delivery_delayed": "delivery_delayed",
          "email.opened": "opened", "email.clicked": "clicked", "email.bounced": "bounced",
          "email.complained": "complained", "email.suppressed": "suppressed",
        };
        const event = map[String(evt.type || "")];
        if (!event) return json({ ok: true, ignored: evt.type || "unknown" }, 200, request, env);
        const d = evt.data || {};
        const msgId = d.email_id || null;
        // Our own "sent" row carries the automation attribution — inherit it so
        // opens/bounces count against the right funnel in the insights.
        let sentRow = null;
        if (msgId) {
          const q = (cols) => sbGet(env, "email_events", `message_id=eq.${encodeURIComponent(msgId)}&event=eq.sent&select=${cols}&limit=1`);
          let rows = await q("automation_id,enrollment_id,node_id,subject,email");
          // node_id arrives with a migration; before it runs, ask without it.
          if (!rows) rows = await q("automation_id,enrollment_id,subject,email");
          sentRow = rows && rows[0];
        }
        // Our own send log already recorded this message as sent; Resend's
        // "sent" for it is the same send, and counting both doubled the
        // funnel's sent figure (30 Sep 2026).
        if (event === "sent" && sentRow) return json({ ok: true, duplicate: true }, 200, request, env);
        const addr = String((Array.isArray(d.to) ? d.to[0] : d.to) || (sentRow && sentRow.email) || "").toLowerCase();
        let contact = null;
        if (addr) {
          const cs = await sbGet(env, "contacts", `email=eq.${encodeURIComponent(lc(addr))}&select=*&limit=1`);
          contact = cs && cs[0];
        }
        await logEmailEvent(env, {
          contact, email: addr, event, provider: "resend",
          messageId: msgId, subject: (sentRow && sentRow.subject) || d.subject || null,
          url: (d.click && d.click.link) || null,
          detail: (d.bounce && (d.bounce.message || d.bounce.subType || d.bounce.type)) || null,
          raw: evt, occurredAt: evt.created_at || null,
          automationId: (sentRow && sentRow.automation_id) || null,
          enrollmentId: (sentRow && sentRow.enrollment_id) || null,
          nodeId: (sentRow && sentRow.node_id) || null,
        });
        // CRM actions, per the suppression plan.
        if (contact) {
          const stamp = { event, subject: (sentRow && sentRow.subject) || null, at: new Date().toISOString() };
          if (event === "delivered") {
            await sbPatch(env, "contacts", `id=eq.${encodeURIComponent(contact.id)}`, { soft_bounce_count: 0, last_email_event: stamp });
          } else if (event === "bounced") {
            const kind = String((d.bounce && d.bounce.type) || "").toLowerCase();
            if (kind === "transient") {
              const n = (Number(contact.soft_bounce_count) || 0) + 1;
              if (n >= SOFT_BOUNCE_LIMIT) await suppressContact(env, contact, "repeated_soft_bounce", `${n} consecutive soft bounces`);
              else await sbPatch(env, "contacts", `id=eq.${encodeURIComponent(contact.id)}`, { soft_bounce_count: n, last_email_event: stamp });
            } else {
              await suppressContact(env, contact, "hard_bounce", (d.bounce && d.bounce.message) || null);
            }
          } else if (event === "complained") {
            await suppressContact(env, contact, "spam_complaint", null);
            await unsubscribeContact(env, contact, "spam_complaint");
            // A spam complaint deserves a human, not just a database row.
            try {
              const who = [contact.first_name, contact.last_name].filter(Boolean).join(" ") || addr;
              const subj = (sentRow && sentRow.subject) || null;
              await sendEmail(env, {
                to: ["danielle@themarketingexperts.co.uk", "hello@tmke.co.uk"],
                subject: `Spam complaint from ${who}`,
                html: `<div style="${EM_WRAP}">
                  <p><strong>${String(who).replace(/</g, "&lt;")}</strong> (${String(addr).replace(/</g, "&lt;")}) reported ${subj ? `“${String(subj).replace(/</g, "&lt;")}”` : "one of our emails"} as spam.</p>
                  <p>Handled automatically: they've been unsubscribed from marketing and their address suppressed, so nothing further will be sent to them.</p>
                  <p>Worth a moment's thought on why - repeated complaints damage tmke.co.uk's sending reputation. Their history is on their contact card in the admin.</p>
                  <p style="${EM_SMALL}">Sent automatically by the email webhook.</p>
                </div>`,
              });
              try {
                await notifyAdmins(env, {
                  area: "problem", event: "spam_complaint",
                  title: `Spam complaint — ${who}`,
                  body: `${addr} reported ${subj || "one of our emails"}. Unsubscribed and suppressed automatically.`,
                  href: "/admin/contacts", key: `spam:${addr}`,
                });
              } catch (_) {}
            } catch (_) { /* the alert is a bonus - the suppression already happened */ }
          } else if (event === "suppressed") {
            await suppressContact(env, contact, "resend_suppressed", null);
          } else if (event === "opened" || event === "clicked") {
            await sbPatch(env, "contacts", `id=eq.${encodeURIComponent(contact.id)}`, { last_email_event: stamp });
          }
        }
        return json({ ok: true }, 200, request, env);
      }

      // ---- Automations: enrol an audience (send-to-a-group) ------------------
      // For "audience" automations: enrols every contact currently carrying any
      // of the chosen tags. Late joiners (tag added afterwards) are picked up by
      // fireTrigger's tag_added path. The unique index makes this idempotent —
      // re-running only enrols people not already live in the funnel.
      if (path.endsWith("/automations/enroll-audience") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const aRows = b.automation_id ? await sbGet(env, "automations", `id=eq.${encodeURIComponent(b.automation_id)}&select=id,status,graph,trigger_type,trigger_config`) : null;
        const auto = aRows && aRows[0];
        if (!auto) return json({ error: "Automation not found." }, 404, request, env);
        if (auto.trigger_type !== "audience") return json({ error: "This automation doesn't start from a group of tags." }, 400, request, env);
        if (auto.status !== "active") return json({ error: "Set the automation to Active first - a draft can't enrol anyone." }, 400, request, env);
        const tags = Array.isArray((auto.trigger_config || {}).tags) ? auto.trigger_config.tags.filter(Boolean) : [];
        if (!tags.length) return json({ error: "Choose at least one tag first." }, 400, request, env);
        const firstId = autoEdgeTo(auto.graph, "trigger", "next");
        if (!firstId) return json({ error: "Add a first step to the funnel before enrolling anyone." }, 400, request, env);
        const list = `{${tags.map((t) => `"${String(t).replace(/"/g, "")}"`).join(",")}}`;
        // Read in pages: every REST read stops at 1,000 rows without saying so,
        // which would leave everyone after the first 1,000 out (Danielle, 23 Oct).
        const pageAll = async (table, q) => {
          const out = [];
          for (let off = 0; off < 100000; off += 1000) {
            const rows = (await sbGet(env, table, `${q}&order=id.asc&limit=1000&offset=${off}`)) || [];
            out.push(...rows);
            if (rows.length < 1000) break;
          }
          return out;
        };
        const matched = await pageAll("contacts", `tags=ov.${encodeURIComponent(list)}&select=id`);
        // Already running through it: left alone, as the one-by-one inserts
        // did when the live-enrolment index refused them.
        const live = new Set((await pageAll("automation_enrollments", `automation_id=eq.${auto.id}&status=in.(active,waiting)&select=id,contact_id`)).map((r) => r.contact_id));
        const fresh = matched.filter((ct) => !live.has(ct.id));
        let enrolled = 0, failed = 0;
        for (let i = 0; i < fresh.length; i += 500) {
          const batch = fresh.slice(i, i + 500).map((ct) => ({
            automation_id: auto.id, contact_id: ct.id, status: "active",
            current_node_id: firstId, next_run_at: nowISO(), context: { audience: tags },
          }));
          const res = await sbPost(env, "automation_enrollments", batch);
          if (res && res.ok) enrolled += batch.length; else failed += batch.length;
        }
        return json({ ok: true, matched: matched.length, enrolled, already: matched.length - fresh.length, failed }, 200, request, env);
      }

      // ---- Email: send one published template to one contact, now -----------
      // The contact file's "Send an email". Same road as an automation's send
      // step — the opt-in gate, the branded render, the per-recipient
      // unsubscribe link for marketing, tracking for transactional, and the
      // event log — so "did they get it?" has the same answer here.
      if (path.endsWith("/email/send-to-contact") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        if (!b.contact_id || !b.template_id) return json({ error: "Need a contact and a template." }, 400, request, env);
        const cRows = await sbGet(env, "contacts", `id=eq.${encodeURIComponent(b.contact_id)}&select=*`);
        const contact = cRows && cRows[0];
        if (!contact || !contact.email) return json({ error: "Contact not found." }, 404, request, env);
        const tRows = await sbGet(env, "email_templates", `id=eq.${encodeURIComponent(b.template_id)}&select=*`);
        const t = tRows && tRows[0];
        if (!t) return json({ error: "That email template no longer exists." }, 404, request, env);
        const sendKind = b.send_kind === "marketing" ? "marketing" : "transactional";
        // The gate says no to marketing without opt-in, and to anyone
        // unsubscribed, suppressed or do-not-contact. `force` overrides ONLY
        // the opt-in check, for a one-off the admin has decided on; the rest
        // still stands.
        const gate = await gateEmail(env, contact, sendKind, null, null);
        if (!gate.ok && !(b.force && /opt/i.test(String(gate.reason || "")))) return json({ error: "Not sent: " + gate.reason, blocked: true }, 409, request, env);
        const brand = { ...defaultBrand(), ...(t.branding || {}), ...(await brandMasterSocials(env)) };
        const recipient = { name: [contact.first_name, contact.last_name].filter(Boolean).join(" ") || contact.email, first_name: contact.first_name || "", email: contact.email, company: contact.company || "" };
        Object.assign(recipient, await agentFunnelContext(env, contact));
        const unsubUrl = sendKind === "marketing" ? await unsubUrlFor(env, contact.email) : null;
        if (unsubUrl) { recipient.unsubscribeUrl = unsubUrl; recipient.unsubscribe_url = unsubUrl; }
        const { subject, html } = renderTemplate(
          { subject: (b.subject && String(b.subject).trim()) || t.subject, preheader: t.preheader, mode: t.mode, blocks: t.blocks, customHtml: t.custom_html, branding: t.branding },
          { brand, mergeCtx: mergeContextFor(recipient, brand) }
        );
        let htmlOut = html, m365Id = null;
        if (sendKind !== "marketing") {
          m365Id = "m365-" + crypto.randomUUID();
          try { htmlOut = await injectTracking(env, html, { email: contact.email, messageId: m365Id }); } catch (_) { htmlOut = html; }
        }
        /* Tag the links on a hand-sent marketing email too.

           The automation path has always done this; this one never did, so an
           email sent by hand from a contact file reached the site carrying no
           campaign at all. Its clicks were real and its visits were real and
           nothing could join the two, which is how a campaign with fifteen
           clicks showed one attributed visit. The campaign is the subject,
           because that is what it is called everywhere else you look at it. */
        if (sendKind === "marketing") {
          try { htmlOut = tagMarketingLinks(html, { campaign: subject || null, content: "by-hand" }); }
          catch (_) { htmlOut = html; }
        }
        const sent = sendKind === "marketing"
          ? await sendMarketingEmail(env, { to: [contact.email], subject, html: htmlOut, unsubUrl })
          : await sendEmail(env, { to: [contact.email], subject, html: htmlOut });
        await logEmailEvent(env, {
          contact, email: contact.email,
          event: (sent && sent.ok) ? "sent" : "blocked",
          provider: sendKind === "marketing" ? "resend" : "m365",
          messageId: (sent && sent.id) || m365Id,
          subject,
          detail: (sent && sent.ok) ? `Sent by hand from the contact file by ${user.email || "an admin"}` : String((sent && sent.error) || "send failed").slice(0, 200),
        });
        if (!(sent && sent.ok)) return json({ error: String((sent && sent.error) || "The send failed.") }, 502, request, env);
        return json({ ok: true, subject, to: contact.email }, 200, request, env);
      }

      // ---- Automations: enrol hand-picked contacts ----------------------------
      // The "Chosen contacts" start, and a way to add specific people to any
      // active funnel. Idempotent: someone already in the funnel is skipped and
      // counted as `already`.
      if (path.endsWith("/automations/enroll-contacts") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const ids = Array.isArray(b.contact_ids) ? b.contact_ids.filter((x) => typeof x === "string" && x).slice(0, 500) : [];
        if (!b.automation_id || !ids.length) return json({ error: "Need an automation and at least one contact." }, 400, request, env);
        const aRows = await sbGet(env, "automations", `id=eq.${encodeURIComponent(b.automation_id)}&select=id,status,graph,trigger_type`);
        const auto = aRows && aRows[0];
        if (!auto) return json({ error: "Automation not found." }, 404, request, env);
        if (auto.status !== "active") return json({ error: "Set the automation to Active first - a draft can't enrol anyone." }, 400, request, env);
        const firstId = autoEdgeTo(auto.graph, "trigger", "next");
        if (!firstId) return json({ error: "Add a first step to the funnel before enrolling anyone." }, 400, request, env);
        const list = `(${ids.map((x) => `"${x.replace(/"/g, "")}"`).join(",")})`;
        const found = (await sbGet(env, "contacts", `id=in.${encodeURIComponent(list)}&select=id,email`)) || [];
        let enrolled = 0;
        for (const ct of found) {
          const res = await sbPost(env, "automation_enrollments", {
            automation_id: auto.id, contact_id: ct.id, status: "active",
            current_node_id: firstId, next_run_at: nowISO(), context: { manual: true, by: user.email || null },
          });
          if (res && res.ok) enrolled++;
        }
        return json({ ok: true, matched: found.length, enrolled, already: found.length - enrolled, missing: ids.length - found.length }, 200, request, env);
      }

      // ---- Automations: inbound email webhook -------------------------------
      // Point an inbound email provider (Cloudflare Email Routing → Worker, or
      // Resend/Mailgun inbound) at this URL. It fires the "inbound_email" trigger
      // for the sender. If AUTOMATIONS_INBOUND_SECRET is set, the provider must
      // pass ?secret=… (wrangler secret put AUTOMATIONS_INBOUND_SECRET).
      if (path.endsWith("/automations/inbound") && request.method === "POST") {
        if (env.AUTOMATIONS_INBOUND_SECRET && url.searchParams.get("secret") !== env.AUTOMATIONS_INBOUND_SECRET) {
          return json({ error: "Unauthorised" }, 401, request, env);
        }
        const b = await request.json().catch(() => ({}));
        const fromRaw = b.from || b.sender || (b.envelope && b.envelope.from) || "";
        const m = /<([^>]+)>/.exec(String(fromRaw));     // strip "Name <email>"
        const email = (m ? m[1] : String(fromRaw)).trim().toLowerCase();
        if (!email) return json({ error: "No sender address" }, 400, request, env);
        const r = await fireTrigger(env, "inbound_email", { email, source: "inbound_email" }, { subject: b.subject || null });
        return json(r, 200, request, env);
      }

      // ---- Discovery call — books a short call + a CRM lead ------------------
      if (path.endsWith("/videography/discovery") && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        const { date, start, duration, interests, name, email, phone, company, message, password, marketing_opt_in } = b || {};
        if (!date || !start || !name || !email) return json({ error: "Missing call details" }, 400, request, env);
        // Account treatment mirrors /smm/discovery: a verified session token
        // books straight onto the member's account; everyone else sets a
        // password (account-at-booking).
        const authedUser = await getUser(request, env);
        if (!authedUser && (!password || !smmPasswordOk(password))) return json({ error: "A password of at least 8 characters including a number and a special character is required." }, 400, request, env);
        let accountUserId = authedUser ? authedUser.id : null, accountCreated = false;
        if (!authedUser) try {
          const cr = await fetch(`${env.SUPABASE_URL}/auth/v1/admin/users`, {
            method: "POST",
            headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json" },
            body: JSON.stringify({ email, password, email_confirm: true, user_metadata: { full_name: name, company: company || null, phone: phone || null } }),
          });
          if (cr.ok) { const u = await cr.json(); accountUserId = (u && u.id) || null; accountCreated = true; }
          else {
            const u = await findUserByEmail(env, email);
            if (u) accountUserId = u.id;
          }
        } catch (_) { /* account is best-effort; the call still books */ }
        const dur = parseInt(duration || "30", 10);
        const endHm = minToHm(hmToMin(start) + dur);
        const check = await graph(env, "POST", `/users/${encodeURIComponent(env.JACK_UPN)}/calendar/getSchedule`, {
          schedules: [env.JACK_UPN],
          startTime: { dateTime: `${date}T${start}:00`, timeZone: "Europe/London" },
          endTime: { dateTime: `${date}T${endHm}:00`, timeZone: "Europe/London" },
          availabilityViewInterval: Math.max(15, dur),
        });
        const view = (check.value && check.value[0] && check.value[0].availabilityView) || "";
        if (view && /[^0]/.test(view)) return json({ error: "That time was just taken - please choose another." }, 409, request, env);
        const interestList = Array.isArray(interests) ? interests : [];
        const ev = await graph(env, "POST", `/users/${encodeURIComponent(env.JACK_UPN)}/events`, {
          subject: `Discovery Call - ${name}`,
          body: { contentType: "text", content: [interestList.length && `Interested in: ${interestList.join(", ")}`, message && `Notes: ${message}`, phone && `Phone: ${phone}`, company && `Company: ${company}`].filter(Boolean).join("\n") },
          start: { dateTime: `${date}T${start}:00`, timeZone: "Europe/London" },
          end: { dateTime: `${date}T${endHm}:00`, timeZone: "Europe/London" },
          attendees: [{ emailAddress: { address: email, name }, type: "required" }],
          isOnlineMeeting: true,
        });
        const token = (crypto.randomUUID && crypto.randomUUID()) || `${date}-${start}`;
        let discoveryId = null;
        try {
          const insRes = await sbPost(env, "videography_bookings", {
            kind: "discovery", service_type: "discovery", client_name: name, client_email: email,
            client_phone: phone || null, company: company || null, service: "Discovery Call",
            shoot_date: `${date}T${start}:00`, stage: "discovery_call_booked",
            discovery_interests: interestList, notes: message || null, reschedule_token: token, ms_event_id: ev.id || null, duration_min: dur,
            account_user_id: accountUserId, marketing_opt_in: !!marketing_opt_in,
          }, "return=representation");
          const arr = await insRes.json();
          discoveryId = Array.isArray(arr) && arr[0] ? arr[0].id : null;
        } catch (_) {}
        const dateNice = (() => { try { return new Date(`${date}T12:00:00`).toLocaleDateString("en-GB", { weekday: "long", day: "numeric", month: "long", year: "numeric" }); } catch (_) { return date; } })();
        const ics = buildICS({ uid: `${ev.id || token}@tmke.co.uk`, date, start, endHm, summary: "Discovery Call - TMKE", description: ["A quick call with Jack to talk through your videography.", interestList.length && `Interested in: ${interestList.join(", ")}`].filter(Boolean).join("\n"), location: "Online / phone", organizer: env.JACK_UPN, attendeeEmail: email, attendeeName: name });
        const icsB64 = bufToBase64(new TextEncoder().encode(ics).buffer);
        const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
        await sendEmail(env, {
          to: email, subject: `Your discovery call is booked - ${dateNice}`,
          html: await wrapInBrandedBase(env, `
            <h1 style="${EM_H1}">Your call is booked</h1>
            <p style="${EM_P}">Hi ${esc(name)}, your discovery call with Jack is confirmed for <strong>${esc(dateNice)} at ${esc(start)}</strong>. We've attached a calendar invite - no prep needed, just bring your questions.</p>
            <p style="${EM_P}">Need to change it? <a href="${(env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "")}/manage?token=${encodeURIComponent(token)}" style="color:#371e28">Reschedule or cancel your call</a>.</p>`),
          attachments: [{ filename: "discovery-call.ics", content: icsB64, contentType: "text/calendar" }],
        });
        await logBookingMessage(env, {
          booking_id: discoveryId, booking_source: "videography",
          account_user_id: accountUserId, client_email: email,
          kind: "confirmation", subject: `Your discovery call is booked - ${dateNice}`,
          body: `Your discovery call with Jack is confirmed for ${dateNice} at ${start}. It's an online/phone call - no prep needed, just bring your questions.`,
        });
        await sendEmail(env, {
          to: env.JACK_NOTIFY || env.JACK_UPN, subject: `New discovery call - ${name} - ${dateNice} ${start}`,
          html: `<div style="${EM_WRAP}">
            <h1 style="${EM_H1}">Discovery call booked</h1>
            <div style="${EM_QUOTE}">
              <div><span style="color:#888">Client:</span> ${esc(name)}</div>
              ${company ? `<div><span style="color:#888">Company:</span> ${esc(company)}</div>` : ""}
              <div><span style="color:#888">Email:</span> ${esc(email)}</div>
              ${phone ? `<div><span style="color:#888">Phone:</span> ${esc(phone)}</div>` : ""}
              <div><span style="color:#888">When:</span> ${esc(dateNice)} at ${esc(start)}</div>
              ${interestList.length ? `<div><span style="color:#888">Interested in:</span> ${esc(interestList.join(", "))}</div>` : ""}
              ${message ? `<div><span style="color:#888">Notes:</span> ${esc(message)}</div>` : ""}
            </div></div>`,
        });
        // CRM: upsert the contact (this endpoint previously skipped it).
        try {
          const parts = String(name || "").trim().split(/\s+/);
          const ci = { email, first_name: parts.shift() || name, last_name: parts.join(" ") || null,
            phone: phone || null, company: company || null, source: "videography_discovery",
            lifecycle: "lead", marketing_opt_in: !!marketing_opt_in,
            tags: crmTags(email, ["Interest: Videography", "Discovery-Call-Booked: Videography"], { optIn: !!marketing_opt_in, member: !!(accountUserId || accountCreated) }), user_id: accountUserId || null };
          await fireTrigger(env, "form_submitted", ci, { form: "videography_discovery", tag: "Discovery Call" });
          if (accountCreated) await fireTrigger(env, "account_created", ci, { form: "videography_discovery" });
        } catch (_) {}
        return json({ ok: true, eventId: ev.id, account_created: accountCreated }, 200, request, env);
      }

      // ---- Manage a booking by token (portal + tokenised email links) -------
      // Authorised by the per-booking reschedule_token (a capability). Used by
      // the account portal and the email "manage your booking" links.
      if (path.endsWith("/videography/booking") && request.method === "GET") {
        const token = (url.searchParams.get("token") || "").trim();
        if (!token) return json({ error: "Missing token" }, 400, request, env);
        const rows = await sbGet(env, "videography_bookings", `reschedule_token=eq.${encodeURIComponent(token)}&select=id,kind,service,service_type,client_name,client_email,shoot_date,stage,postcode,total_pence,discovery_interests,duration_min`);
        const bk = rows && rows[0];
        if (!bk) return json({ error: "Booking not found" }, 404, request, env);
        const days = bk.shoot_date ? (new Date(bk.shoot_date) - new Date()) / 86400000 : null;
        return json({ booking: bk, can_cancel: days != null && days >= 3, can_reschedule: days != null && days >= 2 }, 200, request, env);
      }

      // ---- Cancel a booking (≥3 days' notice; enforced server-side) ----------
      if (path.endsWith("/videography/cancel") && request.method === "POST") {
        const { token } = await request.json().catch(() => ({}));
        if (!token) return json({ error: "Missing token" }, 400, request, env);
        const rows = await sbGet(env, "videography_bookings", `reschedule_token=eq.${encodeURIComponent(token)}&select=*`);
        const bk = rows && rows[0];
        if (!bk) return json({ error: "Booking not found" }, 404, request, env);
        if (bk.stage === "cancelled") return json({ ok: true, already: true }, 200, request, env);
        const days = bk.shoot_date ? (new Date(bk.shoot_date) - new Date()) / 86400000 : 0;
        if (days < 3) return json({ error: "Cancellations within 3 days can't be made online - please email jack@tmke.co.uk. Note: cancellations within 48 hours are chargeable in full." }, 422, request, env);
        if (bk.ms_event_id) { try { await graph(env, "DELETE", `/users/${encodeURIComponent(env.JACK_UPN)}/events/${bk.ms_event_id}`); } catch (_) {} }
        // Checked, because it used to fail silently: 'cancelled' was missing from
        // the stage constraint, so the write was rejected while the client was
        // told it had worked and the booking stayed live in the pipeline.
        const cancelRes = await sbPatch(env, "videography_bookings", `id=eq.${bk.id}`, { stage: "cancelled" });
        if (cancelRes && !cancelRes.ok) {
          const detail = await cancelRes.text().catch(() => "");
          console.error("cancel failed to save", cancelRes.status, detail);
          return json({ error: "We couldn't cancel that just then - please email jack@tmke.co.uk." }, 502, request, env);
        }
        const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
        await sendEmail(env, {
          to: bk.client_email, subject: `Booking cancelled - ${bk.service || "TMKE"}`,
          html: await wrapInBrandedBase(env, `
            <h1 style="${EM_H1}">Your booking is cancelled</h1>
            <p style="${EM_P}">Hi ${esc(bk.client_name || "")}, we've cancelled your ${esc(bk.service || "booking")}. If this was a mistake or you'd like to rebook, just head back to <a href="https://tmke.co.uk/videography" style="color:#371e28">tmke.co.uk/videography</a>.</p>`),
        });
        await sendEmail(env, { to: env.JACK_NOTIFY || env.JACK_UPN, subject: `Cancelled - ${bk.service || "Booking"} - ${bk.client_name || ""}`, html: `<div style="${EM_WRAP}"><p>${esc(bk.client_name || "")} cancelled their ${esc(bk.service || "booking")} (was ${esc(bk.shoot_date || "")}).</p></div>` });
        /* The one that costs money when it is missed: a slot is free and
           nobody knows it. */
        try {
          await notifyAdmins(env, {
            area: "videography", event: "booking_cancelled",
            title: `Cancelled — ${bk.service || "booking"}`,
            body: [bk.client_name, bk.shoot_date].filter(Boolean).join(" · "),
            href: "/admin/videography", key: `cancel:${bk.id}`,
          });
        } catch (_) {}
        await logBookingMessage(env, {
          booking_id: bk.id, booking_source: "videography", account_user_id: bk.account_user_id, client_email: bk.client_email,
          kind: "cancellation", subject: `Booking cancelled - ${bk.service || "TMKE"}`,
          body: `Your ${bk.service || "booking"} has been cancelled. If this was a mistake or you'd like to rebook, head to tmke.co.uk/videography.`,
        });
        return json({ ok: true }, 200, request, env);
      }

      // ---- Reschedule a booking (≥2 days' notice; moves the 365 event) -------
      if (path.endsWith("/videography/reschedule") && request.method === "POST") {
        const { token, date, start } = await request.json().catch(() => ({}));
        if (!token || !date || !start) return json({ error: "Missing details" }, 400, request, env);
        const rows = await sbGet(env, "videography_bookings", `reschedule_token=eq.${encodeURIComponent(token)}&select=*`);
        const bk = rows && rows[0];
        if (!bk) return json({ error: "Booking not found" }, 404, request, env);
        if (bk.stage === "cancelled") return json({ error: "This booking was cancelled." }, 422, request, env);
        const days = bk.shoot_date ? (new Date(bk.shoot_date) - new Date()) / 86400000 : 0;
        if (days < 2) return json({ error: "Rescheduling within 2 days can't be done online - please email jack@tmke.co.uk." }, 422, request, env);
        // Slot length: the stored duration, else read the existing 365 event, else 60.
        let dur = bk.duration_min || 0;
        if (!dur && bk.ms_event_id) {
          try {
            const ev0 = await graph(env, "GET", `/users/${encodeURIComponent(env.JACK_UPN)}/events/${bk.ms_event_id}?$select=start,end`);
            if (ev0 && ev0.start && ev0.end) { const d = Math.round((new Date(ev0.end.dateTime) - new Date(ev0.start.dateTime)) / 60000); if (d > 0) dur = d; }
          } catch (_) {}
        }
        if (!(dur > 0)) dur = 60;
        const endHm = minToHm(hmToMin(start) + dur);
        // Re-check the new slot is free (the existing event sits at the old time).
        const check = await graph(env, "POST", `/users/${encodeURIComponent(env.JACK_UPN)}/calendar/getSchedule`, {
          schedules: [env.JACK_UPN],
          startTime: { dateTime: `${date}T${start}:00`, timeZone: "Europe/London" },
          endTime: { dateTime: `${date}T${endHm}:00`, timeZone: "Europe/London" },
          availabilityViewInterval: Math.max(15, dur),
        });
        const view = (check.value && check.value[0] && check.value[0].availabilityView) || "";
        if (view && /[^0]/.test(view)) return json({ error: "That time isn't free - please pick another." }, 409, request, env);
        // ...and against the bookings board, leaving this booking out of it.
        {
          const blocks = await diaryBlocks(env, date, bk.service_type || "", token);
          if (blocks.day || overlapsAny(blocks.ranges, hmToMin(start), hmToMin(start) + dur)) {
            return json({ error: "That date is already taken - please pick another." }, 409, request, env);
          }
        }
        if (bk.ms_event_id) {
          // Move it, and bring its title and details up to the current format.
          const evInvite = shootInvite({ serviceType: bk.service_type, service: bk.service, name: bk.client_name, company: bk.company || bk.client_company, email: bk.client_email, phone: bk.client_phone,
            pkgKey: bk.package, address: bk.property_address, postcode: bk.postcode, addOns: bk.add_ons, distanceMiles: bk.distance_miles, surchargePence: bk.surcharge_pence, totalPence: bk.total_pence, notes: bk.notes,
            manageUrl: bk.reschedule_token ? `${(env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "")}/manage?token=${encodeURIComponent(bk.reschedule_token)}` : null });
          await graph(env, "PATCH", `/users/${encodeURIComponent(env.JACK_UPN)}/events/${bk.ms_event_id}`, {
            start: { dateTime: `${date}T${start}:00`, timeZone: "Europe/London" },
            end: { dateTime: `${date}T${endHm}:00`, timeZone: "Europe/London" },
            subject: evInvite.subject,
            body: { contentType: "html", content: evInvite.html },
            ...(evInvite.where ? { location: { displayName: evInvite.where } } : {}),
          });
        }
        await sbPatch(env, "videography_bookings", `id=eq.${bk.id}`, { shoot_date: `${date}T${start}:00` });
        const dateNice = (() => { try { return new Date(`${date}T12:00:00`).toLocaleDateString("en-GB", { weekday: "long", day: "numeric", month: "long", year: "numeric" }); } catch (_) { return date; } })();
        // A new starter moving their Studio Day: TEG's sheet gets the new date
        // now, rather than at the next morning's check (Dani, 4 Nov).
        if (/new-starter/i.test(String(bk.service || ""))) { try { await agentSheetWrite(env, bk.client_email, { booked: `${dateNice}, ${start}` }); } catch (_) {} }
        const rsInvite = shootInvite({ serviceType: bk.service_type, service: bk.service, name: bk.client_name, company: bk.company || bk.client_company, email: bk.client_email, phone: bk.client_phone,
          pkgKey: bk.package, address: bk.property_address, postcode: bk.postcode, totalPence: bk.total_pence, lead: "Rescheduled booking.",
          manageUrl: bk.reschedule_token ? `${(env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "")}/manage?token=${encodeURIComponent(bk.reschedule_token)}` : null });
        const ics = buildICS({ uid: `${bk.ms_event_id || bk.reschedule_token}@tmke.co.uk`, date, start, endHm, summary: rsInvite.subject, description: rsInvite.text, location: rsInvite.where || "", organizer: env.JACK_UPN, attendeeEmail: bk.client_email, attendeeName: bk.client_name });
        const icsB64 = bufToBase64(new TextEncoder().encode(ics).buffer);
        const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
        await sendEmail(env, {
          to: bk.client_email, subject: `Booking rescheduled - ${dateNice}`,
          html: await wrapInBrandedBase(env, `
            <h1 style="${EM_H1}">Your booking has moved</h1>
            <p style="${EM_P}">Hi ${esc(bk.client_name || "")}, your ${esc(bk.service || "booking")} is now <strong>${esc(dateNice)} at ${esc(start)}</strong>. An updated calendar invite is attached.</p>`),
          attachments: [{ filename: "booking.ics", content: icsB64, contentType: "text/calendar" }],
        });
        await sendEmail(env, { to: env.JACK_NOTIFY || env.JACK_UPN, subject: `Rescheduled - ${bk.service || "Booking"} - ${bk.client_name || ""}`, html: `<div style="${EM_WRAP}"><p>${esc(bk.client_name || "")} moved their ${esc(bk.service || "booking")} to ${esc(dateNice)} at ${esc(start)}.</p></div>` });
        try {
          await notifyAdmins(env, {
            area: "videography", event: "booking_rescheduled",
            title: `Moved — ${bk.service || "booking"}`,
            body: [bk.client_name, dateNice, start].filter(Boolean).join(" · "),
            href: "/admin/videography",
          });
        } catch (_) {}
        await logBookingMessage(env, {
          booking_id: bk.id, booking_source: "videography", account_user_id: bk.account_user_id, client_email: bk.client_email,
          kind: "reschedule", subject: `Booking rescheduled - ${dateNice}`,
          body: `Your ${bk.service || "booking"} has moved to ${dateNice} at ${start}. An updated calendar invite is on its way.`,
        });
        return json({ ok: true }, 200, request, env);
      }

      // Cancellation waitlist (gated). The studio/section is "fully booked", so we
      // capture an approved-domain partner's details + preferred slot and email a
      // confirmation. The allow-list is server-side (NOT client-supplied).
      if (path.endsWith("/waitlist/register") && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        const { section, name, email, phone, date, time, service } = b || {};
        const pkg = (b && b.package) || "";
        if (!name || !email || !date || !time) return json({ error: "Missing details" }, 400, request, env);
        const allowed = (env.WAITLIST_DOMAINS || "fineandcountry.com,thepropertyexperts.co.uk")
          .split(",").map((d) => d.trim().toLowerCase()).filter(Boolean);
        const mm = String(email).toLowerCase().trim().match(/@([^@\s]+)$/);
        const dom = mm ? mm[1] : "";
        const ok = dom && allowed.some((d) => dom === d || dom.endsWith("." + d));
        if (!ok) return json({ error: "That email isn't on an approved partner domain." }, 403, request, env);
        await sbPost(env, "session_waitlist", {
          section: section || "studio", package: pkg || null,
          name, email, phone: phone || null, email_domain: dom,
          preferred_date: date, preferred_time: time, status: "waiting",
        });
        if (env.RESEND_API_KEY) {
          try {
            await fetch("https://api.resend.com/emails", {
              method: "POST",
              headers: { Authorization: `Bearer ${env.RESEND_API_KEY}`, "Content-Type": "application/json" },
              body: JSON.stringify({
                from: env.MAIL_FROM || "TMKE <onboarding@resend.dev>",
        // MAIL_FROM is posts@tmke.co.uk, which sends fine (the domain is
        // verified) but isn't a mailbox anyone reads. Point replies at a real
        // one so "please stop emailing me" reaches a human.
        reply_to: env.MAIL_REPLY_TO || "hello@tmke.co.uk",
                to: email,
                subject: `You're on the cancellation list - ${service || section || "The Studio"}`,
                html: waitlistHtml({ name, service: service || section || "The Studio", pkg, date, time }),
              }),
            });
          } catch (_) { /* email is best-effort */ }
        }
        return json({ ok: true }, 200, request, env);
      }
      // ---- Public: newsletter / subscribe (NO auth — anonymous visitors) -----
      // Must live in this pre-auth block: the homepage + videography subscribe
      // boxes POST here with no session token, so it can't sit behind the login
      // gate below (that silently 401'd every signup and dropped the contact).
      if (path.endsWith("/newsletter") && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        if (b && b.hp) return json({ ok: true }, 200, request, env); // honeypot
        const email = String((b && b.email) || "").trim();
        if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return json({ error: "Please add a valid email." }, 400, request, env);
        const name = String((b && b.name) || "").trim();
        const parts = name.split(/\s+/).filter(Boolean);
        try {
          // This endpoint serves two different acts of consent: the footer
          // subscribe box, and ticking "marketing" during member signup
          // (member-signup.js posts source:"signup"). The contact's own source
          // stays "newsletter" as it always has — only the audit trail draws
          // the distinction, because "they subscribed" and "they ticked a box
          // while joining" are not the same evidence.
          const joined = String((b && b.source) || "").trim() === "signup";
          // Both acts give consent (Marketing-Opt-In). Only the footer box is a
          // request for the newsletter itself, so only that one is tagged
          // Newsletter-Subscriber - which is what the newsletter will go to.
          await fireTrigger(env, "form_submitted", {
            email, first_name: parts.shift() || null, last_name: parts.join(" ") || null,
            source: "newsletter", lifecycle: "lead", marketing_opt_in: true,
            tags: crmTags(email, joined ? [] : ["Newsletter-Subscriber"], { optIn: true }),
          }, { form: "newsletter" }, joined ? "join_signup" : "newsletter_footer");
        } catch (_) {}
        return json({ ok: true }, 200, request, env);
      }

      // ---- Public: the Member Hub demo (NO auth) ----------------------------
      // /demo asks for a name and an email before opening the hub without an
      // account. The person becomes a lead tagged "Hub demo" on its own
      // trigger, so a follow-up can be built for demo visitors alone. No
      // marketing consent is implied by trying the demo.
      if (path.endsWith("/hub-demo") && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        if (b && b.hp) return json({ ok: true }, 200, request, env); // honeypot
        const email = String((b && b.email) || "").trim().toLowerCase();
        if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return json({ error: "Please add a valid email." }, 400, request, env);
        const parts = String((b && b.name) || "").trim().split(/\s+/).filter(Boolean);
        try {
          await fireTrigger(env, "hub_demo_started", {
            email, first_name: parts.shift() || null, last_name: parts.join(" ") || null,
            source: "hub_demo", lifecycle: "lead",
            tags: crmTags(email, ["Hub demo"], { optIn: false }),
          }, { form: "hub-demo" }, "hub_demo");
        } catch (_) {}
        return json({ ok: true }, 200, request, env);
      }

      // ---- Public: contact-form enquirer into the CRM (NO auth) -------------
      // /contact wrote the enquiry straight to Supabase from the browser and
      // stopped there, so an enquirer never became a contact at all and the
      // marketing tickbox was stored on the enquiry row and read by nothing —
      // ticking it opted nobody in. This adds the missing half.
      //
      // Fires its own `contact_form_submitted` trigger rather than sharing
      // `form_submitted`. Automations are both the funnel builder and the
      // register of every automated email the site sends, so an acknowledgement
      // belongs there and not hard-coded here — but on a dedicated trigger, so
      // building one reaches contact-form enquirers only and can't widen an
      // existing funnel by accident. Nothing listens to it yet, so today this
      // creates the contact and records consent and sends nobody anything.
      //
      // The form still does its own enquiries insert, which is left untouched —
      // this is called afterwards, and failing here must never cost the enquiry.
      if (path.endsWith("/contact/enquirer") && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        if (b && b.hp) return json({ ok: true }, 200, request, env); // honeypot
        const email = String((b && b.email) || "").trim().toLowerCase();
        if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return json({ error: "Please add a valid email." }, 400, request, env);
        const consent = b.marketing_consent === true;
        // RFC 2606 reserved domains cannot receive mail, so there is nothing to
        // send and nobody to disturb. Skipping them lets this endpoint be
        // exercised end to end — CRM write included — without emailing a real
        // person or the team, which is what it took to find the fault below.
        const reserved = /@(example\.(com|net|org)|[^@]*\.(test|invalid|example|localhost))$/i.test(email);
        const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
        const firstName = String(b.first_name || "").trim();
        const fullName = [b.first_name, b.last_name].map((s) => String(s || "").trim()).filter(Boolean).join(" ") || email;
        const message = String(b.message || "").trim();
        const company = String(b.business_name || "").trim();

        // 1. The CRM write goes FIRST. It ran last to begin with, behind two
        //    sendEmail calls, which meant anything slow or broken in the mail
        //    path — a Graph token, a subrequest ceiling, a hang rather than a
        //    throw — cost the contact entirely. The record matters more than
        //    the courtesy email, so it is no longer downstream of it.
        let crm = null, crmError = null;
        try {
          crm = await fireTrigger(env, "contact_form_submitted", {
            email,
            first_name: b.first_name || null,
            last_name: b.last_name || null,
            phone: b.phone || null,
            company: b.business_name || null,
            source: "contact_form",
            lifecycle: "lead",
            // null, not false: an enquiry from someone who already opted in
            // elsewhere must not quietly withdraw their consent.
            marketing_opt_in: consent ? true : null,
            tags: crmTags(email, [], { optIn: consent }),
          }, { form: "contact_form", industry: b.industry || null }, "contact_form");
        } catch (e) {
          crmError = String((e && e.message) || e);
        }
        // Swallowing this silently is what made the first failure undiagnosable.
        if (crmError || !crm || !crm.ok) console.error("contact enquirer CRM write failed", crmError, JSON.stringify(crm));

        // 2. Acknowledgement to the enquirer. Transactional — a reply to
        //    something they did — so it reaches them whether or not they ticked
        //    the marketing box. Same shape as the videography auto-ack.
        let ackError = null;
        try {
          if (!reserved) await sendEmail(env, {
            to: email,
            subject: "Thanks for getting in touch - TMKE",
            html: await wrapInBrandedBase(env, `
              <h1 style="${EM_H1}">Thanks - we've got your message</h1>
              <p style="${EM_P}">Hi ${esc(firstName || "there")}, thanks for getting in touch with TMKE. Your message has reached the team and someone will come back to you shortly.</p>
              ${message ? `<p style="${EM_P}">Here's what you sent us, for your records:</p><div style="${EM_QUOTE_TEXT}">${esc(message)}</div>` : ""}
              <p style="${EM_P}">If anything's changed in the meantime, just reply to this email and it'll come straight to us.</p>`),
          });
        } catch (e) { ackError = String((e && e.message) || e); console.error("contact enquirer ack email failed", ackError); }

        // 3. Alert to the team. An internal admin email, so it goes via the
        //    Worker rather than an automation, same as Jack's booking alert.
        let notifyError = null;
        try {
          if (!reserved) await sendEmail(env, {
            to: env.ENQUIRY_NOTIFY || env.SMM_MANAGER_UPN || "hello@tmke.co.uk",
            subject: `New contact enquiry - ${fullName}`,
            html: `<div style="${EM_WRAP}">
              <h1 style="${EM_H1}">New contact enquiry</h1>
              <div style="${EM_QUOTE}">
                <div><span style="color:#888">Name:</span> ${esc(fullName)}</div>
                ${company ? `<div><span style="color:#888">Business:</span> ${esc(company)}</div>` : ""}
                <div><span style="color:#888">Email:</span> ${esc(email)}</div>
                ${b.phone ? `<div><span style="color:#888">Phone:</span> ${esc(b.phone)}</div>` : ""}
                ${b.industry ? `<div><span style="color:#888">Industry:</span> ${esc(b.industry)}</div>` : ""}
                ${message ? `<div><span style="color:#888">Message:</span> ${esc(message)}</div>` : ""}
                <div><span style="color:#888">Marketing opt-in:</span> ${consent ? "Yes" : "No"}</div>
              </div>
              <p style="${EM_SMALL}">Saved to the Enquiries inbox (/admin/enquiries). They've had an automatic acknowledgement.</p></div>`,
          });
        try {
          await notifyAdmins(env, {
            area: "hub", event: "contact_form",
            title: "Someone used the contact form",
            body: [name, email, (message || "").slice(0, 120)].filter(Boolean).join(" · "),
            href: "/admin/enquiries",
          });
        } catch (_) {}
        } catch (e) { notifyError = String((e && e.message) || e); console.error("contact enquirer team alert failed", notifyError); }

        // Reports what actually happened. The browser ignores it — the enquiry
        // is already saved and the sender must never see an error for something
        // that worked — but it makes the endpoint testable from outside, which
        // the first version was not.
        return json({
          ok: true,
          contact_id: (crm && crm.contact_id) || null,
          enrolled: (crm && crm.enrolled) || 0,
          errors: { crm: crmError || (crm && crm.error) || null, ack: ackError, notify: notifyError },
        }, 200, request, env);
      }
    } catch (err) {
      return json({ error: String(err && err.message ? err.message : err) }, 500, request, env);
    }

    // Auth. Hot upload path (part/complete/abort) uses a fast local expiry check
    // — it already requires an unguessable uploadId minted by the fully-authed
    // /create. Everything else does full Supabase validation.
    //
    // This has no path scoping of its own, so it silently gates EVERY route
    // defined below it in the file, not just the upload cluster it was
    // written for - which broke the edit-request page (genuinely public: an
    // F&C agent or TEG new starter clicking an email link has no TMKE
    // account to sign in with) the moment those routes landed after this
    // point. Explicit bypass here rather than reordering the file, so the
    // next route added below doesn't fall into the same trap silently.
    const publicNoAuth = path.endsWith("/videography/edit-request/context")
      || path.endsWith("/videography/edit-request")
      || path.endsWith("/assets/review-grid")
      // Approve / Reject an invoice from the email: the signed link is the
      // proof, and Jack and Abbie shouldn't have to sign in (Danielle, 21 Oct).
      || path.endsWith("/invoicing/approval")
      || path.endsWith("/videography/fc-fee")
      || path.includes("/accounts-portal/")   // its own link and passcode, checked in the route
      || (path.endsWith("/download") && url.searchParams.get("sig"))    // proof is in the link
      || (path.endsWith("/preview") && url.searchParams.get("sig"));
    if (!publicNoAuth) {
      const hot = path.endsWith("/part") || path.endsWith("/complete") || path.endsWith("/abort");
      if (hot) {
        if (!cheapValid(request)) return json({ error: "Unauthorised" }, 401, request, env);
      } else {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Unauthorised" }, 401, request, env);
      }
    }

    try {
      // ---- The accounts portal (public: the link and passcode are the proof) ----
      if (path.endsWith("/accounts-portal/open") && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        const p = await accountsPortalRow(env);
        if (!p) return json({ code: "not_ready" }, 503, request, env);
        if (String((b && b.token) || "") !== p.token) return json({ code: "unknown" }, 404, request, env);
        if (!p.enabled) return json({ code: "closed" }, 403, request, env);
        const lockedFor = p.locked_until ? Date.parse(p.locked_until) - Date.now() : 0;
        if (lockedFor > 0) return json({ code: "locked", minutes: Math.ceil(lockedFor / 60000) }, 429, request, env);
        if (portalCode(b && b.passcode) !== p.passcode) {
          const tries = (p.failed_tries || 0) + 1;
          if (tries >= PORTAL_TRIES) {
            await sbPatch(env, "accounts_portal", "id=eq.1", { failed_tries: 0, locked_until: new Date(Date.now() + PORTAL_LOCK_MIN * 60000).toISOString() });
            return json({ code: "locked", minutes: PORTAL_LOCK_MIN }, 429, request, env);
          }
          await sbPatch(env, "accounts_portal", "id=eq.1", { failed_tries: tries });
          return json({ code: "wrong", left: PORTAL_TRIES - tries }, 401, request, env);
        }
        const exp = Date.now() + PORTAL_DAYS * 24 * 60 * 60 * 1000;
        const sig = await portalSig(env, `accounts:${p.token}`, p.passcode, exp);
        if (!sig) return json({ error: "The portal isn't configured on the Worker." }, 503, request, env);
        await sbPatch(env, "accounts_portal", "id=eq.1", { failed_tries: 0, locked_until: null, last_opened_at: new Date().toISOString() });
        return json({ session: `${p.token}.${exp}.${sig}`, expires: exp }, 200, request, env);
      }
      if (path.includes("/accounts-portal/")) {
        const p = await accountsFromSession(env, request);
        if (!p) return json({ code: "signed_out" }, 401, request, env);
        // Only what accounts need to see, nothing about how it's filed with us.
        const shown = (v) => ({ id: v.id, number: v.number, route: v.route, kind: v.kind, client: v.client, payer: v.payer, sent: v.sent, due: v.due, month: v.month, net_pence: v.net_pence, note: v.note, status: v.status, marked_at: v.marked_at });
        if (path.endsWith("/accounts-portal/invoices") && request.method === "GET") {
          const open = await invoiceBook(env, PORTAL_FILTER);
          if (!open) return json({ error: "Couldn't load the invoices." }, 502, request, env);
          // What accounts have marked stays, with its box and Undo, until its
          // month has nothing open (Dani, 6 Nov). Card payments still come off.
          const months = [...new Set(open.map((v) => v.month))].filter(Boolean).sort();
          let marked = [];
          if (months.length) {
            const from = `${months[0]}-01`;
            const rows = await invoiceBook(env, `status=eq.paid&accounts_marked_at=not.is.null&or=(sent_at.gte.${from},issued_date.gte.${from})`);
            if (!rows) return json({ error: "Couldn't load the invoices." }, 502, request, env);
            marked = rows.filter((v) => months.includes(v.month) && v.method !== "direct_debit");
          }
          // By number, so a row keeps its place when it's marked and reloaded.
          const all = [...open, ...marked].sort((a, c) => String(c.number).localeCompare(String(a.number), "en", { numeric: true }));
          return json({ ok: true, today: invToday().ymd, invoices: all.map(shown) }, 200, request, env);
        }
        const b = request.method === "POST" ? await request.json().catch(() => ({})) : {};
        const id = String((b && b.id) || url.searchParams.get("id") || "");
        if (!/^[0-9a-f-]{36}$/i.test(id)) return json({ error: "Which invoice?" }, 400, request, env);
        const inv = (await sbGet(env, "invoices", `id=eq.${id}&select=id,number,status,payment_method,accounts_marked_at,template,booking_id,booking_source`))?.[0];
        // Open on the portal, or one they've confirmed and might want to undo.
        if (!inv || inv.payment_method === "direct_debit" || !(inv.status === "sent" || (inv.status === "paid" && inv.accounts_marked_at))) return json({ error: "That invoice isn't on this page any more." }, 404, request, env);
        const at = `id=eq.${id}`;
        if (path.endsWith("/accounts-portal/invoice-pdf") && request.method === "GET") {
          const key = `invoices/${inv.number || inv.id}.pdf`;
          let head = null;
          try { head = await env.BUCKET.head(key); } catch (_) {}
          if (!head) {
            const full = (await sbGet(env, "invoices", `${at}&select=*`))?.[0];
            const st = (await sbGet(env, "invoice_settings", "id=eq.1&select=*"))?.[0] || {};
            try { await env.BUCKET.put(key, await renderInvoicePdf(env, { ...st, template: inv.template || st.template }, full), { httpMetadata: { contentType: "application/pdf" } }); }
            catch (_) { return json({ error: "Couldn't open that invoice. Please try again." }, 502, request, env); }
          }
          const exp = Date.now() + 60 * 60 * 1000;
          const sig = await mediaSig(env, key, exp);
          if (!sig) return json({ error: "Couldn't open that invoice." }, 503, request, env);
          const base = String(env.WORKER_PUBLIC_URL || url.origin).replace(/\/+$/, "");
          return json({ url: `${base}/download?key=${encodeURIComponent(key)}&exp=${exp}&sig=${encodeURIComponent(sig)}` }, 200, request, env);
        }
        if (path.endsWith("/accounts-portal/note") && request.method === "POST") {
          const note = String(b.note || "").trim().slice(0, 2000);
          const r = await sbPatch(env, "invoices", at, { accounts_note: note || null });
          return r.ok ? json({ ok: true, note }, 200, request, env) : json({ error: "Couldn't save that note." }, 502, request, env);
        }
        if (path.endsWith("/accounts-portal/mark") && request.method === "POST") {
          const action = String(b.action || "");
          if (action === "paid") {
            if (inv.status !== "sent") return json({ error: "That one's already marked." }, 409, request, env);
            const r = await sbPatch(env, "invoices", `${at}&status=eq.sent`, { status: "paid", paid_date: invToday().ymd, accounts_marked_at: new Date().toISOString() });
            if (!r.ok) return json({ error: "Couldn't save that. Please try again." }, 502, request, env);
            const fx = await invoicePaidEffects(env, id, "Accounts portal");
            return json({ ok: true, ...fx }, 200, request, env);
          }
          if (action === "undo") {
            if (inv.status !== "paid" || !inv.accounts_marked_at) return json({ error: "That one can't be undone from here." }, 409, request, env);
            const r = await sbPatch(env, "invoices", at, { status: "sent", paid_date: null, accounts_marked_at: null });
            if (!r.ok) return json({ error: "Couldn't undo that. Please try again." }, 502, request, env);
            // The shoot goes back to unpaid unless its PIN has already gone. A
            // PIN can't be un-sent, so Dani's told rather than left to find out.
            if (inv.booking_id && (inv.booking_source || "videography") === "videography") {
              const bk = (await sbGet(env, "videography_bookings", `id=eq.${inv.booking_id}&select=id,client_name,pin_released_at`))?.[0];
              if (bk && !bk.pin_released_at) await sbPatch(env, "videography_bookings", `id=eq.${bk.id}`, { paid_at: null });
              else if (bk) await sendEmail(env, { to: invDanielle(env), subject: `Accounts undid ${inv.number}, but the PIN has already gone.`, html: await wrapInBrandedBase(env, `<div style="${EM_WRAP}"><p style="${EM_P}">Hi Danielle,</p><p style="${EM_P}">Accounts marked ${invEsc(inv.number || "an invoice")} paid, then undid it. ${invEsc(bk.client_name || "The client")}'s gallery PIN went out when it was marked paid, so they already have it.</p></div>`) });
            }
            return json({ ok: true }, 200, request, env);
          }
          return json({ error: "Which action?" }, 400, request, env);
        }
        return json({ error: "Not found" }, 404, request, env);
      }

      // ---- Send an email via Resend (admin only) ----
      // Powers the admin email-template builder's "Send test", and is the relay
      // ---- Admin: preview an automated email (renders the REAL builder with
      // sample data — read-only, changes nothing that sends). ------------------
      // Preview an automated email with sample data — and (POST) send that exact
      // preview to yourself as a test, so what you check is what goes out.
      if (path.endsWith("/email/preview/send") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String((b && b.id) || "");
        const to = String((b && b.to) || "").trim();
        if (!to || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(to)) return json({ ok: false, error: "Enter a valid email address." }, 200, request, env);
        const built = (await deliveryPreview(env, id)) || emailPreviewSample(id);
        if (!built) return json({ ok: false, error: "There's no preview for that email yet." }, 200, request, env);
        let html = built.html;
        if (b && b.branded) html = await wrapInBrandedBase(env, html);
        const sent = await sendEmail(env, { to, subject: `[Test] ${built.subject}`, html });
        return sent && sent.ok
          ? json({ ok: true, to }, 200, request, env)
          : json({ ok: false, error: (sent && sent.error) || "Couldn't send it." }, 200, request, env);
      }

      if (path.endsWith("/email/preview") && (request.method === "GET" || request.method === "POST")) {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        // POST carries unsaved style settings from the style editor, so it can
        // preview a change through the real pipeline before committing to it.
        const body = request.method === "POST" ? await request.json().catch(() => ({})) : {};
        const id = body.id || url.searchParams.get("id") || "";
        const branded = body.branded === true || url.searchParams.get("branded") === "1";
        const override = body.styles && typeof body.styles === "object" ? body.styles : null;
        const built = (await deliveryPreview(env, id)) || emailPreviewSample(id);
        if (!built) return json({ ok: true, supported: false }, 200, request, env);
        try {
          let html = built.html;
          if (branded) html = await wrapInBrandedBase(env, html, override);
          else html = styleEmailContent(html, override || EMS);
          return json({ ok: true, supported: true, subject: built.subject, html }, 200, request, env);
        } catch (e) { return json({ ok: false, error: String((e && e.message) || e) }, 200, request, env); }
      }

      // for marketing/transactional sends generally. The caller is already a
      // valid Supabase user (gated below); we additionally require a TMKE admin
      // email so a signed-in customer can't drive the mailer. The verified
      // sender domain comes from MAIL_FROM — callers may only set a display name.
      if (path.endsWith("/email/send") && request.method === "POST") {
        const sender = await getUser(request, env);
        if (!isAdminEmail(sender)) return json({ error: "Admins only." }, 403, request, env);
        let body;
        try { body = await request.json(); } catch (_) { return json({ error: "Bad JSON" }, 400, request, env); }
        const toRaw = body && body.to;
        const to = (Array.isArray(toRaw) ? toRaw : [toRaw])
          .map((x) => String(x || "").trim()).filter(Boolean).slice(0, 50);
        const subject = String((body && body.subject) || "").replace(/[\r\n]+/g, " ").slice(0, 300);
        const html = String((body && body.html) || "");
        if (!to.length) return json({ error: "No recipient address." }, 400, request, env);
        if (!html) return json({ error: "Nothing to send." }, 400, request, env);
        const fromName = body && body.fromName ? String(body.fromName).replace(/[<>\r\n]/g, "").trim().slice(0, 80) : "";
        // Send via Microsoft 365 (MAIL_SENDER = hello@tmke.co.uk) — the SAME pipeline
        // the automated/transactional emails use, so a Studio test matches the real
        // send and isn't limited to your own address (as the Resend sandbox is until
        // its domain is verified).
        const result = await sendEmail(env, { to, subject, html, fromName: fromName || undefined });
        if (!result.ok) return json({ error: result.error || "Send failed." }, 502, request, env);
        return json({ ok: true }, 200, request, env);
      }

      // ---- Microsoft 365 connection health (admin) ----
      if (path.endsWith("/ms/status") && request.method === "GET") {
        try {
          const u = await graph(env, "GET", `/users/${encodeURIComponent(env.JACK_UPN)}?$select=displayName,mail,userPrincipalName`);
          return json({ connected: true, name: u.displayName, upn: u.userPrincipalName || u.mail }, 200, request, env);
        } catch (e) {
          return json({ connected: false, error: String(e && e.message ? e.message : e) }, 200, request, env);
        }
      }

      // ---- Create a multipart upload ----
      if (path.endsWith("/create") && request.method === "POST") {
        const { bookingId, fileName, contentType, folder, category, prefix } = await request.json();
        // The internal archive browser uploads into whatever folder is open,
        // which can be nested as deep as someone has made it - so it sends the
        // prefix itself rather than a folder + category pair.
        if (prefix) {
          const user = await getUser(request, env);
          if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
          const name = String(fileName || "file").replace(/[^a-zA-Z0-9._-]+/g, "-").replace(/-+/g, "-").slice(0, 120);
          const key = archivePrefix(prefix) + `${Date.now()}-${name}`;
          const mpx = await env.BUCKET.createMultipartUpload(key, { httpMetadata: contentType ? { contentType } : undefined });
          return json({ key, uploadId: mpx.uploadId }, 200, request, env);
        }
        // A booking id is unique but tells you nothing when you're looking
        // through storage months later. When the admin centre supplies a folder
        // name, files land under it - and under their category, so exteriors and
        // interiors are separate without anyone renaming a thing.
        const key = folder
          ? safeFolderKey(folder, category, `${Date.now()}-${fileName}`)
          : safeKey(bookingId, `${Date.now()}-${fileName}`);
        const mp = await env.BUCKET.createMultipartUpload(key, {
          httpMetadata: contentType ? { contentType } : undefined,
        });
        return json({ key, uploadId: mp.uploadId }, 200, request, env);
      }

      // ---- Upload one part (bytes streamed in the request body) ----
      if (path.endsWith("/part") && request.method === "PUT") {
        const key = url.searchParams.get("key");
        const uploadId = url.searchParams.get("uploadId");
        const partNumber = parseInt(url.searchParams.get("partNumber") || "0", 10);
        if (!key || !uploadId || !partNumber)
          return json({ error: "Missing key/uploadId/partNumber" }, 400, request, env);
        const mp = env.BUCKET.resumeMultipartUpload(key, uploadId);
        const body = await request.arrayBuffer();
        const part = await mp.uploadPart(partNumber, body);
        return json({ partNumber, etag: part.etag }, 200, request, env);
      }

      // ---- Complete the multipart upload ----
      if (path.endsWith("/complete") && request.method === "POST") {
        const { key, uploadId, parts } = await request.json();
        if (!key || !uploadId || !Array.isArray(parts))
          return json({ error: "Missing key/uploadId/parts" }, 400, request, env);
        const mp = env.BUCKET.resumeMultipartUpload(key, uploadId);
        const obj = await mp.complete(
          parts.map((p) => ({ partNumber: p.partNumber, etag: p.etag }))
        );
        return json({ ok: true, key, size: obj.size }, 200, request, env);
      }

      // ---- Abort ----
      if (path.endsWith("/abort") && request.method === "POST") {
        const { key, uploadId } = await request.json();
        const mp = env.BUCKET.resumeMultipartUpload(key, uploadId);
        await mp.abort();
        return json({ ok: true }, 200, request, env);
      }

      // ---- List a booking's files ----
      // ---- List one folder of the archive (admins) ----
      // ?prefix= lists that folder: the files in it, and the folders inside it.
      // The internal library browses the same objects the deliveries do - one
      // copy in R2, no second home for the same video.
      if (path.endsWith("/list") && request.method === "GET" && url.searchParams.get("prefix") !== null) {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        return json(await listArchive(env, archivePrefix(url.searchParams.get("prefix"))), 200, request, env);
      }

      // ---- A social media shoot is ready: tell whoever runs that account ----
      // Sent when the shoot reaches "gallery ready". The client never sees these
      // videos, so there is no Pixieset gallery and no client email - what is
      // needed is for the account's manager to know the footage is in the
      // Library, and a link straight to that client's folder.
      if (path.endsWith("/videography/smm-ready") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String((b && b.booking_id) || "");
        if (!id) return json({ error: "Which shoot?" }, 400, request, env);
        const rows = await sbGet(env, "videography_bookings",
          `id=eq.${encodeURIComponent(id)}&select=id,client_name,client_company,brand,service,service_type,shoot_date,archive_folder,smm_lead_id&limit=1`);
        const bk = rows && rows[0];
        if (!bk) return json({ error: "Shoot not found." }, 404, request, env);
        if (!bk.smm_lead_id) return json({ ok: true, skipped: "not a social media shoot" }, 200, request, env);

        const leads = await sbGet(env, "smm_leads", `id=eq.${encodeURIComponent(bk.smm_lead_id)}&select=id,business_name,contact_name,social_media_manager&limit=1`);
        const lead = (leads && leads[0]) || {};
        const clientName = lead.business_name || lead.contact_name || bk.client_company || bk.client_name || "the client";

        // The manager is held as a name, and admins are held as addresses, so
        // the name is matched against them. No match means the social media
        // inbox, which is better than nobody being told.
        const manager = String(lead.social_media_manager || "").trim();
        const admins = (await sbGet(env, "admins", "select=email")) || [];
        const wanted = manager.toLowerCase().split(/\s+/).filter(Boolean);
        const match = manager && admins.find((a2) => {
          const local = String(a2.email || "").toLowerCase().split("@")[0].replace(/[._-]+/g, " ");
          return wanted.every((w) => local.includes(w)) || (wanted[0] && local.split(" ")[0] === wanted[0]);
        });
        const to = (match && match.email) || env.SMM_NOTIFY || env.MAIL_SENDER;
        if (!to) return json({ error: "No one to tell - set SMM_NOTIFY on the Worker." }, 503, request, env);

        const folder = String(bk.archive_folder || "").trim();
        const site = String(env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "");
        // Their portal, when they have one (made at booking): the folder shows
        // now, and the portal's own email takes the manager the link and
        // passcode (Dani, 4 Nov). The Library email is the fallback.
        try {
          if (folder) {
            await runSmmPortalFlags(env);
            const portal = await smmClientPortal(env, { id: bk.smm_lead_id, ...lead }, false);
            if (portal && portal.enabled && portal.notify_email && portalFolders(portal).includes(archivePrefix(folder))) {
              await runPortalFolderNotices(env);
              try {
                await notifyAdmins(env, {
                  area: "social", event: "smm_content_ready", title: `Content ready — ${clientName}`,
                  body: `${bk.service || "Shoot"}${bk.shoot_date ? " on " + bk.shoot_date : ""} is in ${portal.name}'s portal.`,
                  href: "/admin/videography?panel=portals", also: [portal.notify_email], key: `smm-ready:${bk.id}`,
                  meta: { booking_id: bk.id, lead_id: lead.id || null },
                });
              } catch (_) {}
              return json({ ok: true, to: portal.notify_email, portal: portal.name }, 200, request, env);
            }
          }
        } catch (_) {}
        const link = folder ? `${site}/admin/content?folder=${encodeURIComponent(folder)}` : `${site}/admin/content`;
        const esc2 = (v) => String(v ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
        const when = bk.shoot_date ? new Date(bk.shoot_date).toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" }) : "";
        const html = await wrapInBrandedBase(env, `
          <h1 style="${EM_H1}">${esc2(clientName)}'s content is ready</h1>
          <p style="${EM_P}">The ${esc2(bk.service || bk.service_type || "shoot")}${when ? ` from ${esc2(when)}` : ""} has been edited and is in the Library.</p>
          <p style="margin:0 0 24px;"><a href="${esc2(link)}" style="${EM_BTN}">Open it in the Library</a></p>
          <p style="${EM_P}">If you need any edits, just message Jack - no form to fill in.</p>
          <p style="${EM_SMALL}">Nothing has gone to the client: this footage is ours to use for their social media.</p>`);
        const sent = await sendEmail(env, { to, subject: `Ready in the Library - ${clientName}`, html });
        if (!sent.ok) return json({ error: sent.error || "The email didn't send." }, 502, request, env);
        /* Their client's shoot is edited and in the Library. This one belongs
           to the account manager — Abby for hers — because she is the one who
           has to do something with it. */
        try {
          await notifyAdmins(env, {
            area: "social", event: "smm_content_ready",
            title: `Content ready — ${clientName}`,
            body: `${bk.service || "Shoot"}${bk.shoot_date ? " on " + bk.shoot_date : ""} is edited and in the Library.`,
            href: "/admin/content", also: [to], key: `smm-ready:${bk.id}`,
            meta: { booking_id: bk.id, lead_id: lead.id || null },
          });
        } catch (_) {}
        return json({ ok: true, to, link }, 200, request, env);
      }

      // Release a portal shoot before it's paid, or take that back (Dani, 6 Nov).
      // One shoot at a time, by management, with who and when kept on it.
      // ---- The portal email for one shoot, sent now, by a person (Dani, 7 Nov) ----
      if (path.endsWith("/videography/portal-send") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const body = await request.json().catch(() => ({}));
        const to = (Array.isArray(body.to) ? body.to : []).map((x) => String(x || "").trim()).filter(Boolean);
        if (!to.length || to.some((x) => !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(x))) return json({ error: "One of those email addresses doesn't look right." }, 400, request, env);
        const rows = await sbGet(env, "videography_bookings", `id=eq.${encodeURIComponent(body.booking_id || "")}&select=*`);
        const bk = rows && rows[0];
        if (!bk || bk.delivery_method !== "portal" || !bk.archive_folder) return json({ error: "That shoot isn't delivered by client portal." }, 400, request, env);
        const prefix = archivePrefix(bk.archive_folder);
        const portals = (await sbGet(env, "client_portals", "enabled=eq.true&select=id,name,first_name,token,passcode,folders,notified_folders,notify_email,smm_client_id")) || [];
        const p = portals.find((x) => portalFolders(x).includes(prefix));
        if (!p) return json({ error: "Choose their portal first, and make sure it's turned on." }, 400, request, env);
        if (TEG_PORTAL_NAME.test(String(p.name || "")) || p.smm_client_id) return json({ error: "That portal has its own emails." }, 400, request, env);
        if (!(await portalShownFolders(env, p)).includes(prefix)) return json({ error: "It isn't showing in their portal yet, so there's nothing for them to open." }, 409, request, env);
        await loadEmailStyles(env);
        const mail = await portalShootMail(env, p, prefix, bk);
        const sent = await sendEmail(env, { to, subject: mail.subject, html: mail.html });
        if (!sent || !sent.ok) return json({ error: "The email didn't send: " + String((sent && sent.error) || "unknown error").slice(0, 200) }, 502, request, env);
        const told = [...new Set([...(p.notified_folders || []), prefix])];
        await sbPatch(env, "client_portals", `id=eq.${encodeURIComponent(p.id)}`, { notify_email: to.join(", "), notified_folders: told });
        const patch = await markPortalEmailed(env, bk, to.join(", "));
        return json({ ok: true, to: to.join(", "), ...(patch || {}) }, 200, request, env);
      }

      if (path.endsWith("/videography/release-before-payment") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!(await isManagement(env, user)) && !isVideographyInvoicer(user.email)) return json(MGMT_ONLY, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String((b && b.booking_id) || "");
        if (!/^[0-9a-f-]{36}$/i.test(id)) return json({ error: "Which shoot?" }, 400, request, env);
        const bk = (await sbGet(env, "videography_bookings", `id=eq.${id}&select=*`))?.[0];
        if (!bk) return json({ error: "Shoot not found." }, 404, request, env);
        if (bk.delivery_method !== "portal") return json({ error: "Set this shoot to Client portal first." }, 400, request, env);
        const on = !!b.on;
        const patch = on ? { released_unpaid_at: new Date().toISOString(), released_unpaid_by: user.email || "management" } : { released_unpaid_at: null, released_unpaid_by: null };
        const r = await sbPatch(env, "videography_bookings", `id=eq.${id}`, patch);
        if (!r || !r.ok) return json({ error: "Couldn't save that. Please try again." }, 502, request, env);
        await logBookingMessage(env, { booking_id: id, booking_source: "videography", client_email: bk.client_email || null, channel: "note", kind: "audit",
          body: on ? `Released before payment by ${user.email || "management"}.` : `Release before payment taken back by ${user.email || "management"}.`, created_by: user.email || "management" });
        return json({ ok: true, ...patch }, 200, request, env);
      }

      // ---- A link to one file that a <video> or a download can use (admins) ----
      if (path.endsWith("/media-link") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const key = url.searchParams.get("key") || "";
        if (!key.startsWith(PART_PREFIX + "/")) return json({ error: "Not an archive file." }, 400, request, env);
        const exp = Date.now() + 6 * 60 * 60 * 1000;                     // long enough to watch, short enough to matter
        const sig = await mediaSig(env, key, exp);
        if (!sig) return json({ error: "Links aren't configured on the Worker." }, 503, request, env);
        const base = String(env.WORKER_PUBLIC_URL || url.origin).replace(/\/+$/, "");
        const q = (dl) => `${base}/download?key=${encodeURIComponent(key)}&exp=${exp}&sig=${encodeURIComponent(sig)}${dl ? "&dl=1" : ""}`;
        return json({ url: q(false), downloadUrl: q(true), expires: exp }, 200, request, env);
      }

      // ---- Creative Studio (Dani, 8 Nov) -----------------------------------
      // Every Library folder as a card: type, date, counts, a picture, its portals.
      if (path.includes("/creative/")) {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const root = `${PART_PREFIX}/`;
        const base = String(env.WORKER_PUBLIC_URL || url.origin).replace(/\/+$/, "");
        const exp = portalLinkExpiry();
        const sign = async (key, dl) => {
          const sig = await mediaSig(env, key, exp);
          return sig ? `${base}/download?key=${encodeURIComponent(key)}&exp=${exp}&sig=${encodeURIComponent(sig)}${dl ? "&dl=1" : ""}` : "";
        };
        const thumbOf = (key) => { const at = key.lastIndexOf("/"); return `${key.slice(0, at)}/${THUMB_DIR}/${key.slice(at + 1)}.jpg`; };
        const previewOf = (key) => { const at = key.lastIndexOf("/"); return `${key.slice(0, at)}/${THUMB_DIR}/${key.slice(at + 1)}.preview.jpg`; };
        const isFilm = (n) => /\.(mp4|mov|m4v|webm)$/i.test(n);
        const isPhoto = (n) => /\.(jpe?g|png|webp|avif|gif|heic)$/i.test(n);
        const linksFor = async (f) => {
          const fresh = `&v=${new Date(f.uploaded).getTime()}`;
          const out = { url: (await sign(f.key, false)) + fresh, downloadUrl: await sign(f.key, true) };
          if (PREVIEWABLE.test(f.key)) out.previewUrl = out.url.replace("/download?", "/preview?");
          if (f.hasThumb) out.thumbUrl = (await sign(thumbOf(f.key), false)) + fresh;
          else if (out.previewUrl) out.thumbUrl = out.previewUrl + "&size=thumb";
          return out;
        };

        if (path.endsWith("/creative/library") && request.method === "GET") {
          const by = new Map();
          let cursor;
          do {
            const page = await env.BUCKET.list({ prefix: root, cursor });
            for (const o of page.objects || []) {
              const rest = o.key.slice(root.length), at = rest.indexOf("/");
              if (at < 1) continue;
              const name = rest.slice(0, at), inner = rest.slice(at + 1);
              if (!by.has(name)) by.set(name, { name, photos: 0, films: 0, first: "", last: "", thumb: "", filmThumb: "", photo: "" });
              const f = by.get(name);
              if (inner.includes(`${THUMB_DIR}/`)) {
                if (inner.endsWith(".preview.jpg")) continue;
                if (!f.thumb && /\.(jpe?g|png|webp)\.jpg$/i.test(inner)) f.thumb = o.key;
                if (!f.filmThumb && /\.(mp4|mov|m4v|webm)\.jpg$/i.test(inner)) f.filmThumb = o.key;
                continue;
              }
              if (!inner || inner.endsWith("/") || /(^|\/)\.keep$|\.library\.json$/i.test(inner)) continue;
              if (isFilm(inner)) f.films += 1;
              else if (isPhoto(inner)) { f.photos += 1; if (!f.photo && PREVIEWABLE.test(inner)) f.photo = o.key; }
              const when = new Date(o.uploaded).toISOString();
              if (!f.first || when < f.first) f.first = when;
              if (!f.last || when > f.last) f.last = when;
            }
            cursor = page.truncated ? page.cursor : null;
          } while (cursor);
          const [bks, portals] = await Promise.all([
            sbGetAll(env, "videography_bookings", "or=(kind.is.null,kind.eq.booking)&select=*&order=id.asc"),
            sbGet(env, "client_portals", "select=name,folders&order=name.asc"),
          ]);
          if (!bks || !portals) return json({ error: "Couldn't read the shoots." }, 502, request, env);
          const typeOf = (text) => {
            const t = String(text || "");
            if (/new.?starter|induction/i.test(t)) return "New starter";
            if (/event/i.test(t)) return "Event coverage";
            if (/\bprop/i.test(t)) return "Property shoots";
            if (/content/i.test(t)) return "Content Studio";
            if (/agent/i.test(t)) return "Agent shoots";
            return "";
          };
          const folders = [];
          for (const f of by.values()) {
            const bk = bks.find((b) => b.archive_folder === f.name) || bks.find((b) => b.id === f.name) || bks.find((b) => archiveNameFor(b) === f.name);
            const bits = f.name.split(" - ").map((x) => x.trim()).filter(Boolean);
            const dateAt = bits.findIndex((x) => /^\d{4}-\d{2}-\d{2}$/.test(x));
            const service = (bk && (bk.service || bk.service_type)) || (dateAt > 1 ? bits.slice(0, dateAt - 1).join(" - ") : "");
            // The folder's own words win for a new starter: "New Starter Booking - On Location" was re-labelled an agent shoot by the 4 Nov service list.
            const type = (/new.?starter|induction/i.test(f.name) ? "New starter" : typeOf(service)) || typeOf(f.name) || (bk ? "" : "Our own");
            const title = String((bk && (bk.shoot_name || bk.client_name || bk.client_company)) || (dateAt >= 1 ? bits[dateAt - 1] : f.name)).trim();
            const date = (bk && bk.shoot_date && String(bk.shoot_date).slice(0, 10)) || (dateAt >= 0 ? bits[dateAt] : "") || f.first.slice(0, 10);
            const prefix = `${root}${f.name}/`;
            const cover = (bk && bk.cover_url) || (f.thumb ? await sign(f.thumb) : f.filmThumb ? await sign(f.filmThumb) : f.photo ? (await sign(f.photo)).replace("/download?", "/preview?") + "&size=thumb" : "");
            folders.push({ prefix, name: f.name, title, service, type, date, photos: f.photos, films: f.films, first: f.first, last: f.last, cover,
              portals: portals.filter((p) => portalFolders(p).includes(prefix)).map((p) => p.name) });
          }
          return json({ folders }, 200, request, env);
        }

        // One folder, with everything inside it and the links to show it.
        if (path.endsWith("/creative/folder") && request.method === "GET") {
          const prefix = archivePrefix(url.searchParams.get("prefix"));
          if (prefix === root) return json({ error: "Choose a folder." }, 400, request, env);
          const objects = [];
          let cursor;
          do {
            const page = await env.BUCKET.list({ prefix, cursor, include: ["httpMetadata"] });
            objects.push(...(page.objects || []));
            cursor = page.truncated ? page.cursor : null;
          } while (cursor);
          const keys = new Set(objects.map((o) => o.key));
          const parts = new Set([""]);
          const files = [];
          for (const o of objects) {
            const inner = o.key.slice(prefix.length);
            if (inner.includes(`${THUMB_DIR}/`) || inner.endsWith("/") || /\.library\.json$/i.test(inner)) continue;
            const at = inner.lastIndexOf("/"), part = at < 0 ? "" : inner.slice(0, at);
            parts.add(part);
            if (/(^|\/)\.keep$/.test(inner)) continue;
            const f = { key: o.key, name: inner.slice(at + 1), part, size: o.size, uploaded: o.uploaded, contentType: (o.httpMetadata && o.httpMetadata.contentType) || "", hasThumb: keys.has(thumbOf(o.key)) };
            files.push({ ...f, ...(await linksFor(f)) });
          }
          files.sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));
          return json({ prefix, parts: [...parts].sort((a, b) => a.localeCompare(b, undefined, { numeric: true })), files }, 200, request, env);
        }

        // A finished photo edit: over the original (key=), or as a copy (prefix= and name=).
        if (path.endsWith("/creative/save") && request.method === "PUT") {
          const type = (request.headers.get("content-type") || "").split(";")[0].trim();
          if (!/^image\/(jpeg|png|webp)$/.test(type)) return json({ error: "Only a JPEG, PNG or WebP can be saved here." }, 400, request, env);
          const size = Number(request.headers.get("content-length") || 0);
          if (!size) return json({ error: "That photo came through empty." }, 400, request, env);
          if (size > 95 * 1024 * 1024) return json({ error: "That photo is too big to save." }, 413, request, env);
          let key = url.searchParams.get("key") || "";
          if (key) {
            if (!key.startsWith(root) || key.includes(`/${THUMB_DIR}/`) || !PREVIEWABLE.test(key)) return json({ error: "Not a photo in the Library." }, 400, request, env);
            if (!(await env.BUCKET.head(key))) return json({ error: "That photo is no longer in the Library." }, 404, request, env);
          } else {
            const prefix = archivePrefix(url.searchParams.get("prefix"));
            const name = String(url.searchParams.get("name") || "").replace(/[^a-zA-Z0-9._-]+/g, "-").replace(/-+/g, "-").slice(0, 120);
            if (prefix === root || !PREVIEWABLE.test(name)) return json({ error: "Choose a folder and a photo name." }, 400, request, env);
            key = `${prefix}${Date.now()}-${name}`;
          }
          const put = await env.BUCKET.put(key, request.body, { httpMetadata: { contentType: type } });
          if (!put) return json({ error: "Storage didn't take that photo. Please try again." }, 502, request, env);
          // The old small pictures describe the old photo, so they go.
          await env.BUCKET.delete([thumbOf(key), previewOf(key)]);
          return json({ ok: true, key, size: put.size, uploaded: put.uploaded, ...(await linksFor({ key, uploaded: put.uploaded, hasThumb: false })) }, 200, request, env);
        }

        // Every portal with its shoots and where each one has got to.
        if (path.endsWith("/creative/portals") && request.method === "GET") {
          const portals = await sbGet(env, "client_portals", "select=*&order=name.asc");
          const all = await sbGetAll(env, "videography_bookings", "or=(kind.is.null,kind.eq.booking)&archive_folder=not.is.null&select=*&order=id.asc");
          if (!portals || !all) return json({ error: "Couldn't read the portals." }, 502, request, env);
          const wanted = new Set(portals.flatMap((p) => portalFolders(p)));
          const inPortals = all.filter((b) => wanted.has(archivePrefix(b.archive_folder)));
          const bks = [], reqs = [];
          for (let i = 0; i < inPortals.length; i += 100) {
            const slice = inPortals.slice(i, i + 100);
            const due = await withInvoicesDue(env, slice);
            const rq = await sbGet(env, "videography_edit_requests", `booking_id=in.(${slice.map((b) => b.id).join(",")})&select=booking_id,status,stripe_session_id`);
            if (!due || !rq) return json({ error: "Couldn't read the shoots." }, 502, request, env);
            bks.push(...due); reqs.push(...rq);
          }
          const asked = new Set(reqs.filter((r) => r.status !== "pending" || !r.stripe_session_id).map((r) => r.booking_id));
          const out = portals.map((p) => {
            const told = new Set((p.notified_folders || []).map((f) => archivePrefix(f)));
            const rows = portalFolders(p).map((prefix) => {
              const mine = bks.filter((b) => archivePrefix(b.archive_folder) === prefix);
              const bk = mine.find((b) => shootDoneForPortal(b)) || mine[0];
              const showing = !mine.length || mine.some((b) => shootDoneForPortal(b));
              const ready = bk && (bk.delivery_method === "portal" ? !!bk.portal_ready_at : ["sent", "delivered"].includes(bk.stage));
              const name = prefix.slice(0, -1).split("/").pop();
              return {
                prefix, title: bk ? portalShootDetails(bk).title : name,
                status: showing ? "Showing" : ready ? "Waiting for payment" : "Not ready yet",
                emailedAt: (bk && bk.gallery_sent_at) || "", told: told.has(prefix),
                edits: bk && bk.delivery_method === "portal" && (isSettled(bk) || bk.released_unpaid_at) ? portalEditWindow(bk, asked).stage : "",
              };
            });
            return { id: p.id, name: p.name, first_name: p.first_name || "", enabled: !!p.enabled, notify_email: p.notify_email || "", token: p.token, locked_until: p.locked_until || null, shoots_added_at: p.shoots_added_at || null,
              type: p.smm_client_id ? "Social media" : /new.?starter/i.test(p.name || "") ? "New starters" : "Client", folders: portalFolders(p), rows };
          });
          return json({ portals: out }, 200, request, env);
        }

        // View as client: two hours inside the portal, without the passcode and
        // without counting as the client opening it.
        if (path.endsWith("/creative/portal-view") && request.method === "POST") {
          const b = await request.json().catch(() => ({}));
          const rows = await sbGet(env, "client_portals", `id=eq.${encodeURIComponent(String((b && b.id) || ""))}&select=id,enabled,token,passcode&limit=1`);
          const p = rows && rows[0];
          if (!p) return json({ error: "That portal isn't there any more." }, 404, request, env);
          if (!p.enabled) return json({ error: "This portal is turned off. Turn it on to view it." }, 403, request, env);
          const expires = Date.now() + 2 * 60 * 60 * 1000;
          const sig = await portalSig(env, p.token, p.passcode, expires);
          if (!sig) return json({ error: "The portal isn't configured on the Worker." }, 503, request, env);
          return json({ session: `${p.token}.${expires}.${sig}`, expires, token: p.token }, 200, request, env);
        }
      }

      // ---- Put one thumbnail (admins) ----
      // Deliberately narrow: only into a .thumbs folder, only small, so this is
      // not a general "write anything anywhere" door.
      if (path.endsWith("/thumb") && request.method === "PUT") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const key = url.searchParams.get("key") || "";
        if (!key.startsWith(PART_PREFIX + "/") || !key.includes(`/${THUMB_DIR}/`) || !key.endsWith(".jpg")) {
          return json({ error: "Not a thumbnail." }, 400, request, env);
        }
        const size = Number(request.headers.get("content-length") || 0);
        if (size > 2 * 1024 * 1024) return json({ error: "Too big for a thumbnail." }, 413, request, env);
        await env.BUCKET.put(key, request.body, { httpMetadata: { contentType: "image/jpeg" } });
        return json({ ok: true, key }, 200, request, env);
      }

      // ---- Make a folder (admins) ----
      // R2 has no folders, only key prefixes - so an empty one needs a marker to
      // exist at all. Zero bytes, and the listing hides it.
      if (path.endsWith("/folder") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const prefix = archivePrefix((b && b.prefix) || "");
        const name = String((b && b.name) || "").replace(/[\\/:*?"<>|]+/g, " ").replace(/\s+/g, " ").trim().slice(0, 80);
        if (!name) return json({ error: "Give the folder a name." }, 400, request, env);
        const key = `${prefix}${name}/.keep`;
        await env.BUCKET.put(key, new Uint8Array(0));
        return json({ ok: true, prefix: `${prefix}${name}/` }, 200, request, env);
      }

      if (path.endsWith("/list") && request.method === "GET") {
        const bookingId = (url.searchParams.get("bookingId") || "").replace(/[^a-zA-Z0-9_-]/g, "");
        const prefix = `${PART_PREFIX}/${bookingId}/`;
        const listed = await env.BUCKET.list({ prefix });
        return json(
          {
            files: listed.objects.map((o) => ({
              key: o.key,
              size: o.size,
              uploaded: o.uploaded,
            })),
          },
          200,
          request,
          env
        );
      }

      // ---- Delete an object ----
      if (path.endsWith("/object") && request.method === "DELETE") {
        // Only the team: every caller is an admin page, and this removes the only copy.
        const deleter = await getUser(request, env);
        if (!deleter || !isAdminEmail(deleter)) return json({ error: "Admins only." }, 403, request, env);
        const key = url.searchParams.get("key");
        if (!key) return json({ error: "Missing key" }, 400, request, env);
        await env.BUCKET.delete(key);
        return json({ ok: true }, 200, request, env);
      }

      // ---- Download / preview an object ----
      // ---- A photo at preview size (signed link, same proof as /download) ----
      // Made the first time anyone looks and kept beside the thumbnails, so each
      // photo is resized once. If it can't be made, this hands over the original:
      // the same picture, only slower, and the log says why.
      if (path.endsWith("/preview") && request.method === "GET") {
        const key = url.searchParams.get("key") || "";
        if (!PREVIEWABLE.test(key) || key.includes(`/${THUMB_DIR}/`)) return json({ error: "Not a photo." }, 400, request, env);
        if (!(await mediaSigValid(env, key, url.searchParams.get("exp"), url.searchParams.get("sig")))) return json({ error: "Link expired." }, 403, request, env);
        const at = key.lastIndexOf("/");
        const previewKey = `${key.slice(0, at)}/${THUMB_DIR}/${key.slice(at + 1)}.preview.jpg`;
        // size=thumb: the small picture, kept where the Library keeps its own.
        const small = url.searchParams.get("size") === "thumb";
        const outKey = small ? `${key.slice(0, at)}/${THUMB_DIR}/${key.slice(at + 1)}.jpg` : previewKey;
        const headers = new Headers(corsHeaders(request, env));
        headers.set("Content-Type", "image/jpeg");
        headers.set("Cache-Control", "private, max-age=86400");
        const kept = await env.BUCKET.get(outKey);
        if (kept) return new Response(kept.body, { headers });
        const original = () => Response.redirect(url.href.replace("/preview?", "/download?").replace("&size=thumb", ""), 302);
        // A small picture is made from the preview when there is one: a fraction of the size to read.
        const obj = (small && (await env.BUCKET.get(previewKey))) || (await env.BUCKET.get(key));
        if (!obj) return json({ error: "Not found" }, 404, request, env);
        if (obj.size > PREVIEW_SOURCE_LIMIT) { console.error("[preview] too big to resize", key, obj.size); return original(); }
        try {
          const max = small ? THUMB_MADE_MAX : PREVIEW_MAX;
          const made = await env.IMAGES.input(obj.body)
            .transform({ width: max, height: max, fit: "scale-down" })
            .output({ format: "image/jpeg", quality: small ? THUMB_MADE_QUALITY : PREVIEW_QUALITY });
          const bytes = await made.response().arrayBuffer();
          await env.BUCKET.put(outKey, bytes, { httpMetadata: { contentType: "image/jpeg" } });
          return new Response(bytes, { headers });
        } catch (err) {
          console.error("[preview] couldn't resize", key, String(err));
          return original();
        }
      }

      if (path.endsWith("/download") && request.method === "GET") {
        const key = url.searchParams.get("key");
        if (!key) return json({ error: "Missing key" }, 400, request, env);
        const signed = await mediaSigValid(env, key, url.searchParams.get("exp"), url.searchParams.get("sig"));
        if (!signed) {
          const user = await getUser(request, env);
          if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        }
        // A browser plays a video by asking for pieces of it (Range). Without
        // answering those, a two-hour file has to arrive whole before it plays
        // and can never be scrubbed - so the range is passed through to R2 and
        // answered with a 206.
        const rangeHeader = request.headers.get("Range") || "";
        const m = /^bytes=(\d*)-(\d*)$/.exec(rangeHeader.trim());
        let range;
        if (m) {
          if (m[1] === "" && m[2] !== "") range = { suffix: Number(m[2]) };
          else if (m[1] !== "") range = { offset: Number(m[1]), ...(m[2] !== "" ? { length: Number(m[2]) - Number(m[1]) + 1 } : {}) };
        }
        const obj = await env.BUCKET.get(key, range ? { range } : undefined);
        if (!obj) return json({ error: "Not found" }, 404, request, env);
        const headers = new Headers(corsHeaders(request, env));
        obj.writeHttpMetadata(headers);
        headers.set("etag", obj.httpEtag);
        headers.set("accept-ranges", "bytes");
        const name = decodeURIComponent(key.split("/").pop() || "file");
        const asFile = url.searchParams.get("dl") === "1";
        headers.set("Content-Disposition", `${asFile ? "attachment" : "inline"}; filename="${name.replace(/"/g, "")}"`);
        // A signed link always means the same file, so the browser can keep it (7 Nov).
        if (signed && !asFile) headers.set("Cache-Control", "private, max-age=21600");
        if (obj.range && typeof obj.range.offset === "number" && obj.size) {
          const start = obj.range.offset;
          const end = start + (obj.range.length || obj.size - start) - 1;
          headers.set("content-range", `bytes ${start}-${end}/${obj.size}`);
          headers.set("content-length", String(end - start + 1));
          return new Response(obj.body, { status: 206, headers });
        }
        headers.set("content-length", String(obj.size));
        return new Response(obj.body, { headers });
      }

      // ============================================================
      // Booking correspondence + documents (member portal + admin)
      // ============================================================

      // ---- Admin: post a manual message to a booking (optionally email it) ----
      if (path.endsWith("/booking/message") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const bookingId = b && b.booking_id;
        const source = b && b.source === "smm" ? "smm" : "videography";
        const bodyText = b && b.body;
        if (!bookingId || !bodyText) return json({ error: "Missing booking or message." }, 400, request, env);
        const bk = await lookupBooking(env, source, bookingId);
        if (!bk) return json({ error: "Booking not found." }, 404, request, env);
        // An email is logged on the thread only once Microsoft has taken it
        // (Dani, 5 Nov 2026): a failed send used to be logged as sent and
        // reported ok, so a proposal could vanish with nobody told.
        const logIt = () => logBookingMessage(env, {
          booking_id: bookingId, booking_source: source,
          account_user_id: bk.account_user_id, client_email: bk.email,
          channel: b.notify ? "email" : "note",
          kind: b.kind === "audit" ? "audit" : "manual",
          subject: b.subject || null,
          body: bodyText, is_automated: b.kind === "audit", created_by: user.email || "admin",
        });
        if (!(b.notify && bk.email)) await logIt();

        // Anyone @-tagged in an internal note gets told, or the tag is decoration.
        if (!b.notify && Array.isArray(b.mentions) && b.mentions.length) {
          const escapeHtmlW = (v) => String(v ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
          const known = new Set(((await sbGet(env, "admins", "select=email")) || []).map((r) => String(r.email || "").toLowerCase()));
          const to = [...new Set(b.mentions.map((m) => String(m || "").toLowerCase()))]
            .filter((m) => known.has(m) && m !== String(user.email || "").toLowerCase());
          for (const addr of to) {
            await sendEmail(env, {
              to: addr,
              subject: `${user.email || "Someone"} tagged you on ${bk.client_name || "a booking"}`,
              html: await wrapInBrandedBase(env, `<div style="${EM_WRAP}">
                <p style="${EM_P}">${escapeHtmlW(user.email || "A colleague")} tagged you in a note on <strong>${escapeHtmlW(bk.client_name || "a booking")}</strong>.</p>
                <p style="${EM_QUOTE}"><span style="${EM_QUOTE_TEXT}">${escapeHtmlW(bodyText)}</span></p>
                <p style="${EM_SMALL}">Open the booking in the admin centre to reply.</p>
              </div>`),
            });
          }
        }
        if (b.notify && bk.email) {
          const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
          // Attach a booking document to the email when one was sent with the message.
          let attachments;
          if (b.document_id) {
            try {
              const drows = await sbGet(env, "booking_documents", `id=eq.${encodeURIComponent(b.document_id)}&select=r2_key,file_name,content_type`);
              const d = drows && drows[0];
              if (d && d.r2_key) {
                const obj = await env.BUCKET.get(d.r2_key);
                if (obj) { const buf = await obj.arrayBuffer(); attachments = [{ filename: d.file_name || "attachment", content: bufToBase64(buf), contentType: d.content_type || "application/octet-stream" }]; }
              }
            } catch (_) {}
            if (!attachments) return json({ error: "Couldn't attach the file, so nothing was sent. Try again, or attach it from your computer." }, 502, request, env);
          }
          // Whatever happens is recorded: the email on the thread when it went,
          // a note saying it didn't when it failed, and the send in the email log.
          const settle = async (sent, subject) => {
            try { await logEmailEvent(env, { email: bk.email, event: sent && sent.ok ? "sent" : "failed", provider: "m365", subject, detail: sent && sent.ok ? null : String((sent && sent.error) || "Microsoft 365 didn't accept it").slice(0, 300) }); } catch (_) {}
            if (sent && sent.ok) { await logIt(); return json({ ok: true }, 200, request, env); }
            const why = String((sent && sent.error) || "Microsoft 365 didn't accept it").slice(0, 200);
            try { await logBookingMessage(env, { booking_id: bookingId, booking_source: source, account_user_id: bk.account_user_id, client_email: bk.email, channel: "note", kind: "manual", subject: "Email not sent", body: `${subject} to ${bk.email} didn't send: ${why}`, is_automated: true, created_by: "system" }); } catch (_) {}
            return json({ error: `The email didn't send: ${why}` }, 502, request, env);
          };
          // SMM correspondence sends from the SMM manager's mailbox when one is
          // configured (SMM_MAIL_SENDER — Danielle's for now, Abby's later), so
          // replies land in her inbox; otherwise falls back to the TMKE mailbox.
          const smmFrom = source === "smm" ? env.SMM_MAIL_SENDER : null;
          const smmFromName = source === "smm" ? (env.SMM_MAIL_FROM_NAME || "TMKE Social Media") : null;
          // A plain email, written by a person, with a short TMKE footer instead of
          // the branded template (Danielle, 5 Nov 2026): proposals, chases and
          // anything else written from a social media client's file.
          if (b.plain) {
            const sign = String(b.sign_as || "").trim().slice(0, 80);
            const paras = String(bodyText).split(/\n{2,}/).map((p) => `<p style="margin:0 0 14px;">${esc(p).replace(/\n/g, "<br>")}</p>`).join("");
            const html = `<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.55;color:#2b2226;max-width:640px;">${paras}
              <p style="margin:22px 0 0;padding-top:12px;border-top:1px solid #e2d9d4;font-size:13px;line-height:1.5;color:#7e6765;">${sign ? `<strong style="color:#2b2226;font-weight:600;">${esc(sign)}</strong><br>` : ""}The Marketing Experts<br><a href="mailto:hello@tmke.co.uk" style="color:#371e28;">hello@tmke.co.uk</a> &middot; <a href="https://tmke.co.uk" style="color:#371e28;">tmke.co.uk</a></p></div>`;
            const subj = b.subject || "A message from The Marketing Experts";
            let sent; try { sent = await sendEmail(env, { to: bk.email, subject: subj, html, attachments, from: smmFrom || undefined, fromName: smmFrom ? smmFromName : undefined }); } catch (e) { sent = { ok: false, error: e && e.message }; }
            return settle(sent, subj);
          }
          const subj = b.subject || `A message about your ${bk.service || "booking"}`;
          let sent;
          try {
            sent = await sendEmail(env, {
              to: bk.email, subject: subj,
              html: await wrapInBrandedBase(env, `
                <p style="${EM_P}">Hi ${esc(bk.name || "")},</p>
                <div style="font-size:12px;line-height:1.6;color:#40353a;white-space:pre-wrap;margin:0 0 14px;">${esc(bodyText)}</div>
                ${attachments ? `<p style="${EM_P}">📎 A document is attached to this email.</p>` : ""}
                <p style="${EM_P}">You can view this and manage your booking in your TMKE workspace.</p>`),
              attachments,
              from: smmFrom || undefined, fromName: smmFrom ? smmFromName : undefined,
            });
          } catch (e) { sent = { ok: false, error: e && e.message }; }
          return settle(sent, subj);
        }
        return json({ ok: true }, 200, request, env);
      }

      /* ---- Member: a question about one of their bookings ----
         "Ask about this booking" used to send members to the general contact
         page. Now it's a message on the booking itself (Danielle, 7 Oct 2026):
         it lands in the booking's thread in the admin centre, Jack and Danielle
         are emailed, and both get a notification. The booking must be theirs. */
      if (path.endsWith("/booking/ask") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in first." }, 401, request, env);
        const b = await request.json().catch(() => ({}));
        const source = b && b.source === "smm" ? "smm" : "videography";
        const bookingId = String((b && b.booking_id) || "");
        const bodyText = String((b && b.body) || "").trim().slice(0, 5000);
        if (!bookingId) return json({ error: "Which booking is this about?" }, 400, request, env);
        if (!bodyText) return json({ error: "Write your question first." }, 400, request, env);
        if (!(await memberBookingIds(env, user)).includes(bookingId)) return json({ error: "We couldn't find that booking on your account." }, 404, request, env);
        const bk = await lookupBooking(env, source, bookingId);
        if (!bk) return json({ error: "We couldn't find that booking on your account." }, 404, request, env);
        let when = "";
        if (source === "videography") {
          const r = (await sbGet(env, "videography_bookings", `id=eq.${encodeURIComponent(bookingId)}&select=shoot_date,kind`)) || [];
          if (r[0] && r[0].shoot_date) {
            const t = r[0].kind === "booking" ? new Date(`${String(r[0].shoot_date).slice(0, 19)}`) : new Date(r[0].shoot_date);
            if (!isNaN(t)) when = t.toLocaleDateString("en-GB", { weekday: "short", day: "numeric", month: "short", timeZone: r[0].kind === "booking" ? "UTC" : "Europe/London" });
          }
        }
        const email = String(user.email || "").toLowerCase();
        const who = bk.name || email;
        const what = [bk.service || "booking", when].filter(Boolean).join(", ");
        const subject = `Question about ${what} - ${who}`;
        await logBookingMessage(env, {
          booking_id: bookingId, booking_source: source,
          account_user_id: user.id, client_email: email,
          direction: "inbound", channel: "hub", kind: "manual",
          subject, body: bodyText, is_automated: false, created_by: email,
        });
        const escQ = (v) => String(v ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
        const site = (env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "");
        const to = source === "smm"
          ? [smmNewBusiness(env), env.ACCOUNTS_NOTIFY || "danielle@tmke.co.uk"]
          : [env.JACK_NOTIFY || env.JACK_UPN, env.ACCOUNTS_NOTIFY || "danielle@tmke.co.uk"];
        for (const addr of [...new Set(to.filter(Boolean).map((x) => String(x).toLowerCase()))]) {
          try {
            await sendEmail(env, {
              to: addr, subject,
              html: `<div style="${EM_WRAP}">
                <p><strong>${escQ(who)}</strong> asked about their ${escQ(what)}:</p>
                <blockquote style="margin:14px 0;padding:10px 14px;border-left:3px solid #371e28;color:#3a3a3a">${escQ(bodyText).replace(/\n/g, "<br>")}</blockquote>
                <p>Reply to <a href="mailto:${escQ(email)}">${escQ(email)}</a>, or answer in the booking's thread: <a href="${site}/admin/${source === "smm" ? "social" : "videography"}">open the admin centre</a>.</p>
              </div>`,
            });
          } catch (_) {}
        }
        try {
          await notifyAdmins(env, {
            area: source === "smm" ? "social" : "videography", event: "booking_question",
            title: `${who} asked about their ${bk.service || "booking"}`,
            body: bodyText.slice(0, 160),
            href: source === "smm" ? "/admin/social" : "/admin/videography",
            meta: { booking_id: bookingId, source },
          });
        } catch (_) {}
        return json({ ok: true }, 200, request, env);
      }

      // ---- Admin: pin / unpin a thread note ----
      if (path.endsWith("/booking/message/pin") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = b && b.id;
        if (!id) return json({ error: "Missing id" }, 400, request, env);
        await fetch(`${env.SUPABASE_URL}/rest/v1/booking_messages?id=eq.${encodeURIComponent(id)}`, {
          method: "PATCH",
          headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=minimal" },
          body: JSON.stringify({ is_pinned: !!(b && b.pinned) }),
        });
        return json({ ok: true }, 200, request, env);
      }

      // ---- Admin: delete a thread note / message ----
      // A note belongs to whoever wrote it. Being an admin gets you into the
      // thread; it does not entitle you to rewrite or remove a colleague's note.
      // Checked here rather than by hiding buttons - the endpoint is the lock,
      // the UI is only the sign on the door.
      if (path.endsWith("/booking/message") && (request.method === "DELETE" || request.method === "PATCH")) {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const body = request.method === "PATCH" ? await request.json().catch(() => ({})) : {};
        const id = (url.searchParams.get("id") || body.id || "").trim();
        if (!id) return json({ error: "Missing id" }, 400, request, env);

        const rows = await sbGet(env, "booking_messages", `id=eq.${encodeURIComponent(id)}&select=id,created_by,channel`);
        const msg = rows && rows[0];
        if (!msg) return json({ error: "Not found." }, 404, request, env);

        const mine = String(msg.created_by || "").toLowerCase() === String(user.email || "").toLowerCase();
        if (!mine) return json({ error: "You can only edit or delete your own notes." }, 403, request, env);
        // Only notes. An emailed message is a record of something that was
        // actually sent, and editing it would make the thread a lie.
        if (msg.channel !== "note") return json({ error: "Only notes can be edited or deleted." }, 422, request, env);

        if (request.method === "DELETE") {
          await fetch(`${env.SUPABASE_URL}/rest/v1/booking_messages?id=eq.${encodeURIComponent(id)}`, {
            method: "DELETE", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}` },
          });
          return json({ ok: true }, 200, request, env);
        }

        const text = String(body.body || "").trim();
        if (!text) return json({ error: "A note can't be empty." }, 400, request, env);
        const res = await sbPatch(env, "booking_messages", `id=eq.${encodeURIComponent(id)}`, { body: text, edited_at: new Date().toISOString() });
        if (res && !res.ok) {
          const detail = await res.text().catch(() => "");
          console.error("note edit failed", res.status, detail);
          // The edited_at column not existing is much the likeliest cause, and
          // the raw Postgres message doesn't say what to do about it.
          // Admin-only endpoint, so the real reason is safe to show - and a
          // bare "couldn't save" leaves nothing to act on.
          return json({ error: /edited_at/i.test(detail)
            ? "Needs a one-off database step: run supabase/smm_manager_and_interbrand.sql."
            : `Couldn't save that edit (${res.status}). ${String(detail).slice(0, 200)}` }, 502, request, env);
        }
        return json({ ok: true }, 200, request, env);
      }

      // ---- Admin: team access (who can use the admin centre) -----------------
      // Anyone on the @tmke.co.uk domain (or the named allowlist) is an admin via
      // SSO and never appears here. This manages the `admins` table — the way to
      // grant admin access to anyone OUTSIDE the domain, and to revoke it.

      // List everyone who's been granted admin access via the table.
      if (path.endsWith("/admin/team") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isOwner(user)) return json({ error: "Only the account owner can manage admin access." }, 403, request, env);
        // is_management is asked for separately: on a project where the column
        // has not been added yet, folding it into the main select would make
        // PostgREST reject the whole query and the team list would come back
        // empty rather than simply un-levelled.
        const rows = (await sbGet(env, "admins", "select=user_id,email,created_at&order=created_at.asc")) || [];
        const profs = (await sbGet(env, "admin_profiles", "select=user_id,full_name,role")) || [];
        let mgmt = null;
        try { mgmt = await sbGet(env, "admins", "select=user_id,is_management"); } catch (_) {}
        const mm = {}; for (const m of (mgmt || [])) mm[m.user_id] = !!m.is_management;
        const pm = {}; for (const p of profs) pm[p.user_id] = p;
        const admins = rows.map((r) => ({
          user_id: r.user_id, email: r.email, created_at: r.created_at,
          full_name: (pm[r.user_id] || {}).full_name || null, role: (pm[r.user_id] || {}).role || null,
          is_management: !!mm[r.user_id],
        }));
        return json({ ok: true, admins, self: user.id }, 200, request, env);
      }

      // Grant admin access: create their login if new, add them to `admins`,
      // and email them how to sign in.
      if (path.endsWith("/admin/team") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isOwner(user)) return json({ error: "Only the account owner can manage admin access." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const email = String((b && b.email) || "").trim().toLowerCase();
        const fullName = String((b && b.full_name) || "").trim();
        const role = String((b && b.role) || "").trim() || "Admin";
        if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return json({ error: "Enter a valid email address." }, 400, request, env);

        // Find or create the auth user.
        let u = await findUserByEmail(env, email);
        let tempPassword = null, created = false;
        if (!u) {
          tempPassword = genTempPassword();
          const cr = await fetch(`${env.SUPABASE_URL}/auth/v1/admin/users`, {
            method: "POST",
            headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json" },
            body: JSON.stringify({ email, password: tempPassword, email_confirm: true, user_metadata: { full_name: fullName || null } }),
          });
          if (cr.ok) { u = await cr.json(); created = true; }
          else {
            u = await findUserByEmail(env, email);
            if (!u) { const t = await cr.text().catch(() => ""); return json({ error: "Couldn't create that login. " + t.slice(0, 160) }, 502, request, env); }
            tempPassword = null; // it existed after all - don't claim a new password
          }
        }
        if (!u || !u.id) return json({ error: "Couldn't resolve that account." }, 502, request, env);

        // Grant admin (idempotent upsert on the primary key).
        await fetch(`${env.SUPABASE_URL}/rest/v1/admins?on_conflict=user_id`, {
          method: "POST",
          headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "resolution=merge-duplicates,return=minimal" },
          body: JSON.stringify({ user_id: u.id, email }),
        });
        // Seed their admin profile name/role for a brand-new login (don't clobber existing).
        if (created && fullName) {
          await fetch(`${env.SUPABASE_URL}/rest/v1/admin_profiles?on_conflict=user_id`, {
            method: "POST",
            headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "resolution=merge-duplicates,return=minimal" },
            body: JSON.stringify({ user_id: u.id, full_name: fullName, role }),
          });
        }

        // Email them how to get in (best-effort — never fail the grant on send).
        const loginUrl = "https://tmke.co.uk/admin/login";
        const who = fullName ? fullName.split(" ")[0] : "there";
        const credLine = tempPassword
          ? `<p style="${EM_P}">Sign in with your email and this temporary password:</p>
             <p style="margin:0 0 18px;"><span style="display:inline-block;font-family:ui-monospace,Menlo,monospace;font-size:12px;font-weight:700;letter-spacing:0.04em;background:#f4f2f1;border:1px solid #e4ded9;border-radius:8px;padding:9px 14px;color:#371e28;">${tempPassword}</span></p>
             <p style="${EM_P}">Please change it once you're in (Forgot password on the sign-in screen).</p>`
          : `<p style="${EM_P}">Sign in with your existing email and password.</p>`;
        const html = `<div style="${EM_WRAP}">
          <div style="font-size:24px;font-weight:800;letter-spacing:0.14em;color:#371e28;margin:0 0 18px;">TMKE</div>
          <p style="${EM_P}">Hi ${who},</p>
          <p style="${EM_P}">You've been given access to the <strong>TMKE admin centre</strong>.</p>
          ${credLine}
          <p style="margin:0 0 22px;"><a href="${loginUrl}" style="${EM_BTN}">Open the admin centre</a></p>
          <p style="${EM_SMALL}">If you weren't expecting this, you can ignore this email.</p>
        </div>`;
        try { await sendEmail(env, { to: email, subject: "Your TMKE admin access", html: await wrapInBrandedBase(env, html) }); } catch (_) {}

        return json({ ok: true, created, temp_password: tempPassword, admin: { user_id: u.id, email, full_name: fullName || null, role } }, 200, request, env);
      }

      // Revoke admin access (removes their `admins` row; the login itself stays).
      if (path.endsWith("/admin/team") && request.method === "DELETE") {
        const user = await getUser(request, env);
        if (!user || !isOwner(user)) return json({ error: "Only the account owner can manage admin access." }, 403, request, env);
        const userId = (url.searchParams.get("user_id") || "").trim();
        if (!userId) return json({ error: "Missing user_id" }, 400, request, env);
        if (userId === user.id) return json({ error: "You can't remove your own access." }, 400, request, env);
        await fetch(`${env.SUPABASE_URL}/rest/v1/admins?user_id=eq.${encodeURIComponent(userId)}`, {
          method: "DELETE", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}` },
        });
        return json({ ok: true }, 200, request, env);
      }

      // Rename an admin (their display name across the admin). Upserts admin_profiles.
      if (path.endsWith("/admin/team") && request.method === "PATCH") {
        const user = await getUser(request, env);
        if (!user || !isOwner(user)) return json({ error: "Only the account owner can manage admin access." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const userId = String((b && b.user_id) || "").trim();
        const fullName = String((b && b.full_name) || "").trim();
        if (!userId) return json({ error: "Missing user_id" }, 400, request, env);

        // Level change: its own shape, so the name is not required alongside.
        // Owner-gated like everything else on this endpoint — an admin cannot
        // promote themselves, which is the whole point of a second tier.
        if (typeof b.is_management === "boolean") {
          const r = await fetch(`${env.SUPABASE_URL}/rest/v1/admins?user_id=eq.${encodeURIComponent(userId)}`, {
            method: "PATCH",
            headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=minimal" },
            body: JSON.stringify({ is_management: b.is_management }),
          });
          if (!r.ok) {
            const detail = await r.text().catch(() => "");
            // The one failure worth naming: the column has not been added yet.
            const missing = /is_management/.test(detail) && /column/i.test(detail);
            return json({ error: missing
              ? "The management tier hasn't been set up on the database yet — run supabase/admins_management_flag.sql."
              : "Couldn't change that access level." }, 500, request, env);
          }
          return json({ ok: true }, 200, request, env);
        }

        if (!fullName) return json({ error: "Enter a name." }, 400, request, env);
        const row = { user_id: userId, full_name: fullName };
        if (b && typeof b.role === "string" && b.role.trim()) row.role = b.role.trim();
        await fetch(`${env.SUPABASE_URL}/rest/v1/admin_profiles?on_conflict=user_id`, {
          method: "POST",
          headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "resolution=merge-duplicates,return=minimal" },
          body: JSON.stringify(row),
        });
        return json({ ok: true }, 200, request, env);
      }

      // Reset an admin's password: set a fresh temporary password and email it.
      if (path.endsWith("/admin/team/reset") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isOwner(user)) return json({ error: "Only the account owner can manage admin access." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const userId = String((b && b.user_id) || "").trim();
        if (!userId) return json({ error: "Missing user_id" }, 400, request, env);
        const email = await sbAdminUserEmail(env, userId);
        if (!email) return json({ error: "Couldn't find that account." }, 404, request, env);
        const tempPassword = genTempPassword();
        const up = await fetch(`${env.SUPABASE_URL}/auth/v1/admin/users/${encodeURIComponent(userId)}`, {
          method: "PUT",
          headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json" },
          body: JSON.stringify({ password: tempPassword }),
        });
        if (!up.ok) { const t = await up.text().catch(() => ""); return json({ error: "Couldn't reset the password. " + t.slice(0, 160) }, 502, request, env); }

        let fullName = "";
        try { const p = await sbGet(env, "admin_profiles", `user_id=eq.${encodeURIComponent(userId)}&select=full_name`); fullName = (p && p[0] && p[0].full_name) || ""; } catch (_) {}
        const who = fullName ? fullName.split(" ")[0] : "there";
        const loginUrl = "https://tmke.co.uk/admin/login";
        const html = `<div style="${EM_WRAP}">
          <div style="font-size:24px;font-weight:800;letter-spacing:0.14em;color:#371e28;margin:0 0 18px;">TMKE</div>
          <p style="${EM_P}">Hi ${who},</p>
          <p style="${EM_P}">Your <strong>TMKE admin</strong> password has been reset. Your previous password no longer works.</p>
          <p style="${EM_P}">Sign in with your email and this temporary password:</p>
          <p style="margin:0 0 18px;"><span style="display:inline-block;font-family:ui-monospace,Menlo,monospace;font-size:12px;font-weight:700;letter-spacing:0.04em;background:#f4f2f1;border:1px solid #e4ded9;border-radius:8px;padding:9px 14px;color:#371e28;">${tempPassword}</span></p>
          <p style="${EM_P}">Please change it once you're in (Forgot password on the sign-in screen).</p>
          <p style="margin:0 0 22px;"><a href="${loginUrl}" style="${EM_BTN}">Open the admin centre</a></p>
          <p style="${EM_SMALL}">If you didn't expect this, contact hello@tmke.co.uk.</p>
        </div>`;
        try { await sendEmail(env, { to: email, subject: "Your TMKE admin password has been reset", html: await wrapInBrandedBase(env, html) }); } catch (_) {}

        return json({ ok: true, temp_password: tempPassword, email }, 200, request, env);
      }

      /* ---- A member's brand kit, pre-filled from our own records ------------
         A TEG agent opening the Studio for the first time should already be
         set up: their brand's colours, fonts, logo and website, and their own
         name, job title, phone and email. Asking an agent to go and find their
         brand guidelines is how a brand kit ends up half-filled and wrong, and
         a print asset with the wrong grey on it is money.

         The member cannot read contacts or agent_profiles themselves — nor
         should they — so the Worker does the lookup with the service key and
         hands back a kit. It never overwrites: the hub asks only when a field
         is empty, and anything the member has typed wins. Headshots are not
         here yet, and come from somewhere else. */
      if (path.endsWith("/member/brand-prefill") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in first." }, 401, request, env);
        // ?brand=… for an agent who works for two: the kit is per brand.
        const want = url.searchParams.get("brand");
        const { brand, brands, kit } = await brandKitFor(env, { userId: user.id, email: user.email, brand: want });
        /* Whether the kit they are actually using is still the supplied one.
           The brand kit page asks so it knows whether to offer the way back
           -- to somebody who kept their own when offered, or has changed it
           since. It is only ever an offer, so it does not read as a telling-off. */
        const mineRows = await sbGet(env, "member_brand_kits",
          `user_id=eq.${encodeURIComponent(user.id)}&select=kit&limit=1`);
        const mine = (mineRows && mineRows[0] && mineRows[0].kit) || null;
        return json({
          ok: true, brand, brands, kit,
          hasKit: !!(mine && Object.keys(mine).length),
          matches: kitIsBrands(mine, kit),
        }, 200, request, env);
      }

      /* Run whenever a member arrives: has their brand changed anything they
         haven't made their own? Cheap, and it self-heals — nothing to schedule
         and nothing to push. */

      /* ---- TEG headshots → our brand photos ----------------------------------
         Preview (a page of twenty at a time) and import (one person at a
         time, by email: the Worker looks their picture up at TEG itself and
         never fetches a link handed to it). Only background-free pictures,
         only TEG's own brands for now (Fine & Country later), only people
         in our CRM with a profile for that brand, and never over a photo
         someone at TMKE set by hand (Danielle, 30 Sep 2026). */
      if (path.endsWith("/teg/headshots/preview") || path.endsWith("/teg/headshots/import")) {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!env.TEG_API_SECRET) return json({ error: "No TEG_API_SECRET set on the Worker." }, 400, request, env);
        const photoPage = async (qs) => {
          const r = await fetch(`${TEG_API}/photoApi?${qs}`, { headers: { "x-api-secret": env.TEG_API_SECRET } });
          const o = await r.json().catch(() => null);
          if (!o) throw new Error(`photoApi answered ${r.status}`);
          return Array.isArray(o.data) ? o.data : [];
        };
        const emailOf = (r) => String(r.email || r.member_email || "").toLowerCase().trim();
        const urlOf = (r) => (typeof r.photo_url === "string" && /^https?:\/\//i.test(r.photo_url)) ? r.photo_url : null;
        // What would happen for one TEG record, and why.
        const plan = async (r) => {
          const email = emailOf(r), photo = urlOf(r);
          const name = r.full_name || r.name || [r.first_name, r.last_name].filter(Boolean).join(" ") || email || "—";
          const brand = brandFromEmailDomain(email);
          const base = { name, email, brand: brand || "Other", photo };
          if (!email) return { ...base, action: "skip", why: "No email on the TEG record" };
          if (brand === "Fine & Country") return { ...base, action: "skip", why: "Fine & Country, for later" };
          if (!photo) return { ...base, action: "skip", why: "No picture at TEG" };
          const sn = await sniffImage(photo);
          if (!sn.transparent) return { ...base, action: "skip", why: sn.transparent === false ? "Still has a background" : "Couldn't read the picture", format: sn.format };
          // Case-blind: TEG writes some addresses with capitals (SJ.Bannister@…).
          let cs = (await sbGet(env, "contacts", `email=ilike.${encodeURIComponent(email)}&select=id,first_name,last_name&limit=1`)) || [];
          let matchedBy = "";
          /* Dual agents: TEG may list them under their other brand's address,
             which is on that brand's profile here, not on the contact
             (Sean McMahon, Tony Poon, 1 Oct 2026). Then, last, an exact
             first-and-last name, but only when exactly one contact has it. */
          if (!cs.length) {
            const ap = (await sbGet(env, "agent_profiles", `email=ilike.${encodeURIComponent(email)}&select=contact_id&limit=1`)) || [];
            if (ap.length) { cs = [{ id: ap[0].contact_id }]; matchedBy = "their brand profile's email"; }
          }
          /* The same address at another TEG brand: tony.poon@thelettingexperts
             here, tony.poon@thepropertyexperts on our contact (1 Oct 2026). */
          if (!cs.length) {
            const local = email.split("@")[0];
            if (local) {
              const likes = (await sbGet(env, "contacts", `email=ilike.${encodeURIComponent(local.replace(/[%_]/g, (c) => "\\" + c))}%40*&select=id,email&limit=10`)) || [];
              const teg = likes.filter((c) => String(c.email || "").toLowerCase().split("@")[0] === local && brandFromEmailDomain(c.email) && brandFromEmailDomain(c.email) !== "Fine & Country");
              if (teg.length === 1) { cs = teg; matchedBy = `the same name at ${String(teg[0].email).split("@")[1]}`; }
            }
          }
          // Last: the name, exactly, when only one contact has it. TEG's photo
          // records carry a full name, not first and last separately.
          if (!cs.length) {
            const parts = String(r.first_name && r.last_name ? `${r.first_name} ${r.last_name}` : name).trim().split(/\s+/);
            if (parts.length >= 2) {
              const first = parts[0], last = parts.slice(1).join(" ");
              const byName = (await sbGet(env, "contacts", `first_name=ilike.${encodeURIComponent(first)}&last_name=ilike.${encodeURIComponent(last)}&select=id&limit=2`)) || [];
              if (byName.length === 1) { cs = byName; matchedBy = "name only, worth a check"; }
            }
          }
          if (!cs.length) return { ...base, action: "skip", why: "Not in our CRM" };
          base.matched_by = matchedBy;
          const profs = (await sbGet(env, "agent_profiles", `contact_id=eq.${encodeURIComponent(cs[0].id)}&select=id,brand,left_at,brand_photo_url,brand_photo_source`)) || [];
          const isBrand = (p) => String(p.brand || "").trim().toLowerCase() === String(brand || "").toLowerCase();
          const live = profs.filter((p) => !p.left_at && !/fine\s*&\s*country/i.test(p.brand || ""));
          const mine = live.filter(isBrand);
          /* TEG holds one photo per person, not one per brand. Dual agents
             (TPE and TLE) were left with an empty profile for their other
             brand, or skipped outright when their email's brand had no
             profile here (1 Oct 2026). So the photo also fills their other
             TEG-brand profiles that have none; it never replaces a photo
             already there on another brand. */
          const others = live.filter((p) => !isBrand(p) && !p.brand_photo_url);
          if (!mine.length && !others.length) return { ...base, contact_id: cs[0].id, action: "skip", why: live.length ? "Photo set on every profile already" : `No profile for ${brand || "that brand"} yet` };
          const mineFree = mine.filter((p) => !(p.brand_photo_url && p.brand_photo_source !== "teg"));
          const targets = [...mineFree, ...others];
          if (!targets.length) return { ...base, contact_id: cs[0].id, action: "skip", why: "Photo set by hand at TMKE", current: mine[0] && mine[0].brand_photo_url };
          const had = mineFree.some((p) => p.brand_photo_url && p.brand_photo_source === "teg");
          return { ...base, contact_id: cs[0].id, profiles: targets.map((p) => p.id), also: others.map((p) => p.brand), action: had && !others.length ? "update" : "import", format: sn.format, width: sn.width, height: sn.height };
        };
        try {
          if (path.endsWith("/preview") && request.method === "GET") {
            const skip = Math.max(0, parseInt(url.searchParams.get("skip") || "0", 10));
            const rows = await photoPage(new URLSearchParams({ limit: "20", skip: String(skip) }));
            const out = [];
            for (const r of rows) out.push(await plan(r));
            return json({ ok: true, rows: out, page: rows.length }, 200, request, env);
          }
          if (path.endsWith("/import") && request.method === "POST") {
            const b = await request.json().catch(() => ({}));
            const email = String(b.email || "").toLowerCase().trim();
            if (!email) return json({ error: "Whose headshot?" }, 400, request, env);
            const rec = (await photoPage(new URLSearchParams({ limit: "5", email }))).find((r) => emailOf(r) === email);
            if (!rec) return json({ error: "TEG has no picture for that email." }, 404, request, env);
            const p = await plan(rec);
            if (p.action === "skip") return json({ ok: false, skipped: p.why }, 200, request, env);
            // Our own copy, so print never depends on TEG's links staying up.
            const img = await fetch(p.photo);
            if (!img.ok) return json({ error: `Couldn't fetch the picture (${img.status}).` }, 502, request, env);
            const type = p.format === "webp" ? "image/webp" : "image/png";
            const slug = String(p.brand || "brand").toLowerCase().replace(/[^a-z0-9]+/g, "-");
            const key = `agent-photos/teg/${slug}/${email.replace(/[^a-z0-9@._-]/g, "")}.${p.format === "webp" ? "webp" : "png"}`;
            const up = await fetch(`${env.SUPABASE_URL}/storage/v1/object/pack-images/${key}`, {
              method: "POST",
              headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": type, "x-upsert": "true", "cache-control": "3600" },
              body: await img.arrayBuffer(),
            });
            if (!up.ok) return json({ error: `Couldn't store it: ${(await up.text().catch(() => "")).slice(0, 160)}` }, 502, request, env);
            const publicUrl = `${env.SUPABASE_URL}/storage/v1/object/public/pack-images/${key}?v=${Date.now()}`;
            const now = new Date().toISOString();
            for (const id of p.profiles || []) {
              await sbPatch(env, "agent_profiles", `id=eq.${encodeURIComponent(id)}`, { brand_photo_url: publicUrl, brand_photo_source: "teg", brand_photo_updated_at: now });
            }
            return json({ ok: true, url: publicUrl, profiles: (p.profiles || []).length, action: p.action }, 200, request, env);
          }
        } catch (e) {
          return json({ error: String((e && e.message) || e).slice(0, 200) }, 502, request, env);
        }
        return json({ error: "Not found" }, 404, request, env);
      }

      /* ---- Team Hub roster (CSV export) → our CRM ---------------------------
         Danielle exports the Team Hub as CSV and uploads it on the TEG page.
         The page sends only the columns this needs (no home address, no
         personal email or phone). Focus for now: The Property Experts,
         Prestige, The Letting Experts (1 Oct 2026). Rules she set:
           · date joined = Date Launched, else Date Compliant, never Signed
           · new starters: agents (Partners); support staff listed apart
           · leavers: flagged only, nothing changed
           · details fill blanks only, never overwrite what's been typed */
      /* ---- The Team Hub check (Danielle, 1 Oct; live from 19 Oct 2026) ----
         Their roster against our CRM: new joiners, leavers, and what has
         changed since the last check. Read live from the Team Hub (read-only;
         nothing there is ever written), or from a CSV export as a fallback.
         Nothing changes on our side either until an action is chosen. */
      if (path.endsWith("/teg/roster/live") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const out = await runRosterCheck(env, String(user.email || "").toLowerCase());
        return json(out, out.error ? 502 : 200, request, env);
      }
      if (path.endsWith("/teg/roster/changes/done") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const ids = (Array.isArray(b.ids) ? b.ids : []).map(String).filter((x) => /^[0-9a-f-]{36}$/i.test(x)).slice(0, 500);
        if (!ids.length) return json({ ok: true, done: 0 }, 200, request, env);
        const r = await sbPatch(env, "teg_roster_changes", `id=in.(${ids.join(",")})&done_at=is.null`, { done_at: new Date().toISOString(), done_by: String(user.email || "").toLowerCase() });
        return json({ ok: !!(r && r.ok), done: ids.length }, r && r.ok ? 200 : 500, request, env);
      }
      if (path.endsWith("/teg/roster/preview") || path.endsWith("/teg/roster/apply")) {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const ctx = await rosterContext(env);
        const { FOCUS, lc, digits, byId } = ctx;

        if (path.endsWith("/preview") && request.method === "POST") {
          const b = await request.json().catch(() => ({}));
          return json({ ok: true, ...rosterCompare(ctx, Array.isArray(b.rows) ? b.rows : [], rosterToday()) }, 200, request, env);
        }

        if (path.endsWith("/apply") && request.method === "POST") {
          const b = await request.json().catch(() => ({}));
          const done = [], failed = [];
          for (const a of (Array.isArray(b.actions) ? b.actions : []).slice(0, 25)) {
            try {
              if (a.kind === "add") {
                const f = a.fields || {}, brands = (a.brands || []).filter((x) => FOCUS.includes(x));
                const email = lc(a.email);
                if (!email || !brands.length) throw new Error("needs an email and a brand");
                // From the pop-out: first and last name as typed; else split the full name.
                const [first0, ...rest0] = String(a.name || "").trim().split(/\s+/);
                const first = String(a.first_name || "").trim() || first0 || "";
                const last = a.first_name != null ? String(a.last_name || "").trim() : rest0.join(" ");
                const type = /^The Letting Experts/.test(brands[0]) ? "Type: Lettings" : "Type: Estate-Agent";
                const cid = await sbRpc(env, "upsert_contact", { p_email: email, p_first_name: first || null, p_last_name: last || null, p_phone: f.phone || null, p_company: brands[0], p_source: "teg_team_hub", p_tags: [...crmTags(email, [], {}), type] });
                const contactId = Array.isArray(cid) ? cid[0] : cid;
                if (!contactId) throw new Error("couldn't create the contact");
                for (const brand of brands) {
                  await ensureAgentProfile(env, contactId, { first_name: first, last_name: last, email }, { brand, job_title: f.job_title, date_joined: f.date_joined, postcode: f.postcode, area: f.area, email: null, phone: null });
                }
                done.push(a.key);
                if (a.return_id) (b.created = b.created || {})[a.key] = contactId;
              } else if (a.kind === "add_profile") {
                const f = a.fields || {};
                const c = byId.get(a.contact_id);
                if (!c) throw new Error("contact not found");
                await ensureAgentProfile(env, a.contact_id, { first_name: c.first_name, last_name: c.last_name, email: c.email }, { brand: a.brand, job_title: f.job_title, date_joined: f.date_joined, postcode: f.postcode, area: f.area, email: lc(f.email) !== lc(c.email) ? f.email : null, phone: digits(f.phone) !== digits(c.phone) ? f.phone : null });
                done.push(a.key);
              } else if (a.kind === "fill") {
                // Re-read now and fill only what's still blank.
                const prof = (await sbGet(env, "agent_profiles", `id=eq.${encodeURIComponent(a.profile_id)}&select=*`))?.[0];
                if (!prof) throw new Error("profile not found");
                const patch = {};
                for (const [k, v] of Object.entries(a.fields || {})) {
                  if (!["job_title", "date_joined", "postcode", "area", "email", "phone"].includes(k) || !v) continue;
                  if (prof[k] == null || prof[k] === "") patch[k] = v;
                }
                if (Object.keys(patch).length) { const r = await sbPatch(env, "agent_profiles", `id=eq.${encodeURIComponent(a.profile_id)}`, patch); if (r && r.ok === false) throw new Error("couldn't save"); }
                done.push(a.key);
              } else if (a.kind === "link") {
                /* "It's them": a new joiner who is already here under another
                   email. Their Team Hub email goes on their brand profile, so
                   the next check matches them; a brand they lack is added. */
                const c = byId.get(a.contact_id);
                const email = lc(a.email);
                if (!c || !email) throw new Error("contact not found");
                const f = a.fields || {};
                for (const brand of (a.brands || []).filter((x) => FOCUS.includes(x))) {
                  const prof = ctx.profs.find((p) => p.contact_id === a.contact_id && lc(p.brand) === lc(brand) && !p.left_at);
                  if (!prof) await ensureAgentProfile(env, a.contact_id, { first_name: c.first_name, last_name: c.last_name, email: c.email }, { brand, job_title: f.job_title, date_joined: f.date_joined, postcode: f.postcode, area: f.area, email: email !== lc(c.email) ? email : null, phone: null });
                  else if (!prof.email && email !== lc(c.email)) { const r = await sbPatch(env, "agent_profiles", `id=eq.${encodeURIComponent(prof.id)}`, { email }); if (r && r.ok === false) throw new Error("couldn't save"); }
                }
                // And as their second email where that's free, so a profile
                // that already holds another address still leaves a match.
                if (email !== lc(c.email) && !lc(c.secondary_email)) await sbPatch(env, "contacts", `id=eq.${encodeURIComponent(a.contact_id)}`, { secondary_email: email });
                done.push(a.key);
              } else if (a.kind === "left") {
                // A leaver kept on file: their profile at that brand is marked
                // as left (the date they left, else today). The contact stays.
                if (!byId.get(a.contact_id)) throw new Error("contact not found");
                const when = /^\d{4}-\d{2}-\d{2}$/.test(a.left_at || "") ? a.left_at : rosterToday();
                const brandQ = a.brand ? `&brand=eq.${encodeURIComponent(a.brand)}` : "";
                const r = await sbPatch(env, "agent_profiles", `contact_id=eq.${encodeURIComponent(a.contact_id)}&left_at=is.null${brandQ}`, { left_at: when, left_brand: a.brand || null });
                if (r && r.ok === false) throw new Error("couldn't save");
                done.push(a.key);
              }
            } catch (e) { failed.push({ key: a.key, error: String((e && e.message) || e).slice(0, 160) }); }
          }
          return json({ ok: true, done, failed, created: b.created || {} }, 200, request, env);
        }
        return json({ error: "Not found" }, 404, request, env);
      }

      /* Our current TEG-brand agents with no brand photo yet, for chasing
         once the import has run. Fine & Country left out for now. */
      if (path.endsWith("/teg/missing-photos") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const profs = (await sbGetAll(env, "agent_profiles", "left_at=is.null&brand_photo_url=is.null&brand=not.is.null&select=contact_id,brand,email,job_title&order=brand.asc,contact_id.asc")) || [];
        const want = profs.filter((p) => !/fine\s*&\s*country/i.test(p.brand || ""));
        const ids = [...new Set(want.map((p) => p.contact_id))];
        const people = new Map();
        for (let i = 0; i < ids.length; i += 100) {
          ((await sbGet(env, "contacts", `id=in.(${ids.slice(i, i + 100).join(",")})&select=id,first_name,last_name,email`)) || []).forEach((c) => people.set(c.id, c));
        }
        const rows = want.map((p) => { const c = people.get(p.contact_id) || {}; return { name: [c.first_name, c.last_name].filter(Boolean).join(" ") || c.email || "—", email: String(c.email || p.email || "").toLowerCase(), brand: p.brand, job_title: p.job_title || "" }; })
          .sort((a, b) => a.brand.localeCompare(b.brand) || a.name.localeCompare(b.name));
        return json({ ok: true, rows }, 200, request, env);
      }


      /* Every brand's kit, for the admin studio's brand picker.

         Designing a Property Experts postcard in TMKE's colours and hoping is
         not designing. This hands the pane the same kit a member of that brand
         would open with -- same conversion, same shapes -- so what is on the
         canvas is what they will get. Staff only: it is every brand at once,
         which is not a thing any member should be able to ask for. */
      /* Find a screen in a mockup photo (Dani, 24 Oct): the Studio sends the
         photo and what to look for ("the laptop screen", "the book cover"),
         Claude returns its four corners in the photo's pixels. The Studio then
         snaps each side onto the nearest edge in the photo, so this only has
         to be close. Admin Studio only for now. */
      if (path.endsWith("/studio/find-screen") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!env.ANTHROPIC_API_KEY) return json({ error: "AI isn't configured." }, 503, request, env);
        const b = await request.json().catch(() => ({}));
        const m = /^data:(image\/(?:jpeg|png|webp));base64,(.+)$/.exec(String(b.image || ""));
        const W = Math.round(Number(b.width)), H = Math.round(Number(b.height));
        if (!m || !(W > 0 && H > 0)) return json({ error: "Send the photo as an image and its size." }, 400, request, env);
        const what = String(b.what || "the screen").slice(0, 120);
        const pt = { type: "object", properties: { x: { type: "number" }, y: { type: "number" } }, required: ["x", "y"], additionalProperties: false };
        const schema = {
          type: "object",
          properties: {
            found: { type: "boolean" },
            topLeft: pt, topRight: pt, bottomRight: pt, bottomLeft: pt,
            note: { type: "string" },
          },
          required: ["found", "topLeft", "topRight", "bottomRight", "bottomLeft", "note"],
          additionalProperties: false,
        };
        const prompt =
          `This photo is ${W} x ${H} pixels. Find ${what} in it: the flat surface a design will be placed onto in a mockup.\n\n` +
          "Give the four corners of that surface in this photo's pixel coordinates (x across from the left edge, y down from the top edge), " +
          "as they appear in the photo, in perspective.\n" +
          "- For a laptop, phone, tablet or monitor, it is the display area itself (the glass that shows the picture), inside the bezel, not the outer edge of the device.\n" +
          "- Where the display's corners are rounded, give the point where its straight edges would meet.\n" +
          "- If the surface runs off the edge of the photo, carry its edges on and give the corners where they would be, even if that is outside the photo (negative, or beyond the width or height).\n" +
          "- topLeft is the corner that is top left as the surface is meant to be read, and the rest follow clockwise.\n" +
          `If there is no ${what}, set found to false. In note, say in a few words what you found.`;
        let res, out;
        try {
          res = await aiFetch(env, "admin", {
            max_tokens: 16000,
            output_config: { effort: "high", format: { type: "json_schema", schema } },
            messages: [{ role: "user", content: [
              { type: "image", source: { type: "base64", media_type: m[1], data: m[2] } },
              { type: "text", text: prompt },
            ] }],
          });
          out = await res.json().catch(() => null);
        } catch (e) {
          return json({ error: "Couldn't reach Claude: " + (e.message || e) }, 502, request, env);
        }
        if (!res.ok || !out) {
          const why = (out && out.error && out.error.message) || "";
          if (/credit balance/i.test(why)) return json({ error: "The Claude API credit has run out. Top it up at console.anthropic.com, under Billing." }, 502, request, env);
          return json({ error: why || ("Claude said " + res.status) }, 502, request, env);
        }
        if (out.stop_reason === "refusal") return json({ error: "Claude declined to look at this photo." }, 422, request, env);
        const text = (out.content || []).filter((c) => c.type === "text").map((c) => c.text).join("");
        let r = null;
        try { r = JSON.parse(text); } catch (_) {}
        if (!r) return json({ error: "Claude's answer couldn't be read." }, 502, request, env);
        if (!r.found) return json({ ok: true, found: false, note: r.note || "" }, 200, request, env);
        const corners = [r.topLeft, r.topRight, r.bottomRight, r.bottomLeft].map((p) => ({ x: Number(p.x), y: Number(p.y) }));
        if (corners.some((p) => !isFinite(p.x) || !isFinite(p.y))) return json({ error: "Claude's corners weren't numbers." }, 502, request, env);
        return json({ ok: true, found: true, corners, note: r.note || "" }, 200, request, env);
      }

      /* Glare and dim for a screen in a mockup (Dani, 24 Oct): Claude sees the
         photo with the artwork in, bare, and the screen's corners, and
         suggests how much of each would make it sit in the photo's light. */
      if (path.endsWith("/studio/screen-light") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!env.ANTHROPIC_API_KEY) return json({ error: "AI isn't configured." }, 503, request, env);
        const b = await request.json().catch(() => ({}));
        const m = /^data:(image\/(?:jpeg|png|webp));base64,(.+)$/.exec(String(b.image || ""));
        const W = Math.round(Number(b.width)), H = Math.round(Number(b.height));
        const pts = Array.isArray(b.corners) ? b.corners.slice(0, 4).map((p) => `(${Math.round(Number(p.x))}, ${Math.round(Number(p.y))})`).join(", ") : "";
        if (!m || !(W > 0 && H > 0)) return json({ error: "Send the mockup as an image and its size." }, 400, request, env);
        const schema = {
          type: "object",
          properties: { glare: { type: "number" }, dim: { type: "number" }, note: { type: "string" } },
          required: ["glare", "dim", "note"],
          additionalProperties: false,
        };
        const prompt =
          `This is a ${W} x ${H} pixel mockup: a photo with a design placed onto a screen in it` +
          (pts ? `, at the corners ${pts} (top left, top right, bottom right, bottom left)` : "") + ".\n\n" +
          "The design was dropped in flat, at full brightness. Judge the light in the rest of the photo (how bright it is, where the light comes from, whether it's moody or bright, colour or black and white) " +
          "and say how much glare and how much dim the screen needs to look like a real screen in that room rather than pasted on.\n" +
          "- glare, 0 to 100: a soft white sheen from the top left of the screen. 0 is none; 20 is a subtle reflection; 50 is a strong one, as from a bright window.\n" +
          "- dim, 0 to 100: black laid over the design. 0 leaves it at full brightness; 20 suits a softly lit room; 40 or more only suits a dark or moody photo.\n" +
          "Most good mockups sit low on both. In note, say in one short sentence why.";
        let res, out;
        try {
          res = await aiFetch(env, "admin", {
            max_tokens: 16000,
            output_config: { effort: "medium", format: { type: "json_schema", schema } },
            messages: [{ role: "user", content: [
              { type: "image", source: { type: "base64", media_type: m[1], data: m[2] } },
              { type: "text", text: prompt },
            ] }],
          });
          out = await res.json().catch(() => null);
        } catch (e) {
          return json({ error: "Couldn't reach Claude: " + (e.message || e) }, 502, request, env);
        }
        if (!res.ok || !out) {
          const why = (out && out.error && out.error.message) || "";
          if (/credit balance/i.test(why)) return json({ error: "The Claude API credit has run out. Top it up at console.anthropic.com, under Billing." }, 502, request, env);
          return json({ error: why || ("Claude said " + res.status) }, 502, request, env);
        }
        if (out.stop_reason === "refusal") return json({ error: "Claude declined to look at this photo." }, 422, request, env);
        const text = (out.content || []).filter((c) => c.type === "text").map((c) => c.text).join("");
        let r = null;
        try { r = JSON.parse(text); } catch (_) {}
        if (!r) return json({ error: "Claude's answer couldn't be read." }, 502, request, env);
        const clamp = (v) => Math.max(0, Math.min(100, Math.round(Number(v) || 0)));
        return json({ ok: true, glare: clamp(r.glare), dim: clamp(r.dim), note: String(r.note || "").slice(0, 200) }, 200, request, env);
      }

      if (path.endsWith("/studio/brand-kits") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const rows = await sbGet(env, "brand_profiles", "select=*&order=brand") || [];
        const studioRow = rows.find((r) => r.brand === "__studio__") || null;
        const si = (studioRow && studioRow.stand_ins) || {};
        // Two we ship with the site, so the toggle has somebody to show
        // before anybody has uploaded anything. Both 1080x1350 cut-outs --
        // the same shape a real photograph arrives in.
        // New names, not the old files replaced: Cloudflare keeps a replaced
        // image for hours (Dani's new stand-ins, 16 Oct).
        const SI_DEFAULT = { female: "/images/stand-in-female-2.webp", male: "/images/stand-in-male-2.webp" };
        return json({
          ok: true,
          // The hub's own kit, under the name it is known by rather than the
          // reserved key the database files it under.
          studio: studioRow
            ? { brand: "The Marketing Experts (hub)", kit: brandHalf(studioRow, "The Marketing Experts") }
            : null,
          brands: rows
            .filter((r) => r.brand && r.brand !== "__studio__")
            .map((r) => {
              const host = kitBrandOf(r.brand);
              const kitRow = host === r.brand ? r : (rows.find((x) => x.brand === host) || r);
              return { brand: r.brand, kit: brandHalf(kitRow, r.brand) };
            }),
          standIns: {
            female: si.female || SI_DEFAULT.female,
            male: si.male || SI_DEFAULT.male,
            ghost: "/images/agent-photo-ghost.svg",
          },
        }, 200, request, env);
      }

      /* The two invented people the design studio lays templates out against.
         Not a member's photo and never served as one -- a real agent gets
         their own, or the ghost. Any signed-in member may read them: the
         studio needs them the moment it opens a template. */
      if (path.endsWith("/studio/stand-ins") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in first." }, 401, request, env);
        const rows = await sbGet(env, "brand_profiles", "brand=eq.__studio__&select=stand_ins&limit=1");
        const si = (rows && rows[0] && rows[0].stand_ins) || {};
        return json({
          ok: true,
          female: si.female || "/images/stand-in-female-2.webp",
          male: si.male || "/images/stand-in-male-2.webp",
          ghost: "/images/agent-photo-ghost.svg",
        }, 200, request, env);
      }

      if (path.endsWith("/member/brand-sync") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in first." }, 401, request, env);
        const out = await syncBrandKit(env, { userId: user.id, email: user.email });
        return json(out, 200, request, env);
      }

      /* They built their own kit before we had brand kits to give, and have
         said yes to taking their brand's. Their own is replaced — which is why
         it is only ever reached by somebody pressing a button that says so. */
      if (path.endsWith("/member/brand-adopt") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in first." }, 401, request, env);
        const b = await request.json().catch(() => ({}));
        const { brand, kit } = await brandKitFor(env, { userId: user.id, email: user.email, brand: b && b.brand });
        if (!brand || !kit) return json({ error: "You're not in a brand we hold a kit for." }, 400, request, env);

        if (b && b.decline) {
          /* Keeping their own. We still record a base — the one we offered —
             so the next brand change can be compared against something. They
             keep everything they have; only a field they later set BACK to
             the brand's value will follow it after that. */
          await sbPatch(env, "member_brand_kits", `user_id=eq.${encodeURIComponent(user.id)}`, {
            base: kit, base_brand: brand, synced_at: new Date().toISOString(),
          });
          return json({ ok: true, state: "kept-their-own", brand }, 200, request, env);
        }

        const next = Object.assign({}, kit, { updatedAt: Date.now() });
        await sbPost(env, "member_brand_kits", {
          user_id: user.id, kit: next, base: kit, base_brand: brand,
          synced_at: new Date().toISOString(), updated_at: new Date().toISOString(),
        }, "resolution=merge-duplicates,return=minimal");
        return json({ ok: true, state: "adopted", brand, kit: next }, 200, request, env);
      }

      /* ---- "I work for one of these brands" --------------------------------
         An agent on a personal address has no way to tell us who they are.
         This is that way — and it releases nothing: it files a request, and a
         person decides. The brands offered are only ones we hold a kit for,
         so nobody asks for something that doesn't exist. */
      if (path.endsWith("/member/brand-request") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in first." }, 401, request, env);
        const { brand } = await brandKitFor(env, { userId: user.id, email: user.email });
        const rows = await sbGet(env, "brand_access_requests",
          `user_id=eq.${encodeURIComponent(user.id)}&select=brand,status,created_at&order=created_at.desc&limit=1`);
        const bps = await sbGet(env, "brand_profiles", "select=brand&order=brand");
        const brands = (bps || [])
          .map((b) => b.brand)
          .filter((b) => b && b !== "__studio__");
        return json({
          ok: true,
          brand: brand || null,                     // already in a brand: nothing to ask
          request: (rows && rows[0]) || null,
          brands,
        }, 200, request, env);
      }

      if (path.endsWith("/member/brand-request") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in first." }, 401, request, env);
        const b = await request.json().catch(() => ({}));
        const brand = String((b && b.brand) || "").trim();
        if (!brand) return json({ error: "Pick a brand." }, 400, request, env);

        const known = await sbGet(env, "brand_profiles", `brand=eq.${encodeURIComponent(brand)}&select=brand&limit=1`);
        if (!known || !known.length) return json({ error: "We don't know that brand." }, 400, request, env);

        const already = await brandKitFor(env, { userId: user.id, email: user.email });
        if (already.brand) return json({ ok: true, alreadyIn: already.brand }, 200, request, env);

        const open = await sbGet(env, "brand_access_requests",
          `user_id=eq.${encodeURIComponent(user.id)}&status=eq.pending&select=id&limit=1`);
        if (open && open.length) return json({ ok: true, pending: true }, 200, request, env);

        const res = await sbPost(env, "brand_access_requests", {
          user_id: user.id,
          email: String(user.email || "").toLowerCase(),
          name: String((b && b.name) || (user.user_metadata && user.user_metadata.full_name) || "").trim() || null,
          brand,
          note: String((b && b.note) || "").slice(0, 500) || null,
        }, "return=minimal");
        if (!res.ok) {
          const msg = await res.text();
          return json({ error: msg.slice(0, 200) || "Could not send that." }, 500, request, env);
        }
        /* Raised 22 Sep: the only way to learn a request had arrived was to
           open the Brands page and look. Fine for one a month, useless during
           the TEG rollout when they arrive in a batch and somebody sits
           unbranded for a week. */
        const asked = String((b && b.name) || user.email || "").trim();
        try {
          await notifyAdmins(env, {
            area: "hub", event: "brand_request",
            title: `Brand kit requested — ${brand}`,
            body: `${asked} (${user.email}) says they work for ${brand}.`,
            href: "/admin/brands", key: `brand-req:${user.id}`,
            meta: { user_id: user.id, brand },
          });
        } catch (_) {}
        try {
          await sendEmail(env, {
            to: env.ACCOUNTS_NOTIFY || "danielle@tmke.co.uk",
            subject: `Brand kit requested — ${brand}`,
            html: `<div style="${EM_WRAP}"><p><strong>${esc(asked)}</strong> (${esc(user.email || "")}) has asked to be set up with <strong>${esc(brand)}</strong>.</p>
              <p><a href="${esc((env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, ""))}/admin/brands">Approve or decline it</a></p></div>`,
          });
        } catch (_) {}
        return json({ ok: true, pending: true }, 200, request, env);
      }

      /* Admin: the queue, with the contacts each request might BE. Matching on
         name within the brand they claim, because the whole point is that
         their sign-in email is not the one we hold. */
      if (path.endsWith("/admin/brand-requests") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const rows = await sbGet(env, "brand_access_requests",
          "status=eq.pending&select=*&order=created_at.asc") || [];

        const out = [];
        for (const r of rows) {
          let candidates = [];
          const name = String(r.name || "").trim();
          const last = name.split(/\s+/).filter(Boolean).pop();
          if (last && last.length > 2) {
            const hits = await sbGet(env, "contacts",
              `last_name=ilike.${encodeURIComponent(last)}&select=id,first_name,last_name,email,phone,user_id&limit=12`) || [];
            for (const c of hits) {
              const ap = await sbGet(env, "agent_profiles",
                `contact_id=eq.${encodeURIComponent(c.id)}&select=brand,job_title,area,left_at&limit=1`);
              const prof = (ap && ap[0]) || null;
              candidates.push({
                id: c.id,
                name: [c.first_name, c.last_name].filter(Boolean).join(" "),
                email: c.email,
                phone: c.phone || null,
                linked: !!c.user_id,
                brand: prof ? prof.brand : null,
                left: !!(prof && prof.left_at),
              });
            }
            // The ones in the brand they claim, first.
            candidates.sort((a, b) => (b.brand === r.brand) - (a.brand === r.brand));
          }
          out.push(Object.assign({}, r, { candidates }));
        }
        return json({ ok: true, requests: out }, 200, request, env);
      }

      if (path.endsWith("/admin/brand-requests/decide") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String((b && b.id) || "").trim();
        const decision = String((b && b.decision) || "").trim();   // approve | reject
        if (!id || !["approve", "reject"].includes(decision)) {
          return json({ error: "Missing request or decision." }, 400, request, env);
        }
        const rows = await sbGet(env, "brand_access_requests", `id=eq.${encodeURIComponent(id)}&select=*&limit=1`);
        const req = rows && rows[0];
        if (!req) return json({ error: "That request is gone." }, 404, request, env);

        if (decision === "reject") {
          await sbPatch(env, "brand_access_requests", `id=eq.${encodeURIComponent(id)}`, {
            status: "rejected", decided_at: new Date().toISOString(), decided_by: user.email || null,
          });
          return json({ ok: true }, 200, request, env);
        }

        /* Approving means two things: this account IS that contact, and that
           contact is in that brand. Binding the account to the contact we
           already hold is what makes their old details — their real work
           email, their phone, their area — theirs again. */
        let contactId = String((b && b.contact_id) || req.contact_id || "").trim() || null;
        if (!contactId) {
          const mine = await sbGet(env, "contacts", `email=eq.${encodeURIComponent(req.email)}&select=id&limit=1`);
          contactId = (mine && mine[0] && mine[0].id) || null;
        }
        if (!contactId) {
          const made = await sbPost(env, "contacts", {
            email: req.email, user_id: req.user_id, lifecycle: "member", source: "brand request",
          }, "return=representation");
          const body = await made.json().catch(() => null);
          contactId = body && body[0] && body[0].id;
        }
        if (!contactId) return json({ error: "Could not find or make a contact for them." }, 500, request, env);

        await sbPatch(env, "contacts", `id=eq.${encodeURIComponent(contactId)}`, { user_id: req.user_id });
        await sbPost(env, "agent_profiles", {
          contact_id: contactId,
          brand: req.brand,
          added_by: "brand request",
        }, "resolution=merge-duplicates,return=minimal");
        await mergeBrandKit(env, { userId: req.user_id, email: req.email });
        await sbPatch(env, "brand_access_requests", `id=eq.${encodeURIComponent(id)}`, {
          status: "approved", contact_id: contactId,
          decided_at: new Date().toISOString(), decided_by: user.email || null,
        });
        return json({ ok: true, contact_id: contactId }, 200, request, env);
      }

      /* Remove one of a person's brands. Only ever a brand they were added to
         by mistake — somebody who has LEFT a brand is marked left_at, which
         keeps the history and stops the access. Deleting is for "this was
         never true". */
      if (path.endsWith("/agent/profile/remove") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String((b && b.id) || "").trim();
        if (!id) return json({ error: "Missing profile id" }, 400, request, env);
        const rows = await sbGet(env, "agent_profiles", `id=eq.${encodeURIComponent(id)}&select=contact_id,is_primary`);
        const row = rows && rows[0];
        if (!row) return json({ error: "That brand is already gone." }, 404, request, env);
        await fetch(`${env.SUPABASE_URL}/rest/v1/agent_profiles?id=eq.${encodeURIComponent(id)}`, {
          method: "DELETE",
          headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}` },
        });
        // Somebody has to be primary, or their Studio has no kit to open in.
        // The card is told which, so it shows the right one straight away.
        let primary = null;
        if (row.is_primary) {
          const left = await sbGet(env, "agent_profiles",
            `contact_id=eq.${encodeURIComponent(row.contact_id)}&select=id&order=created_at.asc&limit=1`);
          if (left && left[0]) {
            await sbPatch(env, "agent_profiles", `id=eq.${encodeURIComponent(left[0].id)}`, { is_primary: true });
            primary = left[0].id;
          }
        }
        return json({ ok: true, primary }, 200, request, env);
      }

      // ---- Admin: internal-agent (TEG) profile on a contact -------------------
      // Reads/writes the agent_profiles row for a contact. On save, when the
      // contact is a new starter on Academy/Pro and has no code yet, generates
      // their personalised 100% single-use free-videography code.
      if (path.endsWith("/agent/profile") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const cid = (url.searchParams.get("contact_id") || "").trim();
        if (!cid) return json({ error: "Missing contact_id" }, 400, request, env);
        // A person can work for two brands, so this returns all their rows.
        // `profile` stays for callers that want one: the primary.
        const rows = await sbGet(env, "agent_profiles",
          `contact_id=eq.${encodeURIComponent(cid)}&select=*&order=is_primary.desc,created_at.asc`) || [];
        return json({
          ok: true,
          profile: rows.find((r) => r.is_primary) || rows[0] || null,
          profiles: rows,
        }, 200, request, env);
      }

      if (path.endsWith("/agent/profile") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const contactId = String((b && b.contact_id) || "").trim();
        if (!contactId) return json({ error: "Missing contact_id" }, 400, request, env);

        const cRows = await sbGet(env, "contacts", `id=eq.${encodeURIComponent(contactId)}&select=id,first_name,last_name,email`);
        const contact = cRows && cRows[0];
        if (!contact) return json({ error: "Contact not found." }, 404, request, env);

        await ensureAgentProfile(env, contactId, contact, {
          brand: (b && b.brand) || null,
          job_title: (b && b.job_title) || null,
          area: (b && b.area) || null,
          date_joined: (b && b.date_joined) || null,
          postcode: (b && b.postcode) || null,
          // Their number and address AT THIS BRAND — a dual agent often has
          // one of each, and the footer has to print the right one.
          email: (b && b.email) || null,
          phone: (b && b.phone) || null,
          // "" means clear it; absent means leave whatever is there.
          brand_photo_url: (b && typeof b.brand_photo_url === "string")
            ? (b.brand_photo_url.trim() || null) : undefined,
          is_new_starter: !!(b && b.is_new_starter),
          induction_month: (b && b.induction_month) || null,
          package: (b && b.package) || null,
          trainer_name: (b && b.trainer_name) || null,
          trainer_email: (b && b.trainer_email) || null,
        });

        /* Which brand their Studio opens in. Exactly one, so setting a new
           primary has to clear the old one first — the index would refuse a
           second, and the refusal would land as an unexplained save failure. */
        const wantPrimary = String((b && b.brand) || "").trim();
        if (b && b.make_primary && wantPrimary) {
          await sbPatch(env, "agent_profiles",
            `contact_id=eq.${encodeURIComponent(contactId)}&is_primary=is.true`, { is_primary: false });
          await sbPatch(env, "agent_profiles",
            `contact_id=eq.${encodeURIComponent(contactId)}&brand=eq.${encodeURIComponent(wantPrimary)}`, { is_primary: true });
        }

        const saved = await sbGet(env, "agent_profiles",
          `contact_id=eq.${encodeURIComponent(contactId)}&select=*&order=is_primary.desc,created_at.asc`) || [];
        return json({
          ok: true,
          profile: saved.find((r) => String(r.brand || "").trim() === wantPrimary) || saved[0] || null,
          profiles: saved,
        }, 200, request, env);
      }

      // ---- TEG new-starter sheet sync (manual "sync now" for testing) ---------
      if (path.endsWith("/agent/sync") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        try { await pinArchiveFolders(env); await runStarterPortalAdds(env); } catch (_) {}
        const summary = await syncAgentSheet(env);
        try { await newStarterEnsureBlocks(env); } catch (_) {}
        try { await runPortalFolderNotices(env); } catch (_) {}
        return json(summary, summary.ok ? 200 : 502, request, env);
      }

      // ---- Admin: invoicing settings (company/finance details) ---------------
      /* A social media client's own invoices, in their hub.

         Invoices are staff-only in the database and rightly so, so this hands
         back only the rows billed to THEIR account — matched through the
         smm_lead their member account is linked to, never through anything
         they can type. Each one carries what they can do with it: a signed
         card link while it is payable, and a signed PDF once it exists.

         The same /invoicing/pay page the emailed button uses, so there is one
         payment route rather than a second one to keep in step. */
      /* A client writing to their own social team.

         The same thread the admin side already writes to, so a reply lands in
         the conversation rather than in a separate inbox nobody opens. It
         reaches the account manager the lead names — hers, not the social
         inbox — and leaves a notification, because an email is a thing that
         can be missed and this one has a person waiting on it. */
      if (path.endsWith("/smm/message") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in." }, 401, request, env);
        const b = await request.json().catch(() => ({}));
        const bodyText = String((b && b.body) || "").trim();
        if (!bodyText) return json({ error: "Write a message first." }, 400, request, env);

        const email = String(user.email || "").toLowerCase();
        const leads = (await sbGet(env, "smm_leads",
          `or=(account_user_id.eq.${user.id},email.ilike.${encodeURIComponent(email)})&select=id,full_name,business,social_media_manager,client_status&order=created_at.desc`)) || [];
        const lead = leads.find((l) => l.client_status === "active") || leads[0];
        if (!lead) return json({ error: "We couldn't find your account." }, 404, request, env);

        const who = String((b && b.name) || lead.full_name || email).trim();
        const subject = `Message from ${who}${lead.business ? ` — ${lead.business}` : ""}`;
        await logBookingMessage(env, {
          booking_id: lead.id, booking_source: "smm",
          account_user_id: user.id, client_email: email,
          direction: "inbound", channel: "hub", kind: "manual",
          subject, body: bodyText, is_automated: false, created_by: email,
        });

        const manager = await smmManagerEmail(env, lead.social_media_manager);
        const to = manager || smmNewBusiness(env);
        if (to) {
          try {
            await sendEmail(env, {
              to, subject,
              html: `<div style="${EM_WRAP}">
                <p><strong>${esc(who)}</strong>${lead.business ? ` (${esc(lead.business)})` : ""} sent this from their hub:</p>
                <blockquote style="margin:14px 0;padding:10px 14px;border-left:3px solid #371e28;color:#3a3a3a">${esc(bodyText).replace(/\n/g, "<br>")}</blockquote>
                <p>${esc(b && b.phone ? "They gave " + b.phone + " as their number. " : "")}Reply to <a href="mailto:${esc(email)}">${esc(email)}</a>.</p>
              </div>`,
            });
          } catch (_) {}
        }
        try {
          await notifyAdmins(env, {
            area: "social", event: "smm_client_message",
            title: `Message from ${who}`,
            body: bodyText.slice(0, 160),
            href: "/admin/social", also: [manager],
            meta: { lead_id: lead.id },
          });
        } catch (_) {}
        return json({ ok: true }, 200, request, env);
      }

      if (path.endsWith("/smm/invoices") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in." }, 401, request, env);
        const email = String(user.email || "").toLowerCase();
        const leads = (await sbGet(env, "smm_leads",
          `or=(account_user_id.eq.${user.id},email.ilike.${encodeURIComponent(email)})&select=id,client_status,inter_brand_invoice&order=created_at.desc`)) || [];
        // Inter-brand cards are billed to another TEG brand, not the client:
        // their invoices aren't the client's to see.
        const ids = leads.filter((l) => !l.inter_brand_invoice).map((l) => l.id);
        if (!ids.length) return json({ ok: true, invoices: [] }, 200, request, env);

        const rows = (await sbGet(env, "invoices",
          `booking_id=in.(${ids.map((i) => `"${i}"`).join(",")})&booking_source=eq.smm&status=neq.draft&select=id,number,total_pence,status,issued_date,due_date,paid_date,pay_by_card&order=issued_date.desc`)) || [];

        const base = String(env.WORKER_PUBLIC_URL || url.origin).replace(/\/+$/, "");
        const out = [];
        for (const inv of rows) {
          // A void invoice is not theirs to see: it was cancelled, and showing
          // it only raises a question whose answer is "ignore that one".
          if (inv.status === "void") continue;
          let payUrl = null;
          if (inv.pay_by_card && inv.status !== "paid") {
            const t = await invoicePaySign(env, inv.id);
            if (t) payUrl = `${base}/invoicing/pay?t=${encodeURIComponent(t)}`;
          }
          out.push({
            id: inv.id, number: inv.number, total_pence: inv.total_pence,
            status: inv.status, issued_date: inv.issued_date, due_date: inv.due_date,
            paid_date: inv.paid_date, pay_url: payUrl,
          });
        }
        return json({ ok: true, invoices: out }, 200, request, env);
      }

      /* The PDF of one of their own invoices. Same renderer the admin uses;
         the check is that the invoice is billed to a lead their account owns,
         which is the only thing standing between a member and somebody else's
         bill. */
      if (path.endsWith("/smm/invoice-pdf") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in." }, 401, request, env);
        const id = (url.searchParams.get("id") || "").trim();
        if (!id) return json({ error: "Which invoice?" }, 400, request, env);
        const rows = await sbGet(env, "invoices", `id=eq.${encodeURIComponent(id)}&select=*`);
        const inv = rows && rows[0];
        if (!inv || inv.booking_source !== "smm") return json({ error: "Not found." }, 404, request, env);

        const email = String(user.email || "").toLowerCase();
        const mine = (await sbGet(env, "smm_leads",
          `or=(account_user_id.eq.${user.id},email.ilike.${encodeURIComponent(email)})&select=id,inter_brand_invoice`)) || [];
        if (!mine.some((l) => l.id === inv.booking_id && !l.inter_brand_invoice)) return json({ error: "Not found." }, 404, request, env);

        const key = `invoices/${inv.number || inv.id}.pdf`;
        let head = null;
        try { head = await env.BUCKET.head(key); } catch (_) {}
        if (!head) {
          const st = (await sbGet(env, "invoice_settings", "id=eq.1&select=*"))?.[0] || {};
          try {
            const pdf = await renderInvoicePdf(env, { ...st, template: inv.template || st.template }, inv);
            await env.BUCKET.put(key, pdf, { httpMetadata: { contentType: "application/pdf" } });
          } catch (err) { return json({ error: "Couldn't produce the PDF." }, 502, request, env); }
        }
        const exp = Date.now() + 60 * 60 * 1000;
        const sig = await mediaSig(env, key, exp);
        if (!sig) return json({ error: "Links aren't configured on the Worker." }, 503, request, env);
        const base = String(env.WORKER_PUBLIC_URL || url.origin).replace(/\/+$/, "");
        return json({ url: `${base}/download?key=${encodeURIComponent(key)}&exp=${exp}&sig=${encodeURIComponent(sig)}` }, 200, request, env);
      }

      if (path.endsWith("/invoicing/settings") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const rows = await sbGet(env, "invoice_settings", "id=eq.1&select=*");
        return json({ ok: true, settings: (rows && rows[0]) || null }, 200, request, env);
      }
      if (path.endsWith("/invoicing/settings") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const allowed = ["company_name", "company_address", "company_reg_no", "vat_number", "vat_rate", "bank_name", "account_name", "sort_code", "account_number", "payment_terms_days", "invoice_prefix", "next_number", "accounts_cc_email", "footer_note", "template", "accent_color", "logo_url", "show_bank", "font_family", "font_size", "email_footer_image_url", "automation_mode", "morning_jobs_on"];
        const row = { id: 1 };
        for (const k of allowed) if (b && k in b) row[k] = b[k];
        await fetch(`${env.SUPABASE_URL}/rest/v1/invoice_settings?on_conflict=id`, {
          method: "POST",
          headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "resolution=merge-duplicates,return=minimal" },
          body: JSON.stringify(row),
        });
        return json({ ok: true }, 200, request, env);
      }

      // ---- Brand kit (shared, admin-centre-wide: colours, fonts, logos) -------
      if (path.endsWith("/brand") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const rows = await sbGet(env, "brand_settings", "id=eq.1&select=*");
        return json({ ok: true, brand: (rows && rows[0]) || null }, 200, request, env);
      }
      if (path.endsWith("/brand") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isOwner(user)) return json({ error: "Only the account owner can change the brand kit." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const SOCIAL_KEYS = ["website", "linkedin", "instagram", "facebook", "twitter", "youtube"];
        const row = { id: 1 };
        for (const k of ["colors", "heading_font", "subheading_font", "body_font", "logo_url", "footer_image_url", ...SOCIAL_KEYS]) if (b && k in b) row[k] = b[k];
        if (row.colors && !Array.isArray(row.colors)) delete row.colors;
        const upsert = (payload) => fetch(`${env.SUPABASE_URL}/rest/v1/brand_settings?on_conflict=id`, {
          method: "POST",
          headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "resolution=merge-duplicates,return=minimal" },
          body: JSON.stringify(payload),
        });
        let res = await upsert(row);
        // If the social columns don't exist yet (migration not run), save the
        // rest so the brand kit still works — but flag it so the UI can tell the
        // user the socials didn't persist (run brand_social.sql).
        let socialsSkipped = false;
        const hadSocial = SOCIAL_KEYS.some((k) => k in row);
        if (!res.ok && hadSocial) {
          const base = { ...row }; SOCIAL_KEYS.forEach((k) => delete base[k]);
          res = await upsert(base);
          if (res.ok) socialsSkipped = true;
        }
        if (!res.ok) { const t = await res.text().catch(() => ""); return json({ error: "Couldn't save the brand kit. " + t.slice(0, 200) }, 502, request, env); }
        return json({ ok: true, socialsSkipped }, 200, request, env);
      }

      // ---- Client report settings (super-admin: what clients see in reports) --
      if (path.endsWith("/report-settings") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const rows = await sbGet(env, "report_settings", "id=eq.1&select=visibility");
        return json({ ok: true, visibility: (rows && rows[0] && rows[0].visibility) || {} }, 200, request, env);
      }
      if (path.endsWith("/report-settings") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isOwner(user)) return json({ error: "Only a super-admin can change what clients see." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const vis = (b && b.visibility && typeof b.visibility === "object" && !Array.isArray(b.visibility)) ? b.visibility : {};
        // Keep only boolean values (defence against junk keys).
        const clean = {};
        for (const k of Object.keys(vis)) if (typeof vis[k] === "boolean") clean[k] = vis[k];
        const res = await fetch(`${env.SUPABASE_URL}/rest/v1/report_settings?on_conflict=id`, {
          method: "POST",
          headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "resolution=merge-duplicates,return=minimal" },
          body: JSON.stringify({ id: 1, visibility: clean }),
        });
        if (!res.ok) { const t = await res.text().catch(() => ""); return json({ error: "Couldn't save report settings. " + t.slice(0, 200) }, 502, request, env); }
        return json({ ok: true }, 200, request, env);
      }

      // ---- Admin: invoice recipients (address book) --------------------------
      if (path.endsWith("/invoicing/recipients") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const rows = (await sbGet(env, "invoice_recipients", "select=*&order=name.asc")) || [];
        return json({ ok: true, recipients: rows }, 200, request, env);
      }
      if (path.endsWith("/invoicing/recipients") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const name = String((b && b.name) || "").trim();
        const email = String((b && b.email) || "").trim();
        if (!name || !email) return json({ error: "A name and email are required." }, 400, request, env);
        const res = await sbPost(env, "invoice_recipients", { name, email, contact_name: (b && b.contact_name) || null, address: (b && b.address) || null, notes: (b && b.notes) || null }, "return=representation");
        let rec = null; try { const j = await res.json(); rec = Array.isArray(j) ? j[0] : j; } catch (_) {}
        return json({ ok: true, recipient: rec }, 200, request, env);
      }
      if (path.endsWith("/invoicing/recipients") && request.method === "DELETE") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const id = (url.searchParams.get("id") || "").trim();
        if (!id) return json({ error: "Missing id" }, 400, request, env);
        await fetch(`${env.SUPABASE_URL}/rest/v1/invoice_recipients?id=eq.${encodeURIComponent(id)}`, {
          method: "DELETE", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}` },
        });
        return json({ ok: true }, 200, request, env);
      }

      // ---- Admin: send an invoice (render PDF → email + CC accounts → sent) ---
      // ---- Fine & Country: Paula's answer to the marketing fee check --------
      // As with invoice approval, the page has the button: opening the link
      // alone changes nothing (mail scanners open every link).
      if (path.endsWith("/videography/fc-fee") && (request.method === "GET" || request.method === "POST")) {
        const page = (title, inner, status = 200) => new Response(invApprovalPage(title, inner), { status, headers: { "Content-Type": "text/html; charset=utf-8" } });
        const f = request.method === "POST" ? await request.formData().catch(() => null) : null;
        const t = f ? String(f.get("t") || "") : (url.searchParams.get("t") || "");
        const a = (f ? f.get("a") : url.searchParams.get("a")) === "no" ? "no" : "yes";
        const id = await invVerifyFor(env, "fcfee", t);
        if (!id) return page("That link doesn't work", `<p style="font-size:13px;line-height:1.6">Use the buttons in the email, or reply to it.</p>`, 400);
        const bk = (await sbGet(env, "videography_bookings", `id=eq.${encodeURIComponent(id)}&select=*`))?.[0];
        if (!bk) return page("That shoot isn't there any more", "");
        const when = bk.shoot_date ? new Date(bk.shoot_date).toLocaleDateString("en-GB", { weekday: "long", day: "numeric", month: "long", timeZone: "Europe/London" }) : "";
        const what = `${invEsc(bk.client_name || "The agent")}'s shoot${when ? ` on ${invEsc(when)}` : ""}${bk.fc_office ? `, ${invEsc(FC_OFFICE_LABELS[bk.fc_office] || "")}` : ""}`;
        if (request.method === "GET") {
          if (bk.fc_fee_answer) return page("Thanks, we've got your answer", `<p style="font-size:13px;line-height:1.6">${what}: you said the marketing fee ${bk.fc_fee_answer === "yes" ? "has" : "hasn't"} been received. If that's changed, reply to the email.</p>`);
          const btn = "display:inline-block;padding:11px 20px;border-radius:4px;border:0;background:#371e28;color:#fff;font:600 12px Verdana,Geneva,sans-serif;letter-spacing:.06em;text-transform:uppercase;cursor:pointer";
          return page(a === "yes" ? "Confirm the marketing fee has been received?" : "The marketing fee hasn't been received?",
            `<p style="font-size:13px;line-height:1.6">${what}.</p><form method="post" action="${url.pathname}"><input type="hidden" name="t" value="${invEsc(t)}"><input type="hidden" name="a" value="${a}"><button type="submit" style="${btn}">${a === "yes" ? "Yes, it's been received" : "No, not yet"}</button></form>`);
        }
        const now = new Date().toISOString();
        const hdr = { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=minimal" };
        const patch = a === "yes"
          ? { fc_fee_answer: "yes", fc_fee_answered_at: now, fc_fee_answered_by: bk.fc_confirm_email || "Fine & Country", brand_fee_confirmed: true, brand_fee_confirmed_at: now, brand_fee_confirmed_by: `${bk.fc_confirm_email || "Fine & Country"} (by email)` }
          : { fc_fee_answer: "no", fc_fee_answered_at: now, fc_fee_answered_by: bk.fc_confirm_email || "Fine & Country" };
        await fetch(`${env.SUPABASE_URL}/rest/v1/videography_bookings?id=eq.${bk.id}`, { method: "PATCH", headers: hdr, body: JSON.stringify(patch) });
        await logBookingMessage(env, { booking_id: bk.id, booking_source: "videography", channel: "note", kind: "audit", subject: a === "yes" ? "Marketing fee confirmed" : "Marketing fee NOT received", body: `Fine & Country answered the fee check: ${a === "yes" ? "received" : "not received yet"}.`, is_automated: true, created_by: "system" });
        if (a === "no") {
          const loc = String(bk.property_address || bk.location || "").replace(/\s*\n\s*/g, ", ").trim();
          await sendEmail(env, { to: invDanielle(env), cc: invJack(env) || null, subject: `The marketing fee for ${bk.client_name || "a Fine & Country"}'s shoot hasn't been received.`, html: await wrapInBrandedBase(env, `<div style="${EM_WRAP}"><p style="${EM_P}">Hi Danielle and Jack,</p><p style="${EM_P}">Paula has let us know that the marketing fee for ${invEsc(bk.client_name || "the agent")}'s ${invEsc(bk.service || "videography")} shoot${when ? ` on ${invEsc(when)}` : ""}${loc ? ` at ${invEsc(loc)}` : ""} hasn't been received yet.</p><p style="${EM_P}">Please don't invoice this shoot until it has.</p><p style="${EM_P}"><a href="${invSite(env)}/admin/videography?booking=${bk.id}" style="${EM_BTN}">Open the booking</a></p></div>`) });
        }
        return page("Thank you", `<p style="font-size:13px;line-height:1.6">${a === "yes" ? "Thank you for confirming. We'll invoice the shoot as planned." : "Thank you for letting us know. We've told Danielle and Jack, and we won't invoice the shoot until the fee has been received."}</p>`);
      }
      // ---- Admin: which F&C office an agent sits under (TEG Team Hub) -------
      if (path.endsWith("/videography/fc-office") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const f = await tegFcOffice(env, url.searchParams.get("email") || "");
        return json({ ok: true, ...f, label: f.key ? FC_OFFICE_LABELS[f.key] : null }, 200, request, env);
      }
      // ---- Admin: a monthly number for a recurring invoice (TPE agents) -----
      if (path.endsWith("/invoicing/recurring/quantity") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const qty = Number(b.qty);
        if (!b.recurring_id || !/^\d{4}-\d{2}$/.test(String(b.month || "")) || !(qty >= 0)) return json({ error: "Which invoice, which month and the number, please." }, 400, request, env);
        const r = await fetch(`${env.SUPABASE_URL}/rest/v1/recurring_quantities?on_conflict=recurring_id,month`, { method: "POST", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "resolution=merge-duplicates,return=minimal" }, body: JSON.stringify({ recurring_id: b.recurring_id, month: b.month, qty, entered_by: user.email || null, entered_at: new Date().toISOString() }) });
        return r.ok ? json({ ok: true }, 200, request, env) : json({ error: "Couldn't save it: " + (await r.text()).slice(0, 160) }, 502, request, env);
      }
      // ---- Admin: what the social media To do view works from (Dani, 5 Nov 2026) ----
      // One read for everyone instead of a thread per client: the last time
      // anything happened, content plans, call notes, proposal/contract files,
      // emails sent (for chases), reports, stage dates and shoots to come.
      if (path.endsWith("/smm/todo-data") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const [msgs, docs, evs, reps, shoots] = await Promise.all([
          sbGetAll(env, "booking_messages", "booking_source=eq.smm&select=booking_id,channel,direction,subject,is_automated,created_at&order=created_at.asc"),
          sbGetAll(env, "booking_documents", "booking_source=eq.smm&select=booking_id,category,title,file_name,created_at&order=created_at.asc"),
          sbGetAll(env, "smm_stage_events", "select=lead_id,stage,reached_at&order=reached_at.asc"),
          sbGetAll(env, "smm_reports", "select=lead_id,month,year,published_at").then((x) => x || sbGetAll(env, "smm_reports", "select=lead_id,month,year")),
          sbGetAll(env, "videography_bookings", "smm_lead_id=not.is.null&stage=neq.cancelled&select=smm_lead_id,shoot_date,service,stage"),
        ]);
        const out = {};
        const L = (id) => (out[id] = out[id] || { last: null, plans: [], notes: {}, prep: null, agreement: null, emails: [], reports: {}, reached: {}, shoots: [] });
        const bump = (o, at) => { if (at && (!o.last || at > o.last)) o.last = at; };
        for (const m of msgs || []) {
          const o = L(m.booking_id); bump(o, m.created_at);
          const sub = String(m.subject || "").toLowerCase();
          if (m.channel === "note" && /^(discovery|pricing|onboarding) call notes$/.test(sub)) o.notes[sub.split(" ")[0]] = m.created_at;
          if (m.channel === "email" && m.direction !== "inbound" && !m.is_automated) o.emails.push(m.created_at);
        }
        for (const d of docs || []) {
          const o = L(d.booking_id); bump(o, d.created_at);
          if (d.category === "content_plan") o.plans.push({ title: d.title || d.file_name || "", at: d.created_at });
          if (d.category === "prep") o.prep = d.created_at;
          if (d.category === "agreement") o.agreement = d.created_at;
        }
        for (const e of evs || []) { const o = L(e.lead_id); bump(o, e.reached_at); o.reached[e.stage] = e.reached_at; }
        for (const r of reps || []) { const o = L(r.lead_id); const ym = `${r.year}-${String(Number(r.month) + 1).padStart(2, "0")}`; o.reports[ym] = o.reports[ym] || !!r.published_at; }
        for (const v of shoots || []) if (v.shoot_date) L(v.smm_lead_id).shoots.push({ at: v.shoot_date, shoot_date: v.shoot_date, stage: v.stage, service: v.service });
        return json({ ok: true, byLead: out }, 200, request, env);
      }
      // ---- Admin: every social media client's unpaid invoices, for the board ----
      // (Dani, 5 Nov 2026): which month, when it's due, overdue or not. No
      // amounts, so it's the client file's view, not the ledger.
      if (path.endsWith("/smm/outstanding-invoices") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const recs = (await sbGet(env, "recurring_invoices", "kind=eq.social&select=id,lead_id,pays_ahead")) || (await sbGet(env, "recurring_invoices", "kind=eq.social&select=id,lead_id")) || [];
        const byRec = Object.fromEntries(recs.filter((r) => r.lead_id).map((r) => [r.id, r]));
        const ids = Object.keys(byRec);
        const or = ids.length ? `&or=(booking_source.eq.smm,recurring_id.in.(${ids.join(",")}))` : "&booking_source=eq.smm";
        const rows = (await sbGet(env, "invoices", `status=not.in.(paid,void,draft)${or}&select=id,number,booking_id,recurring_id,billing_month,issued_date,due_date,status&order=due_date.asc&limit=1000`)) || [];
        const out = {};
        for (const v of rows) {
          const rec = v.recurring_id ? byRec[v.recurring_id] : null;
          const lead = (rec && rec.lead_id) || v.booking_id;
          if (!lead) continue;
          const ym = v.billing_month || String(v.issued_date || "").slice(0, 7);
          (out[lead] = out[lead] || []).push({ id: v.id, number: v.number, status: v.status, due_date: v.due_date, month: rec && rec.pays_ahead && ym ? ymAdd(ym, 1) : ym });
        }
        return json({ ok: true, byLead: out }, 200, request, env);
      }
      // ---- Admin: Abbie's monthly social media invoice list ------------------
      // Every social media client on the invoice schedule, this month and
      // next: ticked to invoice, and what's been raised (Danielle, 22 Oct).
      if (path.endsWith("/smm/monthly-invoices") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const t0 = invToday(), months = [t0.ym, invToday(32 - t0.day).ym];
        const rows = (await sbGet(env, "recurring_invoices", "active=eq.true&kind=eq.social&select=id,name,contact_name,bill_to_name,amount_pence,pay_by_card,lead_id,day_of_month,auto_send&order=name.asc")) || [];
        const stopped = await smmStoppedLeads(env, rows.map((r) => r.lead_id));
        rows.forEach((r) => { if (r.lead_id && stopped.has(r.lead_id)) r.stopped = stopped.get(r.lead_id); });
        const ids = rows.map((r) => r.id);
        const ticks = ids.length ? (await sbGet(env, "recurring_month_approvals", `recurring_id=in.(${ids.join(",")})&month=in.(${months.join(",")})&select=recurring_id,month,approved,updated_by`)) || [] : [];
        const invs = ids.length ? (await sbGet(env, "invoices", `recurring_id=in.(${ids.join(",")})&billing_month=in.(${months.join(",")})&status=neq.void&select=recurring_id,billing_month,number,status`)) || [] : [];
        // Raised another way (from their file, say): on the client, for the month (10 Nov 2026).
        const leadIds = rows.map((r) => r.lead_id).filter(Boolean);
        const byLead = leadIds.length ? (await sbGet(env, "invoices", `booking_source=eq.smm&booking_id=in.(${leadIds.join(",")})&recurring_id=is.null&status=neq.void&select=booking_id,billing_month,issued_date,number,status,line_items`)) || [] : [];
        const leads = leadIds.length ? (await sbGet(env, "smm_leads", `id=in.(${leadIds.join(",")})&select=id,business,full_name`)) || [] : [];
        const onboard = (v) => (v.line_items || []).some((l) => /onboarding/i.test(String(l && l.description || ""))) && (v.line_items || []).length === 1;
        const conf = (await sbGet(env, "social_invoice_months", `month=in.(${months.join(",")})&select=*`)) || [];
        return json({ ok: true, today: t0.ymd, months: months.map((m) => ({ month: m, label: invMonthLabel(m), confirmed: conf.find((c) => c.month === m) || null })),
          rows: rows.map((r) => { const l = leads.find((x) => x.id === r.lead_id) || {}; return { ...r, business: l.business || "", person: l.full_name || r.contact_name || "", cells: Object.fromEntries(months.map((m) => [m, {
            ticked: !!ticks.find((x) => x.recurring_id === r.id && x.month === m && x.approved),
            invoice: invs.find((x) => x.recurring_id === r.id && x.billing_month === m)
              || byLead.find((x) => x.booking_id === r.lead_id && (x.billing_month || String(x.issued_date || "").slice(0, 7)) === m && !onboard(x)) || null,
          }])) }; }) }, 200, request, env);
      }
      if (path.endsWith("/smm/monthly-invoices") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        if (!b.recurring_id || !/^\d{4}-\d{2}$/.test(String(b.month || ""))) return json({ error: "Which client and month?" }, 400, request, env);
        const r = await fetch(`${env.SUPABASE_URL}/rest/v1/recurring_month_approvals?on_conflict=recurring_id,month`, { method: "POST", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "resolution=merge-duplicates,return=minimal" }, body: JSON.stringify({ recurring_id: b.recurring_id, month: b.month, approved: !!b.approved, updated_by: user.email || null, updated_at: new Date().toISOString() }) });
        return r.ok ? json({ ok: true }, 200, request, env) : json({ error: /recurring_month_approvals/.test(await r.text()) ? "Run supabase/invoicing_automation_3.sql first." : "Couldn't save that." }, 502, request, env);
      }
      // Send now (Dani, 10 Nov 2026): someone ticked after their day, or missed,
      // invoiced straight away from their monthly setup, the same invoice and
      // email the 5th would have sent. Ticks them for the month too.
      if (path.endsWith("/smm/monthly-invoices/send-now") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String(b.recurring_id || ""), m = String(b.month || "");
        if (!/^[0-9a-f-]{36}$/i.test(id) || !/^\d{4}-\d{2}$/.test(m)) return json({ error: "Which client and month?" }, 400, request, env);
        const r = (await sbGet(env, "recurring_invoices", `id=eq.${id}&active=eq.true&kind=eq.social&select=*`))?.[0];
        if (!r) return json({ error: "Their monthly invoice isn't set up." }, 404, request, env);
        if (m > invToday().ym) return json({ error: "That month hasn't started yet." }, 400, request, env);
        const had = (await sbGet(env, "invoices", `recurring_id=eq.${id}&billing_month=eq.${m}&status=neq.void&select=id,number,status&order=created_at.desc`)) || [];
        const gone = had.find((v) => v.status !== "draft");
        if (gone) return json({ error: `${gone.number} has already gone for ${invMonthLabel(m)}.` }, 409, request, env);
        await fetch(`${env.SUPABASE_URL}/rest/v1/recurring_month_approvals?on_conflict=recurring_id,month`, { method: "POST", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "resolution=merge-duplicates,return=minimal" }, body: JSON.stringify({ recurring_id: id, month: m, approved: true, updated_by: user.email || null, updated_at: new Date().toISOString() }) });
        let invId = had[0] && had[0].id;
        if (!invId) {
          const st = (await sbGet(env, "invoice_settings", "id=eq.1&select=*"))?.[0] || {};
          const made = await raiseRecurringDraft(env, st, r, m, null, user.email || null);
          if (!made.ok) return json({ error: made.error }, made.code || 502, request, env);
          invId = made.invoice.id;
        }
        const sent = await sendInvoiceNow(env, { id: invId }, user.email || "admin");
        if (!sent.ok) return json({ error: sent.error }, sent.code || 502, request, env);
        const inv = (await sbGet(env, "invoices", `id=eq.${invId}&select=number`))?.[0] || {};
        return json({ ok: true, number: inv.number || "", sent_to: sent.sent_to }, 200, request, env);
      }
      if (path.endsWith("/smm/monthly-invoices/confirm") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        if (!/^\d{4}-\d{2}$/.test(String(b.month || ""))) return json({ error: "Which month?" }, 400, request, env);
        const hdr = { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "resolution=merge-duplicates,return=minimal" };
        const r = b.undo
          ? await fetch(`${env.SUPABASE_URL}/rest/v1/social_invoice_months?month=eq.${b.month}`, { method: "DELETE", headers: hdr })
          : await fetch(`${env.SUPABASE_URL}/rest/v1/social_invoice_months?on_conflict=month`, { method: "POST", headers: hdr, body: JSON.stringify({ month: b.month, confirmed_by: user.email || null, confirmed_at: new Date().toISOString() }) });
        return r.ok ? json({ ok: true }, 200, request, env) : json({ error: "Couldn't save that." }, 502, request, env);
      }
      // ---- Admin: the covering email an invoice would go with ----------------
      // So the send screens show the same words the automatic invoicing uses.
      if (path.endsWith("/invoicing/email-draft") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const inv = (await sbGet(env, "invoices", `id=eq.${encodeURIComponent(url.searchParams.get("id") || "")}&select=*`))?.[0];
        if (!inv) return json({ error: "Invoice not found." }, 404, request, env);
        const st = (await sbGet(env, "invoice_settings", "id=eq.1&select=*"))?.[0] || {};
        return json({ ok: true, ...invoiceEmail(inv, st, await invoiceEmailCtx(env, inv)) }, 200, request, env);
      }
      // ---- Approve or reject an invoice from the email (no sign-in) ----------
      // The link opens a page with the button: nothing happens on the click
      // through alone, because mail scanners open every link in an email
      // (Microsoft's do, for nearly every message) and would approve it.
      if (path.endsWith("/invoicing/approval") && request.method === "GET") {
        const t = url.searchParams.get("t") || "", a = url.searchParams.get("a") === "reject" ? "reject" : "approve";
        const id = await invApprovalVerify(env, t);
        const page = (title, inner) => new Response(invApprovalPage(title, inner), { status: 200, headers: { "Content-Type": "text/html; charset=utf-8" } });
        if (!id) return page("That link doesn't work", `<p style="font-size:13px;line-height:1.6">It may have been copied wrongly. Use the buttons in the email.</p>`);
        const ap = (await sbGet(env, "invoice_approvals", `id=eq.${encodeURIComponent(id)}&select=*`))?.[0];
        const inv = ap ? (await sbGet(env, "invoices", `id=eq.${ap.invoice_id}&select=*`))?.[0] : null;
        if (!ap || !inv) return page("That link doesn't work any more", `<p style="font-size:13px;line-height:1.6">Check your latest email.</p>`);
        if (ap.status !== "pending") { const r = await decideInvoiceApproval(env, id, a, ""); return page(r.title, `<p style="font-size:13px;line-height:1.6">${r.msg}</p>`); }
        const summary = a === "approve"
          ? `<p style="font-size:13px;line-height:1.6">Clicking the button sends it to ${invEsc(inv.bill_to_name || "them")} for ${gbpW(inv.total_pence || 0)}.</p>${invLinesHtml(inv)}`
          : `<p style="font-size:13px;line-height:1.6">Your note goes to Danielle, and nothing is sent until it's approved.</p>`;
        const btn = "display:inline-block;padding:11px 20px;border-radius:4px;border:0;background:#371e28;color:#fff;font:600 12px Verdana,Geneva,sans-serif;letter-spacing:.06em;text-transform:uppercase;cursor:pointer";
        const form = a === "approve"
          ? `<form method="post" action="${url.pathname}"><input type="hidden" name="t" value="${invEsc(t)}"><input type="hidden" name="a" value="approve"><button type="submit" style="${btn}">Approve and send</button></form>
             <p style="font-size:12px;line-height:1.6;margin-top:14px">Something wrong? <a href="${url.pathname}?t=${encodeURIComponent(t)}&a=reject" style="color:#371e28">Reject it instead</a>.</p>`
          : `<form method="post" action="${url.pathname}"><input type="hidden" name="t" value="${invEsc(t)}"><input type="hidden" name="a" value="reject">
               <textarea name="notes" rows="5" required style="width:100%;box-sizing:border-box;padding:10px;border:1px solid #c9bfba;border-radius:4px;font:13px Verdana,Geneva,sans-serif" placeholder="e.g. The travel should be 60 miles each way, and it's for the Stratford office."></textarea>
               <p style="margin-top:12px"><button type="submit" style="${btn}">Send to Danielle</button></p></form>`;
        return page(a === "approve" ? `Approve invoice ${invEsc(inv.number)}?` : "What needs changing?", summary + form);
      }
      if (path.endsWith("/invoicing/approval") && request.method === "POST") {
        const f = await request.formData().catch(() => null);
        const t = f ? String(f.get("t") || "") : "", a = f && f.get("a") === "reject" ? "reject" : "approve";
        const notes = f ? String(f.get("notes") || "").trim().slice(0, 2000) : "";
        const id = await invApprovalVerify(env, t);
        if (!id) return new Response(invApprovalPage("That link doesn't work", ""), { status: 400, headers: { "Content-Type": "text/html; charset=utf-8" } });
        const r = await decideInvoiceApproval(env, id, a, notes);
        return new Response(invApprovalPage(r.title, `<p style="font-size:13px;line-height:1.6">${r.msg}</p>`), { status: 200, headers: { "Content-Type": "text/html; charset=utf-8" } });
      }
      // ---- Admin: send an invoice (back) to someone to approve --------------
      // "Send to Jack again" after a rejection, or the first time for a draft
      // the morning run couldn't send (no email, fee not confirmed).
      if (path.endsWith("/invoicing/approval/request") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const inv = (await sbGet(env, "invoices", `id=eq.${encodeURIComponent(String(b.invoice_id || ""))}&select=*`))?.[0];
        if (!inv) return json({ error: "Invoice not found." }, 404, request, env);
        if (inv.status !== "draft") return json({ error: "Only a draft can go for approval: this one has been sent." }, 400, request, env);
        if (!inv.bill_to_email) return json({ error: "Add an email to send it to first." }, 400, request, env);
        const st = (await sbGet(env, "invoice_settings", "id=eq.1&select=automation_mode"))?.[0] || {};
        let about = "";
        if (inv.booking_id && (inv.booking_source || "videography") === "videography") {
          const bk = (await sbGet(env, "videography_bookings", `id=eq.${inv.booking_id}&select=client_name,client_company,shoot_date`))?.[0];
          if (bk) about = `${bk.client_name || bk.client_company || "the client"}'s shoot${bk.shoot_date ? ` on ${new Date(bk.shoot_date).toLocaleDateString("en-GB", { weekday: "long", day: "numeric", month: "long", timeZone: "Europe/London" })}` : ""}`;
        }
        // Back to whoever it went to last (Abbie for social media), else Jack.
        const last = (await sbGet(env, "invoice_approvals", `invoice_id=eq.${inv.id}&select=approver_email,kind&order=requested_at.desc&limit=1`))?.[0];
        // Sent by a person, so it's real whatever the automatic invoicing's
        // mode (Danielle, 22 Oct 2026): it goes to Jack, and approving it sends
        // it to the client. "-manual" on the kind tells the approval so.
        const kind = String(b.kind || (last && last.kind) || "videography").replace(/-manual$/, "") + "-manual";
        const r = await requestInvoiceApproval(env, inv, { kind, approver: String(b.approver || "").trim() || (last && last.approver_email) || invJack(env), bookingId: (inv.booking_source || "videography") === "videography" ? (inv.booking_id || null) : null, about, mode: "live" });
        if (!r.ok) return json({ error: r.error || "Couldn't send it." }, 502, request, env);
        return json({ ok: true, approval: r.approval, test: false }, 200, request, env);
      }
      // ---- Admin: approvals, newest first (the Approvals tab) ---------------
      if (path.endsWith("/invoicing/approvals") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const aps = (await sbGet(env, "invoice_approvals", "select=*&order=requested_at.desc&limit=200")) || [];
        const ids = [...new Set(aps.map((x) => x.invoice_id))];
        const invs = ids.length ? (await sbGet(env, "invoices", `id=in.(${ids.join(",")})&select=id,number,bill_to_name,bill_to_email,total_pence,status,booking_id`)) || [] : [];
        const st = (await sbGet(env, "invoice_settings", "id=eq.1&select=automation_mode"))?.[0] || {};
        // Monthly numbers still to fill in (this month and next), for the
        // invoices that need one (the TPE hub's agents).
        let numbers = [];
        try {
          const qs = (await sbGet(env, "recurring_invoices", "active=eq.true&quantity_label=not.is.null&select=id,name,quantity_label,day_of_month,amount_pence")) || [];
          const t0 = invToday(), months = [t0.ym, invToday(32 - t0.day).ym];
          for (const r of qs) for (const m of months) {
            const q = (await sbGet(env, "recurring_quantities", `recurring_id=eq.${r.id}&month=eq.${m}&select=qty,entered_by,entered_at`))?.[0] || null;
            numbers.push({ recurring_id: r.id, name: r.name, label: r.quantity_label, day: r.day_of_month, unit_pence: r.amount_pence, month: m, month_label: invMonthLabel(m), qty: q ? Number(q.qty) : null, entered_by: q ? q.entered_by : null });
          }
        } catch (_) {}
        return json({ ok: true, mode: st.automation_mode || "off", numbers, approvals: aps.map((x) => ({ ...x, invoice: invs.find((i) => i.id === x.invoice_id) || null })) }, 200, request, env);
      }
      // ---- Admin: run this morning's automatic invoicing now ----------------
      if (path.endsWith("/invoicing/automation/run") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!(await isManagement(env, user))) return json(MGMT_ONLY, 403, request, env);
        return json(await runInvoiceAutomation(env), 200, request, env);
      }
      if (path.endsWith("/invoicing/invoices/send") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        let b = await request.json().catch(() => ({}));
        /* Everyone else can resend an invoice that has already gone, exactly as
           it was: no new invoices, no changes to the email (Danielle, 28 Oct
           2026). A change goes through Danielle. */
        if (!(await isManagement(env, user)) && !(isVideographyInvoicer(user.email) && await isVideographyInvoice(env, b && b.id))) {
          const cur = (await sbGet(env, "invoices", `id=eq.${encodeURIComponent(String(b.id || ""))}&select=status`))?.[0];
          if (!cur) return json({ error: "Invoice not found." }, 404, request, env);
          if (cur.status !== "sent" && cur.status !== "paid") return json({ error: "Only an invoice that has already been sent can be resent. Ask Danielle to send a new one." }, 403, request, env);
          b = { id: b.id };
        }
        const sent = await sendInvoiceNow(env, b, user.email || "an admin");
        if (!sent.ok) return json({ error: sent.error }, sent.code || 502, request, env);
        return json(sent, 200, request, env);
      }

      // ---- A link to the PDF of an invoice (admins) ----
      // The PDF is stored when the invoice is sent, so this is the document the
      // client received. If it predates that, it is rendered and stored now.
      if (path.endsWith("/invoicing/invoice-pdf") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const id = url.searchParams.get("id") || "";
        const rows = id ? await sbGet(env, "invoices", `id=eq.${encodeURIComponent(id)}&select=*`) : null;
        const inv = rows && rows[0];
        if (!inv) return json({ error: "Invoice not found." }, 404, request, env);
        const key = `invoices/${inv.number || inv.id}.pdf`;
        let head = null;
        try { head = await env.BUCKET.head(key); } catch (_) {}
        if (!head) {
          const st2 = (await sbGet(env, "invoice_settings", "id=eq.1&select=*"))?.[0] || {};
          try {
            const pdf2 = await renderInvoicePdf(env, { ...st2, template: inv.template || st2.template }, inv);
            await env.BUCKET.put(key, pdf2, { httpMetadata: { contentType: "application/pdf" } });
          } catch (err) { return json({ error: "Couldn't produce the PDF: " + ((err && err.message) || err) }, 502, request, env); }
        }
        const exp = Date.now() + 60 * 60 * 1000;
        const sig = await mediaSig(env, key, exp);
        if (!sig) return json({ error: "Links aren't configured on the Worker." }, 503, request, env);
        const base = String(env.WORKER_PUBLIC_URL || url.origin).replace(/\/+$/, "");
        return json({ url: `${base}/download?key=${encodeURIComponent(key)}&exp=${exp}&sig=${encodeURIComponent(sig)}`, stored: !!head }, 200, request, env);
      }

      // One invoice, in full. The list select is lean and carries no line items,
      // and reading the table straight from the browser depends on the admin's
      // own RLS row - which is one more thing to be wrong when an editor won't
      // populate. The service role has no such doubt.
      if (path.endsWith("/invoicing/invoice") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!(await isManagement(env, user))) return json(MGMT_ONLY, 403, request, env);
        const id = (url.searchParams.get("id") || "").trim();
        if (!id) return json({ error: "Missing id" }, 400, request, env);
        const rows = await sbGet(env, "invoices", `id=eq.${encodeURIComponent(id)}&select=*`);
        const inv = rows && rows[0];
        if (!inv) return json({ error: "Invoice not found." }, 404, request, env);
        return json({ ok: true, invoice: inv }, 200, request, env);
      }

      // ---- Invoicing's overview: the whole book and what needs Dani ----------
      if (path.endsWith("/invoicing/book") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!(await isManagement(env, user))) return json(MGMT_ONLY, 403, request, env);
        const invoices = await invoiceBook(env, "status=in.(draft,sent,paid)");
        if (!invoices) return json({ code: "needs_sql", error: "Run supabase/accounts_portal.sql in Supabase first." }, 503, request, env);
        const t0 = invToday();
        // Drafts waiting for someone to approve them.
        const pending = (await sbGet(env, "invoice_approvals", "status=eq.pending&select=id,invoice_id,approver_email,kind")) || [];
        // Numbers an invoice needs before it can go (the TPE hub's agents).
        const numbers = [];
        try {
          const qs = (await sbGet(env, "recurring_invoices", "active=eq.true&quantity_label=not.is.null&select=id,name,quantity_label,day_of_month,amount_pence")) || [];
          const months = t0.day >= 25 ? [t0.ym, ymAdd(t0.ym, 1)] : [t0.ym];
          for (const r of qs) for (const m of months) {
            if (m === t0.ym && t0.day > (r.day_of_month || 28)) continue;
            const q = (await sbGet(env, "recurring_quantities", `recurring_id=eq.${r.id}&month=eq.${m}&select=qty`))?.[0];
            if (!q) numbers.push({ recurring_id: r.id, name: r.name, label: r.quantity_label, day: r.day_of_month, unit_pence: r.amount_pence, month: m, month_label: invMonthLabel(m) });
          }
        } catch (_) {}
        // Abbie's ticks, in the days before the 5th when social invoices go.
        let ticks = null;
        try {
          const m = t0.day <= 5 ? t0.ym : t0.day >= 28 ? ymAdd(t0.ym, 1) : null;
          if (m && !((await sbGet(env, "social_invoice_months", `month=eq.${m}&select=month`)) || []).length) {
            const recs = (await sbGet(env, "recurring_invoices", "active=eq.true&kind=eq.social&select=id")) || [];
            const ticked = recs.length ? (await sbGet(env, "recurring_month_approvals", `recurring_id=in.(${recs.map((r) => r.id).join(",")})&month=eq.${m}&approved=eq.true&select=recurring_id`)) || [] : [];
            ticks = { month: m, month_label: invMonthLabel(m), ticked: ticked.length, total: recs.length };
          }
        } catch (_) {}
        // Shoots released before payment stay in Needs you until they're paid,
        // or nothing would push anyone to raise the invoice (Dani, 6 Nov).
        let released = [];
        try {
          const rows = (await sbGet(env, "videography_bookings", "released_unpaid_at=not.is.null&paid_at=is.null&select=id,client_name,client_company,company,service")) || [];
          const invs = rows.length ? (await sbGet(env, "invoices", `booking_id=in.(${rows.map((r) => `"${r.id}"`).join(",")})&status=neq.void&select=booking_id,number,status&order=created_at.desc`)) || [] : [];
          released = rows.map((r) => {
            const iv = invs.find((x) => x.booking_id === r.id);
            return { id: r.id, client: r.company || r.client_company || r.client_name || "A shoot", service: r.service || "", number: iv ? iv.number || "" : "", status: iv ? iv.status : "" };
          });
        } catch (_) {}
        const portal = await accountsPortalRow(env);
        return json({ ok: true, today: t0.ymd, invoices, pending, numbers, ticks, released, portal_ready: !!portal }, 200, request, env);
      }
      if (path.endsWith("/invoicing/book/update") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!(await isManagement(env, user))) return json(MGMT_ONLY, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String(b.id || "");
        if (!/^[0-9a-f-]{36}$/i.test(id)) return json({ error: "Which invoice?" }, 400, request, env);
        const patch = {};
        if (b.note !== undefined) patch.accounts_note = String(b.note || "").trim().slice(0, 2000) || null;
        if (b.pay_by_card !== undefined) patch.pay_by_card = !!b.pay_by_card;
        if (b.sector !== undefined) { if (b.sector && !["social", "video", "studio", "agent"].includes(b.sector)) return json({ error: "Which sector?" }, 400, request, env); patch.sector = b.sector || null; }
        if (!Object.keys(patch).length) return json({ error: "Nothing to save." }, 400, request, env);
        const r = await sbPatch(env, "invoices", `id=eq.${id}`, patch);
        if (!r.ok) return json({ error: "Couldn't save that." }, 502, request, env);
        return json({ ok: true }, 200, request, env);
      }
      // A draft approved from Invoicing, by someone who can raise it anyway.
      if (path.endsWith("/invoicing/approval/decide") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!(await isManagement(env, user))) return json(MGMT_ONLY, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const r = await decideInvoiceApproval(env, String(b.approval_id || ""), "approve", "");
        return json({ ok: true, title: r.title, msg: r.msg }, 200, request, env);
      }
      // A note to accounts about one invoice.
      if (path.endsWith("/invoicing/accounts-email") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!(await isManagement(env, user))) return json(MGMT_ONLY, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String(b.id || "");
        const inv = (await sbGet(env, "invoices", `id=eq.${encodeURIComponent(id)}&select=id,accounts_reminders`))?.[0];
        const p = await accountsPortalRow(env);
        if (!inv || !p) return json({ error: "Couldn't find that." }, 404, request, env);
        const subject = String(b.subject || "").trim().slice(0, 200), text = String(b.body || "").trim().slice(0, 6000);
        if (!subject || !text) return json({ error: "Add a subject and a message." }, 400, request, env);
        const paras = invEsc(text).split(/\n{2,}/).map((x) => `<p style="${EM_P}">${x.replace(/\n/g, "<br>").replace(/\[link to the portal\]/g, `<a href="${accountsLink(env, p)}" style="color:#371e28;text-decoration:underline">${accountsLink(env, p)}</a>`)}</p>`).join("");
        const sent = await sendEmail(env, { to: p.email_to, cc: accountsCc(env, p, user.email), subject, html: await wrapInBrandedBase(env, `<div style="${EM_WRAP}">${paras}</div>`) });
        if (!sent.ok) return json({ error: "Couldn't send it. Please try again." }, 502, request, env);
        const list = (Array.isArray(inv.accounts_reminders) ? inv.accounts_reminders : []).concat(invToday().ymd);
        await sbPatch(env, "invoices", `id=eq.${id}`, { accounts_reminders: list });
        return json({ ok: true, to: p.email_to, reminders: list }, 200, request, env);
      }
      // The portal's link, passcode and emails.
      if (path.endsWith("/invoicing/portal-settings")) {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!(await isManagement(env, user))) return json(MGMT_ONLY, 403, request, env);
        let p = await accountsPortalRow(env);
        if (!p) return json({ code: "needs_sql", error: "Run supabase/accounts_portal.sql in Supabase first." }, 503, request, env);
        if (request.method === "POST") {
          const b = await request.json().catch(() => ({}));
          const patch = { updated_at: new Date().toISOString(), updated_by: user.email || null };
          if (b.enabled !== undefined) patch.enabled = !!b.enabled;
          if (b.emails_on !== undefined) patch.emails_on = !!b.emails_on;
          const emailList = (v) => String(v || "").split(/[;,]/).map((x) => x.trim()).filter(Boolean);
          const okList = (a) => a.every((x) => /^[^@\s,]+@[^@\s,]+\.[^@\s,]+$/.test(x));
          if (b.email_to !== undefined) { const t = emailList(b.email_to); if (!t.length || !okList(t)) return json({ error: "One of the To addresses doesn't look right." }, 400, request, env); patch.email_to = t.join(", "); }
          if (b.email_cc !== undefined) { const t = emailList(b.email_cc); if (!okList(t)) return json({ error: "One of the Copied in addresses doesn't look right." }, 400, request, env); patch.email_cc = t.join(", ") || null; }
          if (b.passcode !== undefined) { const c = portalCode(b.passcode); if (c.length < 6 || c.length > 12) return json({ error: "A passcode needs 6 to 12 letters or numbers." }, 400, request, env); patch.passcode = c; patch.failed_tries = 0; patch.locked_until = null; }
          const r = await sbPatch(env, "accounts_portal", "id=eq.1", patch);
          if (!r.ok) return json({ error: "Couldn't save that." }, 502, request, env);
          p = await accountsPortalRow(env);
        } else if (request.method !== "GET") return json({ error: "Not found" }, 404, request, env);
        return json({ ok: true, link: accountsLink(env, p), passcode: p.passcode, enabled: p.enabled, email_to: p.email_to, email_cc: p.email_cc === undefined ? null : p.email_cc, cc_ready: p.email_cc !== undefined, emails_on: p.emails_on, last_opened_at: p.last_opened_at }, 200, request, env);
      }
      // The first email to accounts: what it says, sending it, and when it last went.
      if (path.endsWith("/invoicing/first-email")) {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!(await isManagement(env, user))) return json(MGMT_ONLY, 403, request, env);
        const p = await accountsPortalRow(env);
        if (!p) return json({ error: "Couldn't load the portal's settings." }, 502, request, env);
        const mail = accountsFirstEmail(env, p), code = accountsPasscodeEmail(p);
        const last = ((await sbGet(env, "invoice_automation_log", "key=like.accounts-first-email:*&select=created_at,detail&order=created_at.desc&limit=1")) || [])[0] || null;
        if (request.method === "GET") return json({ ok: true, ...mail, passcode_subject: code.subject, passcode_html: code.html, last_sent_at: last ? last.created_at : null, last_sent_to: last ? last.detail : null }, 200, request, env);
        if (request.method !== "POST") return json({ error: "Not found" }, 404, request, env);
        const b = await request.json().catch(() => ({}));
        const me = user.email || invDanielle(env);
        const sent = await sendEmail(env, b.test
          ? { to: me, subject: `Test: ${mail.subject}`, html: await wrapInBrandedBase(env, mail.html) }
          : { to: p.email_to, cc: accountsCc(env, p, me), subject: mail.subject, html: await wrapInBrandedBase(env, mail.html) });
        if (!sent.ok) return json({ error: "Couldn't send it. Please try again." }, 502, request, env);
        if (!b.test) await invLogOnce(env, `accounts-first-email:${Date.now()}`, p.email_to);
        const sentCode = await sendEmail(env, b.test
          ? { to: me, subject: `Test: ${code.subject}`, html: await wrapInBrandedBase(env, code.html) }
          : { to: p.email_to, cc: accountsCc(env, p, me), subject: code.subject, html: await wrapInBrandedBase(env, code.html) });
        // The first has gone by now, so say exactly what's missing.
        if (!sentCode.ok) return json({ error: "The first email went, but the passcode email didn't. Please send the passcode by hand." }, 502, request, env);
        return json({ ok: true, to: b.test ? me : p.email_to }, 200, request, env);
      }
      // The month-end email: what it says, and sending it now.
      if (path.endsWith("/invoicing/month-end")) {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!(await isManagement(env, user))) return json(MGMT_ONLY, 403, request, env);
        const p = await accountsPortalRow(env);
        if (!p) return json({ code: "needs_sql", error: "Run supabase/accounts_portal.sql in Supabase first." }, 503, request, env);
        const mail = await accountsMonthEndMail(env, p);
        if (!mail) return json({ error: "Couldn't build the email." }, 502, request, env);
        if (request.method === "GET") return json({ ok: true, ...mail, emails_on: p.emails_on }, 200, request, env);
        if (request.method !== "POST") return json({ error: "Not found" }, 404, request, env);
        const b = await request.json().catch(() => ({}));
        const me = user.email || invDanielle(env);
        const sent = await sendEmail(env, b.test
          ? { to: me, subject: `Test: ${mail.subject}`, html: await wrapInBrandedBase(env, mail.html) }
          : { to: p.email_to, cc: accountsCc(env, p, me), subject: mail.subject, html: await wrapInBrandedBase(env, mail.html) });
        if (!sent.ok) return json({ error: "Couldn't send it. Please try again." }, 502, request, env);
        return json({ ok: true, to: b.test ? me : p.email_to }, 200, request, env);
      }
      // The Month-end review as a PDF, downloaded or sent to Sam. The figures
      // come from the page, which is management only and has just read them.
      if (path.endsWith("/invoicing/month-review") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!(await isManagement(env, user))) return json(MGMT_ONLY, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const d = b.data || {};
        if (!/^\d{4}-\d{2}$/.test(String(d.month || "")) || !Array.isArray(d.months) || !d.revenueByMonth || !d.open) return json({ error: "Which month?" }, 400, request, env);
        let pdf;
        const browser = await puppeteer.launch(env.BROWSER);
        try {
          const page = await browser.newPage();
          await page.setContent(reviewHtml({ ...d, costs: Array.isArray(d.costs) ? d.costs : [] }), { waitUntil: "networkidle0" });
          pdf = await page.pdf({ printBackground: true, preferCSSPageSize: true });
        } catch (e) { return json({ error: "Couldn't build the PDF. Please try again." }, 502, request, env); }
        finally { await browser.close(); }
        const name = `TMKE-month-end-review-${d.month}.pdf`;
        if (b.action === "email") {
          const to = "samantha@themarketingexperts.co.uk";
          const month = invMonthLabel(d.month);
          const sent = await sendEmail(env, { to, cc: user.email || invDanielle(env), subject: `Month-end review, ${month}.`, attachments: [{ filename: name, content: bufToBase64(pdf), contentType: "application/pdf" }], html: await wrapInBrandedBase(env, `<div style="${EM_WRAP}"><h1 style="${EM_H1}">Month-End Review, ${invEsc(month)}.</h1><p style="${EM_P}">Hi Sam,</p><p style="${EM_P}">Here's the review for ${invEsc(month)}: revenue, costs and profit by sector, and what's still open. It's attached as a PDF.</p><p style="${EM_P}">Thank you,<br>Danielle</p></div>`) });
          if (!sent.ok) return json({ error: "Couldn't send it. Please try again." }, 502, request, env);
          return json({ ok: true, to }, 200, request, env);
        }
        return new Response(pdf, { status: 200, headers: { "Content-Type": "application/pdf", "Content-Disposition": `attachment; filename="${name}"`, ...corsHeaders(request, env) } });
      }
      // ---- Revenue: costs by sector, and where each kind of money goes -------
      if (path.endsWith("/revenue/costs")) {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!(await isManagement(env, user))) return json({ error: "Revenue is management only." }, 403, request, env);
        if (request.method === "POST") {
          const b = await request.json().catch(() => ({}));
          const SECT = ["social", "video", "studio", "agent"], thisYm = invToday().ym, by = user.email || null;
          const hdr = { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "resolution=merge-duplicates,return=minimal" };
          const pence = (v) => (v == null || v === "" ? null : Math.max(0, Math.round(Number(v))));
          const cur = await sbGet(env, "revenue_costs", "select=*");
          if (!cur) return json({ code: "needs_sql", error: "Run supabase/accounts_portal.sql in Supabase first." }, 503, request, env);
          const upserts = [], deletes = [];
          // A base change applies from this month on; earlier months keep the
          // base they had. A first-ever figure counts for every month, since
          // those months had nothing.
          for (const a of SECT) {
            const nb = b.base && b.base[a];
            if (!nb) continue;
            const staff = pence(nb.staff), tech = pence(nb.tech);
            const had = cur.filter((r) => r.kind === "base" && r.sector === a).sort((x, y) => (x.month < y.month ? 1 : -1))[0];
            if (had && had.staff_pence === staff && had.tech_pence === tech) continue;
            const hadReal = had && (had.staff_pence != null || had.tech_pence != null);
            upserts.push({ kind: "base", month: hadReal ? thisYm : (had ? had.month : "0000-00"), sector: a, staff_pence: staff, tech_pence: tech, updated_by: by, updated_at: new Date().toISOString() });
          }
          // A month that matches its base isn't different, so its row goes.
          const baseAfter = (ym, a) => {
            const fresh = upserts.filter((r) => r.kind === "base" && r.sector === a && r.month <= ym)[0];
            if (fresh) return fresh;
            return cur.filter((r) => r.kind === "base" && r.sector === a && r.month <= ym).sort((x, y) => (x.month < y.month ? 1 : -1))[0] || { staff_pence: null, tech_pence: null };
          };
          for (const ym of Object.keys(b.months || {})) {
            if (!/^\d{4}-\d{2}$/.test(ym)) continue;
            for (const a of SECT) {
              const nm = b.months[ym] && b.months[ym][a];
              if (!nm) continue;
              const staff = pence(nm.staff), tech = pence(nm.tech), base = baseAfter(ym, a);
              if (base.staff_pence === staff && base.tech_pence === tech) deletes.push(`kind=eq.month&month=eq.${ym}&sector=eq.${a}`);
              else upserts.push({ kind: "month", month: ym, sector: a, staff_pence: staff, tech_pence: tech, updated_by: by, updated_at: new Date().toISOString() });
            }
          }
          for (const qs of deletes) { const r = await fetch(`${env.SUPABASE_URL}/rest/v1/revenue_costs?${qs}`, { method: "DELETE", headers: hdr }); if (!r.ok) return json({ error: "Couldn't save that." }, 502, request, env); }
          if (upserts.length) { const r = await fetch(`${env.SUPABASE_URL}/rest/v1/revenue_costs?on_conflict=kind,month,sector`, { method: "POST", headers: hdr, body: JSON.stringify(upserts) }); if (!r.ok) return json({ error: "Couldn't save that." }, 502, request, env); }
          const rules = Object.entries(b.rules || {}).filter(([, v]) => [...SECT, "pick"].includes(v)).map(([source, sector]) => ({ source, sector, updated_by: by, updated_at: new Date().toISOString() }));
          if (rules.length) { const r = await fetch(`${env.SUPABASE_URL}/rest/v1/revenue_rules?on_conflict=source`, { method: "POST", headers: hdr, body: JSON.stringify(rules) }); if (!r.ok) return json({ error: "Couldn't save that." }, 502, request, env); }
        } else if (request.method !== "GET") return json({ error: "Not found" }, 404, request, env);
        const rows = await sbGet(env, "revenue_costs", "select=kind,month,sector,staff_pence,tech_pence");
        const rules = await sbGet(env, "revenue_rules", "select=source,sector");
        if (!rows || !rules) return json({ code: "needs_sql", error: "Run supabase/accounts_portal.sql in Supabase first." }, 503, request, env);
        return json({ ok: true, rows, rules: Object.fromEntries(rules.map((r) => [r.source, r.sector])), this_month: invToday().ym }, 200, request, env);
      }

      // ---- Admin: invoices (create draft / list / mark paid) -----------------
      // ---- Admin: the month-end chase list ----------------------------------
      //
      // What accounts has to confirm at the end of a month, in one table:
      // everything raised this month, plus anything still unpaid from any
      // month. Two questions get asked of it, so the rows carry which one they
      // are - has an inter-brand transfer actually been done, or has an
      // ordinary invoice landed in the bank.
      //
      // Inter-brand isn't on the invoice. It lives on the booking, as
      // payment_route brand_invoice (Fine & Country) or brand_invoice_teg (a
      // TEG sister brand), so the bookings are fetched and matched back. An
      // invoice with no booking is treated as ordinary, which is what a
      // manually raised one is.
      if (path.endsWith("/invoicing/report") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!(await isManagement(env, user))) return json(MGMT_ONLY, 403, request, env);

        // Default to the month we are in. YYYY-MM.
        const now = new Date();
        const raw = String(url.searchParams.get("month") || "").trim();
        const month = /^\d{4}-\d{2}$/.test(raw)
          ? raw
          : `${now.getUTCFullYear()}-${String(now.getUTCMonth() + 1).padStart(2, "0")}`;
        const [yy, mm] = month.split("-").map(Number);
        const monthStart = `${month}-01`;
        const nextMonth = mm === 12 ? `${yy + 1}-01-01` : `${yy}-${String(mm + 1).padStart(2, "0")}-01`;

        try {
          // sent and paid only. A draft has not left the building, so accounts
          // cannot reconcile it and listing it only invites questions about
          // money nobody has been asked for yet.
          const rows = await sbGet(env, "invoices",
            "select=id,number,booking_id,booking_source,bill_to_name,bill_to_email,client_name,total_pence,status,issued_date,due_date,paid_date,payment_method"
            + "&status=in.(sent,paid)&order=issued_date.desc&limit=1000")
            .catch(() => null)
            || await sbGet(env, "invoices",   // no client_name column yet
              "select=id,number,booking_id,booking_source,bill_to_name,bill_to_email,total_pence,status,issued_date,due_date,paid_date,payment_method"
              + "&status=in.(sent,paid)&order=issued_date.desc&limit=1000");

          const inMonth  = (v) => !!v.issued_date && v.issued_date >= monthStart && v.issued_date < nextMonth;
          const unpaid   = (v) => v.status !== "paid";
          const relevant = (rows || []).filter((v) => inMonth(v) || unpaid(v));

          // Who the work was FOR, which is not who it is billed to - one payer
          // can cover several clients, and an accounts team reconciling on
          // "billed to" alone has to fall back to matching invoice numbers.
          //
          // booking_id points at different tables depending on the strand, so
          // this is two lookups rather than one: shoots live in
          // videography_bookings, social clients in smm_leads.
          const idsFor = (src) => [...new Set(
            relevant.filter((v) => (v.booking_source || "videography") === src).map((v) => v.booking_id).filter(Boolean))];
          const vidIds = idsFor("videography");
          const smmIds = idsFor("smm");
          const inList = (ids) => ids.map((i) => `"${i}"`).join(",");
          const routeById = new Map();
          const clientById = new Map();
          if (vidIds.length) {
            try {
              const bks = await sbGet(env, "videography_bookings",
                `id=in.(${inList(vidIds)})&select=id,payment_route,fc_office,teg_brand,client_name,company`);
              for (const b of bks || []) {
                routeById.set(String(b.id), b);
                clientById.set(String(b.id), b.company || b.client_name || null);
              }
            } catch (_) { /* no route means "ordinary", which is the safe reading */ }
          }
          if (smmIds.length) {
            try {
              const leads = await sbGet(env, "smm_leads",
                `id=in.(${inList(smmIds)})&select=id,business,full_name,first_name,last_name`);
              for (const l of leads || []) {
                const name = l.business || l.full_name
                  || `${l.first_name || ""} ${l.last_name || ""}`.trim() || null;
                clientById.set(String(l.id), name);
              }
            } catch (_) { /* a missing name is worth less than a missing report */ }
          }

          const today = new Date().toISOString().slice(0, 10);
          const out = relevant.map((v) => {
            const bk = v.booking_id ? routeById.get(String(v.booking_id)) : null;
            const route = bk && bk.payment_route;
            const interBrand = route === "brand_invoice" || route === "brand_invoice_teg";
            const brand = route === "brand_invoice"
              ? ("Fine & Country" + (bk && bk.fc_office ? ` — ${bk.fc_office}` : ""))
              : route === "brand_invoice_teg"
                ? ("TEG" + (bk && bk.teg_brand ? ` — ${String(bk.teg_brand).replace(/_/g, " ")}` : ""))
                : null;
            const overdue = v.status !== "paid" && v.due_date && v.due_date < today
              ? Math.floor((Date.parse(today) - Date.parse(v.due_date)) / 86400000)
              : 0;
            return {
              id: v.id, number: v.number || "—",
              bill_to: v.bill_to_name || "—",
              // What the invoice says, or the booking if it predates the field.
              client: v.client_name || (v.booking_id && clientById.get(String(v.booking_id))) || null,
              strand: v.booking_source === "smm" ? "Social media" : v.booking_source === "videography" ? "Videography" : null,
              total_pence: Number(v.total_pence) || 0,
              status: v.status, issued_date: v.issued_date, due_date: v.due_date, paid_date: v.paid_date,
              inter_brand: interBrand, brand,
              raised_this_month: inMonth(v),
              outstanding: unpaid(v),
              days_overdue: overdue,
            };
          });

          const sum = (f) => out.filter(f).reduce((t, r) => t + r.total_pence, 0);
          return json({
            ok: true, month,
            payments: out,
            totals: {
              raised: sum((r) => r.raised_this_month),
              outstanding: sum((r) => r.outstanding),
              outstanding_inter_brand: sum((r) => r.outstanding && r.inter_brand),
              outstanding_other: sum((r) => r.outstanding && !r.inter_brand),
            },
          }, 200, request, env);
        } catch (e) {
          console.error("invoicing/report", String((e && e.message) || e).slice(0, 200));
          return json({ error: "Couldn't build the report." }, 502, request, env);
        }
      }

      if (path.endsWith("/invoicing/invoices") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        /* Abbie, Jack and the team see the invoices for the client or shoot
           they have open, never the ledger (Danielle, 28 Oct 2026). */
        if (!url.searchParams.get("booking_id") && !(await isManagement(env, user))) return json(MGMT_ONLY, 403, request, env);
        const extra = url.searchParams.get("booking_id") ? `&booking_id=eq.${encodeURIComponent(url.searchParams.get("booking_id"))}` : "";
        const tail = `${extra}&order=created_at.desc&limit=300`;
        const BASE = "id,number,bill_to_name,bill_to_email,cc_email,total_pence,status,issued_date,due_date,paid_date,payment_method,billing_month,created_at";
        // PostgREST rejects the whole query for one unknown column, so if
        // supabase/invoicing_stripe.sql hasn't run yet, asking for pay_by_card
        // would blank the entire invoice list rather than just omitting a badge.
        // recurring_id tells a client's first monthly invoice from their onboarding fee.
        let rows = await sbGet(env, "invoices", `select=${BASE},sent_to,sent_at,payment_ref,pay_by_card,terms_days,release_on_payment,recurring_id${tail}`);
        if (!rows) rows = await sbGet(env, "invoices", `select=${BASE},sent_to,sent_at,payment_ref,pay_by_card,terms_days,release_on_payment${tail}`);
        if (!rows) rows = await sbGet(env, "invoices", `select=${BASE},sent_to,payment_ref,pay_by_card,terms_days,release_on_payment${tail}`);
        if (!rows) rows = (await sbGet(env, "invoices", `select=${BASE}${tail}`)) || [];
        return json({ ok: true, invoices: rows }, 200, request, env);
      }
      // Ensure a Direct Debit client's ghost invoice exists for the current month
      // (called when their Invoicing tab opens), then return their invoice list.
      if (path.endsWith("/invoicing/dd/ensure") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const bookingId = String((b && b.booking_id) || "").trim();
        if (!bookingId) return json({ error: "Missing booking_id." }, 400, request, env);
        const lead = (await sbGet(env, "smm_leads", `id=eq.${encodeURIComponent(bookingId)}&select=*`))?.[0];
        if (lead && lead.direct_debit) { try { await ensureDdInvoice(env, lead, ymNow()); } catch (_) {} }
        const rows = (await sbGet(env, "invoices", `booking_id=eq.${encodeURIComponent(bookingId)}&select=id,number,bill_to_name,bill_to_email,total_pence,status,issued_date,due_date,paid_date,payment_method,billing_month,created_at&order=created_at.desc&limit=300`)) || [];
        return json({ ok: true, invoices: rows }, 200, request, env);
      }
      if (path.endsWith("/invoicing/invoices") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        if (!(await isManagement(env, user))) {
          // Jack, on a Videography shoot that exists, and nothing else.
          const bid = String((b && b.booking_id) || "");
          const shoot = isVideographyInvoicer(user.email) && (b.booking_source || "videography") === "videography" && /^[0-9a-f-]{36}$/i.test(bid)
            && (await sbGet(env, "videography_bookings", `id=eq.${bid}&select=id&limit=1`))?.[0];
          if (!shoot) return json(MGMT_ONLY, 403, request, env);
          b.booking_source = "videography";
        }
        const made = await createInvoiceDraft(env, b, user.email || null);
        if (!made.ok) return json({ error: made.error }, made.code || 502, request, env);
        return json({ ok: true, invoice: made.invoice }, 200, request, env);
      }
      if (path.endsWith("/invoicing/invoices") && request.method === "PATCH") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String((b && b.id) || "").trim();
        const status = ["draft", "sent", "paid", "void"].includes(b && b.status) ? b.status : null;
        // Jack may change the words of a Videography draft, and void a draft he's
        // replaced (editing one saves a new one); anything sent stays with management.
        if (!(await isManagement(env, user))) {
          const own = isVideographyInvoicer(user.email) && await isVideographyInvoice(env, id);
          const draftNow = own && (await sbGet(env, "invoices", `id=eq.${encodeURIComponent(id)}&select=status`))?.[0]?.status === "draft";
          const ok = draftNow && ((!status && b && Array.isArray(b.line_items)) || status === "void");
          if (!ok) return json(MGMT_ONLY, 403, request, env);
        }

        // Editing the CONTENT of an invoice, as opposed to its status. Only
        // allowed while it is still a draft: once an invoice has been sent the
        // client holds a numbered document, and quietly changing ours would
        // leave two different papers claiming to be the same invoice. A sent
        // invoice is reissued instead.
        if (!status && b && Array.isArray(b.line_items)) {
          const cur = (await sbGet(env, "invoices", `id=eq.${encodeURIComponent(id)}&select=status`))?.[0];
          if (!cur) return json({ error: "Invoice not found." }, 404, request, env);
          if (cur.status !== "draft") return json({ error: "Only a draft can be edited. Reissue a sent invoice instead." }, 409, request, env);

          const items = b.line_items
            .map((it) => ({ description: String((it && it.description) || "").trim(), qty: it && it.qty != null ? Number(it.qty) : 1, unit_pence: Math.round(Number((it && it.unit_pence) || 0)) }))
            .filter((it) => it.description || it.unit_pence);
          if (!items.length) return json({ error: "Add at least one line item." }, 400, request, env);

          const st2 = (await sbGet(env, "invoice_settings", "id=eq.1&select=vat_rate"))?.[0] || {};
          const vatRate2 = st2.vat_rate != null ? Number(st2.vat_rate) : 20;
          const subtotal2 = items.reduce((sum, it) => sum + it.unit_pence * (it.qty || 1), 0);
          const vat2 = Math.round(subtotal2 * vatRate2 / 100);
          const patch2 = {
            line_items: items, subtotal_pence: subtotal2, vat_pence: vat2, total_pence: subtotal2 + vat2,
            bill_to_name: (b.bill_to_name || "").trim() || null,
            client_name: b.client_name !== undefined ? (String(b.client_name || "").trim() || null) : undefined,
            bill_to_email: b.bill_to_email || null,
            bill_to_address: b.bill_to_address || null,
            cc_email: b.cc_email !== undefined ? (String(b.cc_email || "").trim() || null) : undefined,
            issued_date: b.issued_date || null, due_date: b.due_date || null,
            notes: b.notes || null,
            pay_by_card: !!b.pay_by_card,
            release_on_payment: !!b.release_on_payment,
            terms_days: (b.terms_days != null && b.terms_days !== "") ? Math.max(0, Math.round(Number(b.terms_days))) : null,
            recurring_id: b.recurring_id !== undefined ? (b.recurring_id || null) : undefined,
            billing_month: b.billing_month !== undefined ? (/^\d{4}-\d{2}$/.test(String(b.billing_month || "")) ? b.billing_month : null) : undefined,
          };
          Object.keys(patch2).forEach((k) => patch2[k] === undefined && delete patch2[k]);
          let pr2 = await sbPatch(env, "invoices", `id=eq.${encodeURIComponent(id)}`, patch2);
          if (!pr2.ok) {
            // The optional columns again - save the edit rather than lose it.
            const { terms_days: _t, release_on_payment: _r, pay_by_card: _p, client_name: _c, recurring_id: _ri, ...lean } = patch2;
            pr2 = await sbPatch(env, "invoices", `id=eq.${encodeURIComponent(id)}`, lean);
            if (!pr2.ok) return json({ error: "Couldn't save the changes." }, 502, request, env);
          }
          const updated = (await sbGet(env, "invoices", `id=eq.${encodeURIComponent(id)}&select=*`))?.[0] || null;
          return json({ ok: true, invoice: updated }, 200, request, env);
        }

        if (!id || !status) return json({ error: "Missing id or status." }, 400, request, env);
        const patch = { status };
        if (status === "paid") patch.paid_date = (b && b.paid_date) || new Date().toISOString().slice(0, 10);
        await fetch(`${env.SUPABASE_URL}/rest/v1/invoices?id=eq.${encodeURIComponent(id)}`, {
          method: "PATCH", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=minimal" },
          body: JSON.stringify(patch),
        });
        // When marked paid, re-render the saved PDF so the stored copy (and the
        // client's future hub view) shows the "Paid · <date>" stamp.
        if (status === "paid") await invoicePaidEffects(env, id, user.email || "admin");
        // A voided invoice has nothing left to approve: its request stops showing as Waiting (10 Nov 2026).
        if (status === "void") await sbPatch(env, "invoice_approvals", `invoice_id=eq.${encodeURIComponent(id)}&status=eq.pending`, { status: "superseded" });
        return json({ ok: true }, 200, request, env);
      }
      // ---- Management: the monthly invoicing checklist + recurring invoices --
      if (path.endsWith("/invoicing/monthly") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!(await isManagement(env, user))) return json(MGMT_ONLY, 403, request, env);
        const want = String(url.searchParams.get("from") || "");
        const from = /^\d{4}-\d{2}$/.test(want) ? want : ymAdd(londonToday().ym, -5);
        try { return json({ ok: true, ...(await monthlyInvoiceChecklist(env, from, 6)) }, 200, request, env); }
        catch (e) { return json({ error: `Couldn't build the checklist: ${e.message || e}` }, 502, request, env); }
      }
      if (path.endsWith("/invoicing/month-note") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!(await isManagement(env, user))) return json(MGMT_ONLY, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const kind = b.row_kind === "recurring" ? "recurring" : b.row_kind === "social" ? "social" : null;
        const rowId = String(b.row_id || "").trim(), month = String(b.month || "");
        if (!kind || !rowId || !/^\d{4}-\d{2}$/.test(month)) return json({ error: "Which client and month?" }, 400, request, env);
        const note = String(b.note || "").trim(), skip = !!b.skip;
        const hdr = { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json" };
        const where = `row_kind=eq.${kind}&row_id=eq.${encodeURIComponent(rowId)}&month=eq.${month}`;
        // Nothing left to say: the note goes.
        const r = !note && !skip
          ? await fetch(`${env.SUPABASE_URL}/rest/v1/invoice_month_notes?${where}`, { method: "DELETE", headers: hdr })
          : await fetch(`${env.SUPABASE_URL}/rest/v1/invoice_month_notes?on_conflict=row_kind,row_id,month`, { method: "POST", headers: { ...hdr, Prefer: "resolution=merge-duplicates" },
              body: JSON.stringify({ row_kind: kind, row_id: rowId, month, note: note || null, skip, updated_by: user.email || null, updated_at: new Date().toISOString() }) });
        if (!r.ok) {
          const t = await r.text().catch(() => "");
          return json({ error: /invoice_month_notes/.test(t) ? "Run supabase/invoice_month_notes.sql first." : "Couldn't save the note." }, 502, request, env);
        }
        return json({ ok: true }, 200, request, env);
      }
      // ---- Allocate an invoice already sent to a recurring invoice's month ----
      // GET: the invoices that could be it (sent or paid, not raised from a
      // booking). POST: link one, for good: from then on the checklist follows
      // that invoice, so paying it ticks Paid (Danielle, 30 Sep 2026).
      if (path.endsWith("/invoicing/allocate") && (request.method === "GET" || request.method === "POST")) {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!(await isManagement(env, user))) return json(MGMT_ONLY, 403, request, env);
        const hdr = { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json" };
        if (request.method === "GET") {
          const r = await fetch(`${env.SUPABASE_URL}/rest/v1/invoices?status=in.(sent,paid)&booking_id=is.null&select=id,number,bill_to_name,bill_to_email,client_name,total_pence,issued_date,status,billing_month,recurring_id,line_items&order=issued_date.desc.nullslast,created_at.desc&limit=300`, { headers: hdr });
          if (!r.ok) {
            const t = await r.text().catch(() => "");
            return json({ error: /recurring_id/.test(t) ? "Run supabase/invoice_month_notes.sql first." : "Couldn't list the invoices." }, 502, request, env);
          }
          const rows = (await r.json()).map((iv) => ({ ...iv, line: ((iv.line_items || [])[0] || {}).description || "", line_items: undefined }));
          return json({ ok: true, invoices: rows }, 200, request, env);
        }
        const b = await request.json().catch(() => ({}));
        const id = String(b.invoice_id || "").trim(), rec = String(b.recurring_id || "").trim(), month = String(b.month || "");
        if (!id || !rec || !/^\d{4}-\d{2}$/.test(month)) return json({ error: "Which invoice, and for which month?" }, 400, request, env);
        const r = await fetch(`${env.SUPABASE_URL}/rest/v1/invoices?id=eq.${encodeURIComponent(id)}&booking_id=is.null`, { method: "PATCH", headers: { ...hdr, Prefer: "return=representation" }, body: JSON.stringify({ recurring_id: rec, billing_month: month }) });
        const done = r.ok ? await r.json().catch(() => []) : [];
        if (!r.ok || !done.length) return json({ error: "Couldn't link that invoice." }, 502, request, env);
        return json({ ok: true }, 200, request, env);
      }
      // Raise a recurring invoice for a month by hand, from its own setup, and
      // return the draft for the email review (Dani, 10 Nov 2026). A month that
      // needs a number (the TPE hub's agents) takes it here and keeps it.
      if (path.endsWith("/invoicing/recurring/raise") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!(await isManagement(env, user))) return json(MGMT_ONLY, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String(b.recurring_id || "").trim(), ym = String(b.month || "");
        if (!/^[0-9a-f-]{36}$/i.test(id) || !/^\d{4}-\d{2}$/.test(ym)) return json({ error: "Which invoice, and for which month?" }, 400, request, env);
        const r = (await sbGet(env, "recurring_invoices", `id=eq.${id}&select=*`))?.[0];
        if (!r) return json({ error: "That regular invoice isn't there any more." }, 404, request, env);
        const had = (await sbGet(env, "invoices", `recurring_id=eq.${id}&billing_month=eq.${ym}&status=neq.void&select=*&order=created_at.desc`)) || [];
        const sentOne = had.find((v) => v.status !== "draft");
        if (sentOne) return json({ error: `${sentOne.number} has already gone for ${invMonthLabel(ym)}.` }, 409, request, env);
        // A draft for the month already: carry on with that one.
        if (had[0]) return json({ ok: true, invoice: had[0], existing: true }, 200, request, env);
        let qty = null;
        if (r.quantity_label) {
          const typed = b.qty != null && String(b.qty).trim() !== "" ? Math.round(Number(b.qty)) : null;
          if (typed != null && !(typed >= 0)) return json({ error: `The ${String(r.quantity_label).toLowerCase()} should be a number.` }, 400, request, env);
          if (typed != null) {
            await fetch(`${env.SUPABASE_URL}/rest/v1/recurring_quantities?on_conflict=recurring_id,month`, { method: "POST", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "resolution=merge-duplicates,return=minimal" }, body: JSON.stringify({ recurring_id: id, month: ym, qty: typed, entered_by: user.email || null, entered_at: new Date().toISOString() }) });
            qty = typed;
          } else {
            const q = (await sbGet(env, "recurring_quantities", `recurring_id=eq.${id}&month=eq.${ym}&select=qty`))?.[0];
            if (!q) return json({ error: `Add the ${String(r.quantity_label).toLowerCase()} for ${invMonthLabel(ym)} first.`, needs: r.quantity_label }, 400, request, env);
            qty = Number(q.qty);
          }
        }
        const st = (await sbGet(env, "invoice_settings", "id=eq.1&select=*"))?.[0] || {};
        const made = await raiseRecurringDraft(env, st, r, ym, qty, user.email || null);
        if (!made.ok) return json({ error: made.error }, made.code || 502, request, env);
        return json({ ok: true, invoice: made.invoice }, 200, request, env);
      }
      if (path.endsWith("/invoicing/recurring") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const r = await fetch(`${env.SUPABASE_URL}/rest/v1/recurring_invoices?active=eq.true&select=*&order=name.asc`, { headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}` } });
        return json({ ok: true, recurring: r.ok ? await r.json() : [] }, 200, request, env);
      }
      if (path.endsWith("/invoicing/recurring") && (request.method === "POST" || request.method === "DELETE")) {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!(await isManagement(env, user))) return json(MGMT_ONLY, 403, request, env);
        const hdr = { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=representation" };
        if (request.method === "DELETE") {
          const id = String(url.searchParams.get("id") || "").trim();
          if (!id) return json({ error: "Which one?" }, 400, request, env);
          // Stopped rather than deleted: its months stay readable if it's needed again.
          const r = await fetch(`${env.SUPABASE_URL}/rest/v1/recurring_invoices?id=eq.${encodeURIComponent(id)}`, { method: "PATCH", headers: hdr, body: JSON.stringify({ active: false }) });
          return r.ok ? json({ ok: true }, 200, request, env) : json({ error: "Couldn't remove it." }, 502, request, env);
        }
        const b = await request.json().catch(() => ({}));
        const row = {
          name: String(b.name || "").trim(), contact_name: String(b.contact_name || "").trim() || null,
          amount_pence: b.amount_pence != null && b.amount_pence !== "" ? Math.round(Number(b.amount_pence)) : null,
          match_email: String(b.match_email || "").trim().toLowerCase(), match_text: String(b.match_text || "").trim() || null,
          start_month: /^\d{4}-\d{2}$/.test(String(b.start_month || "")) ? b.start_month : null,
        };
        // Automatic sending (Danielle, 21 Oct 2026): sent only when these
        // come, so an older form saving the basic fields leaves them alone.
        if (b.auto !== undefined) {
          const a = b.auto || {}, t = (x) => String(x || "").trim() || null;
          Object.assign(row, {
            auto_send: !!a.auto_send,
            day_of_month: a.day_of_month ? Math.min(28, Math.max(1, Math.round(Number(a.day_of_month)))) : null,
            frequency: ["monthly", "quarterly", "6monthly", "yearly", "oneoff"].includes(a.frequency) ? a.frequency : "monthly",
            end_month: /^\d{4}-\d{2}$/.test(String(a.end_month || "")) ? a.end_month : null,
            bill_to_name: t(a.bill_to_name), bill_to_email: t(a.bill_to_email), cc_email: t(a.cc_email), bill_to_address: t(a.bill_to_address),
            terms_days: a.terms_days !== "" && a.terms_days != null ? Math.max(0, Math.round(Number(a.terms_days))) : null,
            line_items: t(a.line) ? [{ description: t(a.line), qty: 1, unit_pence: row.amount_pence || 0 }] : null,
          });
          if (row.auto_send && !row.day_of_month) return json({ error: "Say which day of the month it goes out." }, 400, request, env);
          if (row.auto_send && !row.amount_pence) return json({ error: "Add the amount before it can send itself." }, 400, request, env);
        }
        if (!row.name || !row.match_email) return json({ error: "A name and the address the invoice goes to, please." }, 400, request, env);
        // From a social media client's file (Dani, 5 Nov 2026): the row is
        // theirs, card payment is set there, and a new one is sent the same way
        // as the other social clients'. No per-invoice approver: Abbie's ticks
        // on Monthly invoices are the approval (22 Oct, invoicing_automation_3.sql).
        if (b.pay_by_card !== undefined) row.pay_by_card = !!b.pay_by_card;
        if (b.pays_ahead !== undefined) row.pays_ahead = !!b.pays_ahead;
        if (b.due_day !== undefined && b.due_day !== "" && b.due_day != null) row.due_day = Math.min(28, Math.max(1, Math.round(Number(b.due_day))));
        if (b.social && b.lead_id) {
          row.kind = "social"; row.lead_id = String(b.lead_id);
          if (!b.id) {
            const sib = (await sbGet(env, "recurring_invoices", "active=eq.true&kind=eq.social&select=approver_email,template,due_day,bcc_email&order=created_at.asc&limit=1"))?.[0];
            if (sib) for (const k of ["template", "due_day", "bcc_email"]) if (sib[k] != null && row[k] === undefined) row[k] = sib[k];
          }
        }
        const r = b.id
          ? await fetch(`${env.SUPABASE_URL}/rest/v1/recurring_invoices?id=eq.${encodeURIComponent(b.id)}`, { method: "PATCH", headers: hdr, body: JSON.stringify(row) })
          : await fetch(`${env.SUPABASE_URL}/rest/v1/recurring_invoices`, { method: "POST", headers: hdr, body: JSON.stringify(row) });
        if (!r.ok) {
          const t = await r.text().catch(() => "");
          if (/pays_ahead/.test(t)) return json({ error: "Run supabase/recurring_pays_ahead.sql first: it adds Pays a month ahead." }, 502, request, env);
          return json({ error: /auto_send|day_of_month|line_items|bill_to_|frequency|end_month|terms_days/.test(t) ? "Run supabase/invoicing_automation.sql first." : /recurring_invoices/.test(t) ? "Run supabase/recurring_invoices.sql first." : "Couldn't save it." }, 502, request, env);
        }
        return json({ ok: true }, 200, request, env);
      }
      // ---- Admin: delete an invoice (hard delete + its PDF) ------------------
      if (path.endsWith("/invoicing/invoices") && request.method === "DELETE") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const id = String(url.searchParams.get("id") || "").trim();
        if (!id) return json({ error: "Missing id." }, 400, request, env);
        const inv = (await sbGet(env, "invoices", `id=eq.${encodeURIComponent(id)}&select=id,number,status`))?.[0];
        // Management only, drafts included (Danielle, 28 Oct 2026): the team
        // can see and resend invoices, not change them.
        // Jack may delete a Videography draft, nothing that has been sent.
        if (!(await isManagement(env, user)) && !(isVideographyInvoicer(user.email) && inv && inv.status === "draft" && await isVideographyInvoice(env, id))) return json(MGMT_ONLY, 403, request, env);
        await fetch(`${env.SUPABASE_URL}/rest/v1/invoices?id=eq.${encodeURIComponent(id)}`, {
          method: "DELETE", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}` },
        });
        if (inv && inv.number) { try { await env.BUCKET.delete(`invoices/${inv.number}.pdf`); } catch (_) {} }
        return json({ ok: true }, 200, request, env);
      }
      // ---- Admin: void an invoice (email accounts + admin, then delete) ------
      if (path.endsWith("/invoicing/invoices/void") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!(await isManagement(env, user))) return json(MGMT_ONLY, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String((b && b.id) || "").trim();
        const reason = String((b && b.reason) || "").trim();
        if (!id) return json({ error: "Missing id." }, 400, request, env);
        const inv = (await sbGet(env, "invoices", `id=eq.${encodeURIComponent(id)}&select=*`))?.[0];
        if (!inv) return json({ error: "Invoice not found." }, 404, request, env);
        const st = (await sbGet(env, "invoice_settings", "id=eq.1&select=*"))?.[0] || {};
        const esc = (x) => String(x ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
        const html = `<div style="${EM_WRAP}">
          <p style="margin:0 0 14px"><strong>Invoice ${esc(inv.number)} has been voided</strong> and removed from the system - please disregard it.</p>
          <table style="border-collapse:collapse;margin:0 0 14px;font-size:12px">
            <tr><td style="padding:2px 18px 2px 0;color:#7a6b70">Client</td><td style="padding:2px 0"><strong>${esc(inv.bill_to_name || "")}</strong></td></tr>
            <tr><td style="padding:2px 18px 2px 0;color:#7a6b70">Amount</td><td style="padding:2px 0">${money(inv.total_pence)}</td></tr>
            ${inv.billing_month ? `<tr><td style="padding:2px 18px 2px 0;color:#7a6b70">Period</td><td style="padding:2px 0">${esc(inv.billing_month)}</td></tr>` : ""}
            <tr><td style="padding:2px 18px 2px 0;color:#7a6b70">Voided by</td><td style="padding:2px 0">${esc(user.email || "an admin")}</td></tr>
          </table>
          <p style="margin:0 0 6px;color:#7a6b70">Reason</p>
          <p style="margin:0;padding:11px 14px;background:#f4f2f1;border-left:3px solid #371e28;border-radius:4px">${esc(reason || "-")}</p>
        </div>`;
        const voidMail = invoiceMailTo(st.accounts_cc_email || DD_DEFAULT_RECIPIENT, user.email || null);
        await sendEmail(env, {
          to: voidMail.to,
          cc: voidMail.cc,
          subject: `Invoice ${inv.number} voided - ${inv.bill_to_name || ""}`,
          html: await wrapInBrandedBase(env, html),
        });
        await fetch(`${env.SUPABASE_URL}/rest/v1/invoices?id=eq.${encodeURIComponent(id)}`, {
          method: "DELETE", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}` },
        });
        if (inv.number) { try { await env.BUCKET.delete(`invoices/${inv.number}.pdf`); } catch (_) {} }
        return json({ ok: true }, 200, request, env);
      }

      // ---- Admin: set an SMM client's status (active / paused / ended) --------
      // Persists on the lead and swaps the SMM-Status tag on their CRM contact.
      // Active also lifts their lifecycle to Customer (per the tagging framework).
      // ---- Admin: delete an SMM lead/card (cascade: invoices, thread, docs) --
      // Mostly for clearing test cards before go-live.
      if (path.endsWith("/smm/lead") && request.method === "DELETE") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const id = String(url.searchParams.get("id") || "").trim();
        if (!id) return json({ error: "Missing id." }, 400, request, env);
        const hdr = { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}` };
        // Delete any invoices + their PDFs first.
        try {
          const invs = (await sbGet(env, "invoices", `booking_id=eq.${encodeURIComponent(id)}&select=number`)) || [];
          for (const iv of invs) { if (iv.number) { try { await env.BUCKET.delete(`invoices/${iv.number}.pdf`); } catch (_) {} } }
        } catch (_) {}
        for (const t of ["invoices", "booking_documents", "booking_messages"]) {
          try { await fetch(`${env.SUPABASE_URL}/rest/v1/${t}?booking_id=eq.${encodeURIComponent(id)}`, { method: "DELETE", headers: hdr }); } catch (_) {}
        }
        await fetch(`${env.SUPABASE_URL}/rest/v1/smm_leads?id=eq.${encodeURIComponent(id)}`, { method: "DELETE", headers: hdr });
        return json({ ok: true }, 200, request, env);
      }
      if (path.endsWith("/smm/status") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const leadId = b && b.lead_id;
        // Internal: one of us, run as a client but never invoiced (Danielle, 19 Oct).
        const status = ["active", "paused", "ended", "internal"].includes(b && b.status) ? b.status : null;
        if (!leadId || !status) return json({ error: "Missing lead or status." }, 400, request, env);
        const rows = await sbGet(env, "smm_leads", `id=eq.${encodeURIComponent(leadId)}&select=id,email,full_name,first_name,last_name,business,account_user_id`);
        const lead = rows && rows[0];
        if (!lead) return json({ error: "Lead not found." }, 404, request, env);
        // Persist the status on the lead.
        await fetch(`${env.SUPABASE_URL}/rest/v1/smm_leads?id=eq.${encodeURIComponent(leadId)}`, {
          method: "PATCH", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=minimal" },
          body: JSON.stringify(status === "ended" ? { client_status: status, pipeline_stage: "lost" } : { client_status: status }),
        });
        // Reflect on the CRM contact: one SMM-Status tag at a time, and
        // everything else the card knows (syncSmmContact).
        const crm = await syncSmmContact(env, leadId);
        return json({ ok: true, crm }, 200, request, env);
      }

      // ---- Admin: book a sales meeting for an SMM lead --------------------
      // Saves meeting_at + moves the lead to Meeting set; optionally sends the
      // client a diary invite (calendar event on the SMM manager's diary + ICS).
      if (path.endsWith("/smm/meeting") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const leadId = b && b.lead_id;
        const date = b && b.date, start = b && b.start;
        if (!leadId || !date || !start) return json({ error: "Missing lead, date or time." }, 400, request, env);
        const rows = await sbGet(env, "smm_leads", `id=eq.${encodeURIComponent(leadId)}&select=id,email,full_name,first_name,account_user_id,phone,social_media_manager,ms_event_id,meeting_at`);
        const lead = rows && rows[0];
        if (!lead) return json({ error: "Lead not found." }, 404, request, env);
        const meetingAt = `${date}T${start}:00`;
        // How the call happens (Danielle, 5 Nov 2026): a Teams call by default,
        // or a phone call, or in person somewhere.
        const how = ["teams", "phone", "in_person"].includes(b.mode) ? b.mode : "teams";
        const where = String(b.location || "").trim().slice(0, 200);
        const howLabel = how === "teams" ? "Teams call" : how === "phone" ? "Phone call" : "In person";
        // hello@ can't make Teams links (no licence), so the link is added later
        // from the file and the invite updated (Danielle, 5 Nov 2026). Set before
        // the invite's wording, which reads it.
        const autoTeams = !!env.SMM_MEETING_UPN;
        // What the invite says (Danielle, 5 Nov 2026; wording by the copywriter):
        // which call it is, how we'll meet, how to move it.
        const callKind = ["discovery", "pricing", "onboarding"].includes(b.call) ? b.call : "meeting";
        const inviteBody = (() => {
          const e = (v) => String(v ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
          const mins = parseInt(b.duration || "30", 10);
          const what = {
            discovery: `Thanks for booking a call with us.</p><p>We'll spend ${mins} minutes getting to know your business, what you're looking to achieve with your social media and where we might be able to help. It's also a chance for us both to see whether we're the right fit.`,
            pricing: `Thanks for taking the time to read through our proposal. Over ${mins} minutes, we'll talk you through the package, the price and the onboarding fee, and answer any questions you have. We'll also talk about when you'd like to start.`,
            onboarding: `Welcome to The Marketing Experts. Over ${mins} minutes, we'll go through how we'll work together: access to your accounts, your brand, who we'll be speaking to and what happens in your first month.`,
            meeting: `We're looking forward to speaking with you. We've set aside ${mins} minutes, and if there's anything you'd like us to cover, reply to this invite and let us know.`,
          }[callKind];
          const meet = how === "teams" ? (autoTeams ? "We'll meet on Microsoft Teams. You'll find the joining details in this invite, but if you have any trouble accessing them, just let us know." : `<span data-teams-line>We'll meet on Microsoft Teams. We'll update this invite with your joining link before the call.</span>`)
            : how === "phone" ? (lead.phone ? `We'll call you on ${e(lead.phone)}.` : "We'll give you a call at the time booked.")
            : `We'll see you at ${e(where || "the place we agreed")}.`;
          return [`Hi ${e(lead.first_name || "there")},`, what, meet, "If you need to rearrange, simply reply to this invite or email us at hello@tmke.co.uk.", "Speak soon,", "The Team at The Marketing Experts"].map((x) => `<p>${x}</p>`).join("");
        })();
        const callTitle = { discovery: "Discovery call", pricing: "Pricing call", onboarding: "Onboarding call", meeting: "Meeting" }[callKind];
        // Advance to Meeting set only when asked (a booking for a later-stage
        // client just records the meeting without moving them back).
        const meetingPatch = { meeting_at: meetingAt };
        if (b.set_stage !== false) meetingPatch.pipeline_stage = "meeting_set";
        await fetch(`${env.SUPABASE_URL}/rest/v1/smm_leads?id=eq.${encodeURIComponent(leadId)}`, {
          method: "PATCH", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=minimal" },
          body: JSON.stringify(meetingPatch),
        });
        // Meetings booked from the file are organised from a mailbox with Teams
        // (Danielle, 5 Nov 2026: hello@ has no Teams licence), with hello@ as a
        // guest so its calendar still has every call.
        const cal = env.SMM_MEETING_UPN || env.SMM_MANAGER_UPN;
        const hello = env.SMM_MANAGER_UPN;

        const dur = parseInt(b.duration || "30", 10);
        const endHm = minToHm(hmToMin(start) + dur);
        const dateNice = (() => { try { return new Date(`${date}T12:00:00`).toLocaleDateString("en-GB", { weekday: "long", day: "numeric", month: "long", year: "numeric" }); } catch (_) { return date; } })();
        let invited = false, joinUrl = "", teamsFailed = false, teamsWhy = "", moved = false;
        const moving = !!(b.replace && lead.ms_event_id);
        if (b.send_invite && cal && lead.email) {
          try {
            // The event in hello@'s Outlook calendar: Outlook sends the invite
            // itself, with the Teams link on it for a Teams call.
            const event = {
              // Their name in it too, so hello@'s calendar says who it's with.
              subject: `${callTitle}: The Marketing Experts and ${lead.full_name || lead.email}.`,
              body: { contentType: "HTML", content: inviteBody },
              start: { dateTime: `${date}T${start}:00`, timeZone: "Europe/London" },
              end: { dateTime: `${date}T${endHm}:00`, timeZone: "Europe/London" },
              attendees: [
                { emailAddress: { address: lead.email, name: lead.full_name || "" }, type: "required" },
                ...(hello && hello.toLowerCase() !== cal.toLowerCase() && hello.toLowerCase() !== String(lead.email || "").toLowerCase() ? [{ emailAddress: { address: hello, name: "TMKE" }, type: "required" }] : []),
                // The person who manages the client (Managed by), at their own
                // address. Abigail is left off while Danielle tests (SMM_INVITE_MANAGER).
                ...(() => {
                  const name = String(lead.social_media_manager || "").trim();
                  const addr = SMM_MANAGER_EMAILS[name];
                  if (!addr || addr.toLowerCase() === cal.toLowerCase() || addr.toLowerCase() === String(lead.email || "").toLowerCase()) return [];
                  if (name === "Abigail Saunders" && !SMM_INVITE_MANAGER) return [];
                  return [{ emailAddress: { address: addr, name }, type: "required" }];
                })(),
              ],
              ...(how === "teams" ? (autoTeams ? { isOnlineMeeting: true, onlineMeetingProvider: "teamsForBusiness" } : { isOnlineMeeting: false, location: { displayName: "Microsoft Teams (link to follow)" } })
                : { isOnlineMeeting: false, location: { displayName: how === "phone" ? `Phone call${lead.phone ? ": we'll call " + lead.phone : ""}` : (where || "In person") } }),
            };
            let made;
            // Moving a call (Danielle, 5 Nov 2026): the same Outlook meeting is
            // updated, so everyone's diary moves it rather than getting a second
            // one. If it can't be updated, the old one is cancelled first.
            if (moving) {
              try { made = await graph(env, "PATCH", `/users/${encodeURIComponent(cal)}/events/${encodeURIComponent(lead.ms_event_id)}`, event); moved = true; }
              catch (_) {
                // Not this organiser's (booked from hello@ before the switch): cancel it there.
                for (const box of [cal, hello].filter(Boolean)) { try { await graph(env, "POST", `/users/${encodeURIComponent(box)}/events/${encodeURIComponent(lead.ms_event_id)}/cancel`, { comment: "This call has moved; a new invite follows." }); break; } catch (_) {} }
              }
            }
            if (!made) {
              try { made = await graph(env, "POST", `/users/${encodeURIComponent(cal)}/events`, event); }
              catch (e) {
                // A mailbox that can't host Teams still gets the meeting, just without the link.
                if (how !== "teams") throw e;
                teamsFailed = true;
                const plain = { ...event, isOnlineMeeting: false }; delete plain.onlineMeetingProvider;
                made = await graph(env, "POST", `/users/${encodeURIComponent(cal)}/events`, plain);
              }
            }
            // Kept, so the next move or cancel finds this meeting, and the file
            // knows a Teams link still needs adding (supabase/smm_meeting_link.sql).
            if (made && made.id) {
              const hdrs = { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=minimal" };
              const url = `${env.SUPABASE_URL}/rest/v1/smm_leads?id=eq.${encodeURIComponent(leadId)}`;
              try {
                const r1 = await fetch(url, { method: "PATCH", headers: hdrs, body: JSON.stringify({ ms_event_id: made.id, meeting_how: how, meeting_link: (made.onlineMeeting && made.onlineMeeting.joinUrl) || null }) });
                if (!r1.ok) await fetch(url, { method: "PATCH", headers: hdrs, body: JSON.stringify({ ms_event_id: made.id }) });
              } catch (_) {}
            }
            joinUrl = (made && made.onlineMeeting && made.onlineMeeting.joinUrl) || "";
            // No link and no error: Microsoft quietly made a plain meeting. Ask the
            // calendar what it can host, so the note can say why.
            if (how === "teams" && autoTeams && !joinUrl && !teamsFailed) {
              teamsFailed = true;
              try { const c = await graph(env, "GET", `/users/${encodeURIComponent(cal)}/calendar?$select=allowedOnlineMeetingProviders,defaultOnlineMeetingProvider`); teamsWhy = (c && Array.isArray(c.allowedOnlineMeetingProviders) && !c.allowedOnlineMeetingProviders.includes("teamsForBusiness")) ? ` ${cal} isn't set up for Teams meetings (it allows: ${c.allowedOnlineMeetingProviders.join(", ") || "none"}).` : ` Microsoft didn't say why; ${cal} may not have a Teams licence.`; } catch (_) { teamsWhy = ` Microsoft didn't say why; ${cal} may not have a Teams licence.`; }
            }
            // The Outlook invite is all they get (Danielle, 5 Nov 2026): no
            // separate confirmation email alongside it.
            invited = true;
          } catch (_) {}
        }
        await logBookingMessage(env, {
          booking_id: leadId, booking_source: "smm", account_user_id: lead.account_user_id, client_email: lead.email,
          kind: "meeting", subject: moving ? "Meeting moved" : "Meeting booked", is_automated: false, created_by: user.email || "admin",
          body: `${moving ? "Moved: " : ""}${howLabel} ${moving ? "now" : "booked"} for ${dateNice} at ${start}${how === "in_person" && where ? `, at ${where}` : ""}.${invited ? ` Outlook invite sent to the client from ${cal}.` : ""}${joinUrl ? ` Teams link: ${joinUrl}` : ""}${teamsFailed ? ` The Teams link couldn't be made, so the invite went without one.${teamsWhy}` : ""}${how === "teams" && !autoTeams && invited ? " Teams link to add: use Add the Teams link on the file, and everyone gets the updated invite." : ""}${lead.email && cal && lead.email.toLowerCase() === cal.toLowerCase() ? ` No invite: the client's email is ${cal}, the calendar the meeting is in.` : ""}`,
        });
        return json({ ok: true, invited, join_url: joinUrl || null, teams_failed: teamsFailed }, 200, request, env);
      }

      // ---- Admin: call notes from a recording's transcript ----------------------
      // Danielle, 5 Nov 2026: a call that was recorded rather than written up.
      // Claude reads the transcript and fills the call notes in; the person
      // checks them before they're saved. Nothing is saved here.
      if (path.endsWith("/smm/call-notes/ai") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const transcript = String(b.transcript || "").trim();
        if (transcript.length < 40) return json({ error: "Paste the transcript first." }, 400, request, env);
        if (transcript.length > 200000) return json({ error: "That transcript is too long to read in one go. Paste the part that covers what they want." }, 400, request, env);
        const kind = b.kind === "pricing" ? "pricing call" : b.kind === "discovery" ? "discovery call" : "call";
        const packages = (Array.isArray(b.packages) ? b.packages : []).map((x) => String(x)).filter(Boolean).slice(0, 12);
        const PLATS = ["Instagram", "Facebook", "LinkedIn", "YouTube", "TikTok"];
        const schema = { type: "object", additionalProperties: false, required: ["what_they_want", "package_interest", "platforms", "budget", "wants_to_start", "next_step"], properties: {
          what_they_want: { type: "string" }, package_interest: { type: "string" },
          platforms: { type: "array", items: { type: "string", enum: PLATS } },
          budget: { type: "string" }, wants_to_start: { type: "string" }, next_step: { type: "string" } } };
        const prompt = `This is the transcript of a ${kind} between The Marketing Experts (TMKE), a social media agency for estate and letting agents, and a prospective client${b.client ? ` (${String(b.client).slice(0, 120)})` : ""}. Fill in our call notes from it.

Rules:
- Only what was actually said in the call. If something wasn't covered, give an empty string (or an empty list), never a guess.
- British English, plain and short. Write as notes for our team, not as a summary of the conversation.
- what_they_want: what they're after and why now, in two to four sentences.
- package_interest: one of ${packages.length ? packages.map((x) => `"${x}"`).join(", ") : "our packages"} if they leaned towards one, otherwise "".
- platforms: the social platforms they want us to run.
- budget: what they said about money, with their figures, e.g. "Around £600 a month".
- wants_to_start: when they want to start, as they said it.
- next_step: what was agreed would happen next, and who does it.

Transcript:
${transcript}`;
        let aiRes;
        try { aiRes = await aiFetch(env, "admin", { max_tokens: 8000, output_config: { format: { type: "json_schema", schema } }, messages: [{ role: "user", content: prompt }] }); }
        catch (e) { return json({ error: "Couldn't reach Claude." }, 502, request, env); }
        const out = await aiRes.json().catch(() => null);
        if (!aiRes.ok || !out) return json({ error: aiFailMessage(aiRes.status, out && out.error && out.error.message) }, 502, request, env);
        const text = (out.content || []).filter((c) => c.type === "text").map((c) => c.text).join("");
        let notes = null; try { notes = JSON.parse(text); } catch (_) {}
        if (!notes) return json({ error: "Claude's notes couldn't be read. Try again." }, 502, request, env);
        return json({ ok: true, notes }, 200, request, env);
      }

      // ---- Admin: add the Teams link to a booked call -------------------------
      // The manager makes the link in their own Teams and pastes it on the file;
      // the Outlook meeting is updated, so everyone invited gets it (Danielle,
      // 5 Nov 2026).
      if (path.endsWith("/smm/meeting/link") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const link = String(b.url || "").trim();
        if (!/^https:\/\/[^\s]*teams\.(microsoft|live)\.com\/\S+$/i.test(link)) return json({ error: "That doesn't look like a Teams link. It starts https://teams.microsoft.com/ or https://teams.live.com/." }, 400, request, env);
        const lead = (await sbGet(env, "smm_leads", `id=eq.${encodeURIComponent(String(b.lead_id || ""))}&select=id,email,account_user_id,ms_event_id,meeting_at`))?.[0];
        if (!lead || !lead.ms_event_id) return json({ error: "There's no booked meeting on this file to update. Book the call first." }, 400, request, env);
        const boxes = [env.SMM_MEETING_UPN, env.SMM_MANAGER_UPN].filter((x, i, a) => x && a.indexOf(x) === i);
        const esc = (v) => String(v ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
        // The link on a line of its own, with a gap above (Danielle, 5 Nov 2026).
        const joinHtml = `<p>We'll meet on Microsoft Teams.<br><br><a href="${esc(link)}">Join the meeting</a>, or use this link:<br>${esc(link)}</p>`;
        let done = false, lastErr = "";
        for (const box of boxes) {
          try {
            const ev = await graph(env, "GET", `/users/${encodeURIComponent(box)}/events/${encodeURIComponent(lead.ms_event_id)}?$select=body`);
            let html = (ev && ev.body && ev.body.content) || "";
            // Swap the "link to follow" line for the link; otherwise add it at the top.
            const swapped = html.replace(/We'll meet on Microsoft Teams\. We'll update this invite with your joining link before the call\./, `We'll meet on Microsoft Teams.<br><br><a href="${esc(link)}">Join the meeting</a>, or use this link:<br>${esc(link)}`);
            html = swapped !== html ? swapped : (/<body[^>]*>/i.test(html) ? html.replace(/<body([^>]*)>/i, `<body$1>${joinHtml}`) : joinHtml + html);
            await graph(env, "PATCH", `/users/${encodeURIComponent(box)}/events/${encodeURIComponent(lead.ms_event_id)}`, { body: { contentType: "HTML", content: html }, location: { displayName: "Microsoft Teams", locationUri: link } });
            done = true; break;
          } catch (e) { lastErr = String((e && e.message) || e).slice(0, 160); }
        }
        if (!done) return json({ error: `Couldn't update the invite: ${lastErr || "the meeting wasn't found"}.` }, 502, request, env);
        try { await fetch(`${env.SUPABASE_URL}/rest/v1/smm_leads?id=eq.${encodeURIComponent(lead.id)}`, { method: "PATCH", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=minimal" }, body: JSON.stringify({ meeting_link: link }) }); } catch (_) {}
        await logBookingMessage(env, { booking_id: lead.id, booking_source: "smm", client_email: lead.email, channel: "note", kind: "note", subject: "Teams link added", created_by: user.email || "admin", body: `Teams link added and the invite updated for everyone: ${link}` });
        return json({ ok: true }, 200, request, env);
      }

      // ---- Admin: cancel a social media client's booked call -------------------
      // Outlook sends everyone the cancellation (Danielle, 5 Nov 2026), and the
      // call comes off the card.
      if (path.endsWith("/smm/meeting/cancel") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const lead = (await sbGet(env, "smm_leads", `id=eq.${encodeURIComponent(String(b.lead_id || ""))}&select=id,email,account_user_id,ms_event_id,meeting_at`))?.[0];
        if (!lead) return json({ error: "Lead not found." }, 404, request, env);
        const cal = env.SMM_MEETING_UPN || env.SMM_MANAGER_UPN;
        let cancelled = false;
        if (lead.ms_event_id && cal) {
          // Whichever calendar organised it: the Teams mailbox, or hello@ (website bookings, and calls booked before 5 Nov).
          for (const box of [cal, env.SMM_MANAGER_UPN].filter((x, i, a) => x && a.indexOf(x) === i)) {
            try { await graph(env, "POST", `/users/${encodeURIComponent(box)}/events/${encodeURIComponent(lead.ms_event_id)}/cancel`, { comment: "We've had to cancel this call. We'll be in touch to find another time." }); cancelled = true; break; }
            catch (_) { try { await graph(env, "DELETE", `/users/${encodeURIComponent(box)}/events/${encodeURIComponent(lead.ms_event_id)}`); cancelled = true; break; } catch (_) {} }
          }
        }
        await fetch(`${env.SUPABASE_URL}/rest/v1/smm_leads?id=eq.${encodeURIComponent(lead.id)}`, { method: "PATCH", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=minimal" }, body: JSON.stringify({ meeting_at: null, ms_event_id: null }) });
        try { await fetch(`${env.SUPABASE_URL}/rest/v1/smm_leads?id=eq.${encodeURIComponent(lead.id)}`, { method: "PATCH", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=minimal" }, body: JSON.stringify({ meeting_how: null, meeting_link: null }) }); } catch (_) {}
        return json({ ok: true, cancelled }, 200, request, env);
      }

      // ---- Admin: add a lead manually (other channels / existing clients) ----
      if (path.endsWith("/smm/lead") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const email = String((b && b.email) || "").trim();
        const first = String((b && b.first_name) || "").trim();
        const last = String((b && b.last_name) || "").trim();
        const full = (String((b && b.full_name) || "").trim()) || `${first} ${last}`.trim();
        if (!full && !email) return json({ error: "Add a name or email." }, 400, request, env);
        const stage = ["waitlist", "inquiry", "meeting_set", "proposal_sent", "pricing_call", "contract_signed", "onboarding", "active_client"].includes(b && b.pipeline_stage) ? b.pipeline_stage : "inquiry";
        const ins = await sbPost(env, "smm_leads", {
          kind: "manual", tag: "Manual", stage: "manual", pipeline_stage: stage,
          first_name: first || null, last_name: last || null, full_name: full || email,
          email: email || null, phone: (b && b.phone) || null, business: (b && b.business) || null,
          client_status: stage === "active_client" ? "active" : null,
          // How they came in and what they said (supabase/smm_stages_and_follow_ups.sql).
          source: String((b && b.source) || "").trim() || null, source_detail: String((b && b.source_detail) || "").trim() || null,
          message: String((b && b.message) || "").trim() || null,
          social_media_manager: String((b && b.social_media_manager) || "").trim() || null,
        }, "return=representation");
        if (!ins.ok) { const detail = await ins.text().catch(() => ""); console.error("smm manual lead insert failed", ins.status, detail); return json({ error: "Couldn't save the lead." }, 502, request, env); }
        let row = null; try { const arr = await ins.json(); row = Array.isArray(arr) && arr[0] ? arr[0] : null; } catch (_) {}
        if (row && row.id) {
          const by = String(user.email || "").split("@")[0].split(/[._]/)[0].replace(/^./, (m) => m.toUpperCase());
          const how = [b.source, b.source_detail].filter((x) => String(x || "").trim()).join(": ");
          await logBookingMessage(env, { booking_id: row.id, booking_source: "smm", client_email: email || null, channel: "note", kind: "note", subject: "Enquiry received", created_by: user.email || "system",
            body: smmEnquiryNote({ route: how ? `${how.charAt(0).toLowerCase()}${how.slice(1)}, added by hand by ${by}` : `a card added by hand by ${by}`, name: full, email, phone: b.phone, business: b.business, message: b.message }) });
        }
        return json({ ok: true, lead: row }, 200, request, env);
      }

      // ---- Admin: bring a client's CRM contact in line with their card -------
      if (path.endsWith("/smm/contact-sync") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        if (!(b && b.lead_id)) return json({ error: "Missing lead." }, 400, request, env);
        const crm = await syncSmmContact(env, b.lead_id);
        if (!crm.ok) return json({ error: crm.reason === "no_email" ? "This card has no email, so there's no contact to update." : "Couldn't update the contact." }, 400, request, env);
        return json({ ok: true, crm }, 200, request, env);
      }

      // ---- Admin: link an SMM card to a member's hub account ------------------
      // Binds smm_leads.account_user_id to the auth user of the given email (the
      // card's own email by default), so their reports pull through on
      // /account/social even if the card was created before they signed up.
      // Safety: the account's name must share the card's first OR last name, so
      // we don't attach the wrong person on a shared/typo'd email. Pass
      // { force: true } to override after the admin confirms. Returns
      // { noAccount } when no hub account exists (so the UI can offer an invite).
      if (path.endsWith("/smm/link") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const leadId = String((b && b.lead_id) || "").trim();
        if (!leadId) return json({ error: "Missing lead id." }, 400, request, env);
        const rows = await sbGet(env, "smm_leads", `id=eq.${encodeURIComponent(leadId)}&select=id,email,first_name,last_name,full_name`);
        const lead = rows && rows[0];
        if (!lead) return json({ error: "That card no longer exists." }, 404, request, env);
        const targetEmail = String((b && b.email) || lead.email || "").trim();
        if (!targetEmail) return json({ error: "This card has no email - add one first, then link." }, 400, request, env);
        const u = await findUserByEmail(env, targetEmail);
        if (!u) return json({ ok: false, noAccount: true, email: targetEmail }, 200, request, env);
        // Identity check — does the account's name share a name with the card?
        const norm = (s) => String(s || "").toLowerCase().replace(/[^a-z\s-]/g, "").split(/[\s-]+/).filter(Boolean);
        const cardTokens = new Set([...norm(lead.first_name), ...norm(lead.last_name), ...norm(lead.full_name)]);
        const acctName = (u.user_metadata && (u.user_metadata.full_name || u.user_metadata.name)) || "";
        const acctTokens = norm(acctName);
        const nameKnown = cardTokens.size > 0 && acctTokens.length > 0;
        const matches = !nameKnown || acctTokens.some((t) => cardTokens.has(t));
        if (!matches && !(b && b.force === true)) {
          return json({ ok: false, nameMismatch: true, email: targetEmail,
            account_name: acctName, card_name: lead.full_name || `${lead.first_name || ""} ${lead.last_name || ""}`.trim() || "(no name on card)" }, 200, request, env);
        }
        const res = await fetch(`${env.SUPABASE_URL}/rest/v1/smm_leads?id=eq.${encodeURIComponent(leadId)}`, {
          method: "PATCH",
          headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=minimal" },
          body: JSON.stringify({ account_user_id: u.id }),
        });
        if (!res.ok) { const t = await res.text().catch(() => ""); return json({ error: "Couldn't link the account. " + t.slice(0, 200) }, 502, request, env); }
        // The contact card follows: member tag, tied to the account, status.
        const crm = await syncSmmContact(env, leadId);
        return json({ ok: true, linked_email: targetEmail, user_id: u.id, crm }, 200, request, env);
      }

      // ---- Admin: invite an SMM client to create their member hub account -----
      // For a manually-added client with no hub account yet: create the account,
      // link the card to it, and email a branded invite with a "set your
      // password" link (→ /reset-password) so they can finish creating it.
      if (path.endsWith("/smm/invite") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
        const b = await request.json().catch(() => ({}));
        const leadId = String((b && b.lead_id) || "").trim();
        if (!leadId) return json({ error: "Missing lead id." }, 400, request, env);
        const rows = await sbGet(env, "smm_leads", `id=eq.${encodeURIComponent(leadId)}&select=id,email,first_name,last_name,full_name,business`);
        const lead = rows && rows[0];
        if (!lead) return json({ error: "That card no longer exists." }, 404, request, env);
        const email = String(lead.email || "").trim();
        if (!email) return json({ error: "This card has no email - add one first." }, 400, request, env);
        const fullName = String(lead.full_name || `${lead.first_name || ""} ${lead.last_name || ""}`.trim() || "").trim();
        const first = String(lead.first_name || fullName.split(/\s+/)[0] || "there").trim();
        // If they already have an account, just link it — no duplicate.
        let u = await findUserByEmail(env, email);
        let created = false;
        if (!u) {
          const cr = await fetch(`${env.SUPABASE_URL}/auth/v1/admin/users`, {
            method: "POST",
            headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json" },
            body: JSON.stringify({ email, password: genTempPassword(), email_confirm: true, user_metadata: { full_name: fullName || null } }),
          });
          if (cr.ok) { try { u = await cr.json(); } catch (_) {} created = true; }
          if (!u || !u.id) u = await findUserByEmail(env, email);
          if (!u || !u.id) { const t = await cr.text().catch(() => ""); return json({ error: "Couldn't create their account. " + t.slice(0, 160) }, 502, request, env); }
        }
        // Link the card to the account.
        await fetch(`${env.SUPABASE_URL}/rest/v1/smm_leads?id=eq.${encodeURIComponent(leadId)}`, {
          method: "PATCH",
          headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=minimal" },
          body: JSON.stringify({ account_user_id: u.id, account_created: created || undefined }),
        });
        // Generate a "set your password" link → /reset-password.
        const site = String(env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "");
        let actionLink = `${site}/forgot-password`;
        try {
          const gl = await fetch(`${env.SUPABASE_URL}/auth/v1/admin/generate_link`, {
            method: "POST",
            headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json" },
            body: JSON.stringify({ type: "recovery", email, options: { redirect_to: `${site}/reset-password` } }),
          });
          if (gl.ok) { const gj = await gl.json().catch(() => ({})); actionLink = (gj && (gj.action_link || (gj.properties && gj.properties.action_link))) || actionLink; }
        } catch (_) {}
        const content = `
          <h1 style="${EM_H1}">Welcome to your TMKE member hub</h1>
          <p style="${EM_P}">Hi ${esc(first)},</p>
          <p style="${EM_P}">As one of our social media management clients, you can manage and oversee your account through our member hub - your plan, your monthly performance reports and everything in one place.</p>
          <p style="${EM_P}">Click below to set your password and open your account.</p>
          <p style="margin:0 0 24px;"><a href="${esc(actionLink)}" style="${EM_BTN}">Create your account</a></p>
          <p style="${EM_P}">If the button doesn't work, paste this into your browser:<br><span style="color:#371e28;">${esc(actionLink)}</span></p>`;
        const html = await wrapInBrandedBase(env, content);
        const sent = await sendEmail(env, { to: email, subject: "Create your TMKE member hub account", html });
        if (!sent.ok) return json({ ok: false, linked: true, emailFailed: true, error: sent.error || "The account is linked, but the invite email didn't send." }, 200, request, env);
        await syncSmmContact(env, leadId);
        return json({ ok: true, invited: email, user_id: u.id }, 200, request, env);
      }

      // ---- Admin: set an invoice document's paid date -------------------------
      if (path.endsWith("/booking/document/paid") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = b && b.id;
        if (!id) return json({ error: "Missing id" }, 400, request, env);
        const paid = /^\d{4}-\d{2}-\d{2}$/.test((b && b.paid_date) || "") ? b.paid_date : null;
        await fetch(`${env.SUPABASE_URL}/rest/v1/booking_documents?id=eq.${encodeURIComponent(id)}`, {
          method: "PATCH", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=minimal" },
          body: JSON.stringify({ paid_date: paid }),
        });
        return json({ ok: true }, 200, request, env);
      }

      // ---- Admin: save/upsert a monthly performance report -------------------
      if (path.endsWith("/smm/report") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const leadId = b && b.lead_id;
        const month = Number(b && b.month), year = Number(b && b.year);
        const platform = (b && b.platform) || "Instagram";
        const data = (b && b.data && typeof b.data === "object") ? b.data : null;
        if (!leadId || !(month >= 0 && month <= 11) || !year || !data) return json({ error: "Need lead, a valid month/year and the report JSON." }, 400, request, env);
        // Link the client's account for member reads.
        let accountUserId = b && b.account_user_id;
        if (!accountUserId) { const r = await sbGet(env, "smm_leads", `id=eq.${encodeURIComponent(leadId)}&select=account_user_id`); accountUserId = (r && r[0] && r[0].account_user_id) || null; }
        // Everything saved here is the working copy (`data`). A live report
        // keeps showing its published copy until it's republished, so a
        // re-upload or an edit never reaches the client unseen.
        const res = await fetch(`${env.SUPABASE_URL}/rest/v1/smm_reports?on_conflict=lead_id,platform,month,year`, {
          method: "POST",
          headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "resolution=merge-duplicates,return=representation" },
          body: JSON.stringify({ lead_id: leadId, account_user_id: accountUserId, platform, month, year, data, uploaded_by: user.email || "admin" }),
        });
        if (!res.ok) { const t = await res.text().catch(() => ""); console.error("smm report upsert failed", res.status, t); return json({ error: "Couldn't save the report. If this is the first run, apply smm_reports.sql.", detail: t }, 502, request, env); }
        let row = null; try { const arr = await res.json(); row = Array.isArray(arr) && arr[0] ? arr[0] : null; } catch (_) {}
        return json({ ok: true, report: row }, 200, request, env);
      }

      // ---- Admin: parse a SocialPilot PDF into report JSON (via Claude) ------
      // So team members who don't use Claude can just upload the PDF here.
      if (path.endsWith("/smm/report/parse") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!env.ANTHROPIC_API_KEY) return json({ error: "AI isn't configured - set the ANTHROPIC_API_KEY secret on the Worker." }, 503, request, env);
        const b = await request.json().catch(() => ({}));
        const raw = String((b && b.pdf) || "");
        const mm = /^data:application\/pdf;base64,(.+)$/i.exec(raw);
        const b64 = mm ? mm[1] : raw;
        if (!b64) return json({ error: "Missing PDF." }, 400, request, env);
        // What each figure IS matters more than finding it. SocialPilot has
        // two kinds of reach and they don't add up to each other:
        //  - PROFILE reach (page 1 "Total Reach", page 2 "Reach Insights") counts
        //    each person once for the month;
        //  - CONTENT reach (the "Instagram Post" / "Instagram Reels" pages) is
        //    each post's reach added together, so one person who saw three reels
        //    counts three times.
        // The old prompt asked for "organicReach = reels+posts+stories", which
        // summed the second kind and got compared with the first. Its Stories
        // page covers only the 24 hours before the report was run, so it's never
        // read. Links and thumbnails aren't asked for: the admin page lifts them
        // out of the PDF itself (lib/socialpilot-pdf.js), which is exact.
        const prompt =
          // Any mix of Instagram, Facebook and LinkedIn (Danielle, 9 Oct 2026):
          // one PDF may hold one platform or several, and each lands in its own
          // part of the JSON so the admin can add it to the month's report.
          "The attached PDF is a SocialPilot report for one client. It may cover Instagram, a Facebook Page, LinkedIn, or several of them. Most figures are in its text; a few are only in charts - read those visually. " +
          "Say which it covers in \"platforms\" (any of \"instagram\", \"facebook\", \"linkedin\"). The top-level Instagram fields (summary, profile, reach, viewsSplit, interactionsByFormat, posts, reels, content, hashtags, demographics, peakTimes, timing, bestDays, morningWindow, eveningWindow, ads) come ONLY from Instagram pages: if there are none, omit them all. \"priorities\" covers every platform in the PDF, each one tagged with its platform. " +
          // Joint reports (Danielle, 9 Oct 2026): SocialPilot can put a client's
          // Facebook Page in the same PDF, before the Instagram pages. Its
          // "Post Performance" table has the same title as Instagram's, so
          // without this its posts end up in the Instagram list.
          "It may ALSO contain a Facebook Page section (pages headed \"Facebook Profile\" or \"Facebook Posts\", with Page Likes, Page Reach, New Fans and their own Post Performance table). Keep the two apart: every field below except \"facebook\" comes from the Instagram pages only (\"Instagram Profile\", \"Instagram Post\", \"Instagram Reels\" and the pages that follow each), and the Facebook pages fill \"facebook\" and nothing else. " +
          "Extract ONE JSON object with this exact shape and reply with ONLY that JSON (no prose, no markdown fences):\n" +
          '{ "platforms": [string], "summary": string (FOR THE TEAM: 3-5 short points on the month, each on its own line starting "- ", one plain sentence each, weighing all the figures together - profile, posts and reels, audience - rather than one statistic; name what went well and what fell short, honestly and without spin), ' +
          '"profile": { "followers": number (Total Followers: a Lifetime Data snapshot on the day the report was run), "newFollowers": number (from "New Followers (n)"), "reach": number (Total Reach), "reachChange": number (signed percent from previous period, negative when the arrow points down), "views": number (Total Views; "2.5K" becomes 2500), "viewsChange": number (signed percent), "interactions": number (Total Interactions), "interactionsChange": number (signed percent), "interactionRate": number (percent), "linkTaps": number (Profile Link Taps) }, ' +
          '"reach": { "follower": number, "nonFollower": number } (the legend of the "Reach Insights" chart: "Follower (n)" and "Non Follower (n)"), ' +
          '"viewsSplit": { "follower": number, "nonFollower": number } (the legend of the "Views Insights" chart), ' +
          '"interactionsByFormat": { "feed": number, "reel": number, "story": number, "ad": number } (the legend of the "Interaction Insights" chart), ' +
          '"posts": { "published": number, "reach": number, "views": number, "interactions": number, "likes": number, "comments": number, "saves": number, "shares": number, "interactionRate": number (percent) } (the "Instagram Post" page), ' +
          '"reels": { same fields as posts } (the "Instagram Reels" page), ' +
          '"content": [ { "title": string (exactly as printed, including any trailing "…"), "type": "Post"|"Reel", "date": "YYYY-MM-DD", "time": "HH:MM", "reach": number, "views": number (reels only; omit for posts), "interactions": number, "likes": number, "comments": number, "saves": number, "shares": number } ] (EVERY row of the "Post Performance" and "Reels Performance" tables, in the order printed, posts first), ' +
          '"hashtags": [ { "name": "#tag", "format": "Post"|"Reel", "count": number, "reach": number (average reach), "interactions": number (average interaction) } ] (every row of both hashtag tables, in the order printed), ' +
          '"demographics": { "age": [ { "range": "18-24"|"25-34"|"35-44"|"45-54"|"55-64"|"65+", "male": number, "female": number, "unspecified": number } ] (read each bar of the "Audience Demographics" chart against its axis), "gender": [ { "label": "Male"|"Female"|"Unspecified", "pct": number, "count": number } ], "topCities": [ { "city": string, "count": number } ] (every row), "topCountries": [ { "country": string, "count": number } ] (every row) }, ' +
          '"peakTimes": { "slots": ["8am","10am","12pm","2pm","4pm","6pm","8pm"], "grid": seven rows (Mon..Sun), each N cells matching slots, 0-3 (0 low .. 3 peak) read from "Followers Online Activity" }, ' +
          '"timing": string, "bestDays": string, "morningWindow": string, "eveningWindow": string, ' +
          '"ads": { "reach": number, "views": number, "interactions": number, "clicks": number, "cpc": number (GBP), "spend": number (GBP), "impressions": number } (ONLY if the report has a paid-ads section with figures; otherwise omit), ' +
          '"facebook": (ONLY if the report has a Facebook Page section; otherwise omit) { "summary": string (FOR THE TEAM: 2-4 short points on the Facebook Page\'s month on its own, each on its own line starting "- ", one plain sentence each, honest, without spin), "pageLikes": number (Total Page Likes, Lifetime Data), "newFans": number, "newFansChange": number (signed percent), "pageReach": number (Page Reach), "pageReachChange": number (signed percent), "pageViews": number, "pageViewsChange": number (signed percent), ' +
          '"posts": { "published": number, "publishedChange": number, "views": number (Posts Views), "viewsChange": number, "engagement": number (Posts Engagement), "engagementChange": number, "reactions": number, "comments": number, "shares": number, "videoPlays": number (Posts Video Plays), "videoPlaysChange": number, "images": number, "videos": number, "text": number, "links": number (from the Publishing Trend legend "Image (n)", "Video (n)", "Text (n)" and "Link (n)") }, ' +
          '"content": [ { "title": string (exactly as printed), "date": "YYYY-MM-DD", "time": "HH:MM", "reach": number, "engagementRate": number (percent), "reactions": number, "shares": number, "videoViews": number (omit when N/A) } ] (EVERY row of the Facebook Post Performance table, in the order printed), ' +
          '"medianByType": [ { "type": "Image"|"Text"|"Video"|"Link", "reach": number, "engagement": number } ] (the Median Reach & Engagement chart: each post type\'s two bar labels, exactly as printed; omit a type with no bars), ' +
          '"topCountries": [ { "country": string, "count": number } ], "topCities": [ { "city": string, "count": number } ] (the Top Countries By Page Fans and Top Cities By Page Fans charts, every bar, as printed: lifetime fans of the Page) }, ' +
          '"linkedin": (ONLY if the report has LinkedIn pages; otherwise omit) { "summary": string (FOR THE TEAM: 2-4 short points on the LinkedIn month on its own, each on its own line starting "- ", one plain sentence each, honest, without spin), "period": string (the date range printed at the foot of the LinkedIn pages, exactly, e.g. "Sep 09, 2026 to Oct 08, 2026"), "followers": number (Total Followers, Lifetime Data), "connections": number (Total Connections; omit for a company page), "followerGrowth": number (from "Follower Growth (n)"), "followerGrowthChange": number (signed percent), "impressions": number (from "Impression (n)" on the Impressions Trend), "impressionsChange": number (signed percent), ' +
          '"posts": { "published": number (Total Posts), "publishedChange": number, "impressions": number (Post Impressions), "impressionsChange": number, "reach": number (Post Reach), "reachChange": number, "reactions": number, "reactionsChange": number, "comments": number, "commentsChange": number, "engagement": number (Post Engagement), "engagementChange": number, "engagementRate": number (percent), "engagementRateChange": number, "text": number, "image": number, "video": number, "article": number, "document": number, "others": number (the Publishing Trend legend) }, ' +
          '"videos": { "published": number (Videos Published), "reach": number (Video Reach), "engagement": number (Video Engagement), "views": number (Video Views), "watchTime": number (Watch Time, in minutes) } (the "LinkedIn Videos" page), ' +
          '"byWeekday": [ { "day": "Monday"|"Tuesday"|"Wednesday"|"Thursday"|"Friday"|"Saturday"|"Sunday", "impressions": number (the Impressions Overview list beside the Impressions Trend, exactly as printed), "engagement": number (reactions and comments together that weekday, read from the Weekly Engagement Trend chart against its axis; omit if that chart isn\'t there) } ] (all seven days, Monday first), ' +
          '"content": [ { "title": string (exactly as printed), "date": "YYYY-MM-DD", "time": "HH:MM", "reach": number, "engagement": number, "reactions": number, "comments": number } ] (EVERY row of the LinkedIn Post Performance table) } — every change is the signed percent printed beside the figure ("in last 30 days" or "Since Previous Period"), negative when the arrow points down, ' +
          '"priorities": [ { "platform": "instagram"|"facebook"|"linkedin", "type": "go"|"caution"|"action", "title": string (2-4 words, e.g. "More reels"), "text": string (one or two sentences, 90-140 characters, written to the client about what we are doing next, never as homework for them) } ] (for each platform in the PDF: 4 for Instagram, 2 for Facebook, 2 for LinkedIn, each about that platform alone, inferred from its own figures: do more of what is working, do less of or change what is not, and close any gap; go = do more, caution = improve, action = fix now) }\n' +
          "LinkedIn pages are headed \"LinkedIn Posts\" or \"LinkedIn Videos\", or show Total Connections; their Post Performance table belongs in \"linkedin\" only. " +
          "Do NOT include anything from the Instagram Stories pages: they cover only the last 24 hours, not the month. Do NOT add figures together or invent totals - every number must be one printed in the report or read from one chart. " +
          "Omit anything not present. Numbers are plain (no commas, units or %) except cpc/spend which are numeric GBP amounts. Reply with ONLY the JSON object.";
        let aiRes;
        try {
          aiRes = await aiFetch(env, "admin", {
            max_tokens: 16000,
            messages: [{ role: "user", content: [
              { type: "document", source: { type: "base64", media_type: "application/pdf", data: b64 } },
              { type: "text", text: prompt },
            ] }],
          });
        } catch (e) { return json({ error: "Couldn't reach the AI service." }, 502, request, env); }
        if (!aiRes.ok) { const t = await aiRes.text().catch(() => ""); return json({ error: aiFailMessage(aiRes.status, t), detail: t.slice(0, 300) }, 502, request, env); }
        const dataRes = await aiRes.json();
        const text = (dataRes.content || []).filter((c) => c.type === "text").map((c) => c.text).join("");
        let parsed;
        try { const s = text.indexOf("{"), e = text.lastIndexOf("}"); parsed = JSON.parse(text.slice(s, e + 1)); }
        catch (_) { return json({ error: "Couldn't read the AI output - try again, or paste the JSON manually.", raw: text.slice(0, 200) }, 502, request, env); }
        const out = parsed && parsed.data && typeof parsed.data === "object" ? parsed.data : parsed;
        return json({ ok: true, data: out, usage: dataRes.usage || null }, 200, request, env);
      }

      // ---- Admin: list reports (optionally for one account) ------------------
      if (path.endsWith("/smm/reports") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const leadId = (url.searchParams.get("lead_id") || "").trim();
        const q = leadId ? `lead_id=eq.${encodeURIComponent(leadId)}&` : "";
        // select=* so published_at comes back once the column exists, and the
        // list still loads before smm_reports_publish.sql has been run.
        // Fetched directly (not sbGet) so a database error comes back as one,
        // rather than as an empty list that reads "No reports yet".
        const rr = await fetch(`${env.SUPABASE_URL}/rest/v1/smm_reports?${q}select=*&order=year.desc,month.desc`, {
          headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}` },
        });
        if (!rr.ok) return json({ error: `Couldn't load reports (${rr.status}): ${(await rr.text()).slice(0, 200)}` }, 502, request, env);
        const reports = (await rr.json()) || [];
        return json({ reports }, 200, request, env);
      }

      // ---- Management report: every client's published month, for the team ----
      // Admin > Social > Settings > Monthly report. Danielle, Sam and Abby
      // only (MGMT_REPORT_EMAILS), checked here as well as hidden on the page.
      // A client counts when their report for the month has data and has been
      // published to them. The two months before come too, for the trend.
      if (path.endsWith("/smm/management-report") && request.method === "GET") {
        const user = await getUser(request, env);
        const allow = String(env.MGMT_REPORT_EMAILS || "").toLowerCase().split(",").map((x) => x.trim()).filter(Boolean);
        if (!user || !isAdminEmail(user) || !allow.includes(String(user.email || "").toLowerCase().trim())) {
          return json({ error: "The monthly management report is for Danielle, Sam and Abbie." }, 403, request, env);
        }
        const m = Number(url.searchParams.get("month")), y = Number(url.searchParams.get("year"));
        if (!Number.isInteger(m) || m < 0 || m > 11 || !Number.isInteger(y) || y < 2020) return json({ error: "Which month?" }, 400, request, env);
        const at = (k) => ({ month: ((k % 12) + 12) % 12, year: Math.floor(k / 12) });
        const k0 = y * 12 + m, p1 = at(k0 - 1), p2 = at(k0 - 2);
        const hdr = { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}` };
        const get = async (table, qs) => {
          const r = await fetch(`${env.SUPABASE_URL}/rest/v1/${table}?${qs}`, { headers: hdr });
          if (!r.ok) throw new Error(`${table} (${r.status}): ${(await r.text()).slice(0, 160)}`);
          return r.json();
        };
        try {
          const months = `or=(and(year.eq.${y},month.eq.${m}),and(year.eq.${p1.year},month.eq.${p1.month}),and(year.eq.${p2.year},month.eq.${p2.month}))`;
          const reps = await get("smm_reports", `${months}&select=id,lead_id,platform,month,year,data,published_data,published_at`);
          const leads = await get("smm_leads", `or=(pipeline_stage.eq.active_client,id.in.(${[...new Set(reps.map((r) => r.lead_id))].join(",") || "00000000-0000-0000-0000-000000000000"}))&select=id,full_name,business,email,social_media_manager,package_name,pipeline_stage,client_status,platforms`);
          const byId = new Map(leads.map((l) => [l.id, l]));
          const isNow = (r) => r.year === y && r.month === m;
          // Any platform's figures count: a month with only Facebook or LinkedIn
          // is still that client's report (it used to need Instagram's).
          const filled = (o) => o && typeof o === "object" && Object.keys(o).length;
          const has = (d) => d && typeof d === "object" && (filled(d.profile) || filled(d.posts) || filled(d.facebook) || filled(d.linkedin));
          const accounts = reps.filter((r) => isNow(r) && r.published_at && has(r.published_data) && byId.has(r.lead_id)).map((r) => {
            const l = byId.get(r.lead_id);
            const earlier = reps.filter((x) => x.lead_id === r.lead_id && (x.platform || "") === (r.platform || "") && !isNow(x))
              .map((x) => ({ month: x.month, year: x.year, data: has(x.published_data) ? x.published_data : x.data || {} }))
              .sort((a, b) => (a.year * 12 + a.month) - (b.year * 12 + b.month));
            return { lead: { id: l.id, name: l.full_name, business: l.business, manager: l.social_media_manager, package: l.package_name },
              // The figures as the client has them; our Summary (what it means,
              // the plan, trends) as it stands now, since it's edited after
              // publishing without a republish.
              report: { id: r.id, platform: r.platform || "Instagram", month: r.month, year: r.year, published_at: r.published_at,
                data: { ...r.published_data, summary: (r.data || {}).summary ?? r.published_data.summary, priorities: (r.data || {}).priorities ?? r.published_data.priorities, trendSummary: (r.data || {}).trendSummary ?? r.published_data.trendSummary, goals: (r.data || {}).goals ?? r.published_data.goals } }, earlier };
          }).sort((a, b) => String(a.lead.business || a.lead.name || "").localeCompare(String(b.lead.business || b.lead.name || "")));
          // Active clients who aren't in it, and why: so a missing month is seen.
          const inIt = new Set(accounts.map((a) => a.lead.id));
          const missing = leads.filter((l) => l.pipeline_stage === "active_client" && !["paused", "ended", "internal"].includes(l.client_status) && !inIt.has(l.id)).map((l) => {
            const mine = reps.find((r) => r.lead_id === l.id && isNow(r));
            const pl = Array.isArray(l.platforms) ? l.platforms : String(l.platforms || "").split(/[,;]/);
            const platform = pl.map((x) => String(x || "").trim()).filter(Boolean).map((x) => x.charAt(0).toUpperCase() + x.slice(1)).join(", ");
            return { name: l.full_name, business: l.business, manager: l.social_media_manager, platform, reason: !mine ? "No report uploaded" : !mine.published_at ? "Report not published" : "Report has no data" };
          }).sort((a, b) => String(a.business || a.name || "").localeCompare(String(b.business || b.name || "")));
          return json({ ok: true, month: m, year: y, accounts, missing }, 200, request, env);
        } catch (e) {
          return json({ error: `Couldn't gather the month: ${e.message || e}` }, 502, request, env);
        }
      }

      // ---- Admin: ask Claude about an account's reports (admin-only) ----------
      if (path.endsWith("/smm/report/ask") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!env.ANTHROPIC_API_KEY) return json({ error: "AI isn't configured - set the ANTHROPIC_API_KEY secret on the Worker." }, 503, request, env);
        const b = await request.json().catch(() => ({}));
        const leadId = b && b.lead_id;
        const question = String((b && b.question) || "").trim().slice(0, 500);
        if (!leadId || !question) return json({ error: "Missing account or question." }, 400, request, env);
        const leadRows = await sbGet(env, "smm_leads", `id=eq.${encodeURIComponent(leadId)}&select=full_name,business`);
        const lead = (leadRows && leadRows[0]) || {};
        const reps = (await sbGet(env, "smm_reports", `lead_id=eq.${encodeURIComponent(leadId)}&select=platform,month,year,data&order=year.asc,month.asc`)) || [];
        if (!reps.length) return json({ error: "No reports for this account yet - upload one first." }, 400, request, env);
        const MN = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
        const accName = lead.business || lead.full_name || "this account";
        const platform = reps[reps.length - 1].platform || "Instagram";
        let dataText = "";
        for (const r of reps) {
          const d = r.data || {}, p = d.profile || {}, rc = d.reach || {};
          dataText += `=== ${MN[r.month]} ${r.year} ===\n`;
          dataText += `Followers: ${p.followers ?? "?"} | New followers: ${p.newFollowers ?? "?"} | Reach: ${p.reach ?? "?"} | Views: ${p.views ?? "?"}\n`;
          dataText += `Interactions: ${p.interactions ?? "?"} | Engagement rate: ${p.interactionRate ?? "?"}% | Link taps: ${p.linkTaps ?? "?"}\n`;
          if (rc.follower != null || rc.nonFollower != null) dataText += `Reach from followers: ${rc.follower ?? "?"} | from non-followers: ${rc.nonFollower ?? "?"}\n`;
          for (const [k, lbl] of [["posts", "Posts"], ["reels", "Reels"]]) { const x = d[k]; if (x) dataText += `${lbl} - published: ${x.published ?? "?"} | reach (each post's reach added, so counts people more than once): ${x.reach ?? "?"} | views: ${x.views ?? "?"} | interactions: ${x.interactions ?? "?"}\n`; }
          if (d.content && d.content.length) dataText += `Every post: ${d.content.map((t) => `${t.title} [${t.type}, ${t.date || "?"}, reach ${t.reach ?? "?"}, interactions ${t.interactions ?? "?"}]`).join("; ")}\n`;
          if (d.ads) dataText += `Paid ads - reach: ${d.ads.reach ?? "?"} | interactions: ${d.ads.interactions ?? "?"} | spend: £${d.ads.spend ?? "?"} | clicks: ${d.ads.clicks ?? "?"} | CPC: £${d.ads.cpc ?? "?"}\n`;
          if (d.bestDays) dataText += `Best days: ${d.bestDays} | Morning window: ${d.morningWindow || "?"} | Evening window: ${d.eveningWindow || "?"}\n`;
          if (d.hashtags && d.hashtags.length) dataText += `Hashtags: ${d.hashtags.map((h) => `${h.name} (reach:${h.reach}, inter:${h.interactions})`).join(", ")}\n`;
          if (d.topContent && d.topContent.length) dataText += `Top content: ${d.topContent.map((t) => `${t.title} [${t.type}]`).join("; ")}\n`;
          if (d.priorities && d.priorities.length) dataText += `Priorities: ${d.priorities.map((pr) => pr.text).join("; ")}\n`;
          dataText += "\n";
        }
        const prompt = `You are a social media analyst reviewing ${reps.length} month(s) of data for ${accName} on ${platform}.\n\nData:\n${dataText}\nQuestion: ${question}\n\nAnswer directly and practically, referencing the actual figures above. Be concise (a few short sentences or bullet points). If the data doesn't cover it, say so.`;
        let aiRes;
        try {
          aiRes = await aiFetch(env, "admin", { max_tokens: 8000, output_config: { effort: "high" }, messages: [{ role: "user", content: prompt }] });
        } catch (e) { return json({ error: "Couldn't reach the AI service." }, 502, request, env); }
        if (!aiRes.ok) { const t = await aiRes.text().catch(() => ""); return json({ error: aiFailMessage(aiRes.status, t), detail: t.slice(0, 300) }, 502, request, env); }
        const dataRes = await aiRes.json();
        const answer = (dataRes.content || []).filter((c) => c.type === "text").map((c) => c.text).join("").trim();
        return json({ ok: true, answer: answer || "(no answer)" }, 200, request, env);
      }

      // ---- Admin: draft the trends summary and the client commentary ---------
      // Two pieces of writing from one read of the account's last three months:
      //  - trendSummary: for the team, in the admin voice, what's moving across
      //    the months (Summary tab, never shown to the client);
      //  - client: the "What it means" story and the "Into <month>" cards, in
      //    the voice of the account manager talking to the client
      //    (docs/smm-report-rules.md §10). A draft for a person to rewrite,
      //    never published by itself.
      // Three months and no further back: social changes too fast for older
      // months to say much about this one.
      if (path.endsWith("/smm/report/draft") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        if (!env.ANTHROPIC_API_KEY) return json({ error: "AI isn't configured - set the ANTHROPIC_API_KEY secret on the Worker." }, 503, request, env);
        const b = await request.json().catch(() => ({}));
        const id = b && b.id;
        const only = ["trends", "client"].includes(b && b.only) ? b.only : "both";
        if (!id) return json({ error: "Missing report." }, 400, request, env);
        const cur = ((await sbGet(env, "smm_reports", `id=eq.${encodeURIComponent(id)}&select=id,lead_id,platform,month,year,data`)) || [])[0];
        if (!cur) return json({ error: "That report wasn't found." }, 404, request, env);
        const all = (await sbGet(env, "smm_reports", `lead_id=eq.${encodeURIComponent(cur.lead_id)}&platform=eq.${encodeURIComponent(cur.platform || "Instagram")}&select=id,month,year,data`)) || [];
        const idx = (r) => r.year * 12 + r.month;
        const months = all.filter((r) => idx(r) <= idx(cur) && idx(r) >= idx(cur) - 2).sort((a, b2) => idx(a) - idx(b2));
        const lead = ((await sbGet(env, "smm_leads", `id=eq.${encodeURIComponent(cur.lead_id)}&select=business,full_name,social_media_manager`)) || [])[0] || {};
        const MN = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
        const nextMonth = MN[(cur.month + 1) % 12];
        // The months side by side, one row per measure, so movement and
        // three-month direction are read off a table rather than guessed at.
        const num = (v) => (v == null || v === "" ? null : Number(String(v).replace(/[^0-9.\-]/g, "")));
        const METRICS = [
          ["Followers total (a snapshot on the day each report was RUN, not month end: never compare across months)", (d) => d.profile?.followers],
          ["New followers (who followed during the month; not net of unfollows)", (d) => d.profile?.newFollowers],
          ["Profile reach (unique people, each counted once)", (d) => d.profile?.reach],
          ["Views (total, repeats included)", (d) => d.profile?.views],
          ["Interactions (total)", (d) => d.profile?.interactions],
          ["Interaction rate % (interactions / profile reach)", (d) => d.profile?.interactionRate],
          ["Profile link taps", (d) => d.profile?.linkTaps],
          ["Posts published", (d) => d.posts?.published],
          ["Post reach (each post's reach added; people counted more than once)", (d) => d.posts?.reach],
          ["Post interactions", (d) => d.posts?.interactions],
          ["Post interaction rate %", (d) => d.posts?.interactionRate],
          ["Reels published", (d) => d.reels?.published],
          ["Reel reach (each reel's reach added)", (d) => d.reels?.reach],
          ["Reel views", (d) => d.reels?.views],
          ["Reel interactions", (d) => d.reels?.interactions],
          ["Reel interaction rate %", (d) => d.reels?.interactionRate],
          ["Content reach from followers (counted content by content; NOT a part of profile reach)", (d) => d.reach?.follower],
          ["Content reach from non-followers (counted content by content; NOT a part of profile reach)", (d) => d.reach?.nonFollower],
        ];
        const cols = months.map((r) => `${MN[r.month].slice(0, 3)} ${r.year}`);
        const table = [`| Measure | ${cols.join(" | ")} |`, `|---|${cols.map(() => "---").join("|")}|`]
          .concat(METRICS.map(([label, get]) => {
            const vals = months.map((r) => num(get(r.data || {})));
            return vals.every((v) => v == null) ? null : `| ${label} | ${vals.map((v) => (v == null ? "-" : v)).join(" | ")} |`;
          }).filter(Boolean)).join("\n");
        const cd = cur.data || {}, cdem = cd.demographics || {};
        /* Which platforms this month covers (Danielle, 10 Oct 2026): every
           point the drafting makes says which one it's about, and Facebook's
           and LinkedIn's figures go in as tables of their own, never added
           to Instagram's. */
        const PN = { instagram: "Instagram", facebook: "Facebook", linkedin: "LinkedIn" };
        const plats = [(cd.profile || cd.posts || cd.reels) ? "instagram" : null, cd.facebook ? "facebook" : null, cd.linkedin ? "linkedin" : null].filter(Boolean);
        if (!plats.length) plats.push("instagram");
        const multi = plats.length > 1;
        const platTable = (key, rows) => {
          const ms = months.filter((r) => (r.data || {})[key]);
          if (!ms.length) return "";
          const c2 = months.map((r) => `${MN[r.month].slice(0, 3)} ${r.year}`);
          return [`| Measure | ${c2.join(" | ")} |`, `|---|${c2.map(() => "---").join("|")}|`].concat(rows.map(([label, get]) => {
            const vals = months.map((r) => { const x = (r.data || {})[key]; return x ? num(get(x)) : null; });
            return vals.every((v) => v == null) ? null : `| ${label} | ${vals.map((v) => (v == null ? "-" : v)).join(" | ")} |`;
          }).filter(Boolean)).join("\n");
        };
        const fbTable = platTable("facebook", [
          ["Page likes (snapshot when the report was run)", (x) => x.pageLikes], ["New page likes", (x) => x.newFans], ["Page reach (unique people)", (x) => x.pageReach],
          ["Page views", (x) => x.pageViews], ["Posts published", (x) => x.posts?.published], ["Post views", (x) => x.posts?.views],
          ["Post engagement (reactions, comments, shares)", (x) => x.posts?.engagement], ["Reactions", (x) => x.posts?.reactions], ["Comments", (x) => x.posts?.comments], ["Shares", (x) => x.posts?.shares], ["Video plays", (x) => x.posts?.videoPlays],
        ]);
        const liTable = platTable("linkedin", [
          ["Followers (snapshot when the report was run)", (x) => x.followers], ["New followers", (x) => x.followerGrowth], ["Connections", (x) => x.connections],
          ["Post impressions", (x) => x.posts?.impressions ?? x.impressions], ["Post reach", (x) => x.posts?.reach], ["Posts published", (x) => x.posts?.published],
          ["Post engagement (reactions and comments)", (x) => x.posts?.engagement], ["Engagement rate %", (x) => x.posts?.engagementRate],
        ]);
        const extra = [];
        const best = (Array.isArray(cd.content) && cd.content.length ? cd.content : (cd.topContent || [])).slice().sort((a, b2) => (Number(b2.reach) || 0) - (Number(a.reach) || 0)).slice(0, 6);
        if (best.length) extra.push(`This month's posts by reach: ${best.map((t) => `"${t.title}" (${t.type || "Post"}, reach ${t.reach ?? "?"}${t.views != null ? `, views ${t.views}` : ""}, interactions ${t.interactions ?? "?"})`).join("; ")}`);
        const ages = (cdem.age || []).map((a) => ({ range: a.range, v: (Number(a.male) || 0) + (Number(a.female) || 0) + (Number(a.unspecified) || 0) }));
        const at = ages.reduce((x, a) => x + a.v, 0);
        if (at) extra.push(`Followers by age (followers, not everyone reached): ${ages.map((a) => `${a.range} ${Math.round(a.v / at * 100)}%`).join(", ")}`);
        if ((cdem.topCities || []).length) extra.push(`Followers' top cities (followers, not everyone reached): ${cdem.topCities.slice(0, 5).map((c) => `${c.city || c.name} ${c.count}`).join(", ")}`);
        const fbBest = (cd.facebook?.content || []).slice().sort((a, b2) => (Number(b2.reach) || 0) - (Number(a.reach) || 0)).slice(0, 5);
        if (fbBest.length) extra.push(`Facebook posts this month by reach: ${fbBest.map((t) => `"${t.title}" (reach ${t.reach ?? "?"}, reactions ${t.reactions ?? "?"}, shares ${t.shares ?? "?"})`).join("; ")}`);
        const liBest = (cd.linkedin?.content || []).slice().sort((a, b2) => (Number(b2.reach) || 0) - (Number(a.reach) || 0)).slice(0, 5);
        if (liBest.length) extra.push(`LinkedIn posts this month by reach: ${liBest.map((t) => `"${t.title}" (reach ${t.reach ?? "?"}, engagement ${t.engagement ?? "?"})`).join("; ")}`);
        if (cd.summary) extra.push(`Team's own read of ${multi ? "Instagram this month" : "this month"}: ${cd.summary}`);
        if (cd.facebook?.summary) extra.push(`Team's own read of Facebook this month: ${cd.facebook.summary}`);
        if (cd.linkedin?.summary) extra.push(`Team's own read of LinkedIn this month: ${cd.linkedin.summary}`);
        if ((cd.priorities || []).length) extra.push(`Team's plan for next month (turn these into the client's "priorities"): ${cd.priorities.map((x) => `[${PN[x.platform] || "Instagram"}] [${x.type}] ${x.title ? x.title + ": " : ""}${x.text}`).join(" | ")}`);
        // What was agreed last month, to test against this month's figures.
        const lastM = months.length > 1 ? months[months.length - 2] : null;
        const agreed = lastM ? ((lastM.data?.client?.priorities || []).length ? lastM.data.client.priorities : (lastM.data?.priorities || [])) : [];
        const agreedText = agreed.length ? agreed.map((x, i) => `${i + 1}. ${x.title ? x.title + ": " : ""}${x.text}`).join("\n") : "None recorded.";
        const dataText = `${multi ? "INSTAGRAM\n" : ""}${table}${fbTable ? `\n\nFACEBOOK PAGE\n${fbTable}` : ""}${liTable ? `\n\nLINKEDIN (each month covers the dates printed on that report)\n${liTable}` : ""}\n\n${extra.join("\n")}\n\nACTIONS AGREED IN ${lastM ? MN[lastM.month].toUpperCase() : "THE PREVIOUS"} REPORT:\n${agreedText}`;
        const asks = [];
        if (only !== "client") asks.push('"trendSummary": string (FOR THE TEAM, not the client. Only if there are two or more months; otherwise null. Points, not paragraphs: ' + (multi ? 'for each platform, a line with just its name and a colon ("Instagram:", "Facebook:", "LinkedIn:"), then 2-4 points about that platform alone, ' : '2-4 points, ') + 'each point on its own line starting "- ", one plain sentence each, on what is moving across these months: what has improved and is holding, what is slipping, and whether last month\'s actions show up in this month\'s figures. Weigh all the figures together, never one statistic alone. Direct, honest, no spin.)');
        // The approved headline figures (src/lib/report-metrics.js): the AI
        // picks keys, the page computes the numbers. Keep the two in step.
        const IG_HEADLINE_KEYS = {
          reach: "profile reach (different people who saw the account) and its change",
          views: "total views and their change",
          interactions: "total interactions and their change",
          netFollowers: "total followers (on the day the report was run) with the month's new followers",
          newFollowers: "people who followed during the month",
          interactionRate: "interaction rate and its change in points",
          reelRate: "reels' interaction rate beside posts'",
          postRate: "posts' interaction rate beside reels'",
          nonFollowerShare: "share of content reach that was non-followers",
          published: "posts and reels published",
          reelViews: "total reel views",
          linkTaps: "taps on the link in their profile",
          topPost: "reach of the best-reaching post",
        };
        /* Facebook's, LinkedIn's and all platforms added together (Danielle,
           19 Oct 2026), offered only for the platforms the month has. Keep in
           step with src/lib/report-metrics.js. */
        const HEADLINE_KEYS = {
          ...(plats.includes("instagram") ? Object.fromEntries(Object.entries(IG_HEADLINE_KEYS).map(([k, v]) => [k, `Instagram: ${v}`])) : {}),
          ...(plats.includes("facebook") ? {
            fb_pageLikes: "Facebook: Page likes, with the month's new likes", fb_newLikes: "Facebook: new Page likes in the month",
            fb_pageReach: "Facebook: Page reach and its change", fb_pageViews: "Facebook: Page views and their change",
            fb_postViews: "Facebook: post views and their change", fb_engagement: "Facebook: engagement on posts and its change",
            fb_videoPlays: "Facebook: video plays and their change", fb_published: "Facebook: posts published",
          } : {}),
          ...(plats.includes("linkedin") ? {
            li_followers: "LinkedIn: followers, with the new ones", li_newFollowers: "LinkedIn: new followers",
            li_impressions: "LinkedIn: impressions and their change", li_reach: "LinkedIn: post reach and its change",
            li_engagement: "LinkedIn: engagement and its change", li_engagementRate: "LinkedIn: engagement rate and its change in points",
            li_videoViews: "LinkedIn: video views", li_published: "LinkedIn: posts published",
          } : {}),
          ...(multi ? {
            all_reach: "all platforms: reach added together", all_views: "all platforms: views added together",
            all_engagement: "all platforms: interactions and engagement added together", all_followers: "all platforms: followers added together, with the new ones",
            all_newFollowers: "all platforms: new followers added together", all_published: "all platforms: everything published",
          } : {}),
        };
        const platEnum = [...plats, ...(multi ? ["all"] : [])].map((x) => `"${x}"`).join("|");
        if (only !== "trends") asks.push(`"client": { "headline": [ four keys from: ${Object.keys(HEADLINE_KEYS).join(", ")} ], "insights": [ { "platform": ${platEnum}, "category": "working"|"learning"|"watch"|"previous", "headline": string, "analysis": string, "evidence": [ string ], "confidence": "strong"|"emerging" } ], "priorities": [ { "platform": ${platEnum}, "type": "go"|"caution"|"action", "title": string, "text": string } ] }`);
        // The rules are docs/smm-report-rules.md §10-11; change them there too.
        const prompt =
`You analyse a UK estate agent's ${plats.map((x) => PN[x]).join(" and ")} for TMKE, their social media agency.${multi ? ` Each platform has its own content, audience and results: read and write about each one separately, and NEVER add, average or compare figures across platforms in what you write. Only the "all_" headline figures add platforms together, and those are worked out for you.` : ""} Below are up to three months of figures for ${lead.business || lead.full_name || "the client"}, oldest to newest (the last column is ${MN[cur.month]} ${cur.year}, the month being reported), then the actions agreed in last month's report.

${dataText}

Reply with ONLY one JSON object, no prose and no markdown fences:
{ ${asks.join(", ")} }

${multi ? `PLATFORMS: every insight and every priority is about ONE platform; say which in "platform", and name the platform in its headline or analysis so it reads clearly on its own ("On Facebook, ..."). Use "all" only for a point that genuinely spans every platform. Give every platform at least one insight and at least one priority, and let the strongest point of the month stand out.\n\nHEADLINE WITH SEVERAL PLATFORMS: each of the four is either one platform's figure or an "all_" figure (every platform added together). Between them, the four should cover every platform the month has, or use an "all_" figure where the story is the whole picture; never all four from one platform. Each insight should rest on one of the four where it can.\n\n` : ""}HEADLINE ("client.headline"): the four figures that explain THIS month's story, chosen from the keys listed. Not the same four every month: pick the ones the insights rest on. The figures themselves are worked out from the data, so give keys only. Keys: ${Object.entries(HEADLINE_KEYS).map(([k, v]) => `${k} (${v})`).join("; ")}.

INSIGHTS ("client.insights"). This is the page that makes the report worth reading. The client can already see the headline numbers; don't narrate them back, and don't write a summary.
- Analyse ${MN[cur.month]} against the previous two months and the actions agreed last month. Test for: month-on-month changes that matter; three-month direction (rising, falling or flat across all three); content patterns (formats or kinds of post that keep outperforming); audience patterns (non-follower discovery, locations, ages); and each agreed action (did we do it, and what happened after).
- Between TWO and FOUR insights: only as many as genuinely exist this month. Never invent one to fill a space. An insight explains something the client couldn't get from reading a headline number.
- "category": "working" (What's working: something clearly paying off), "learning" (What we're learning: a pattern or comparison that should shape what we do), "watch" (One to watch: something not working yet, or a gap to close), "previous" (From last month: how an action agreed last month played out).
- "headline": at most 7 words, a plain statement ("Reels are earning more interaction").
- "analysis": at most 40 words. What we're seeing, what it means for their business, and what we'll do with it, in plain English for an estate agent, not a marketer.
- "evidence": the two or three figures the insight rests on, each short ("Reels 15.34% interaction rate", "Posts 7.74%"). Only figures present in the data.
- "confidence": "strong" when the data clearly supports it (a large change, or three months in the same direction); "emerging" when it's an early signal (one month, or a small change).
- Don't force positives. Include negative or flat performance where it matters to the strategy. Don't repeat statistics just because they are positive.

HARD RULES:
- Implementation is not outcome. You may say a measure improved after a change was made (e.g. reels published went from 1 to 3 and reel interaction rate rose); never say the change caused it unless the data establishes causation.
- A trend needs movement in the same direction across at least three months, or a change large enough to matter. Don't call small or ordinary fluctuations trends. With only two months, describe change, not trend.
- Never infer a relationship between measures with different definitions or denominators. Profile reach counts each person once; post and reel reach add each item's reach; the follower / non-follower figures are counted content by content and are NOT a split of profile reach, so never express them as a share of profile reach or compare them with it. Follower age and location describe followers, not everyone reached.
- The followers total is a snapshot taken whenever the report was run, not at month end, so never compare it between months or quote a change in it. Use new followers for growth, and never call new followers a net gain.
- Don't invent explanations. If the data shows what happened but not why, say what it suggests, not a cause as fact.
- Never invent a number or quote a figure that isn't in the data.

PRIORITIES ("client.priorities"): FOUR things WE will do in ${nextMonth}, drawn from the team's plan and in its order, topped up from the figures if the plan has fewer: more of what is working, less of (or a change to) what isn't, and any gap to close. "title": 2 to 5 words naming the action. "text": two sentences, 25 to 45 words: what we'll do ("Into ${nextMonth} we'll post more reels."), then why, from the figures ("That's because ..."). A fix describes the situation plainly and our fix ("There's currently no link in your bio, so no one can tap through to your website. We'll add one ..."). Never homework for the client.

VOICE (insights and priorities): the account manager talking to the client, "we" and "your"; say "your Instagram profile", never the handle. What they care about most: how many people see them, whether those people are local, whether they're of an age to move home (roughly 25 to 44), and posts that travelled. Never: needs attention, underperforming, declining, poor, not working, red flag, concern, urgent. Never promise a result or compare with other clients. British English, no em dashes, no exclamation marks, no bold or italics.`;
        let aiRes;
        try {
          aiRes = await aiFetch(env, "admin", { max_tokens: 16000, output_config: { effort: "high" }, messages: [{ role: "user", content: prompt }] });
        } catch (e) { return json({ error: "Couldn't reach the AI service." }, 502, request, env); }
        if (!aiRes.ok) { const t = await aiRes.text().catch(() => ""); return json({ error: aiFailMessage(aiRes.status, t), detail: t.slice(0, 300) }, 502, request, env); }
        const out = await aiRes.json();
        const text = (out.content || []).filter((c) => c.type === "text").map((c) => c.text).join("");
        let parsed;
        try { const s0 = text.indexOf("{"), e0 = text.lastIndexOf("}"); parsed = JSON.parse(text.slice(s0, e0 + 1)); }
        catch (_) { return json({ error: "Couldn't read the AI's draft - try again." }, 502, request, env); }
        const data = { ...(cur.data || {}) };
        if (only !== "client") data.trendSummary = months.length > 1 && parsed.trendSummary ? String(parsed.trendSummary).trim() : null;
        if (only !== "trends" && parsed.client) {
          const pr = (Array.isArray(parsed.client.priorities) ? parsed.client.priorities : [])
            .filter((x) => x && x.text).map((x) => ({ platform: [...plats, "all"].includes(x.platform) ? x.platform : plats[0], type: ["go", "caution", "action"].includes(x.type) ? x.type : "go", title: String(x.title || "").trim(), text: String(x.text).trim() }));
          const CATS = ["working", "learning", "watch", "previous"];
          const ins = (Array.isArray(parsed.client.insights) ? parsed.client.insights : [])
            .filter((x) => x && x.headline).slice(0, 4)
            .map((x) => ({
              platform: [...plats, "all"].includes(x.platform) ? x.platform : plats[0],
              category: CATS.includes(x.category) ? x.category : "working",
              headline: String(x.headline).trim(),
              analysis: String(x.analysis || "").trim(),
              evidence: (Array.isArray(x.evidence) ? x.evidence : [x.evidence]).filter(Boolean).map((e) => String(e).trim()).slice(0, 4),
              confidence: x.confidence === "emerging" ? "emerging" : "strong",
            }));
          const headline = (Array.isArray(parsed.client.headline) ? parsed.client.headline : []).filter((k) => HEADLINE_KEYS[k]).filter((k, i, arr) => arr.indexOf(k) === i).slice(0, 4);
          data.client = { headline, insights: ins, priorities: pr, draftedAt: new Date().toISOString() };
        }
        const res = await fetch(`${env.SUPABASE_URL}/rest/v1/smm_reports?id=eq.${encodeURIComponent(cur.id)}`, {
          method: "PATCH",
          headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=minimal" },
          body: JSON.stringify({ data }),
        });
        if (!res.ok) return json({ error: "Drafted, but couldn't save it - try again." }, 502, request, env);
        return json({ ok: true, data }, 200, request, env);
      }

      // ---- Admin: publish, unpublish, republish --------------------------------
      // { ids, action: "publish" | "unpublish" | "republish", notify }
      //  - publish: the working copy becomes what the client sees;
      //  - unpublish: taken out of the client's hub;
      //  - republish: a live report's edits go to the client. `notify` says
      //    whether they should be told it was amended (wrong figures, say:
      //    bell + email + "Updated" on the report) or not (a reworded
      //    sentence: nothing).
      // Publishing always puts "your report is ready" in their bell, and
      // emails them too when `email` is set.
      if (path.endsWith("/smm/report/publish") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const ids = (Array.isArray(b && b.ids) ? b.ids : []).map(String).filter((x) => /^[0-9a-f-]{36}$/i.test(x));
        if (!ids.length) return json({ error: "No reports chosen." }, 400, request, env);
        const action = (b && b.action) || (b && b.publish === false ? "unpublish" : "publish");
        if (!["publish", "unpublish", "republish"].includes(action)) return json({ error: "Unknown action." }, 400, request, env);
        const hdr = { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=representation" };
        const now = new Date().toISOString();
        const patch = async (id, body) => {
          const res = await fetch(`${env.SUPABASE_URL}/rest/v1/smm_reports?id=eq.${encodeURIComponent(id)}`, { method: "PATCH", headers: hdr, body: JSON.stringify(body) });
          if (!res.ok) { const t = await res.text().catch(() => ""); throw new Error(/published_|amend/.test(t) ? "Publishing isn't set up yet - run supabase/smm_reports_republish.sql first." : "Couldn't update that report."); }
          return ((await res.json().catch(() => [])) || [])[0];
        };
        const out = [];
        const notes = { bell: 0, noHub: 0, emailed: 0, noEmail: 0, failed: 0 };
        try {
          if (action === "unpublish") {
            // Recorded in the admin bell: a report leaving a client's hub is
            // worth knowing about, and who did it and when.
            const MNu = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
            const gone = (await sbGet(env, "smm_reports", `id=in.(${ids.join(",")})&select=id,month,year,lead_id`)) || [];
            for (const id of ids) out.push(await patch(id, { published_at: null, published_by: null, published_data: null }));
            for (const g of gone) {
              const ld = ((await sbGet(env, "smm_leads", `id=eq.${encodeURIComponent(g.lead_id)}&select=business,full_name`)) || [])[0] || {};
              try {
                await notifyAdmins(env, {
                  area: "social", event: "smm_report_unpublished",
                  title: `${MNu[g.month]} ${g.year} report taken down`,
                  body: `${ld.business || ld.full_name || "A client"}: removed from their hub by ${user.email || "an admin"}.`,
                  href: "/admin/social", meta: { report_id: g.id, lead_id: g.lead_id },
                });
              } catch (_) {}
            }
          } else {
            const rows = (await sbGet(env, "smm_reports", `id=in.(${ids.join(",")})&select=id,data,published_at,lead_id,month,year`)) || [];
            const MN = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
            const site = String(env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "");
            const leads = {};
            const leadOf = async (id) => (leads[id] ||= ((await sbGet(env, "smm_leads", `id=eq.${encodeURIComponent(id)}&select=account_user_id,email,full_name,business,social_media_manager`)) || [])[0] || {});
            for (const r of rows) {
              const lead = await leadOf(r.lead_id);
              const monthLabel = `${MN[r.month]} ${r.year}`, link = `${site}/account/social/report?r=${r.id}`, href = `/account/social/report?r=${r.id}`;
              if (action === "publish") {
                out.push(await patch(r.id, { published_at: now, published_by: user.email || "admin", published_data: r.data }));
                // The bell always; the email only if the admin ticked it.
                if (await notifyMember(env, lead.account_user_id, { kind: "smm_report_ready", title: `Your ${MN[r.month]} report is ready`, body: `See how your ${reportPlatformWords(r.data)} did, and what we're doing next.`, href, meta: { report_id: r.id } })) notes.bell++;
                else notes.noHub++;
                if (b && b.email) {
                  if (!lead.email) { notes.noEmail++; continue; }
                  const sent = await sendEmail(env, { to: lead.email, subject: `Your ${MN[r.month]} social media report is ready.`, html: await wrapInBrandedBase(env, smmReportReadyHtml({ name: lead.full_name, month: MN[r.month], monthLabel, nextMonth: MN[(r.month + 1) % 12], manager: lead.social_media_manager, platforms: reportPlatformWords(r.data), link,
                    // Only for someone with no hub account yet: sign up with this
                    // address and land on the report once confirmed.
                    joinLink: lead.account_user_id ? null : `${site}/join?email=${encodeURIComponent(lead.email)}&next=${encodeURIComponent(href)}` })) }).catch(() => ({ ok: false }));
                  if (sent && sent.ok !== false) notes.emailed++; else notes.failed++;
                }
              } else {
                if (!r.published_at) continue; // only a live report can be republished
                const notify = !!(b && b.notify);
                out.push(await patch(r.id, { published_data: r.data, amended_at: now, ...(notify ? { amendment_notice_at: now, amendment_email_pending: true } : {}) }));
                if (!notify) continue;
                await notifyMember(env, lead.account_user_id, { kind: "smm_report_amended", title: `Your ${MN[r.month]} report has been updated`, body: "We've made a correction. It's worth another look.", href, meta: { report_id: r.id } });
                if (!lead.email) { notes.noEmail++; continue; }
                const sent = await sendEmail(env, { to: lead.email, subject: `Your ${MN[r.month]} social media report has been updated.`, html: await wrapInBrandedBase(env, smmReportAmendedHtml({ name: lead.full_name, month: MN[r.month], monthLabel, manager: lead.social_media_manager, link, joinLink: lead.account_user_id ? null : `${site}/join?email=${encodeURIComponent(lead.email)}&next=${encodeURIComponent(href)}` })) }).catch(() => ({ ok: false }));
                if (sent && sent.ok !== false) { notes.emailed++; await patch(r.id, { amendment_email_pending: false }).catch(() => {}); } else notes.failed++;
              }
            }
          }
        } catch (e) { return json({ error: e.message }, 502, request, env); }
        return json({ ok: true, notes, reports: out.filter(Boolean).map((r) => ({ id: r.id, published_at: r.published_at, published_data: r.published_data, amended_at: r.amended_at, amendment_notice_at: r.amendment_notice_at })) }, 200, request, env);
      }

      // ---- Admin: delete a report --------------------------------------------
      if (path.endsWith("/smm/report") && request.method === "DELETE") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const id = (url.searchParams.get("id") || "").trim();
        if (!id) return json({ error: "Missing id" }, 400, request, env);
        await fetch(`${env.SUPABASE_URL}/rest/v1/smm_reports?id=eq.${encodeURIComponent(id)}`, {
          method: "DELETE", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}` },
        });
        return json({ ok: true }, 200, request, env);
      }

      // ---- Admin: manually run the inbound-email capture (also on the cron) ---
      if (path.endsWith("/smm/inbox/poll") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const result = await pollSmmInbox(env);
        return json(result || { ok: false }, 200, request, env);
      }

      // ---- Member: my whole correspondence + documents (service role) --------
      // Reads through the verified member session, matching by account OR email,
      // so the portal never misses a row to an RLS/email-casing edge case.
      if (path.endsWith("/booking/mine") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in." }, 401, request, env);
        const ids = await memberBookingIds(env, user);
        if (!ids.length) return json({ messages: [], documents: [] }, 200, request, env);
        const inList = `in.(${ids.join(",")})`;
        // channel=eq.email is NOT optional. booking_messages carries internal
        // notes as channel='note', and its RLS policy exists precisely to keep
        // those from members — but sbGet runs as the service role, which
        // bypasses RLS entirely. Without this filter the Worker hands a member
        // every internal note written about them.
        const messages = (await sbGet(env, "booking_messages", `booking_id=${inList}&channel=eq.email&select=id,booking_id,booking_source,direction,channel,kind,subject,body,is_automated,created_by,created_at&order=created_at.asc`)) || [];
        const documents = (await sbGet(env, "booking_documents", `booking_id=${inList}&select=id,booking_id,booking_source,category,title,file_name,size_bytes,content_type,created_at&order=created_at.asc`)) || [];
        return json({ messages, documents }, 200, request, env);
      }

      // ---- Member: the invoices I am actually being asked to pay ------------
      //
      // Deliberately a Worker route rather than an RLS policy, unlike messages
      // and documents: the pay link is a signed token, and signing needs a
      // secret the browser must never hold. Since a round trip is unavoidable,
      // the filtering happens here too.
      //
      // The route decides visibility, not the billing address. A booking billed
      // to a brand has no invoice as far as the client is concerned — someone
      // else is settling it — and showing them a bill they do not owe is worse
      // than showing them nothing. A package-covered shoot has nothing to bill
      // at all.
      if (path.endsWith("/booking/invoices/mine") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in." }, 401, request, env);

        const email = String(user.email || "").toLowerCase();
        const mine = (await sbGet(env, "videography_bookings",
          `or=(account_user_id.eq.${user.id},client_email.ilike.${encodeURIComponent(email)})`
          + `&select=id,payment_route`)) || [];
        // Only bookings the client settles themselves.
        const payable = mine.filter((b) => (b.payment_route || "agent_card") === "agent_card");
        if (!payable.length) return json({ invoices: [] }, 200, request, env);

        const ids = payable.map((b) => b.id).join(",");
        // Drafts are ours until they are sent, and a void invoice is not a bill.
        const rows = (await sbGet(env, "invoices",
          `booking_id=in.(${ids})&status=in.(sent,paid)`
          + `&select=id,number,booking_id,line_items,subtotal_pence,vat_pence,total_pence,status,issued_date,due_date,paid_date,pay_by_card`
          + `&order=created_at.desc`)) || [];

        const invoices = [];
        for (const iv of rows) {
          // Minted per invoice, and only where there is something to pay.
          let pay_url = null;
          if (iv.pay_by_card && iv.status !== "paid" && env.STRIPE_SECRET_KEY) {
            try { pay_url = await invoicePayUrl(env, iv.id); } catch (_) { pay_url = null; }
          }
          invoices.push({ ...iv, pay_url });
        }
        return json({ invoices }, 200, request, env);
      }

      // ---- Member: my managed-social service (client record + monthly insights)
      if (path.endsWith("/smm/mine") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in." }, 401, request, env);
        const email = String(user.email || "").toLowerCase();
        const leads = (await sbGet(env, "smm_leads", `or=(account_user_id.eq.${user.id},email.ilike.${encodeURIComponent(email)})&select=id,kind,pipeline_stage,client_status,package_name,price,platforms,start_date,instagram_url,facebook_url,linkedin_url,youtube_url,tiktok_url,full_name,business,email,phone,social_media_manager,inter_brand_invoice&order=created_at.desc`)) || [];
        // A member may match more than one card (a manual "test client" card that
        // holds the reports, plus a stray enquiry/brochure card from the same
        // email). Fetch reports across ALL matched cards, then pick the primary:
        // an active client first, else whichever card actually owns reports (so a
        // newer empty card can't hide them), else the most recent.
        let allReports = [];
        if (leads.length) {
          const ids = leads.map((l) => l.id).join(",");
          // Published reports only: a report is a draft until someone presses
          // Publish in Insights (smm_reports_publish.sql).
          // The published copy, never the working one (smm_reports_republish.sql).
          allReports = (await sbGet(env, "smm_reports", `lead_id=in.(${ids})&published_at=not.is.null&select=id,platform,month,year,data:published_data,lead_id,published_at,amendment_notice_at&order=year.desc,month.desc&limit=96`)) || [];
        }
        const lead = leads.find((l) => l.pipeline_stage === "active_client")
          || (allReports.length ? leads.find((l) => l.id === allReports[0].lead_id) : null)
          || leads[0] || null;
        const isClient = !!lead && lead.pipeline_stage === "active_client";
        // Matched on email but not yet linked (they signed up after we started
        // working with them): link it now, so their bell gets notifications.
        if (lead && !lead.account_user_id && String(lead.email || "").toLowerCase() === email) {
          try {
            await fetch(`${env.SUPABASE_URL}/rest/v1/smm_leads?id=eq.${encodeURIComponent(lead.id)}&account_user_id=is.null`, {
              method: "PATCH",
              headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=minimal" },
              body: JSON.stringify({ account_user_id: user.id }),
            });
            lead.account_user_id = user.id;
          } catch (_) {}
        }
        // Their six most recent: enough to look back on, not a growing archive.
        const reports = lead ? allReports.filter((r) => r.lead_id === lead.id).slice(0, 6).map(({ lead_id, ...r }) => r) : [];
        // Super-admin visibility map (what fields clients may see). The page
        // merges this over the code defaults (report-fields.js) before rendering.
        const vrows = await sbGet(env, "report_settings", "id=eq.1&select=visibility");
        const visibility = (vrows && vrows[0] && vrows[0].visibility) || {};
        // Inter-brand: another TEG brand pays for this client, so they're never
        // shown a price (Danielle, 29 Sep 2026). Removed here, not hidden on
        // the page, so it never reaches their browser.
        let client = lead;
        if (lead) {
          const { inter_brand_invoice, ...rest } = lead;
          client = inter_brand_invoice ? { ...rest, price: null, brand_paid: true } : rest;
          // Shot and Scheduled: their quarterly shoot (Dani, 20 Oct).
          if (isShotAndScheduled(lead.package_name)) {
            try { client.shoot = await smmShootCycle(env, lead.id); } catch (_) {}
          }
        }
        return json({ ok: true, isClient, client, reports, visibility }, 200, request, env);
      }

      // ---- Admin: list a booking's messages + documents ----
      // Admin directory, for tagging colleagues in a note. Emails only - the
      // admins table's own RLS deliberately lets a user read just their own
      // row, so the list has to come from here, where the service role runs.
      if (path.endsWith("/admins/list") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const rows = (await sbGet(env, "admins", "select=email&order=email.asc")) || [];
        const emails = rows.map((r) => r.email).filter(Boolean);
        return json({ admins: emails }, 200, request, env);
      }

      // Create a shoot's archive folders. R2 has no folders - keys just contain
      // slashes and the dashboard renders them as a tree - so "creating" one
      // means writing a placeholder object inside it. Without that there is
      // nowhere to put anything until the first file lands, which is the
      // opposite of what Jack needs when he is about to drag files in.
      if (path.endsWith("/videography/archive-create") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String((b && b.booking_id) || "").trim();
        const folder = String((b && b.folder) || "").trim();
        const folders = Array.isArray(b && b.folders) ? b.folders : [];
        if (!id || !folder) return json({ error: "Missing booking or folder name." }, 400, request, env);
        if (!folders.length) return json({ error: "No subfolders to create." }, 400, request, env);

        const made = [];
        for (const sub of folders) {
          const key = safeFolderKey(folder, sub, ".keep");
          try {
            await env.BUCKET.put(key, new Uint8Array(0), { httpMetadata: { contentType: "text/plain" } });
            made.push(key.replace(/\/\.keep$/, ""));
          } catch (err) {
            return json({ error: `Couldn't create ${sub}: ${err && err.message ? err.message : err}` }, 502, request, env);
          }
        }
        // Record the name only once the folders actually exist, so the booking
        // never claims a folder that was never made.
        const dash = r2DashUrl(env, folder);
        await sbPatch(env, "videography_bookings", `id=eq.${encodeURIComponent(id)}`, {
          archive_folder: folder, archive_url: dash || null,
        });
        // The link on the card too, so it's to hand when something has to be
        // sent by hand. Internal note: the client never sees these.
        if (dash) {
          await logBookingMessage(env, {
            booking_id: id, booking_source: "videography", channel: "system", kind: "audit",
            subject: "Storage folder created",
            body: `Content folder in our storage: ${dash}`,
            is_automated: true, created_by: "system",
          });
        }
        return json({ ok: true, created: made, url: dash }, 200, request, env);
      }

      // Update the calendar event's location after the booking was made. For
      // agent shoots the meeting point is agreed with the client afterwards -
      // a coffee shop, a studio, somewhere that isn't their office - and it is
      // no use to Jack sitting in the admin centre if his diary still says a
      // postcode.
      if (path.endsWith("/booking/location") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String((b && b.booking_id) || "").trim();
        if (!id) return json({ error: "Missing booking_id" }, 400, request, env);
        const rows = await sbGet(env, "videography_bookings", `id=eq.${encodeURIComponent(id)}&select=ms_event_id,location,property_address,postcode`);
        const bk = rows && rows[0];
        if (!bk) return json({ error: "Booking not found." }, 404, request, env);
        if (!bk.ms_event_id) return json({ ok: true, updated: false, reason: "no calendar event" }, 200, request, env);
        const where = (bk.property_address || bk.location || bk.postcode || "").replace(/\s*\n\s*/g, ", ").trim();
        if (!where) return json({ ok: true, updated: false, reason: "nothing to set" }, 200, request, env);
        try {
          await graph(env, "PATCH", `/users/${encodeURIComponent(env.JACK_UPN)}/events/${bk.ms_event_id}`, {
            location: { displayName: where },
          });
        } catch (err) {
          return json({ error: "Couldn't update the calendar: " + (err && err.message ? err.message : err) }, 502, request, env);
        }
        return json({ ok: true, updated: true, location: where }, 200, request, env);
      }

      // Sync a booking's client into the CRM. The public booking flow has always
      // done this; a booking added by hand in the admin centre never did, so
      // those clients existed as bookings with no contact card. Same RPC and
      // the same tag rules, so a manual booking lands identically to a
      // self-served one - and upsert_contact merges rather than duplicates when
      // the person is already there.
      if (path.endsWith("/booking/contact") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String((b && b.booking_id) || "").trim();
        if (!id) return json({ error: "Missing booking_id" }, 400, request, env);
        const rows = await sbGet(env, "videography_bookings",
          `id=eq.${encodeURIComponent(id)}&select=client_name,client_email,client_phone,client_company,company,service_type,account_user_id,marketing_opt_in`);
        const bk = rows && rows[0];
        if (!bk) return json({ error: "Booking not found." }, 404, request, env);
        if (!bk.client_email) return json({ ok: true, synced: false, reason: "no email on the booking" }, 200, request, env);

        const fn = String(bk.client_name || "").trim().split(/\s+/);
        const tags = crmTags(bk.client_email, ["Videography-Client", videographyProductTag(bk.service_type)], {
          optIn: !!bk.marketing_opt_in, member: !!bk.account_user_id,
        });
        // sbRpc returns null on failure and stays silent unless you ask - which
        // is how the site-wide contact write once failed unnoticed for days.
        let rpcError = null;
        const res = await sbRpc(env, "upsert_contact", {
          p_email: bk.client_email,
          p_first_name: fn.shift() || bk.client_name || null,
          p_last_name: fn.join(" ") || null,
          p_phone: bk.client_phone || null,
          p_company: bk.client_company || bk.company || null,
          p_source: "videography_" + (bk.service_type || "manual"),
          p_lifecycle: "customer",
          p_marketing_opt_in: !!bk.marketing_opt_in,
          p_tags: tags,
          p_user_id: bk.account_user_id || null,
        }, (status, body) => { rpcError = `${status} ${String(body || "").slice(0, 200)}`; });
        if (rpcError) return json({ error: "Couldn't sync the contact: " + rpcError }, 502, request, env);
        return json({ ok: true, synced: true, email: bk.client_email, tags }, 200, request, env);
      }



/* ---- What follows an invoice being paid ----------------------------------
   The stored PDF gets its Paid stamp, and a videography invoice paid is the
   shoot paid, whichever page the button was pressed on: the PIN keys off the
   booking. From the Invoicing page this used to mark the invoice only, so the
   booking stayed unpaid and the PIN stayed locked (Raj Chinga, 30 Sep 2026). */
async function invoicePaidEffects(env, id, by) {
  try {
    const inv = (await sbGet(env, "invoices", `id=eq.${encodeURIComponent(id)}&select=*`))?.[0];
    if (inv) {
      const st = (await sbGet(env, "invoice_settings", "id=eq.1&select=*"))?.[0] || {};
      const pdf = await renderInvoicePdf(env, { ...st, template: inv.template || st.template }, inv);
      await env.BUCKET.put(`invoices/${inv.number || inv.id}.pdf`, pdf, { httpMetadata: { contentType: "application/pdf" } });
    }
  } catch (_) { /* stamp refresh is best-effort */ }
  const out = { pin_sent: false };
  try {
    const iv = (await sbGet(env, "invoices", `id=eq.${encodeURIComponent(id)}&select=booking_id,booking_source,number`))?.[0];
    if (iv && iv.booking_id && iv.booking_source === "videography") {
      const bk = (await sbGet(env, "videography_bookings", `id=eq.${encodeURIComponent(iv.booking_id)}&select=id,paid_at,pin_released_at`))?.[0];
      if (bk && !bk.paid_at) {
        await sbPatch(env, "videography_bookings", `id=eq.${encodeURIComponent(bk.id)}&paid_at=is.null`, { paid_at: new Date().toISOString() });
        await logBookingMessage(env, { booking_id: bk.id, booking_source: "videography", channel: "note", kind: "audit",
          body: `Payment received — invoice ${iv.number || ""} marked paid.`.replace("  ", " "), is_automated: true, created_by: by });
      }
      if (bk && !bk.pin_released_at) {
        const rel = await sendGalleryPinEmail(env, bk.id);
        if (rel && rel.ok) {
          out.pin_sent = true;
          await logBookingMessage(env, { booking_id: bk.id, booking_source: "videography", channel: "note", kind: "audit",
            body: `PIN released to ${rel.sent_to} — payment received.`, is_automated: true, created_by: by });
        }
      }
    }
  } catch (_) { /* the invoice is paid either way */ }
  return out;
}























// A field like the 360 tour link is typed by hand, and "google.co.uk" is a
// far more natural thing to type than "https://google.co.uk". Used as an
// href exactly as typed, the missing scheme makes the browser treat it as a
// path relative to wherever the link is opened, not an external site - which
// looks and behaves like a dead button, not an obviously wrong one. Fixed at
// render time rather than requiring the address always be entered in full.
function normalizeUrl(v) {
  const s = String(v || "").trim();
  if (!s) return "";
  return /^https?:\/\//i.test(s) ? s : `https://${s}`;
}



// Mints the edit-request page's capability token the first time it's needed
// (i.e. the first time a paid-path gallery email goes out), so the link
// always has something to point at. A plain random id, not HMAC - same style
// as videography_deliveries.token, and it never expires.

// The edits invitation, added only into the two paid-path gallery emails -
// never the not-yet-paid one, which keeps its wording as-is until that flow
// is revisited on purpose. Doesn't mention twilight/extra images by name -
// the /edits page itself surfaces those, conditionally, once they're there.
function editRequestPromptHtml(env, token) {
  const siteUrl = (env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "");
  // EM_P's own top margin is 0 - fine between two body paragraphs, but this
  // sits right after the small-print amendments clause (0 bottom margin on
  // that one too), so without an explicit gap here the two collide with no
  // breathing room and the size/colour jump reads as a formatting mistake.
  return `<p style="${EM_P}margin-top:18px;">Once you've had a chance to look through everything, your package includes one round of edits if there's anything you'd like us to change. Just send us all of your requests using the link below and we'll take care of the rest.</p>
    <p style="${EM_P}"><a href="${siteUrl}/edits?token=${encodeURIComponent(token)}" style="${EM_BTN}">Request Edits</a></p>`;
}

// Emails Jack when a client submits an edit request - a free-text-only one
// straight away, a paid one once the Stripe webhook confirms it. Idempotent
// via notified_at, so a Stripe retry (or a resend) can never double-send.
async function notifyEditRequest(env, requestId) {
  const rows = await sbGet(env, "videography_edit_requests", `id=eq.${encodeURIComponent(requestId)}&select=*`);
  const req = rows && rows[0];
  if (!req) return { ok: false, reason: "no request" };
  if (req.notified_at) return { ok: false, reason: "already notified" };

  const brows = await sbGet(env, "videography_bookings", `id=eq.${encodeURIComponent(req.booking_id)}&select=*`);
  const bk = brows && brows[0];
  if (!bk) return { ok: false, reason: "no booking" };

  const team = [...new Set([env.JACK_NOTIFY || env.JACK_UPN]
    .flatMap((v) => String(v || "").split(","))
    .map((v) => v.trim()).filter(Boolean))];
  if (!team.length) return { ok: false, reason: "no recipient configured" };

  const esc = (v) => String(v ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  const siteUrl = (env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "");
  const bookingLink = `${siteUrl}/admin/videography?booking=${encodeURIComponent(bk.id)}`;

  const twilightRows = Array.isArray(req.twilight_items) ? req.twilight_items : [];
  const twilightTotal = twilightRows.reduce((s, it) => s + (it.price_pence || 0), 0);
  const paidExtras = twilightRows.length > 0 || !!req.extra_images_qty;

  const parts = [];
  const shootTitle = String(bk.shoot_name || "").trim();
  parts.push(`<p style="${EM_P}"><strong>${esc(bk.client_name || "A client")}</strong> has asked for edits on their ${esc((bk.service || "shoot").toLowerCase())}${shootTitle ? `, ${esc(shootTitle)}` : ""}.</p>`);
  if (req.notes) parts.push(`<p style="${EM_P}"><strong>What they asked for:</strong><br>${esc(req.notes).replace(/\n/g, "<br>")}</p>`);
  if (twilightRows.length) {
    parts.push(`<p style="${EM_P}"><strong>Twilight requested:</strong> ${twilightRows.length} image${twilightRows.length === 1 ? "" : "s"}, paid (${esc(gbpW(twilightTotal))}):</p>
      <ul style="${EM_P}">${twilightRows.map((it) => `<li>${esc(it.filename || "unnamed")}</li>`).join("")}</ul>`);
  }
  if (req.extra_images_qty) {
    parts.push(`<p style="${EM_P}"><strong>Extra images bought:</strong> ${req.extra_images_qty} more, paid (${esc(gbpW(req.extra_images_price_pence || 0))}). Increase their download cap on the booking.</p>`);
  }
  parts.push(`<p style="${EM_P}"><a href="${esc(bookingLink)}" style="${EM_BTN}">Open their booking</a></p>`);

  const sent = await sendEmail(env, {
    to: team,
    subject: `Edits requested: ${bk.client_name || "a client"}.`,
    html: await wrapInBrandedBase(env, `<div style="${EM_WRAP}">${parts.join("")}</div>`),
  });
  // What they asked for goes in the shoot's notes whatever happens to the email,
  // and the note says so if Jack wasn't told (Dani, 7 Nov).
  const noteLines = ["Edits requested."];
  if (req.notes) noteLines.push(req.notes);
  if (twilightRows.length) noteLines.push(`Twilight, paid: ${twilightRows.map((it) => it.filename || "unnamed").join(", ")}`);
  if (req.extra_images_qty) noteLines.push(`Extra images bought, paid: ${req.extra_images_qty}`);
  if (!sent.ok) noteLines.push("The email to Jack didn't send, so he needs telling.");
  await logBookingMessage(env, {
    booking_id: bk.id, booking_source: "videography",
    channel: "note", kind: "edit_request",
    subject: `Edit request${paidExtras ? " (paid add-on)" : ""}`,
    body: noteLines.join("\n"),
    is_automated: true, created_by: "system",
  });
  if (!sent.ok) return { ok: false, reason: sent.error || "send failed" };

  await sbPatch(env, "videography_edit_requests", `id=eq.${encodeURIComponent(requestId)}&notified_at=is.null`, {
    status: "notified", notified_at: new Date().toISOString(),
  });
  return { ok: true };
}

// Closes the loop from the client's side: Jack has done the edits (and any
// paid extras) and settled up with them directly, so this just confirms it's
// all done from our end, points them back to their account for the booking
// details, and asks for a review. Idempotent via edits_complete_email_sent_at
// so re-ticking "edits settled" on the client file can never double-send.
async function sendEditsCompleteEmail(env, bookingId) {
  await loadEmailStyles(env);
  const rows = await sbGet(env, "videography_bookings", `id=eq.${encodeURIComponent(bookingId)}&select=*`);
  const bk = rows && rows[0];
  if (!bk) return { ok: false, reason: "no booking" };
  if (bk.edits_complete_email_sent_at) return { ok: false, reason: "already sent" };

  const to = bk.gallery_email || bk.client_email;
  if (!to) return { ok: false, reason: "no recipient" };

  const esc = (v) => String(v ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  const siteUrl = (env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "");
  const firstName = String(bk.client_name || "").trim().split(/\s+/)[0] || "there";

  // Say back what was actually done. A close-out email that only says "all
  // done" makes the reader go and look up which shoot it means.
  const when = bk.shoot_date
    ? new Date(bk.shoot_date).toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" })
    : "";
  const where = (bk.location || bk.postcode || "").trim();
  const facts = [
    ["Shoot", bk.service || "Videography"],
    when ? ["Filmed", when] : null,
    where ? ["Where", where] : null,
  ].filter(Boolean);
  const factsHtml = facts
    .map(([k, v]) => `<p style="${EM_P}margin:0 0 4px;"><strong>${esc(k)}</strong> &nbsp;${esc(v)}</p>`)
    .join("");

  // Only claim the amends are done if they actually asked for some.
  let amendsLine = "";
  try {
    const reqs = await sbGet(env, "videography_edit_requests",
      `booking_id=eq.${encodeURIComponent(bk.id)}&select=id`);
    if (reqs && reqs.length) {
      amendsLine = `<p style="${EM_P}">The changes you asked for have now been made and you&rsquo;ll find the updated content in your gallery.</p>`;
    }
  } catch (_) { /* the rest of the email is still worth sending */ }

  /* Do they already have somewhere to log in to?

     Two ways to have an account, and both count: the booking may be attached
     to one directly (which is what linking a contact in the admin centre now
     does), or the CRM contact on their email may carry a user. Only when
     neither is true is there anything worth inviting them to. Asking someone
     to create an account they already have is the fastest way to be ignored. */
  let hasAccount = !!bk.account_user_id;
  if (!hasAccount) {
    const addr = String(bk.client_email || "").trim().toLowerCase();
    if (addr) {
      try {
        const cs = await sbGet(env, "contacts",
          `email=eq.${encodeURIComponent(lc(addr))}&select=user_id&limit=1`);
        hasAccount = !!(cs && cs[0] && cs[0].user_id);
      } catch (_) { /* can't tell — say nothing rather than nag */ hasAccount = true; }
    }
  }
  const accountLine = hasAccount ? "" : `
    <p style="${EM_P}">One more thing. You don&rsquo;t have a TMKE Member Account yet. It&rsquo;s the easiest way to keep track of your bookings, galleries and invoices all in one place, and it only takes a minute to set up using this email address.</p>
    <p style="${EM_P}">You&rsquo;ll also get access to our exclusive Design Studio, plus marketing insights, resources and training created specifically for the property industry.</p>
    <p style="${EM_P}"><a href="${siteUrl}/join?email=${encodeURIComponent(bk.client_email || "")}" style="${EM_BTN}">Create Your Account</a></p>`;

  /* The review link carries the booking, the name and the service. Without
     them the client retypes what we already know - and, more importantly, the
     review comes back with nothing tying it to the shoot, so their bookings
     page goes on asking for a review they have already left. */
  const reviewUrl = `${siteUrl}/leave-a-review`
    + `?booking=${encodeURIComponent(bk.id)}`
    + `&service=${encodeURIComponent(bk.service || "")}`
    + `&name=${encodeURIComponent(bk.client_name || "")}`;

  // The gallery emails' look (deliveryShell), 10 Nov 2026.
  const built = deliveryEmail("wrap", {
    first: deliveryFirstName(bk.client_name), shoot: deliveryShootLine(bk), cover: bk.cover_url || "",
    galleryUrl: bk.gallery_url || "", reviewUrl, amends: !!amendsLine, hasAccount,
    bookingsUrl: `${siteUrl}/account/bookings`, joinUrl: `${siteUrl}/join?email=${encodeURIComponent(bk.client_email || "")}`,
  });
  const sent = await sendEmail(env, { to, subject: built.subject, html: built.html });
  if (!sent.ok) return { ok: false, reason: sent.error || "send failed" };

  await sbPatch(env, "videography_bookings", `id=eq.${encodeURIComponent(bookingId)}&edits_complete_email_sent_at=is.null`, {
    edits_complete_email_sent_at: new Date().toISOString(),
  });
  await logBookingMessage(env, {
    booking_id: bk.id, booking_source: "videography",
    channel: "email", kind: "edits_complete",
    subject: "All done — close-out email", body: `Sent to ${to}.`,
    is_automated: true, created_by: "system",
  });
  return { ok: true };
}

// The second email: they were sent their gallery before paying, so they have
// the links but not the PIN. This is what closes that loop when the money
// lands - without it, someone who pays after delivery waits for a human to
// notice. Returns quietly when it does not apply.
async function sendGalleryPinEmail(env, bookingId) {
  const rows = await sbGet(env, "videography_bookings", `id=eq.${encodeURIComponent(bookingId)}&select=*`);
  const bk = rows && rows[0];
  if (!bk) return { ok: false, reason: "no booking" };
  // Delivered by portal: no gallery and no PIN. The folder shows by itself.
  if (bk.delivery_method === "portal") return { ok: false, reason: "delivered by portal" };
  // Only if they have already had the gallery: otherwise the normal
  // gallery-ready email will carry the PIN itself, and two emails would be
  // confusing rather than helpful.
  if (!bk.gallery_sent_at) return { ok: false, reason: "gallery not sent yet" };
  if (bk.pin_released_at) return { ok: false, reason: "already released" };
  const prow = await sbGet(env, "videography_gallery_pins", `booking_id=eq.${encodeURIComponent(bookingId)}&select=pin`);
  const pin = (prow && prow[0] && prow[0].pin) || "";
  if (!pin) return { ok: false, reason: "no pin saved" };
  const to = bk.gallery_email || bk.client_email;
  if (!to) return { ok: false, reason: "no address" };
  // Same release moment as the PIN - if a 360 tour is set, this is the first
  // time the client is allowed to see it.
  const trow = await sbGet(env, "videography_tour_links", `booking_id=eq.${encodeURIComponent(bookingId)}&select=url`);
  const tourUrl = normalizeUrl((trow && trow[0] && trow[0].url) || "");

  const siteUrl = (env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "");
  const editsToken = await ensureEditsToken(env, bk);
  // Previous Bookings only helps someone who can sign in to the Studio.
  const account = bk.account_user_id || (bk.client_email && ((await sbGet(env, "contacts", `email=ilike.${encodeURIComponent(bk.client_email)}&user_id=not.is.null&select=id&limit=1`)) || []).length);
  const mail = deliveryEmail("pin", {
    first: deliveryFirstName(bk.client_name), shoot: deliveryShootLine(bk), cover: bk.cover_url || "",
    pin, email: to, galleryUrl: bk.gallery_url, tourUrl,
    extra: bk.extra_link_url ? { label: bk.extra_link_label, url: bk.extra_link_url } : null,
    editsUrl: `${siteUrl}/edits?token=${encodeURIComponent(editsToken)}`, inStudio: !!account,
  });
  const sent = await sendEmail(env, { to, subject: mail.subject, html: mail.html });
  if (!sent.ok) return { ok: false, reason: sent.error || "send failed" };

  await sbPatch(env, "videography_bookings", `id=eq.${encodeURIComponent(bookingId)}`, { pin_released_at: new Date().toISOString() });
  await logBookingMessage(env, {
    booking_id: bookingId, booking_source: "videography",
    account_user_id: bk.account_user_id, client_email: to,
    channel: "email", kind: "pin_released", subject: mail.subject,
    body: "Payment received - PIN sent.", is_automated: true, created_by: "system",
  });
  return { ok: true, sent_to: to };
}

      // "Your gallery is ready". Two versions of the same email, decided by
      // whether the shoot has been paid for - because the PIN is what unlocks
      // downloading, and it is the only thing being withheld.
      // Ask a Fine & Country office to confirm they hold the seller's marketing
      // fee. Jack sends this himself once he has checked the booking details,
      // which is why it is a button rather than something automatic - the whole
      // point is that a person has looked before we ask.
      if (path.endsWith("/videography/fc-confirm") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String((b && b.booking_id) || "").trim();
        const to = String((b && b.to) || "").trim();
        if (!id || !to) return json({ error: "Missing booking or recipient." }, 400, request, env);

        const rows = await sbGet(env, "videography_bookings", `id=eq.${encodeURIComponent(id)}&select=*`);
        const bk = rows && rows[0];
        if (!bk) return json({ error: "Booking not found." }, 404, request, env);

        const esc = (v) => String(v ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
        const office = (FC_OFFICE_LABELS[bk.fc_office] || "your office");
        const where = (bk.property_address || bk.location || "").replace(/\s*\n\s*/g, ", ").trim();
        const when = bk.shoot_date
          ? new Date(bk.shoot_date).toLocaleDateString("en-GB", { weekday: "long", day: "numeric", month: "long", year: "numeric" })
          : "a date to be confirmed";
        const amount = bk.total_pence != null ? gbpW(bk.total_pence) : null;

        const sent = await sendEmail(env, {
          to,
          cc: (b && b.cc) || null,
          subject: `Marketing fee confirmation - ${bk.client_name || "agent"}${where ? ` - ${where}` : ""}`,
          html: await wrapInBrandedBase(env, `<div style="${EM_WRAP}">
            <p style="${EM_P}">Hello,</p>
            <p style="${EM_P}">${esc(bk.client_name || "The agent")} has booked a ${esc((bk.service || "videography").toLowerCase())} shoot with us${where ? ` at ${esc(where)}` : ""}, scheduled for ${esc(when)}.</p>
            <p style="${EM_P}">${esc(firstName(bk.client_name))} has advised that the seller's marketing fee for this property is held by ${esc(office)}, and that the shoot should therefore be invoiced to you rather than to the agent directly.</p>
            <p style="${EM_P}">Before we raise the invoice${amount ? ` for ${esc(amount)}` : ""}, could you please confirm that this is correct?</p>
            <p style="${EM_P}">If the marketing fee isn't held by you, just let us know and we'll invoice the agent directly instead.</p>
            <p style="${EM_P}">Many thanks,<br>TMKE</p>
          </div>`),
        });
        if (!sent.ok) return json({ error: "The email didn't send: " + (sent.error || "unknown") }, 502, request, env);

        await sbPatch(env, "videography_bookings", `id=eq.${encodeURIComponent(id)}`, {
          fc_confirm_email: to, fc_confirm_sent_at: new Date().toISOString(),
        });
        await logBookingMessage(env, {
          booking_id: id, booking_source: "videography",
          account_user_id: bk.account_user_id, client_email: to,
          channel: "email", kind: "fc_fee_confirm",
          subject: `Marketing fee confirmation - ${bk.client_name || "agent"}`,
          body: `Asked ${to} to confirm the marketing fee is held.`,
          is_automated: false, created_by: user.email || "admin",
        });
        return json({ ok: true, sent_to: to }, 200, request, env);
      }

      // Release the PIN by hand - the same email the webhook sends, for payments
      // that arrive by bank transfer rather than card.
      if (path.endsWith("/videography/release-pin") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String((b && b.booking_id) || "").trim();
        if (!id) return json({ error: "Missing booking_id" }, 400, request, env);
        const res = await sendGalleryPinEmail(env, id);
        if (!res.ok) return json({ error: "Not sent: " + res.reason }, 400, request, env);
        return json({ ok: true, sent_to: res.sent_to }, 200, request, env);
      }

      if (path.endsWith("/videography/gallery-email") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String((b && b.booking_id) || "").trim();
        if (!id) return json({ error: "Missing booking_id" }, 400, request, env);

        const rows = await sbGet(env, "videography_bookings", `id=eq.${encodeURIComponent(id)}&select=*`);
        const bk = rows && rows[0];
        if (!bk) return json({ error: "Booking not found." }, 404, request, env);
        if (!bk.gallery_url) return json({ error: "Add the gallery link before sending." }, 400, request, env);
        const to = bk.gallery_email || bk.client_email;
        if (!to) return json({ error: "No email address to send to." }, 400, request, env);

        // THE RULE, in one place: a PIN only ever leaves this building when
        // paid_at is set. Everything else - which template, what the admin card
        // says, the toggle on screen - is presentation. This is the check that
        // actually stops it, and it reads from the database rather than from
        // anything the sender could have changed on screen.
        const paid = isSettled(bk);
        let pin = "", tourUrl = "";
        if (paid) {
          const prow = await sbGet(env, "videography_gallery_pins", `booking_id=eq.${encodeURIComponent(id)}&select=pin`);
          pin = (prow && prow[0] && prow[0].pin) || "";
          if (!pin) return json({ error: "This shoot is paid but has no PIN saved - add it before sending." }, 400, request, env);
          // Same rule as the PIN: only ever fetched, and only ever mentioned in
          // the email, once paid is confirmed here from the database.
          const trow = await sbGet(env, "videography_tour_links", `booking_id=eq.${encodeURIComponent(id)}&select=url`);
          tourUrl = (trow && trow[0] && trow[0].url) || "";
        }

        // Unpaid: attach the invoice and give them a way to pay it.
        let attachments, payUrl = null, invNumber = null;
        if (!paid) {
          const invs = (await sbGet(env, "invoices", `booking_id=eq.${encodeURIComponent(id)}&select=id,number,status,pay_by_card&order=created_at.desc`)) || [];
          const live = invs.find((iv) => iv.status !== "void" && iv.status !== "paid");
          if (live) {
            invNumber = live.number;
            if (live.pay_by_card && env.STRIPE_SECRET_KEY) payUrl = await invoicePayUrl(env, live.id);
            try {
              const obj = await env.BUCKET.get(`invoices/${live.number}.pdf`);
              if (obj) attachments = [{ filename: `Invoice-${live.number}.pdf`, content: bufToBase64(await obj.arrayBuffer()), contentType: "application/pdf" }];
            } catch (_) {}
          }
        }

        // The new emails, agreed 7 Nov. The rule above still decides what's in them.
        const mail = deliveryEmail(paid ? "paid" : "unpaid", {
          first: deliveryFirstName(bk.client_name), shoot: deliveryShootLine(bk), cover: bk.cover_url || "",
          pin, email: to, galleryUrl: bk.gallery_url, tourUrl,
          extra: bk.extra_link_url ? { label: bk.extra_link_label, url: bk.extra_link_url } : null,
          editsUrl: paid ? `${String(env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "")}/edits?token=${encodeURIComponent(await ensureEditsToken(env, bk))}` : "",
          invoiceNo: invNumber, payUrl, attached: !!attachments,
        });
        const sent = await sendEmail(env, { to, subject: mail.subject, html: mail.html, attachments });
        if (!sent.ok) return json({ error: "The email didn't send: " + (sent.error || "unknown") }, 502, request, env);

        await sbPatch(env, "videography_bookings", `id=eq.${encodeURIComponent(id)}`, { gallery_sent_at: new Date().toISOString() });
        await logBookingMessage(env, {
          booking_id: id, booking_source: "videography",
          account_user_id: bk.account_user_id, client_email: to,
          channel: "email", kind: "gallery_ready",
          subject: mail.subject,
          body: paid ? "Gallery link sent with the PIN." : "Gallery link sent; PIN withheld pending payment.",
          is_automated: false, created_by: user.email || "admin",
        });
        return json({ ok: true, sent_to: to, included_pin: paid }, 200, request, env);
      }

      // ---- Public: the edit-request page (no login) --------------------------
      // Reached from a link in the paid-path gallery emails. Token-gated, same
      // style as the /deliver gallery - the credential IS the (unguessable)
      // token, checked against edits_token, no session needed.
      //
      // Which upsell (if any) the page offers is decided HERE from the
      // booking's service, not trusted from the client - property shoots get
      // faux twilight, agent/induction shoots get the extra-images bundle,
      // everything else (Content Studio) gets the free-text box only.
      function editRequestUpsellKind(bk) {
        const hay = `${bk.service_type || ""} ${bk.service || ""}`.toLowerCase();
        if (/property/.test(hay)) return "twilight";
        // Agent shoots proper, and the new-starter induction Studio Day
        // (service "New-Starter Studio Day", service_type "content-studio" -
        // it's an agent-family shoot with a limited image count, same as any
        // other agent booking, just booked through a different flow).
        if (/agent/.test(hay) || /induction|new-starter/.test(hay)) return "extra_images";
        return null;
      }

      if (path.endsWith("/videography/edit-request/context") && request.method === "GET") {
        const token = (url.searchParams.get("token") || "").trim();
        if (!token) return json({ error: "Missing token" }, 400, request, env);
        const rows = await sbGet(env, "videography_bookings",
          `edits_token=eq.${encodeURIComponent(token)}&select=id,client_name,service,service_type,paid_at,payment_route,released_unpaid_at`);
        const bk = rows && rows[0];
        if (!bk) return json({ error: "That link isn't valid." }, 404, request, env);
        // The rule, same as the PIN: read from the database, not from anything
        // the page itself could claim.
        // A shoot released before payment has its content, so it gets its edits too.
        if (!isSettled(bk) && !bk.released_unpaid_at) return json({ error: "This booking hasn't been paid for yet." }, 403, request, env);
        return json({
          ok: true,
          client_name: bk.client_name || "",
          upsell: editRequestUpsellKind(bk),
          twilight_price_pence: FAUX_TWILIGHT_PRICE_PENCE,
          extra_images: EXTRA_IMAGES_BUNDLE,
        }, 200, request, env);
      }

      if (path.endsWith("/videography/edit-request") && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        const token = String((b && b.token) || "").trim();
        if (!token) return json({ error: "Missing token" }, 400, request, env);
        const rows = await sbGet(env, "videography_bookings", `edits_token=eq.${encodeURIComponent(token)}&select=*`);
        const bk = rows && rows[0];
        if (!bk) return json({ error: "That link isn't valid." }, 404, request, env);
        // A shoot released before payment has its content, so it gets its edits too.
        if (!isSettled(bk) && !bk.released_unpaid_at) return json({ error: "This booking hasn't been paid for yet." }, 403, request, env);

        const notes = String((b && b.notes) || "").trim().slice(0, 4000);
        const upsell = editRequestUpsellKind(bk);

        // Filenames and a yes/no are all the client gets to say - the price is
        // always ours, re-derived from the constants above.
        let twilightItems = [];
        if (upsell === "twilight" && Array.isArray(b.twilight_filenames)) {
          twilightItems = b.twilight_filenames
            .map((f) => String(f || "").trim()).filter(Boolean).slice(0, 100)
            .map((filename) => ({ filename, price_pence: FAUX_TWILIGHT_PRICE_PENCE }));
        }
        const wantsExtraImages = upsell === "extra_images" && !!b.extra_images;
        const extraQty = wantsExtraImages ? EXTRA_IMAGES_BUNDLE.qty : null;
        const extraPrice = wantsExtraImages ? EXTRA_IMAGES_BUNDLE.price_pence : null;

        if (!notes && !twilightItems.length && !wantsExtraImages) {
          return json({ error: "Add a note, or choose something to buy, before sending." }, 400, request, env);
        }

        // Line items are held net (that is how they are quoted); the charge is gross.
        const netPence = twilightItems.reduce((s, it) => s + it.price_pence, 0) + (extraPrice || 0);
        const { vat: upsellVat, gross: totalPence } = await vatBreakdown(env, netPence);

        const ins = await sbPost(env, "videography_edit_requests", {
          booking_id: bk.id, notes: notes || null,
          twilight_items: twilightItems, extra_images_qty: extraQty, extra_images_price_pence: extraPrice,
          vat_pence: upsellVat, total_pence: totalPence,
        }, "return=representation");
        const created = await ins.json().catch(() => null);
        const reqRow = Array.isArray(created) ? created[0] : created;
        if (!reqRow || !reqRow.id) {
          // The client gets the same sentence either way - there is nothing
          // useful it could do with a Postgres error code. But it goes to the
          // Worker log, because the one time this fired it was a column the
          // table never had, and the reply said "please try again" about a
          // failure that was never going to stop happening. `wrangler tail`
          // now says which column.
          console.log("edit-request insert failed", ins.status, JSON.stringify(created));
          return json({ error: "Couldn't save your request. Please try again." }, 500, request, env);
        }

        // Free-text only, nothing to pay - tell Jack straight away rather than
        // waiting on a payment that was never coming.
        if (totalPence <= 0) {
          await notifyEditRequest(env, reqRow.id);
          return json({ ok: true }, 200, request, env);
        }

        if (!env.STRIPE_SECRET_KEY) return json({ error: "Card payment isn't available yet - please reply to one of our emails and we'll sort it out." }, 503, request, env);

        const origin = request.headers.get("Origin") || "";
        const allowed = String(env.ALLOWED_ORIGINS || "").split(",").map((s) => s.trim());
        const base = allowed.includes(origin) ? origin : (env.SITE_URL || "https://tmke.co.uk");
        // A request from the client portal goes back there, not to the old edits page.
        const back = /^\/portal(-new)?\?c=[^/\s]+$/.test(String((b && b.return_path) || "")) ? b.return_path : "";
        const productName = twilightItems.length
          ? `Faux twilight - ${twilightItems.length} image${twilightItems.length === 1 ? "" : "s"}`
          : `${EXTRA_IMAGES_BUNDLE.qty} extra images`;

        try {
          const session = await stripeApi(env, "checkout/sessions", {
            mode: "payment",
            "payment_method_types[0]": "card",
            success_url: back ? `${base}${back}&paid=1` : `${base}/edits?token=${encodeURIComponent(token)}&paid=1`,
            cancel_url: back ? `${base}${back}` : `${base}/edits?token=${encodeURIComponent(token)}`,
            "metadata[edit_request_id]": reqRow.id,
            "metadata[upsell_type]": twilightItems.length ? "twilight" : "extra_images",
            "line_items[0][quantity]": 1,
            "line_items[0][price_data][currency]": "gbp",
            "line_items[0][price_data][unit_amount]": totalPence,
            "line_items[0][price_data][product_data][name]": productName,
          });
          await sbPatch(env, "videography_edit_requests", `id=eq.${encodeURIComponent(reqRow.id)}`, { stripe_session_id: session.id });
          return json({ ok: true, checkout_url: session.url }, 200, request, env);
        } catch (e) {
          return json({ error: "Couldn't reach the payment provider. Please try again." }, 502, request, env);
        }
      }

      // Admin-triggered: fires from the "edits settled" tickbox on the client
      // file once Jack's confirmed everything's done and settled with the
      // client directly. Not automatic on the tick itself — the admin calls
      // this explicitly so a re-tick (untick/retick) never re-sends.
      // A shoot booked from the social media side rather than by Jack. The
      // social manager usually hears about it first, so they can enter it —
      // but Jack has to be told, or it sits on a board nobody has looked at.
      if (path.endsWith("/videography/notify-new-booking") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String((b && b.booking_id) || "").trim();
        if (!id) return json({ error: "Missing booking_id" }, 400, request, env);

        const rows = await sbGet(env, "videography_bookings", `id=eq.${encodeURIComponent(id)}&select=*`);
        const bk = rows && rows[0];
        if (!bk) return json({ error: "No such booking." }, 404, request, env);

        // JACK_NOTIFY overrides JACK_UPN rather than adding to it, matching
        // every other booking notification in this file.
        const team = env.JACK_NOTIFY || env.JACK_UPN;
        if (!team) return json({ error: "No recipient configured." }, 503, request, env);

        const esc = (v) => String(v ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
        const siteUrl = (env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "");
        const link = `${siteUrl}/admin/videography?booking=${encodeURIComponent(bk.id)}`;
        const when = bk.shoot_date
          ? new Date(bk.shoot_date).toLocaleString("en-GB", { weekday: "long", day: "numeric", month: "long", year: "numeric", hour: "2-digit", minute: "2-digit", timeZone: "Europe/London" })
          : "No date yet — needs arranging";
        const bookedBy = String((b && b.booked_by) || "").trim();
        const where = bk.property_address || bk.location || "";

        const row = (k, v) => v ? `<p style="${EM_P}"><strong>${esc(k)}</strong> ${esc(v)}</p>` : "";
        const body = `
          <p style="${EM_P}">A shoot has been booked from the social media side${bookedBy ? ` by ${esc(bookedBy)}` : ""}. It is already on your board — nothing to accept, this is just so you know it is there.</p>
          ${row("Client", bk.client_name)}
          ${row("What", bk.service)}
          ${row("When", when)}
          ${row("Where", where)}
          ${row("Notes", bk.notes)}
          <p style="${EM_P}">Covered by their social media package, so there is nothing to invoice.</p>
          <p style="${EM_P}"><a href="${link}" style="${EM_BTN}">Open the booking</a></p>`;

        try {
          await sendEmail(env, {
            to: team,
            subject: `New shoot booked - ${bk.client_name || "SMM client"}${bk.shoot_date ? " - " + when : ""}`,
            html: await wrapInBrandedBase(env, body),
          });
        } catch (e) {
          return json({ error: "Couldn't send that email." }, 502, request, env);
        }
        return json({ ok: true }, 200, request, env);
      }

      if (path.endsWith("/videography/edits-complete-email") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String((b && b.booking_id) || "").trim();
        if (!id) return json({ error: "Missing booking_id" }, 400, request, env);
        const result = await sendEditsCompleteEmail(env, id);
        if (!result.ok) return json({ error: result.reason === "already sent" ? "Already sent." : "Couldn't send that email." }, 400, request, env);
        return json({ ok: true }, 200, request, env);
      }

      // A member's own PIN. Sits behind three checks, because this is the one
      // secret in the whole flow: signed in, the booking is theirs, and it has
      // been paid for. The PIN lives in a table members cannot read at all, so
      // this endpoint is the only way it can reach them - which is the point.
      if (path.endsWith("/videography/my-pin") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in first." }, 401, request, env);
        const id = (url.searchParams.get("booking_id") || "").trim();
        if (!id) return json({ error: "Missing booking_id" }, 400, request, env);

        const rows = await sbGet(env, "videography_bookings",
          `id=eq.${encodeURIComponent(id)}&select=account_user_id,client_email,paid_at,payment_route`);
        const bk = rows && rows[0];
        if (!bk) return json({ error: "Not found." }, 404, request, env);

        const mine = (bk.account_user_id && bk.account_user_id === user.id)
          || (bk.client_email && String(bk.client_email).toLowerCase() === String(user.email || "").toLowerCase());
        // Deliberately the same answer as "no such booking": telling someone
        // a booking exists but isn't theirs is information they don't need.
        if (!mine) return json({ error: "Not found." }, 404, request, env);
        if (!isSettled(bk)) return json({ ok: true, paid: false }, 200, request, env);

        const prow = await sbGet(env, "videography_gallery_pins", `booking_id=eq.${encodeURIComponent(id)}&select=pin`);
        const pin = (prow && prow[0] && prow[0].pin) || "";
        return json({ ok: true, paid: true, pin }, 200, request, env);
      }

      // A member's own 360 tour link. Exactly the same three checks as the
      // PIN above, for exactly the same reason - it lives in its own table
      // no member can read, so this endpoint is the only way it can reach
      // them, and only once paid_at is actually set.
      if (path.endsWith("/videography/my-tour") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in first." }, 401, request, env);
        const id = (url.searchParams.get("booking_id") || "").trim();
        if (!id) return json({ error: "Missing booking_id" }, 400, request, env);

        const rows = await sbGet(env, "videography_bookings",
          `id=eq.${encodeURIComponent(id)}&select=account_user_id,client_email,paid_at,payment_route`);
        const bk = rows && rows[0];
        if (!bk) return json({ error: "Not found." }, 404, request, env);

        const mine = (bk.account_user_id && bk.account_user_id === user.id)
          || (bk.client_email && String(bk.client_email).toLowerCase() === String(user.email || "").toLowerCase());
        if (!mine) return json({ error: "Not found." }, 404, request, env);
        if (!isSettled(bk)) return json({ ok: true, paid: false }, 200, request, env);

        const trow = await sbGet(env, "videography_tour_links", `booking_id=eq.${encodeURIComponent(id)}&select=url`);
        const tourUrl = normalizeUrl((trow && trow[0] && trow[0].url) || "");
        return json({ ok: true, paid: true, url: tourUrl }, 200, request, env);
      }

      if (path.endsWith("/booking/thread") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const id = (url.searchParams.get("booking_id") || "").trim();
        if (!id) return json({ error: "Missing booking_id" }, 400, request, env);
        const messages = (await sbGet(env, "booking_messages", `booking_id=eq.${encodeURIComponent(id)}&select=*&order=created_at.asc`)) || [];
        // Full select includes the invoice date columns; fall back to the base
        // columns if they haven't been added yet (so documents still load).
        let documents = await sbGet(env, "booking_documents", `booking_id=eq.${encodeURIComponent(id)}&select=id,category,title,file_name,size_bytes,content_type,uploaded_by,invoice_date,paid_date,created_at&order=created_at.asc`);
        if (documents == null) documents = (await sbGet(env, "booking_documents", `booking_id=eq.${encodeURIComponent(id)}&select=id,category,title,file_name,size_bytes,content_type,uploaded_by,created_at&order=created_at.asc`)) || [];
        return json({ messages, documents }, 200, request, env);
      }

      // ---- Admin: a client file's Communication tab was opened --------------
      // Everything the client sent (hub messages, emails in) counts as read.
      // Danielle, 20 Oct 2026. read_at comes with supabase/smm_communication.sql.
      if (path.endsWith("/booking/thread/read") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const id = String((b && b.booking_id) || "").trim();
        if (!id) return json({ error: "Missing booking_id" }, 400, request, env);
        const res = await fetch(`${env.SUPABASE_URL}/rest/v1/booking_messages?booking_id=eq.${encodeURIComponent(id)}&direction=eq.inbound&read_at=is.null`, {
          method: "PATCH",
          headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=minimal" },
          body: JSON.stringify({ read_at: new Date().toISOString() }),
        });
        if (!res.ok) return json({ error: "Couldn't mark them read: " + (await res.text()).slice(0, 160) }, 500, request, env);
        return json({ ok: true }, 200, request, env);
      }

      // ---- Admin: attach a document (raw body → R2 + row) ----
      if (path.endsWith("/booking/document") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const q = url.searchParams;
        const bookingId = (q.get("booking_id") || "").trim();
        const source = q.get("source") === "smm" ? "smm" : "videography";
        const category = ["agreement", "prep", "strategy", "brand", "invoice", "delivery", "content_plan", "insights_report", "other"].includes(q.get("category")) ? q.get("category") : "other";
        const fileName = (q.get("file_name") || "document").replace(/[^a-zA-Z0-9._-]+/g, "-").slice(0, 120);
        const title = q.get("title") || null;
        const invoiceDate = /^\d{4}-\d{2}-\d{2}$/.test(q.get("invoice_date") || "") ? q.get("invoice_date") : null;
        const contentType = q.get("content_type") || request.headers.get("Content-Type") || "application/octet-stream";
        if (!bookingId) return json({ error: "Missing booking_id" }, 400, request, env);
        const bk = await lookupBooking(env, source, bookingId);
        if (!bk) return json({ error: "Booking not found." }, 404, request, env);
        const idSafe = bookingId.replace(/[^a-zA-Z0-9_-]/g, "");
        const key = `booking-docs/${idSafe}/${Date.now()}-${fileName}`;
        const body = await request.arrayBuffer();
        await env.BUCKET.put(key, body, { httpMetadata: { contentType } });
        // Only reference invoice_date when it's set, so ordinary uploads still
        // work even if that column hasn't been added yet.
        const docRow = {
          booking_id: bookingId, booking_source: source, account_user_id: bk.account_user_id, client_email: bk.email,
          category, title, file_name: fileName, r2_key: key, content_type: contentType, size_bytes: body.byteLength,
          uploaded_by: user.email || "admin",
        };
        if (invoiceDate) docRow.invoice_date = invoiceDate;
        let row = null, insErr = null;
        try {
          const ins = await sbPost(env, "booking_documents", docRow, "return=representation");
          if (!ins.ok) insErr = (await ins.text().catch(() => "")) || `insert ${ins.status}`;
          else { const arr = await ins.json(); row = Array.isArray(arr) && arr[0] ? arr[0] : null; }
        } catch (e) { insErr = (e && e.message) || "insert failed"; }
        if (!row) {
          // Don't leave an orphaned R2 object when the DB row didn't save.
          try { await env.BUCKET.delete(key); } catch (_) {}
          console.error("booking_document insert failed", insErr);
          const why = /category/i.test(String(insErr)) ? `The database doesn't accept "${category}" files yet: run supabase/booking_document_categories.sql.`
            : "Couldn't save the record. If this is an invoice, re-run smm_crm.sql (adds invoice_date / paid_date).";
          return json({ error: why, detail: insErr }, 502, request, env);
        }
        return json({ ok: true, document: row }, 200, request, env);
      }

      // ---- Admin: remove a document (R2 object + row) ----
      if (path.endsWith("/booking/document") && request.method === "DELETE") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const id = (url.searchParams.get("id") || "").trim();
        if (!id) return json({ error: "Missing id" }, 400, request, env);
        const rows = await sbGet(env, "booking_documents", `id=eq.${encodeURIComponent(id)}&select=r2_key`);
        const doc = rows && rows[0];
        if (doc && doc.r2_key) { try { await env.BUCKET.delete(doc.r2_key); } catch (_) {} }
        await fetch(`${env.SUPABASE_URL}/rest/v1/booking_documents?id=eq.${encodeURIComponent(id)}`, {
          method: "DELETE", headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}` },
        });
        return json({ ok: true }, 200, request, env);
      }

      // ---- Member (or admin): download a booking document (ownership-checked) ----
      if (path.endsWith("/booking/document") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user) return json({ error: "Sign in to download." }, 401, request, env);
        const id = (url.searchParams.get("id") || "").trim();
        if (!id) return json({ error: "Missing id" }, 400, request, env);
        const rows = await sbGet(env, "booking_documents", `id=eq.${encodeURIComponent(id)}&select=*`);
        const doc = rows && rows[0];
        if (!doc) return json({ error: "Not found" }, 404, request, env);
        const owns = (doc.account_user_id && doc.account_user_id === user.id) ||
          (doc.client_email && String(doc.client_email).toLowerCase() === String(user.email || "").toLowerCase());
        if (!owns && !isAdminEmail(user)) return json({ error: "Forbidden" }, 403, request, env);
        const obj = await env.BUCKET.get(doc.r2_key);
        if (!obj) return json({ error: "File missing" }, 404, request, env);
        const headers = new Headers(corsHeaders(request, env));
        obj.writeHttpMetadata(headers);
        headers.set("etag", obj.httpEtag);
        headers.set("Content-Disposition", `attachment; filename="${String(doc.file_name || "document").replace(/"/g, "")}"`);
        return new Response(obj.body, { headers });
      }

      // ---- Admin: bulk-import contacts (one chunk of rows per request) --------
      // ---- Admin: a member's last hub login (from Supabase Auth) -----------
      // The contact record only tracks last_seen_at (any touchpoint); the real
      // "last logged into the members hub" is auth.users.last_sign_in_at, which
      // only the service role can read — so it comes through here.
      if (path.endsWith("/contacts/member-login") && request.method === "GET") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const uid = new URL(request.url).searchParams.get("user_id");
        if (!uid) return json({ error: "Missing user_id." }, 400, request, env);
        const res = await fetch(`${env.SUPABASE_URL}/auth/v1/admin/users/${encodeURIComponent(uid)}`, {
          headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}` },
        });
        if (!res.ok) return json({ last_sign_in_at: null }, 200, request, env);
        const u = await res.json().catch(() => ({}));
        return json({ last_sign_in_at: (u && u.last_sign_in_at) || null }, 200, request, env);
      }

      // ---- Admin: link a contact card to a member's hub account --------------
      // Given a contact, look up the auth user for its email. If one exists and
      // its name shares the contact's first OR last name, bind contacts.user_id
      // to it (so the card shows as a member). Returns { noAccount } when no hub
      // account exists (UI then offers an invite), or { nameMismatch } when an
      // account exists under a different name (admin can force with { force }).
      // Mirrors the SMM /smm/link flow.
      if (path.endsWith("/contacts/link") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const cid = String((b && b.contact_id) || "").trim();
        if (!cid) return json({ error: "Missing contact id." }, 400, request, env);
        const rows = await sbGet(env, "contacts", `id=eq.${encodeURIComponent(cid)}&select=id,email,first_name,last_name,user_id`);
        const contact = rows && rows[0];
        if (!contact) return json({ error: "That contact no longer exists." }, 404, request, env);
        const email = String(contact.email || "").trim();
        if (!email) return json({ error: "This contact has no email - add one first." }, 400, request, env);
        const u = await findUserByEmail(env, email);
        if (!u) return json({ ok: false, noAccount: true, email }, 200, request, env);
        // Identity check — does the account's name share a name with the card?
        const norm = (s) => String(s || "").toLowerCase().replace(/[^a-z\s-]/g, "").split(/[\s-]+/).filter(Boolean);
        const cardTokens = new Set([...norm(contact.first_name), ...norm(contact.last_name)]);
        const acctName = (u.user_metadata && (u.user_metadata.full_name || u.user_metadata.name)) || "";
        const acctTokens = norm(acctName);
        const nameKnown = cardTokens.size > 0 && acctTokens.length > 0;
        const matches = !nameKnown || acctTokens.some((t) => cardTokens.has(t));
        if (!matches && !(b && b.force === true)) {
          return json({ ok: false, nameMismatch: true, email,
            account_name: acctName, card_name: `${contact.first_name || ""} ${contact.last_name || ""}`.trim() || "(no name on card)" }, 200, request, env);
        }
        const res = await fetch(`${env.SUPABASE_URL}/rest/v1/contacts?id=eq.${encodeURIComponent(cid)}`, {
          method: "PATCH",
          headers: { apikey: env.SUPABASE_SERVICE_ROLE, Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE}`, "Content-Type": "application/json", Prefer: "return=minimal" },
          body: JSON.stringify({ user_id: u.id }),
        });
        if (!res.ok) { const t = await res.text().catch(() => ""); return json({ error: "Couldn't link the account. " + t.slice(0, 200) }, 502, request, env); }
        return json({ ok: true, linked: true, user_id: u.id, account_name: acctName }, 200, request, env);
      }

      // ---- Admin: invite a contact to create their member hub account ---------
      // For a contact with no hub account yet: send a branded invite whose button
      // opens the join page (email pre-filled) so they self-serve their account.
      // Double-checks no account already exists before sending, and logs the
      // invite as a note on the card. Unlike /smm/invite this does NOT create the
      // auth user — the join page owns sign-up.
      if (path.endsWith("/contacts/invite") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
        const b = await request.json().catch(() => ({}));
        const cid = String((b && b.contact_id) || "").trim();
        if (!cid) return json({ error: "Missing contact id." }, 400, request, env);
        const rows = await sbGet(env, "contacts", `id=eq.${encodeURIComponent(cid)}&select=id,email,first_name,last_name,user_id`);
        const contact = rows && rows[0];
        if (!contact) return json({ error: "That contact no longer exists." }, 404, request, env);
        const email = String(contact.email || "").trim();
        if (!email) return json({ error: "This contact has no email - add one first." }, 400, request, env);
        // Guard: never invite someone who already has an account.
        const existing = await findUserByEmail(env, email);
        if (existing) return json({ ok: false, alreadyHasAccount: true, email }, 200, request, env);
        const first = String(contact.first_name || "there").trim();
        const fullName = `${contact.first_name || ""} ${contact.last_name || ""}`.trim();
        const site = String(env.SITE_URL || "https://tmke.co.uk").replace(/\/+$/, "");
        const joinLink = `${site}/join?email=${encodeURIComponent(email)}${fullName ? `&name=${encodeURIComponent(fullName)}` : ""}`;
        const content = `
          <h1 style="${EM_H1}">Create your TMKE account</h1>
          <p style="${EM_P}">Hi ${esc(first)},</p>
          <p style="${EM_P}">We'd love to set you up with a TMKE member account - your own space to design content, plan your marketing, browse The Edit, book shoots and keep everything in one place.</p>
          <p style="${EM_P}">It only takes a minute. Click below to get started.</p>
          <p style="margin:0 0 24px;"><a href="${esc(joinLink)}" style="${EM_BTN}">Create your account</a></p>
          <p style="${EM_P}">If the button doesn't work, paste this into your browser:<br><span style="color:#371e28;">${esc(joinLink)}</span></p>`;
        const html = await wrapInBrandedBase(env, content);
        const sent = await sendEmail(env, { to: email, subject: "Create your TMKE account", html });
        if (!sent.ok) return json({ ok: false, emailFailed: true, error: sent.error || "The invite email didn't send." }, 200, request, env);
        // Log the invite on the contact card so it shows in Notes/Activity.
        try { await sbPost(env, "contact_notes", { contact_id: cid, body: `Invitation to create a member account sent to ${email}.`, author: "System" }); } catch (_) {}
        return json({ ok: true, invited: email }, 200, request, env);
      }

      if (path.endsWith("/contacts/import") && request.method === "POST") {
        const user = await getUser(request, env);
        if (!user || !isAdminEmail(user)) return json({ error: "Admins only." }, 403, request, env);
        const b = await request.json().catch(() => ({}));
        const rows = Array.isArray(b.rows) ? b.rows : [];
        const batchTags = Array.isArray(b.batch_tags) ? b.batch_tags : [];
        const optIn = b.marketing_opt_in === true;
        // "These are internal (Experts Group) agents" — forces them TEG + marketing
        // YES, and fills the TEG tab (brand/postcode/date-joined) from the columns.
        const internal = b.internal === true;
        const source = (typeof b.source === "string" && b.source.trim()) ? b.source.trim() : "import";
        if (!rows.length) return json({ error: "No rows." }, 400, request, env);
        if (rows.length > 500) return json({ error: "Send at most 500 rows per request." }, 400, request, env);
        let imported = 0, skipped = 0, teg = 0;
        for (const r of rows) {
          const email = String((r && r.email) || "").trim().toLowerCase();
          if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) { skipped++; continue; }
          const company = r.company || null;
          // A row is TEG if flagged internal, or its email/brand says so.
          const isFc = isFcBrand(company) || networkTag(email) === "Network: Fine-and-Country";
          const isTeg = !isFc && (internal || networkTag(email) === "Network: TEG" || isTegBrand(company));
          // TEG is always marketing YES, and so is Fine & Country: its own
          // network, but the same group (Dani, 6 Nov 2026).
          const rowOptIn = optIn || isTeg || isFc;
          const rowTags = Array.isArray(r.tags) ? r.tags : (r.tags ? String(r.tags).split(/[;,]/).map((s) => s.trim()) : []);
          const netTag = isFc ? "Network: Fine-and-Country" : isTeg ? "Network: TEG" : networkTag(email);
          const tags = Array.from(new Set([...rowTags, ...batchTags, rowOptIn ? "Marketing-Opt-In" : null, netTag].filter(Boolean)));
          // Checked before the upsert, so a re-import doesn't log everyone a
          // second time. One indexed lookup per opted-in row: imports are an
          // occasional admin action, not a hot path.
          const rowPrior = rowOptIn ? await wasOptedIn(env, email) : null;
          try {
            const cid = await sbRpc(env, "upsert_contact", {
              p_email: email,
              p_first_name: r.first_name || null,
              p_last_name: r.last_name || null,
              p_phone: r.phone || null,
              p_company: company,
              p_source: source,
              // Don't touch lifecycle on import — it's derived from the Network:TEG
              // tag, and forcing a value would clobber a manual "Past". (null →
              // new contacts still default to 'lead' inside upsert_contact.)
              p_lifecycle: null,
              p_marketing_opt_in: rowOptIn ? true : null,
              p_tags: tags,
            });
            imported++;
            // Record HOW they came to be opted in, and be honest about it. A
            // TEG agent is opted in because `rowOptIn = optIn || isTeg` decided
            // it, not because they agreed — that's legitimate interest, and
            // logging it as consent would make this trail useless as evidence
            // the day someone asks.
            if (rowOptIn && rowPrior === false) {
              const byTeg = isTeg && !optIn;
              await logConsent(env, {
                contactId: Array.isArray(cid) ? cid[0] : cid, email,
                action: "opted_in",
                basis: byTeg ? "legitimate_interest" : "consent",
                source: byTeg ? "teg_auto" : "csv_import",
                detail: byTeg
                  ? "TEG network member - opted in automatically on import as part of The Experts Group, not by an act of consent."
                  : "Imported with the marketing opt-in box ticked.",
                actor: "Import",
                raw: { source, internal },
              });
            }
            // TEG contact → register as an internal agent (fills the TEG tab).
            // NOT a videography new-starter, so no code/funnel — those need a package.
            const contactId = Array.isArray(cid) ? cid[0] : cid;
            if (contactId && isTeg) {
              try {
                await ensureAgentProfile(env, contactId, { first_name: r.first_name, last_name: r.last_name, email }, {
                  brand: company, postcode: r.postcode || null, date_joined: parseISODate(r.date_joined) || (r.date_joined || null), is_new_starter: false,
                });
                teg++;
              } catch (_) {}
            }
          } catch (_) { skipped++; }
        }
        return json({ ok: true, imported, skipped, teg }, 200, request, env);
      }

      return json({ error: "Not found" }, 404, request, env);
    } catch (err) {
      return json({ error: String(err && err.message ? err.message : err) }, 500, request, env);
    }
  },
};
